window.__SUM[3]={"LR003640":{"pair":"a -> Mc3r","headline":"Agouti binds and inhibits MC3R in two abstract-only papers, with weaker effect at MC3R than MC1R/MC4R in the human study.","interaction_type":"direct binding","direction_and_effect":"ASIP has relatively weak inhibitory effects at hMC3R, with surmountable inhibition of alpha-MSH-stimulated cAMP [PMID:9058374]. Agouti residues Arg116 and Phe118 are needed for affinity at melanocortin receptors 1, 3 and 4 [PMID:9454589]. Curators label the effects antagonist and inverse agonist respectively.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"pIC50 6.7","assay":"melanocortin receptor binding inhibition, curator-recorded","system":"mouse agouti, mouse receptor","cite":"PMID:9454589"}],"species_and_systems":"Mouse agouti and receptor in the binding paper [PMID:9454589]; human ASIP at human receptor in L cells [PMID:9058374]. Mouse pair is ortholog-inferred.","localisation_and_range":"Agouti is flagged secreted [flag].","caveats":"Abstracts only. The pIC50 is curator-recorded and is not in the abstract text, which describes mutants.","key_references":[{"PMID":"9058374","why":"Weak but real ASIP inhibition at hMC3R, with mechanism"},{"PMID":"9454589","why":"Agouti binding determinants at MC1R, MC3R and MC4R"}],"covers":["LR003640"]},"LR002065":{"pair":"ADAM10 -> EFNA5","headline":"ADAM10 forms a ternary complex with EphA3 and ephrin-A5 and cleaves ephrin-A5 in trans; this is a sheddase-substrate relationship, not a direct binary binding.","interaction_type":"functional only","direction_and_effect":"ADAM10 cleaves ephrin-A5 bound to EphA3; the cleavage occurs in trans, with ADAM10 and substrate on opposing cells [PMID:16239146]. UniProt records a ternary EFNA5-EPHA3-ADAM10 complex mediating EFNA5 shedding [DB:UniProt].","molecular_requirements":"A functional EphA3/ephrin-A5 complex creates a new recognition motif for the ADAM10 cysteine-rich domain; ADAM10 constitutively associates with EphA3 [PMID:16239146]. Direct ADAM10-ephrin-A5 binding is not reported.","affinity_potency":[],"species_and_systems":"Mouse species recorded for both partners in the curator row; the paper structure and functional work [PMID:16239146]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"Both flagged membrane (not secreted); EFNA5 transmembrane [flag]; cleavage between opposing cell membranes [PMID:16239146].","caveats":"One paper, abstract only. Another judged row was different-entity.","key_references":[{"PMID":"16239146","why":"ADAM10 cleaves ephrin-A5 in trans within the EphA3 complex"}],"covers":["LR002065","LR005391"]},"LR005017":{"pair":"ADAM29 -> ITGA4","headline":"Human ADAM29 supports integrin alpha4-dependent cell adhesion; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Human ADAM11, ADAM23 and ADAM29 selectively support integrin alpha4-dependent cell adhesion; the disintegrin-like domains of these catalytically inactive ADAMs are ligands [PMID:28913673].","molecular_requirements":"Alpha4-dependent; partner beta chain not stated in our evidence [PMID:28913673].","affinity_potency":[],"species_and_systems":"Human proteins; integrin binding assays [PMID:28913673]. Mouse pair is ortholog-inferred.","localisation_and_range":"ADAM29 is flagged non-secreted [flag].","caveats":"Abstract read only and the evidence sentence is truncated; adhesion support only, no affinity.","key_references":[{"PMID":"28913673","why":"Non-catalytic ADAM29 is an integrin alpha4 ligand"}],"covers":["LR001629","LR005017"]},"LR002074":{"pair":"ADAM9 -> ITGA1","headline":"ADAM9 disintegrin adhesion of HEK-293 cells is blocked by anti-alpha1 antibody; alpha1 was not captured in pull-down.","interaction_type":"functional only","direction_and_effect":"Antibodies to alpha1, alpha3, alpha6, alphav and beta1 blocked adhesion of HEK-293 cells to GST-disintegrin protein [PMID:15361064].","molecular_requirements":"Alpha1 acts with beta1; the curator note says alpha1 chain was not recovered in the GST-disintegrin pulldown, unlike alpha3, alpha6 and alphav [PMID:15361064].","affinity_potency":[],"species_and_systems":"Human HEK-293 cells; renal cortical lysates; recombinant GST-disintegrin [PMID:15361064]. Mouse pair is ortholog-inferred.","localisation_and_range":"ADAM9 is flagged secreted [flag]; the paper describes ADAM9 as expressed in a punctate basolateral distribution on renal tubular cells [PMID:15361064].","caveats":"Abstract read only; support is blocking antibody only, not direct capture.","key_references":[{"PMID":"15361064","why":"ADAM9 disintegrin is a ligand for multiple beta1 integrins"}],"covers":["LR002074","LR005400"]},"LR001633":{"pair":"ADGRB1 -> RTN4RL1","headline":"ADGRB1 ectodomain binds RTN4RL1 directly in a CRISPRa and AVEXIS study; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"ADGRB1 probe stained cells overexpressing RTN4R, RTN4RL1 and RTN4RL2 and ectodomains interacted directly in AVEXIS in both bait-prey orientations [PMID:30477585]. CRISPRa guides targeting RTN4RL1 and RTN4RL2 were enriched when ADGRB1 was used as the selection probe [PMID:30477585].","molecular_requirements":"The N-terminal thrombospondin type 1 repeats 1-3 of ADGRB1 were sufficient for binding; ADGRB1 but not ADGRB2 interacted [PMID:30477585].","affinity_potency":[],"species_and_systems":"Human cDNAs in HEK293 cells and recombinant ectodomains; four independent experiments for the staining result [PMID:30477585]. Mouse pair is ortholog-inferred.","localisation_and_range":"The receptor side is a GPI-linked membrane protein per the paper [PMID:30477585]; ADGRB1 is flagged secreted [flag] but the assay used its ectodomain, and its native range is not reported in our evidence.","caveats":"Single paper; binding only, no signalling or functional effect shown. No affinity value. No database support.","key_references":[{"PMID":"30477585","why":"CRISPRa screen and AVEXIS showing ADGRB1-RTN4R family binding"}],"covers":["LR001633","LR005021"]},"LR005404":{"pair":"ADGRE5 -> THY1","headline":"CD97 (ADGRE5) binds Thy-1 in adhesion and protein-binding assays (one paper, abstract only).","interaction_type":"direct binding","direction_and_effect":"CD97-expressing cells adhered to Thy-1 on activated dermal endothelial cells, Thy-1 CHO cells and immobilized Thy-1; soluble CD97 bound immobilized Thy-1 [PMID:22210915]. Adhesion was partly blocked by CD97 and Thy-1 antibodies [PMID:22210915].","molecular_requirements":"The CD97 stalk is implicated: stalk antibody blocked more strongly than EGF-domain antibody, binding was calcium independent, and CD97 without stalk or EMR2 failed to bind [PMID:22210915].","affinity_potency":[],"species_and_systems":"Human cells and recombinant proteins; CD97 upregulated on neutrophils of psoriasis patients [PMID:22210915].","localisation_and_range":"Thy-1 is on endothelial cells, so contact-mediated leukocyte-endothelium adhesion [PMID:22210915]. Thy-1 is annotated transmembrane [flag].","caveats":"One paper, abstract only; antibody blocking was partial; no affinity reported [PMID:22210915].","key_references":[{"PMID":"22210915","why":"adhesion and binding assays with stalk mapping"}],"covers":["LR002078","LR005404"]},"LR002083":{"pair":"ADGRL1 -> TENM2","headline":"LPH1 (ADGRL1) binds teneurin-2 (Lasso splice variant) strongly; one abstract-only paper plus a UniProt statement.","interaction_type":"direct binding","direction_and_effect":"LPH1 and Lasso (a teneurin-2 splice variant) interact strongly and specifically and copurify from rat brain [PMID:21724987]. Cells expressing them attract each other and form junctions [PMID:21724987]. A C-terminal Lasso fragment interacts with LPH1 and induces Ca(2+) signals in presynaptic boutons [PMID:21724987]. UniProt describes teneurin-2 as a ligand of ADGRL1 [DB:UniProt].","molecular_requirements":"The splice variant Lasso was the isolated form [PMID:21724987].","affinity_potency":[],"species_and_systems":"Rat brain extract purification, cell co-culture, hippocampal neurons [PMID:21724987]; human and mouse pairs are ortholog-inferred.","localisation_and_range":"Both membrane-bound; LPH1 presynaptic and Lasso postsynaptic, so trans-synaptic [PMID:21724987].","caveats":"Abstract only; no affinity reported. The stored evidence sentence only states copurification, which is weaker than direct binding.","key_references":[{"PMID":"21724987","why":"purification of Lasso/teneurin-2 as LPH1 ligand"}],"covers":["LR002083","LR005409"]},"LR005413":{"pair":"ADM -> RAMP1","headline":"Evidence is for AM2/IMD binding RAMP-CLR complexes, not adrenomedullin; RAMP1 is a CLR co-receptor, not a stand-alone receptor.","interaction_type":"direct binding","direction_and_effect":"AM2/IMD bound purified RAMP1-, RAMP2- and RAMP3-CLR ECD complexes, preferring the CGRP and AM2 receptor complexes; a 2.05 Angstrom crystal structure of an RAMP1-CLR ECD with an AM2/IMD antagonist fragment was solved [PMID:30139742]. GtoPdb lists ADM as full agonist at RAMP1 [DB:GtoPdb].","molecular_requirements":"RAMP1 acts only paired with CLR; RAMP1:CLR favours CGRP, RAMP2/RAMP3 favour AM [PMID:30139742].","affinity_potency":[],"species_and_systems":"Purified ECD complexes; species human per curator label [PMID:30139742].","localisation_and_range":"ADM flagged secreted [flag].","caveats":"The paper's own finding is about AM2/IMD, not ADM. For ADM, RAMP1:CLR is the CGRP-preferring receptor, so this pair is weak. Abstract only.","key_references":[{"PMID":"30139742","why":"RAMP-CLR ECD structure and AM2/IMD binding"}],"covers":["LR002087","LR005413"]},"LR005026":{"pair":"ADM2 -> RAMP3","headline":"ADM2 binds the RAMP3-CLR (AM2 receptor) complex among three RAMP-CLR ECDs; one abstract plus database support, RAMP3 acts with CLR.","interaction_type":"direct binding","direction_and_effect":"AM2/IMD bound the purified RAMP3-CLR ECD complex, preferring the CGRP and AM2 receptor complexes [PMID:30139742]. GtoPdb lists a full agonist [DB:GtoPdb]. A cryoEM structure with chains of ADM2 and RAMP3 is recorded [DB:PDB 6UVA].","molecular_requirements":"RAMP3 with CLR/CALCRL; UniProt says RAMP3 and CALCRL form the receptor complex for ADM and ADM2 [DB:UniProt].","affinity_potency":[{"value":"pEC50 8.899999618530273-10.100000381469727","assay":"GtoPdb agonist record","system":"not given","cite":"DB:GtoPdb"}],"species_and_systems":"Purified recombinant ECD complexes; curators annotate human ligand and receptor. Mouse pair projected from human.","localisation_and_range":"RAMP3 is flagged transmembrane; ADM2 secreted [flag].","caveats":"The one shown paper is abstract-only. One paper is pending; three are review_only.","key_references":[{"PMID":"30139742","why":"AM2/IMD binding across RAMP-CLR ECD complexes"}],"covers":["LR001638","LR005026"]},"LR002092":{"pair":"AGRN -> ITGB1","headline":"The same single 1997 abstract-only paper as ITGAV: beta1 antibodies fully blocked agrin signalling, but direct binding is not shown.","interaction_type":"functional only","direction_and_effect":"Agrin-induced aggregation of acetylcholine receptors on cultured myotubes was completely blocked by antibodies to the beta1 integrin subunit [PMID:9367446]. Cells expressing alpha(v) and beta1 adhered to immobilised agrin, blocked by anti-beta1 antibodies [PMID:9367446].","molecular_requirements":"The abstract points to alpha(v)beta1 as the relevant integrin [PMID:9367446]; Reactome lists an Agrin:Integrin alphaVbeta1 complex [DB:Reactome]. A beta1-alone requirement is not tested in our evidence.","affinity_potency":[],"species_and_systems":"Experimental species unspecified in the curator record [PMID:9367446]. Cultured myotubes and non-muscle cells.","localisation_and_range":"Agrin is a basal lamina-associated proteoglycan; ITGB1 is flagged as a non-secreted receptor [flag] [PMID:9367446].","caveats":"Abstract read only; antibody-block data cannot separate direct binding from modulation, and the authors say integrins are 'components or modulators' [PMID:9367446]. Only one paper supports this pair. No affinity reported.","key_references":[{"PMID":"9367446","why":"Anti-beta1 antibodies completely blocked agrin-induced receptor aggregation"}],"covers":["LR002092","LR005418"]},"LR005422":{"pair":"AGRP -> SDC1","headline":"Syndecan-1 is reported to potentiate AGRP action via heparan sulfate chains in transgenic mice; modulation, not a signalling receptor.","interaction_type":"functional only","direction_and_effect":"Transgenic hypothalamic syndecan-1 expression produced hyperphagia and maturity-onset obesity resembling reduced alpha-MSH action; via their HS chains syndecans potentiate the action of agouti-related protein and agouti signaling protein, endogenous inhibitors of alphaMSH [PMID:11461706].","molecular_requirements":"Heparan sulfate chains are required for the potentiation [PMID:11461706]. No direct binding to AGRP is reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse in vivo transgenics [PMID:11461706]. Human pair is ortholog-inferred; mouse is not.","localisation_and_range":"SDC1 is flagged secreted and transmembrane [flag]; the effect is in the hypothalamus [PMID:11461706].","caveats":"Abstract-only. The SDC1 evidence is ectopic transgenic overexpression; the physiological syndecan in hypothalamus is syndecan-3 [PMID:11461706]. Syndecans are modulators rather than receptors that transduce an AGRP signal.","key_references":[{"PMID":"11461706","why":"Hypothalamic syndecan-1 transgene causes hyperphagia and obesity; syndecans potentiate AGRP"}],"covers":["LR002096","LR005422"]},"LR000049":{"pair":"AHSG -> INSR","headline":"Purified human AHSG inhibits insulin receptor kinase activity without competing with insulin for binding; evidence is functional, one 1993 paper.","interaction_type":"functional only","direction_and_effect":"AHSG acts as an inhibitor of the insulin receptor tyrosine kinase: it blocked insulin-stimulated IR autophosphorylation in vitro and in vivo, substrate phosphorylation, IRS-1 phosphorylation and IRS-1/p85 association, and insulin-dependent mitogenesis [PMID:7906861].","molecular_requirements":"Not reported in our evidence. AHSG does not compete with insulin for IR binding and does not affect IGF-I-stimulated kinase activity [PMID:7906861].","affinity_potency":[],"species_and_systems":"Serum-purified human AHSG; effects in H-35 hepatoma cells and in vitro kinase assays; species of the cells is not stated in our evidence [PMID:7906861].","localisation_and_range":"AHSG is flagged secreted and INSR a transmembrane receptor [flag]; BioGRID lists a reconstituted complex [DB:BioGRID 278041].","caveats":"Not a classical ligand-site interaction: it acts at the kinase level and not by competing with insulin [PMID:7906861]. No direct binding or affinity data in our evidence beyond a BioGRID record. Abstract only; single paper.","key_references":[{"PMID":"7906861","why":"AHSG inhibits IR tyrosine kinase, not competing with insulin"}],"covers":["LR000049","LR003599"]},"LR001642":{"pair":"ALCAM -> L1CAM","headline":"Antibody blocking suggests L1cam is needed for ALCAM-promoted axon growth of mouse midbrain dopamine neurons; no direct binding shown in our evidence.","interaction_type":"functional only","direction_and_effect":"ALCAM promoted axon growth of mouse midbrain dopamine neurons, and neutralizing antibodies for L1cam abolished the effect; the authors propose a trans-heterophilic interaction [PMID:31300520]. ALCAM also abolished Sema3A's growth effect and induced branching with Sema3C [PMID:31300520].","molecular_requirements":"L1cam is described as one of three components of a Semaphorin receptor complex (Nrp1, Chl1, L1cam) [PMID:31300520]; which is needed alone is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Murine primary midbrain cultures [PMID:31300520]; curator records human for both partners.","localisation_and_range":"ALCAM acts as an extracellular substrate presented to cell-bound partners (juxtacrine/matrix-like) [PMID:31300520]. Reactome lists an L1:ALCAM complex [DB:Reactome R-HSA-443658].","caveats":"Single paper, abstract only; inhibition by antibodies is indirect and shows no binding. No affinity.","key_references":[{"PMID":"31300520","why":"Antibody blocking of Nrp1/Chl1/L1cam abolishes ALCAM growth effect"}],"covers":["LR001642","LR005030"]},"LR005035":{"pair":"ALKAL2 -> LTK","headline":"ALKAL2 binds and robustly activates LTK in human systems; structural and cell evidence, no affinity values.","interaction_type":"direct binding","direction_and_effect":"ALKAL2 (AUG-alpha) binds and robustly activates LTK as well as ALK [PMID:26630010]. ALKAL1 and ALKAL2 are both strong activators of LTK [PMID:34646012]. GtoPdb lists agonist/activation [DB:GtoPdb].","molecular_requirements":"LTK-ALKAL2 complexes were 2 receptors : 1 cytokine [PMID:34646012]. The crystallised LTK complex was with ALKAL1; ALKAL1 is called the high-affinity cytokine for LTK [PMID:34646012], so ALKAL2 is the weaker-described partner here, though no values are given. Other subunit or co-receptor requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human recombinant proteins and cells expressing human LTK [PMID:26630010] [PMID:34646012]. Mouse pair inferred by orthology.","localisation_and_range":"ALKAL2 is flagged as secreted [flag]; Reactome has the LTK dimer:ALKAL1,2 complex at the plasma membrane [DB:Reactome].","caveats":"The LTK structural work used ALKAL1, so the ALKAL2-LTK result rests on the stoichiometry statement and the 2015 abstract [PMID:34646012] [PMID:26630010]; the latter was read as abstract only. No affinity or potency values for ALKAL2-LTK in our evidence. One row pending.","key_references":[{"PMID":"26630010","why":"Binding and robust LTK activation by ALKAL2"},{"PMID":"34646012","why":"LTK-cytokine complex stoichiometry and activation"}],"covers":["LR001647","LR005035"]},"LR003604":{"pair":"ANGPT1 -> ITGB1","headline":"Integrin-mediated cell adhesion to angiopoietin and alpha5beta1 binding by an Ang1 fragment; chain-level evidence, abstract only.","interaction_type":"direct binding","direction_and_effect":"Monomeric DeltaAng1 bound alpha(5)beta(1) integrin with similar affinity compared with Tie2 and stimulated endothelial adhesion and MAPK activation [PMID:15781448]. HUVECs adhered and spread on Ang-1, and the adhesion was independent of Tie2 per the abstract [PMID:11346644].","molecular_requirements":"Binding was shown for the alpha5beta1 heterodimer, not ITGB1 alone [PMID:15781448]. The title of PMID:11346644 states the adhesion is integrin-mediated, but the dossier abstract is truncated and names no specific integrin chain.","affinity_potency":[],"species_and_systems":"Recombinant human DeltaAng1 and endothelial cells, chick CAM [PMID:15781448]; HUVECs and fibroblasts with or without Tie2 [PMID:11346644].","localisation_and_range":"ANGPT1 is flagged as secreted [flag]; the cell-adhesion result implies the ligand can act as an immobilised substrate [PMID:11346644].","caveats":"Both confirming papers are abstract only; no numeric affinity. Conflicting or negative row: a mouse neuronal study judged pair_absent only noted beta1 integrin on neurons and that it was previously found to act as an Ang receptor [PMID:15690488]; it is not a direct test. Three further rows were abstract_insufficient.","key_references":[{"PMID":"15781448","why":"Monomeric Ang1 fragment binds alpha5beta1 with affinity similar to Tie2"},{"PMID":"11346644","why":"Integrin-mediated, Tie2-independent cell adhesion to Ang-1"}],"covers":["LR000054","LR003604"]},"LR000058":{"pair":"ANGPTL4 -> TEK","headline":"ANGPTL4 binds the TEK (Tie2) receptor and acts as an agonist; supported by binding data, functional data and several databases.","interaction_type":"direct binding","direction_and_effect":"ANGPTL4 (angiopoietin-4) bound Tie2 in binding assays, and Tie1 was not bound [PMID:10051567]. Recombinant Ang4 at 400 ng/mL markedly increased Tie2 and Akt phosphorylation in primary human umbilical vein endothelial cells (HUVECs) and induced survival and migration, so it acts as an agonist [PMID:15284220].","molecular_requirements":"Not reported in our evidence beyond Tie2 itself; recombinant Ang3 and Ang4 formed disulfide-linked dimers [PMID:15284220].","affinity_potency":[],"species_and_systems":"Human ANGPTL4 on human endothelial cells (HUVECs). Its mouse counterpart Ang3 acted mainly on mouse endothelium, so activity is species-restricted [PMID:15284220]. The mouse pair here is projected from human evidence.","localisation_and_range":"Ligand flagged secreted, receptor flagged transmembrane [flag]; this implies paracrine signalling onto endothelial cells.","caveats":"Both papers were read as abstracts in our record; the first paper's evidence sentence is a browser-read quote still awaiting spot-check. No affinity is reported in our evidence. GtoPdb lists the pair without action or affinity [DB:GtoPdb]. Also recorded in BioGRID, IntAct (pull down), Reactome and UniProt [DB:BioGRID] [DB:IntAct] [DB:Reactome] [DB:UniProt].","key_references":[{"PMID":"10051567","why":"Binding of angiopoietin-4 to Tie2 but not Tie1"},{"PMID":"15284220","why":"Ang4 drives Tie2 and Akt phosphorylation in HUVECs"}],"covers":["LR000058","LR003608"]},"LR001651":{"pair":"ANGPTL2 -> ITGA5","headline":"ANGPTL2 is associated with integrin alpha5beta1 by co-IP and linked functionally to it; no direct binding assay shown.","interaction_type":"functional only","direction_and_effect":"ANGPTL2 and integrin alpha5beta1 associated by co-immunoprecipitation and co-localization under overexpression [PMID:42609534]. In chondrocytes, changing ANGPTL2 expression altered p38 MAPK activity mediated by integrin alpha5beta1 [PMID:29074299].","molecular_requirements":"The evidence concerns the alpha5beta1 heterodimer; ITGA5 alone is not tested in our evidence.","affinity_potency":[],"species_and_systems":"Human retinal microvascular endothelial cells (HRMECs) and diabetic rat retina [PMID:42609534]; mouse ATDC5 chondrogenic cells and Angptl2 knockout mice [PMID:29074299].","localisation_and_range":"Ligand flagged secreted [flag]; ANGPTL2 also accumulates in cartilage extracellular matrix [PMID:29074299].","caveats":"The first paper was read as an abstract and its association was under overexpression conditions only; the second is a functional readout, not binding. No affinity reported. Three further papers were abstract_insufficient.","key_references":[{"PMID":"42609534","why":"Co-IP and co-localization of ANGPTL2 with integrin alpha5beta1"},{"PMID":"29074299","why":"ANGPTL2 modulates p38 MAPK via integrin alpha5beta1 in chondrocytes"}],"covers":["LR001651","LR005039"]},"LR005431":{"pair":"ANGPTL2 -> MCAM","headline":"CD146 (MCAM) is a direct ANGPTL2 binding partner on adipocytes, shown by pull-down with purified proteins and co-IP in mouse fat.","interaction_type":"direct binding","direction_and_effect":"ANGPTL2 interacted with CD146 in white adipose tissue and the interaction was stronger in obese than lean mice. Pull-down with purified proteins showed direct interaction. ANGPTL2 binding activated CREB, which upregulated CD146 [PMID:33747748]. Anti-CD146 antibodies disrupted the interaction and inhibited obesity [PMID:33747748].","molecular_requirements":"The fourth domain of CD146 was required for the interaction in 293 cells [PMID:33747748].","affinity_potency":[],"species_and_systems":"CD146 was found as an ANGPTL2 interactor on a human proteome microarray; co-IP in mouse white adipose tissue and 293 cells [PMID:33747748]. CD146 also detected in human adipose tissue [PMID:33747748].","localisation_and_range":"The paper calls CD146 a membrane receptor on preadipocytes and mature adipocytes [PMID:33747748]; the entity flag for MCAM says not transmembrane [flag].","caveats":"One paper. CD146 did not co-IP with ANGPTL3 or ANGPTL4 [PMID:33747748]. No affinity reported.","key_references":[{"PMID":"33747748","why":"Direct ANGPTL2-CD146 binding and role in adipocytes"}],"covers":["LR002109","LR005431"]},"LR005440":{"pair":"ANGPTL4 -> SDC1","headline":"ANGPTL4 is reported as a syndecan binder in one full-text paper; SDC1-specific data are thin in our excerpts.","interaction_type":"direct binding","direction_and_effect":"The paper identifies ANGPTL4 as a Wnt signalling antagonist that binds syndecans and promotes LRP6 turnover; curator labels it antagonist [PMID:29017031]. The evidence sentence is the title, and SDC1-specific data are not shown in our excerpts.","molecular_requirements":"N-terminal ANGPTL4 (nANGPTL4) increased LRP6-SDC4 clustering while cANGPTL4 had no effect, so the N-terminal fragment seems relevant, unlike the C-terminal fragment elsewhere [PMID:29017031].","affinity_potency":[],"species_and_systems":"Xenopus embryos and HEK293T cells; human ANGPTL4 and human receptor constructs in the SDC4 data (a sister pair) [PMID:29017031].","localisation_and_range":"SDC1 is flagged both secreted and transmembrane, so shed and membrane forms are possible [flag]; ANGPTL4 is flagged secreted.","caveats":"Binding to SDC1 itself is only supported by the title and by a general statement that syndecans bind ANGPTL4; strongest evidence is for SDC4.","key_references":[{"PMID":"29017031","why":"ANGPTL4 is a Wnt antagonist that binds syndecans and promotes LRP6 turnover"}],"covers":["LR002118","LR005440"]},"LR003613":{"pair":"ANXA1 -> FPR1","headline":"Annexin A1 N-terminal peptides activate FPR on human neutrophils; intact-protein activity is not shown.","interaction_type":"functional only","direction_and_effect":"Peptides from the N-terminal domain of annexin I act as FPR ligands on human neutrophils, triggering dose-dependent Ca2+ transients, inhibiting transendothelial migration and desensitising chemoattractant responses [PMID:10882119]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Peptides Ac1-26 and Ac9-25 but not Ac1-18 interfered with transendothelial passage at 20 \u00b5M, so the N-terminal region matters [PMID:10882119].","affinity_potency":[{"value":"pEC50 5.800000190734863 to 6.099999904632568","assay":"GtoPdb agonist record","system":"not stated","cite":"PMID:10882119"}],"species_and_systems":"Human neutrophils in vitro [PMID:10882119]. The mouse pair is ortholog-inferred, not tested directly.","localisation_and_range":"ANXA1 flagged secreted but not transmembrane; FPR1 transmembrane [flag].","caveats":"Evidence is for peptides, not the intact protein; abstract plus excerpts. BioGRID has an affinity capture-western record [DB:BioGRID]. Three further rows are pending.","key_references":[{"PMID":"10882119","why":"Annexin I N-terminal peptides act as FPR ligands on human neutrophils"}],"covers":["LR000063","LR003613"]},"LR002128":{"pair":"ANXA2 -> TLR4","headline":"Annexin A2 tetramer activates macrophages through TLR4 in functional, knockdown and knockout experiments; no direct binding shown.","interaction_type":"functional only","direction_and_effect":"Soluble annexin A2 tetramer (A2t) activated human monocyte-derived macrophages and murine bone-marrow macrophages; TLR4 siRNA knockdown reduced the human response, anti-TLR4 (but not anti-TLR2) antibodies blocked activation, and TLR4-/- macrophages were refractory. MyD88-deficient macrophages showed a blunted response [PMID:19965653]. This is agonist activity.","molecular_requirements":"The active ligand is the heterotetramer of annexin A2 with S100A10 (A2t), so both chains matter for ligand expression [PMID:19965653]. Whether TLR4 needs co-receptors (e.g. MD-2/CD14) is not reported in our evidence. A previously cloned A2t receptor was dispensable [PMID:19965653].","affinity_potency":[],"species_and_systems":"Human monocyte-derived macrophages and mouse bone-marrow-derived macrophages, in vitro [PMID:19965653]. Both human and mouse pairs are ortholog-inferred.","localisation_and_range":"ANXA2 is flagged as secreted [flag]; the paper describes soluble A2t that can be shed or secreted [PMID:19965653].","caveats":"Single paper, abstract only. No direct TLR4 binding assay; evidence is functional and genetic. The row is gene-level, not complex-level.","key_references":[{"PMID":"19965653","why":"TLR4 dependence of A2t macrophage activation by knockdown, antibody and knockout."}],"covers":["LR002128","LR005445"]},"LR012136":{"pair":"APCDD1 -> FZD2:LRP5","headline":"APCDD1 interacts in vitro with LRP5 and inhibits Wnt signalling; no evidence for this specific FZD2 subunit.","interaction_type":"direct binding","direction_and_effect":"APCDD1 is described as a Wnt inhibitor: it inhibits Wnt signalling cell-autonomously and upstream of beta-catenin, and represses Wnt reporters and target genes [PMID:20393562]. The paper reports an in vitro interaction with WNT3A and LRP5 [PMID:20393562]; IntAct and UniProt record the LRP5 interaction [DB:IntAct, DB:UniProt].","molecular_requirements":"Only LRP5 is shown to interact with APCDD1; FZD2 is not mentioned in the evidence sentence or abstract, so the complex-level pair rests on the LRP5 chain alone. A CCC tool scoring by the least-expressed subunit would add a requirement for FZD2 that our evidence does not support.","affinity_potency":[],"species_and_systems":"Human genetics and human cells for the interaction in vitro; Wnt inhibition also in chick neural development and Xenopus embryos [PMID:20393562].","localisation_and_range":"APCDD1 is described as a membrane-bound glycoprotein [PMID:20393562]; it is not flagged as secreted in the dossier, so juxtacrine or cell-autonomous action is more likely than long-range signalling.","caveats":"Single paper, abstract plus excerpts. Chain-only evidence (LRP5); no data for FZD2. The interaction is 'in vitro' with no affinity. APCDD1 may act as a Wnt-pathway inhibitor rather than a classical ligand.","key_references":[{"PMID":"20393562","why":"APCDD1 interacts with LRP5 and WNT3A and inhibits Wnt signalling."}],"covers":["LR012136"]},"LR005044":{"pair":"APELA -> APLNR","headline":"ELA/Elabela is a well-supported endogenous agonist of the apelin receptor, shown by binding, signalling and in vivo studies in several species.","interaction_type":"direct binding","direction_and_effect":"ELA is an agonist of APLNR (APJ). It inhibited forskolin-induced cAMP, recruited beta-arrestin and induced internalisation, and competed for apelin binding in human heart [PMID:28137936]; it suppressed cAMP, stimulated ERK1/2 phosphorylation and weakly induced calcium mobilisation in CHO cells [PMID:25639753]. Chimeric apela bound APJ directly and apelin competed [PMID:25995451]. In zebrafish, loss of Ela phenocopies loss of aplnr [PMID:24316148]. GtoPdb lists it as an agonist [DB:GtoPdb].","molecular_requirements":"Single-chain GPCR; no co-receptor reported in our evidence. Longer ELA peptides bind better: ELA-32 pKi=9.59\u00b10.08, ELA-21 pKi=8.52\u00b10.11, ELA-11 pKi=7.85\u00b10.05 in human left ventricle [PMID:28137936]. ELA-11 retained full activity in the cAMP assay [PMID:28137936].","affinity_potency":[{"value":"Kd = 0.51 nm","assay":"binding of chimeric apela ligand to APJ","system":"abstract only; species unspecified","cite":"PMID:25995451"},{"value":"EC50 of 11.1 nM (cAMP suppression); 14.3 nM (ERK1/2 phosphorylation)","assay":"cell signalling","system":"CHO cells over-expressing human APJ","cite":"PMID:25639753"},{"value":"pKi=9.59\u00b10.08 (ELA-32)","assay":"competition binding","system":"human left ventricle homogenate","cite":"PMID:28137936"}],"species_and_systems":"Human recombinant and native human heart tissue, CHO and HEK293 cells [PMID:28137936][PMID:25639753]; rat isolated hearts [PMID:26611206]; zebrafish embryos [PMID:24316148]; mouse aortic rings [PMID:25639753]. The mouse pair is inferred from human evidence (ortholog_inferred).","localisation_and_range":"ELA is flagged secreted and non-transmembrane; APLNR is a transmembrane receptor [flag]. ELA is described as a secreted hormone expressed in adult kidney [PMID:25639753], consistent with endocrine or paracrine action.","caveats":"Several papers were read as abstracts only [PMID:25995451][PMID:26611206][PMID:24316148]. The zebrafish paper shows genetic, not binding, evidence [PMID:24316148]. Structures 7W0N, 7W0O and 7W0P contain both chains [DB:PDB 7W0N].","key_references":[{"PMID":"28137936","why":"Competition binding in human heart, signalling, and in vivo effects."},{"PMID":"25995451","why":"Direct binding with Kd and Gi signalling."},{"PMID":"25639753","why":"Potency in mammalian cells."}],"covers":["LR001657","LR005044"]},"LR002137":{"pair":"APOA1 -> SCARB1","headline":"ApoA-I binds SR-B1 in one recent paper by thermophoresis and pull-down; APOA1-Milano binds better.","interaction_type":"direct binding","direction_and_effect":"SR-B1 and APOA1 interact by microscale thermophoresis and affinity capture, with enhanced binding for APOA1-Milano [PMID:38479648]. Excess unlabeled APOA1 reduced DiI-LDL internalization in human coronary endothelial cells, and about 40% less DiI-LDL transcytosis, so APOA1 competes with LDL for SR-B1 [PMID:38479648].","molecular_requirements":"Not reported in our evidence beyond SR-B1 itself. Reconstituted HDL was a better competitor than lipid-free APOA1 [PMID:38479648].","affinity_potency":[],"species_and_systems":"Human coronary artery endothelial cells, HeLa cells expressing SR-B1-GFP, recombinant APOA1 and in vitro binding; male mice used in vivo [PMID:38479648].","localisation_and_range":"APOA1 is flagged secreted, not transmembrane; SCARB1 carries a receptor flag [flag].","caveats":"Pull-down used overexpressed SR-B1-GFP; no Kd is given in the excerpts. BioGRID and IntAct also list an earlier co-immunoprecipitation record [DB:BioGRID][DB:IntAct].","key_references":[{"PMID":"38479648","why":"Binding by thermophoresis and capture, plus LDL competition"}],"covers":["LR002137","LR005454"]},"LR000067":{"pair":"APOB -> LDLR","headline":"Well-known pair; here one NMR/SPR study with LR5 and ApoB peptides plus structures, and one weak mutation paper.","interaction_type":"direct binding","direction_and_effect":"NMR and SPR show peptides from ApoB (site A and site B) bind LDLR repeat LR5 on its convex face; complexes weaken at low Ca2+ and low pH, favouring endosomal dissociation [PMID:24447298]. IntAct lists NMR records and PDB lists structures (9BD8, 9BDE, 9BDT, 9COO) with chains from both proteins [DB:IntAct][DB:PDB 9BD8].","molecular_requirements":"LDLR uses calcium-binding repeats; more than one repeat may be used to chelate lipoproteins [PMID:24447298].","affinity_potency":[],"species_and_systems":"Peptides and LR5 domain in vitro, species not reported [PMID:24447298]; human LDL on cultured fibroblasts [PMID:12031600]. Mouse pair is ortholog-inferred.","localisation_and_range":"ApoB is flagged secreted, not transmembrane; LDLR carries a receptor flag [flag].","caveats":"Peptide fragments, not full-length ApoB. The N3516K paper gave discordant results (poor cell growth but normal or better binding), so it is weak support [PMID:12031600]. Both read as abstracts.","key_references":[{"PMID":"24447298","why":"NMR/SPR of LR5 with ApoB peptides"},{"PMID":"12031600","why":"Receptor binding of mutant ApoB LDL (weak)"}],"covers":["LR000067","LR003616"]},"LR002146":{"pair":"APOE -> LILRB3","headline":"One abstract-level structural paper: APOE4, but not APOE2, binds LilrB3 and activates microglia; isoform-specific.","interaction_type":"direct binding","direction_and_effect":"APOE4, but not APOE2, specifically interacts with LilrB3; two Ig-like domains of the extracellular domain recognise a positively charged patch on the APOE4 N-terminal domain [PMID:36588123]. APOE4 activated human HMC3 microglia into a pro-inflammatory state in a LilrB3-dependent manner [PMID:36588123].","molecular_requirements":"The structure shows two APOE4 molecules engaging two LilrB3 molecules in a hetero-tetrameric complex [PMID:36588123].","affinity_potency":[],"species_and_systems":"Human proteins and human HMC3 microglia [PMID:36588123].","localisation_and_range":"APOE flagged secreted [flag].","caveats":"Abstract only; authors call LilrB3 a putative receptor. Binding is isoform-dependent, so results depend on APOE genotype. Affinity not reported in our evidence.","key_references":[{"PMID":"36588123","why":"structure of APOE4-LilrB3 complex"}],"covers":["LR002146"]},"LR003622":{"pair":"APOE -> LRP1","headline":"Well supported across human and mouse: binding in liver membranes, proximity ligation in pericytes, and brain co-IP.","interaction_type":"direct binding","direction_and_effect":"ApoE liposomes bound specifically to HepG2 cell surfaces and human liver membranes, with a binding protein indistinguishable from LRP; authors concluded LRP might function as an apoE receptor [PMID:2779654]. Proximity ligation showed APOE3 and murine Apoe binding LRP1 with high affinity in pericytes, whereas APOE4-LRP1 was barely detectable [PMID:22622580]. Endogenous APOE pulled down LRP1 from E14.5 mouse brain lysate [PMID:31677479].","molecular_requirements":"Isoform matters: APOE4 binds LRP1 poorly in pericytes [PMID:22622580]. Subunits not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human cells (HepG2, liver membranes) [PMID:2779654]; mouse pericytes and embryonic brain [PMID:22622580] [PMID:31677479]. Human and mouse pairs both have direct evidence.","localisation_and_range":"APOE flagged secreted [flag]; embryonic brain APOE was widely distributed, consistent with a secreted protein [PMID:31677479].","caveats":"Most papers abstract-level; 22622580 text is listed as abstract only although full-text reading is noted. One paper is pending and one abstract-insufficient. 1989 crosslinking is suggestive, not conclusive.","key_references":[{"PMID":"2779654","why":"apoE liposome crosslinking to LRP"},{"PMID":"22622580","why":"APOE3 vs APOE4 LRP1 proximity ligation in pericytes"},{"PMID":"31677479","why":"APOE-LRP1 pull-down in E14.5 brain"}],"covers":["LR000073","LR003622"]},"LR000076":{"pair":"APOE -> LRP8","headline":"Quantified binding of apoE particles to apoER2 (Kd in microg/mL) in cells; abstract level.","interaction_type":"direct binding","direction_and_effect":"POPC-apoE particles of apoE3, apoE4 and truncations bound tightly to apoER2 (Kd 12 +/- 3 to 19 +/- 4 microg/mL); apoE2 bound with reduced affinity (Kd = 31 +/- 5.3 microg/mL) [PMID:12950167]. BioGRID and IntAct record the interaction [DB:BioGRID] [DB:IntAct].","molecular_requirements":"The apoER2-binding domain maps to apoE residues 1-165 [PMID:12950167].","affinity_potency":[{"value":"Kd 12 +/- 3 to 19 +/- 4 microg/mL","assay":"binding of POPC-apoE particles (apoE3, apoE4, truncations)","system":"ldlA-7 and COS-M6 cells expressing apoER2","cite":"PMID:12950167"},{"value":"Kd = 31 +/- 5.3 microg/mL","assay":"POPC-apoE2 binding","system":"ldlA-7 and COS-M6 cells expressing apoER2","cite":"PMID:12950167"}],"species_and_systems":"Human apoE and human apoER2 in cell lines [PMID:12950167]. Human and mouse pairs are listed.","localisation_and_range":"ApoE flagged secreted, LRP8 transmembrane [flag]; UniProt calls LRP8 a cell surface receptor for apoE-containing ligands [DB:UniProt].","caveats":"Affinities are in microg/mL on lipid particles, not molar. Two papers abstract-insufficient.","key_references":[{"PMID":"12950167","why":"apoER2 binding of apoE isoforms and domains"}],"covers":["LR000076","LR003625"]},"LR002155":{"pair":"APP -> APLP2","headline":"APP-APLP2 association shown by FRET and co-IP in cis on the same membrane; a family interaction, not classical signalling.","interaction_type":"direct binding","direction_and_effect":"APP and APLP2 formed heterotypic cis interactions (same membrane) detected by FRET and co-immunoprecipitation; coexpression with APP diminished Abeta42 generation [PMID:19126676]. The trans (cell-cell) interaction was seen only for APLP1, not for APP or APLP2 [PMID:19126676].","molecular_requirements":"The N-terminal half of the ectodomain is crucial for the interaction [PMID:19126676].","affinity_potency":[],"species_and_systems":"Human proteins in cell imaging [PMID:19126676]. Mouse pair is ortholog-inferred.","localisation_and_range":"Both partners flagged secreted and receptor; the evidence is cis, same-membrane [flag] [PMID:19126676].","caveats":"Abstract only. Cis association is not a classical secreted ligand to receptor signalling event; direction not applicable.","key_references":[{"PMID":"19126676","why":"APP family cis interactions by FRET and co-IP"}],"covers":["LR002155","LR005470"]},"LR003631":{"pair":"APP -> GPC1","headline":"Glypican-1 binds fibrillar amyloid-beta via heparan sulfate chains; this is not evidence that APP itself is a GPC1 ligand.","interaction_type":"direct binding","direction_and_effect":"Glypican-1 binds fibrillar Abeta, mainly through its heparan sulfate chains [PMID:15084524]. Co-overexpression of glypican-1 and APP in SH-SY5Y cells reduced viability and increased susceptibility to thapsigargin stress and Abeta toxicity [PMID:15084524].","molecular_requirements":"Binding is mainly mediated by the HS chains, so a glycosaminoglycan rather than the core protein [PMID:15084524]. No signalling partners reported.","affinity_potency":[],"species_and_systems":"Human brain tissue, detergent-insoluble glycosphingolipid-enriched (DIG) membrane fractions and SH-SY5Y cells [PMID:15084524]. Mouse pair is ortholog-inferred.","localisation_and_range":"Glypican-1 is localised in DIG domains and in primitive and classic plaques [PMID:15084524]; GPC1 is flagged secreted and receptor [flag].","caveats":"One paper, abstract only. The ligand tested is fibrillar Abeta, not APP. IntAct lists a surface plasmon resonance array record for APP-GPC1 [DB:IntAct]. Affinity not reported in our evidence.","key_references":[{"PMID":"15084524","why":"Glypican-1 binds fibrillar Abeta via HS chains"}],"covers":["LR000082","LR003631"]},"LR009211":{"pair":"APP -> NGFR","headline":"Two papers show APP-p75NTR interaction; one concerns the Abeta peptide, the other cis trafficking regulation.","interaction_type":"conflicting","direction_and_effect":"Amyloid beta bound p75NTR trimers and monomers and activated c-Jun signalling, but not p140trkA [PMID:11756426]. In a second paper APP interacted with p75NTR by co-IP and increased its cell-surface level; APP loss increased receptor endocytosis [PMID:24224055].","molecular_requirements":"Abeta binds both trimeric and monomeric p75NTR [PMID:11756426].","affinity_potency":[],"species_and_systems":"Rat E17 cortical neurons and NIH-3T3 transfectants for Abeta binding [PMID:11756426]; co-IP and APP knockdown in MEFs, PC12 and rat neurons for the second paper [PMID:24224055]. Both abstract/curation records list human ligand.","localisation_and_range":"APP and NGFR are both membrane proteins [flag]; the trafficking paper suggests a possible cis interaction [PMID:24224055].","caveats":"The first paper's ligand is the Abeta fragment, not APP itself, and was read as an abstract only [PMID:11756426]. The second paper's curator evidence sentence is a section heading. BioGRID and IntAct also record this pair [DB:BioGRID] [DB:IntAct].","key_references":[{"PMID":"11756426","why":"Abeta binding to p75NTR trimers and monomers"},{"PMID":"24224055","why":"APP interacts with p75NTR and regulates its surface levels"}],"covers":["LR009211"]},"LR002164":{"pair":"APP -> NOTCH1","headline":"Co-immunoprecipitation only; secondary finding in an abstract-read paper focused on Notch2.","interaction_type":"direct binding","direction_and_effect":"Notch1 co-immunoprecipitated with APP, suggesting cross-talk between APP and Notch family members [PMID:16118793]. Effect and direction not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human HEK293 cells expressing APP751 and rat primary neurons for the screen [PMID:16118793]; mouse pair is ortholog-inferred.","localisation_and_range":"Both flagged as transmembrane [flag]; APP and Notch2 colocalised on the plasma membrane in COS cells [PMID:16118793].","caveats":"Abstract only; the Notch1 result is secondary to Notch2. BioGRID lists Notch1-APP affinity capture-Western [DB:BioGRID].","key_references":[{"PMID":"16118793","why":"APP-Notch interaction by co-IP"}],"covers":["LR002164","LR005479"]},"LR000085":{"pair":"ARTN -> GFRA1","headline":"Artemin can activate the GFRalpha1-RET complex as an alternative to its preferred GFRalpha3-RET; abstract-level functional evidence.","interaction_type":"functional only","direction_and_effect":"Artemin can activate the GFRalpha1-RET complex and support survival of dopaminergic midbrain neurons in culture [PMID:9883723].","molecular_requirements":"RET is the signalling component with a GFRalpha binding component [PMID:9883723]; GFRA1 alone is not tested separately. Reactome lists RET:GFRA1,GFRA3:ARTN [DB:Reactome].","affinity_potency":[],"species_and_systems":"Cultured neurons; species not specified in the abstract [PMID:9883723].","localisation_and_range":"ARTN flagged secreted [flag].","caveats":"Abstract only; preferred receptor is GFRalpha3-RET, so GFRA1 is a secondary receptor. No direct binding or affinity reported.","key_references":[{"PMID":"9883723","why":"Artemin identification and receptor usage"}],"covers":["LR000085","LR003634"]},"LR000094":{"pair":"AVP -> AVPR1A","headline":"Well supported direct binding and agonism of vasopressin at the V1a receptor, with consistent nanomolar affinity in human recombinant systems.","interaction_type":"direct binding","direction_and_effect":"AVP binds the V1a receptor as a full agonist; GtoPdb lists Type=Agonist, Action=Full agonist [DB:GtoPdb]. AVP raised [Ca2+]i in V1A-expressing cells [PMID:9459574]. Replacing aromatic TM VI residues did not change AVP binding but increased AVP-induced G protein coupling efficacy [PMID:10866830]. A photoreactive antagonist labelled a region including transmembrane domain VII (Asn327-Lys370) [PMID:9334232].","molecular_requirements":"Single-chain GPCR; no co-receptor or extra subunit is reported in our evidence. Human V1a is degraded during incubation with the photoreactive ligand, giving a 46-kDa species lacking the N-terminal region [PMID:9334232].","affinity_potency":[{"value":"Ki 1.4 nmol/L","assay":"radioligand competition binding","system":"human receptor-transfected cell lines","cite":"PMID:10519430"},{"value":"Kd 0.67 nM","assay":"[3H]AVP saturation binding, Scatchard","system":"COS-1 cells expressing human V1A","cite":"PMID:9459574"},{"value":"Kd 0.39 nM","assay":"[3H]AVP saturation binding, Scatchard","system":"CHO cells expressing hV1A","cite":"PMID:9884074"}],"species_and_systems":"Mostly human receptor in transfected CHO, COS-1 or HeLa cells [PMID:9884074][PMID:9459574][PMID:10780976]. The rat hepatic V1a cDNA was also cloned and binds AVP with affinities similar to native rat V1a [PMID:1560825]. The mouse pair is projected from human evidence (ortholog-inferred); no mouse experiment is in the dossier.","localisation_and_range":"AVP is flagged secreted and V1a as a transmembrane receptor [flag], so signalling is paracrine or endocrine.","caveats":"All papers were read as abstracts only. Several confirmed rows use V1a as a selectivity-panel comparator rather than a primary AVP finding, and one notes AVP affinity was not re-measured [PMID:16158071]. 7 further papers were judged abstract_insufficient.","key_references":[{"PMID":"8106369","why":"Cloning of human V1a; single high-affinity [3H]AVP site"},{"PMID":"9884074","why":"Kd of [3H]AVP at hV1A, hV1B, hV2 in CHO cells"},{"PMID":"9459574","why":"Kd of [3H]AVP and AVP-induced Ca2+ response in COS-1 cells"}],"covers":["LR000094","LR003643"]},"LR012019":{"pair":"BAMBI -> ACVR1:ACVR2A","headline":"BAMBI to ACVR1:ACVR2A has no verified paper; support is limited to one BioGRID record that names a different receptor chain pair.","interaction_type":"database-asserted only","direction_and_effect":"The pair is annotated as Inhibitory [flag]; no paper in our evidence confirms this direction. BioGRID lists BMPR1B-BAMBI: Reconstituted Complex [DB:BioGRID 726964].","molecular_requirements":"Complex members are ACVR1 and ACVR2A; the BioGRID record concerns BMPR1B only, which is not a member of this complex [DB:BioGRID 726964]. Subunit requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species of the BioGRID experiment is not given; the pair is human.","localisation_and_range":"Receptor complex is flagged transmembrane [flag]; BAMBI has no annotation flags for secretion.","caveats":"Judged papers were abstract_insufficient or different_entity, so no paper confirms it; the evidence rests on a single database record.","key_references":[],"covers":["LR012019"]},"LR012370":{"pair":"BAMBI -> FZD3:LRP6","headline":"Database-asserted only: a single IntAct coimmunoprecipitation record; no curator-verified paper for this pair.","interaction_type":"database-asserted only","direction_and_effect":"BAMBI is annotated as stimulatory toward this receptor complex [flag]. The only support is one IntAct coimmunoprecipitation record citing PMID 18838381 [DB:IntAct]. No verified paper for this pair is in our evidence; the one judged abstract was marked insufficient.","molecular_requirements":"Complex FZD3:LRP6 is annotated; LRP6 carries a transmembrane flag [flag]. Which subunit the IntAct record covers, and whether both are needed, is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human pair [flag]. IntAct method: anti tag coimmunoprecipitation [DB:IntAct]; cell system not reported in our evidence.","localisation_and_range":"Not reported in our evidence; BAMBI has no secreted or transmembrane flag in the dossier.","caveats":"Database support only, from one co-IP record. BAMBI is called a pseudoreceptor in the related paper title [PMID:18838381], so a ligand role is unclear. The same record is attached to several Frizzled:LRP6 pairs, so it does not distinguish between Frizzled paralogs.","key_references":[],"covers":["LR012370"]},"LR002173":{"pair":"BGLAP -> GPR37","headline":"Osteocalcin binds and activates GPR37 in HEK293 cells with Kd 14.1 +/- 1.8 nM; a mouse myelination phenotype supports it.","interaction_type":"direct binding","direction_and_effect":"Biotinylated osteocalcin bound GPR37, not GPR37L1, with a dissociation constant (Kd) of 14.1 \u00b1 1.8 nM; co-immunoprecipitation also showed direct interaction [PMID:34678058]. Osteocalcin triggered calcium rise, beta-arrestin recruitment (EC50 10.2 \u00b1 2.5 nM), reduced cAMP and raised ERK phosphorylation in GPR37-transfected cells, blocked by GPR37 antibody or pertussis toxin [PMID:34678058]. In mice, OCN deletion gave hypermyelination, so OCN via GPR37 restrains oligodendrocyte differentiation [PMID:34678058].","molecular_requirements":"Gi/o coupling indicated by pertussis toxin sensitivity [PMID:34678058]. No co-receptor reported in our evidence.","affinity_potency":[{"value":"Kd 14.1 \u00b1 1.8 nM","assay":"biotinylated OCN saturation binding","system":"GPR37-transfected HEK293 cells","cite":"PMID:34678058"},{"value":"EC50 10.2 \u00b1 2.5 nM","assay":"beta-arrestin recruitment (PRESTO-Tango)","system":"GPR37-transfected HTLA cells","cite":"PMID:34678058"}],"species_and_systems":"Human GPR37 overexpressed in HEK293-based cells; primary rat oligodendrocytes; OCN-knockout mice [PMID:34678058].","localisation_and_range":"Osteocalcin has a secreted flag [flag]; GPR37 is highly expressed in mature oligodendrocytes [PMID:34678058].","caveats":"Single paper (abstract plus full-text excerpts). Binding measured in overexpressing HEK293 cells. The curator effect label 'antagonist' conflicts with the paper, where OCN activates GPR37 signalling.","key_references":[{"PMID":"34678058","why":"OCN binds and activates GPR37 (Kd, EC50) and regulates myelination"}],"covers":["LR002173","LR005487"]},"LR001660":{"pair":"BGN -> FGFR3","headline":"Cell-free experiments show biglycan binds FGFR3c; one abstract-only paper, and signalling effect is only proposed.","interaction_type":"direct binding","direction_and_effect":"Experiments in a cell-free system confirmed that BGN binds FGFR3c and FGF1 [PMID:25260943]. The authors postulate that BGN, secreted by peritubular cells, modulates FGFR3c signalling [PMID:25260943]; the direction (activating or inhibitory) was not tested in our evidence.","molecular_requirements":"The FGFR3c mesenchymal splice isoform is studied; BGN has a sequence homologous to the FGFR3c-binding site on FGF1 [PMID:25260943].","affinity_potency":[],"species_and_systems":"Human testis (expression) and a cell-free binding system; abstract-only [PMID:25260943].","localisation_and_range":"BGN has a secreted flag [flag]; proposed paracrine action from peritubular cells to adjacent spermatogonia [PMID:25260943].","caveats":"Abstract-only; no affinity values; BGN binds FGF1 too, so it may act through FGF1 rather than as a direct agonist. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"25260943","why":"BGN binds FGFR3c in a cell-free system"}],"covers":["LR001660","LR005046"]},"LR007114":{"pair":"BMP2 -> BMPR1A:BMPR2","headline":"Type I half is directly supported; BMPR2 chain evidence is functional (hMSC knockdown) and database-based.","interaction_type":"direct binding","direction_and_effect":"siRNA knockdown in primary human MSCs showed osteoinductive BMP activity is elicited through BMPR1A and BMPR2 among other receptors; recorded as agonist [PMID:18436533]. GtoPdb lists BMP2 as agonist at BMPR1A and at BMPR2 [DB:GtoPdb].","molecular_requirements":"BMP2-BMPR1A binding is shown by structure, mutagenesis and gel filtration, with the BMPR2 chain not part of those complexes [PMID:10881198][PMID:10692589][PMID:15064755]. The L51P variant kept type II receptor binding, unnamed [PMID:15064755]. BMP-2/4 relied more on BMPR2 than BMP-6/7, and mainly on BMPR1A as type I [PMID:18436533]. UniProt: BMP2 associates with BMPR1A and BMPR2 [DB:UniProt]; BioGRID has BMP2-BMPR2 records [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Human proteins and human primary MSCs [PMID:18436533][PMID:10881198][PMID:10692589].","localisation_and_range":"BMP2 is flagged secreted and not transmembrane, and the receptor complex is flagged transmembrane (annotation flags), so signalling is paracrine/juxtacrine from a secreted ligand to a cell-surface receptor [flag].","caveats":"All four papers were read as abstracts only. None shows the BMPR1A:BMPR2 heteromer binding BMP2 directly; BMPR2 is inferred in 15064755 and absent from the other structural papers. Five further papers were review-only.","key_references":[{"PMID":"18436533","why":"names both BMPR1A and BMPR2 as required in hMSC"},{"PMID":"10881198","why":"structure of BMP-2 with BRIA ectodomains"},{"PMID":"15064755","why":"BMP-2/BRIA interface mutagenesis"}],"covers":["LR007114"]},"LR007123":{"pair":"BMP5 -> ACVR1:ACVR2B","headline":"BMP5 to ACVR1:ACVR2B rests on a GtoPdb agonist assertion only; no verified paper in our evidence.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP5 as agonist (Stimulatory) on the receptor chain(s) [DB:GtoPdb].","molecular_requirements":"Chains in the complex: ACVR1 and ACVR2B; whether both are required or either alone suffices is not reported in our evidence. The pair is a complex; the database rows are per chain, not for the assembled complex, and not every chain has UniProt support.","affinity_potency":[],"species_and_systems":"Experimental species and system not reported in our evidence; the pair is annotated human.","localisation_and_range":"BMP5 is flagged secreted and not transmembrane [flag], so signalling would be paracrine or endocrine; the receptor's localisation is not reported in our evidence.","caveats":"No curator-confirmed paper. Screened papers: 3 review_only, 3 abstract_insufficient. GtoPdb entries show no affinity ('Affinity Units=-') [DB:GtoPdb].","key_references":[],"covers":["LR007123"]},"LR002182":{"pair":"BMP5 -> RGMA","headline":"BMP5 binds RGMA in SPR with Kd 83 nM; single paper, human/human labels, abstract-level curation.","interaction_type":"direct binding","direction_and_effect":"RGMA is an RGM-family BMP co-receptor; curators label the effect agonist [PMID:23029472]. RGMA showed lower affinity than HJV (17 nM) and RGMB (33 nM) for BMP5 [PMID:23029472].","molecular_requirements":"Not reported in our evidence for this pair (no co-receptor or complex requirement tested for BMP5 in the excerpts).","affinity_potency":[{"value":"Kd 83 nM","assay":"SPR","system":"RGMA vs BMP5, mean of 4-9 experiments","cite":"PMID:23029472"}],"species_and_systems":"Curators label both partners human; SPR with recombinant proteins, 4-9 experiments per interaction [PMID:23029472]. Mouse pair is projected from human evidence.","localisation_and_range":"BMP5 is flagged secreted and not transmembrane [flag], so signalling would be paracrine or endocrine. RGMA is flagged secreted [flag].","caveats":"One paper, read as an abstract by the curators with full-text excerpts available. No functional assay for BMP5 with this receptor is shown in the excerpts. None of the RGMs bound BMP9 [PMID:23029472].","key_references":[{"PMID":"23029472","why":"SPR affinity matrix of RGMs for BMP ligands"}],"covers":["LR002182","LR005496"]},"LR007132":{"pair":"BMP6 -> ACVR1:ACVR2B","headline":"BMP6 with ACVR1:ACVR2B is backed by a cryo-EM structure of ALK2-ActRIIB bound to BMP6, plus UniProt, BioGRID and GtoPdb records.","interaction_type":"direct binding","direction_and_effect":"A PDB cryo-EM structure shows ALK2-ActRIIB bound to BMP6 [DB:PDB 9N4K][PMID:40854140]. UniProt says BMP6 associates with type I receptor ACVR1 and type II receptor ACVR2B, and that ACVR2B interacts with BMP6 [DB:UniProt][PMID:18070108]. GtoPdb lists agonist at both chains [DB:GtoPdb].","molecular_requirements":"Both chains appear in the structure (a chain of P22004 and a chain of Q13705, per the PDB record) [DB:PDB 9N4K]; whether either chain alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Structure by electron microscopy; BioGRID also has an affinity-capture-Western record of ACVR2B-BMP6 from a 1999 paper [DB:BioGRID][PMID:10504300]. Species not reported in our evidence beyond human annotation.","localisation_and_range":"BMP6 is flagged secreted and the complex transmembrane [flag].","caveats":"No verified paper row (3 review_only papers). The structure's paper abstract is not in our dossier.","key_references":[],"covers":["LR007132"]},"LR000139":{"pair":"BMP7 -> ACVR1","headline":"Direct binding of BMP7 (OP-1) to ALK-2/ACVR1 shown in 1994, supported by functional papers and database records.","interaction_type":"direct binding","direction_and_effect":"OP-1 (BMP-7) bound ALK-2 efficiently [PMID:8006002]. In endogenous signalling, BMP7's major type I receptor was ALK2, and ALK2 mediated BMP7 but not activin signalling, with Smad1/5 phosphorylation [PMID:9748228]. Curated effect is agonist; GtoPdb lists BMP7 as agonist at ACVR1 [DB:GtoPdb]. Intact ACVR1-R206H (an FOP mutant) responded to Bmp7 and Activin A [PMID:32897189].","molecular_requirements":"ALK-2 is reported as a type I receptor shared by activin and OP-1 but not by BMP-4; binding was enhanced by a co-transfected type II receptor [PMID:8006002]. BMP7 and activin share type II receptors ActRII/ActRIIB but recruit distinct type I receptors [PMID:9748228]. UniProt describes ACVR1 as type I partner with type II ACVR2A [DB:UniProt].","affinity_potency":[],"species_and_systems":"Binding in transfected COS cells and various non-transfected lines, with cell-type dependent profiles [PMID:8006002]. Signalling in P19 cells [PMID:9748228]. The 2020 paper used zebrafish embryos with mouse ACVR1 and an FOP mutant receptor [PMID:32897189]. Curators recorded human experiment species for most rows, and a mouse receptor in PMID:11282024; human and mouse pairs are both listed, neither ortholog-inferred.","localisation_and_range":"BMP7 is flagged as secreted [flag], so action would be paracrine or endocrine; the receptor is flagged as a transmembrane receptor [flag].","caveats":"Most papers were read as abstracts only. PMID:11282024 states ALK-2 preference as background; its own data concern downstream Smad specificity [PMID:11282024]. PMID:32897189 concerns a mutant receptor, not wild-type binding. No affinity value reported.","key_references":[{"PMID":"8006002","why":"Direct binding of OP-1/BMP-7 to ALK-2"},{"PMID":"9748228","why":"ALK2 is the major BMP7 type I receptor; distinct from activin's ALK4"},{"PMID":"32897189","why":"FOP-mutant ACVR1 responds to Bmp7 in zebrafish"}],"covers":["LR000139","LR003688"]},"LR007141":{"pair":"BMP7 -> ACVR1:ACVR2B","headline":"Complex pair supported by database records only; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP7 as agonist at ACVR1 and ACVR2B [DB:GtoPdb]. UniProt says BMP7 associates with type I receptor ACVR1 and type II receptor ACVR2A [DB:UniProt]; ACVR2B is not named there.","molecular_requirements":"BioGRID records BMP7-ACVR2B affinity capture-western [DB:BioGRID]. Whether both chains act together is not shown in our evidence.","affinity_potency":[],"species_and_systems":"Species of the database experiments is not reported in our evidence.","localisation_and_range":"BMP7 is flagged as secreted [flag], so action would be paracrine or endocrine; the receptor is flagged as a transmembrane receptor [flag].","caveats":"No paper was judged (three review-only). The UniProt function text names ACVR2A, not ACVR2B.","key_references":[],"covers":["LR007141"]},"LR007150":{"pair":"BMP8A -> ACVR1:ACVR2B","headline":"BMP8A -> ACVR1:ACVR2B: the mouse paper supports ACVR2B but does not name ACVR1; GtoPdb lists both chains.","interaction_type":"functional only","direction_and_effect":"The verified paper shows BMP8A signalling through ACVR2B, paired with ALK5, in mouse spermatogonia [PMID:28465413]. GtoPdb lists BMP8A as agonist at ACVR1 and ACVR2B [DB:GtoPdb].","molecular_requirements":"ACVR1 plus ACVR2B as a pair is not shown; ACVR2B acts with ALK5 [PMID:28465413].","affinity_potency":[],"species_and_systems":"Undifferentiated mouse spermatogonia and cultured mouse testis explants; abstract-only read; the human pair is listed without ortholog inference but the experiments were mouse [PMID:28465413].","localisation_and_range":"BMP8A is flagged secreted [flag]; the abstract does not state range of action.","caveats":"ACVR1 rests on a GtoPdb record only. Three papers were review-only. Evidence is functional, abstract-level.","key_references":[{"PMID":"28465413","why":"BMP8A signals through SMAD1/5/8 and SMAD2/3 receptor complexes in mouse spermatogonia"}],"covers":["LR007150"]},"LR009040":{"pair":"BMP8A -> BMPR1B","headline":"BMP8A -> BMPR1B rests on a zebrafish Alk6a interaction abstract plus a GtoPdb agonist record.","interaction_type":"functional only","direction_and_effect":"Zebrafish study: Bmp8a interacts with Alk6a, promoting Tbk1 and Irf3 phosphorylation through p38 MAPK and type I interferon production on viral infection [PMID:33750893]. GtoPdb lists an agonist record [DB:GtoPdb].","molecular_requirements":"Alk6a alone is named; type II partners are not reported in our evidence.","affinity_potency":[],"species_and_systems":"bmp8a-/- zebrafish infected with viruses; abstract-only read; a non-human system [PMID:33750893].","localisation_and_range":"BMP8A is flagged secreted [flag]; the abstract does not state range of action.","caveats":"The curators label the evidence direct binding but the abstract says only 'interacts' and gives no binding assay. The dossier maps zebrafish Alk6a onto this human receptor, which the abstract does not do. Abstract only.","key_references":[{"PMID":"33750893","why":"Bmp8a-Alk6a interaction in zebrafish antiviral immunity"}],"covers":["LR009040"]},"LR005503":{"pair":"BPI -> GPC4","headline":"BPI binds glycan-dependent GPC4 on bovine retinal pigment epithelium by affinity chromatography; one abstract-level paper, hedged as 'putative'.","interaction_type":"direct binding","direction_and_effect":"BPI acts as an agonist at the pair: heparitinase, PI-specific phospholipase C and anti-GPC4 antibody suppressed BPI-induced ERK and Akt phosphorylation, and heparitinase inhibited BPI effects on VEGF and PDGF-B mRNA [PMID:18055828].","molecular_requirements":"GPC4 was identified as the BPI-binding 36-kDa band; the effect of heparitinase and PI-PLC suggests a heparan sulfate-bearing, GPI-anchored form is needed. Co-receptors are not reported in our evidence [PMID:18055828].","affinity_potency":[],"species_and_systems":"Human rBPI(21) on bovine retinal pigment epithelial membranes; the human-mouse projection is ortholog-inferred, not experimental [PMID:18055828].","localisation_and_range":"Both entities are flagged is_secreted [flag]; the paper describes GPC4 as a cell-surface protein [PMID:18055828], so membrane-bound presentation is likely.","caveats":"Binding is described with the hedge 'putative' and rests on affinity chromatography plus mass spectrometry; abstract only; no affinity reported [PMID:18055828].","key_references":[{"PMID":"18055828","why":"Affinity-column pull-down and functional blockade identifying GPC4 as a BPI-binding protein."}],"covers":["LR002189","LR005503"]},"LR002191":{"pair":"BSG -> GP6","headline":"BSG (EMMPRIN) binds platelet GPVI directly, with a Kd of 88 nM by SPR and functional rolling assays, from one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"EMMPRIN-Fc supports rolling (not firm adhesion) of ADP-stimulated human platelets; blocking antibodies against EMMPRIN or GPVI reduce it, and GPVI-transfected CHO cells roll on EMMPRIN-Fc [PMID:19350111]. The curator labels GPVI the receptor and the effect agonist.","molecular_requirements":"GPVI alone in transfected CHO cells was sufficient for enhanced rolling on EMMPRIN-Fc; other co-receptors are not reported in our evidence [PMID:19350111].","affinity_potency":[{"value":"Kd 88 nM","assay":"ELISA and surface plasmon resonance, EMMPRIN binding to GPVI","system":"recombinant human proteins","cite":"PMID:19350111"}],"species_and_systems":"Human platelets, CHO transfectants and recombinant Fc fusions; ortholog-inferred mouse version [PMID:19350111].","localisation_and_range":"BSG is flagged transmembrane and not secreted [flag]; contact-mediated (rolling) interaction on platelets and cells [PMID:19350111].","caveats":"Abstract only; one paper. The reciprocal experiment (EMMPRIN-transfected cells on GPVI-Fc) is also reported [PMID:19350111].","key_references":[{"PMID":"19350111","why":"Rolling assays plus ELISA/SPR giving Kd 88 nM for EMMPRIN-GPVI."}],"covers":["LR002191","LR005505"]},"LR000148":{"pair":"BTC -> ERBB3","headline":"Mixed evidence: BTC does not bind ErbB3 alone, but BTC increases ErbB3 phosphorylation and EGFR-ErbB3 heterodimers.","interaction_type":"conflicting","direction_and_effect":"BTC treatment significantly increases ErbB3 phosphorylation and EGFR-ErbB3 heterodimers (phosphorylation and proximity ligation assay) [PMID:30249613]. In contrast, the earlier curated paper was judged to show the pair absent for ErbB3 alone [PMID:9312020].","molecular_requirements":"ErbB3 response depends on a partner: the 1997 data indicate ErbB2:ErbB3 binding but not either chain alone [PMID:9312020]; the 2018 data show EGFR-ErbB3 heterodimers [PMID:30249613].","affinity_potency":[],"species_and_systems":"Species not reported in our evidence for either paper.","localisation_and_range":"BTC is flagged secreted and transmembrane; ERBB3 transmembrane [flag].","caveats":"Both papers abstract-level. The positive result is functional (phosphorylation, proximity), not direct binding; the negative is a verified pair_absent.","key_references":[{"PMID":"30249613","why":"BTC increases ErbB3 phosphorylation and EGFR-ErbB3 heterodimers."},{"PMID":"9312020","why":"Verified negative: no BTC binding to ErbB3 alone."}],"covers":["LR000148"]},"LR005512":{"pair":"C1QA -> LAIR1","headline":"C1q engages LAIR-1 through its collagen-like region, binding human proteins and cells; supports an inhibitory signal.","interaction_type":"direct binding","direction_and_effect":"C1q collagen-like region engages and activates the inhibitory immunoreceptor LAIR-1 [PMID:28325905]. C1q cross-links CD33 and LAIR-1 on monocytes; the curator labels the effect antagonist (inhibitory) [PMID:28325905].","molecular_requirements":"The collagen-like region is the LAIR-1 binding part [PMID:28325905]. CD33 association is reported in monocytes [PMID:28325905].","affinity_potency":[],"species_and_systems":"Human monocytes and transfected HEK293T cells (slot blots of lysates) [PMID:28325905].","localisation_and_range":"C1q annotated secreted; LAIR1 annotated transmembrane [flag].","caveats":"The excerpts present the LAIR-1 binding as previously reported by the authors, so this paper adds dose-dependent binding in slot blot rather than new characterisation. No affinity reported. Two confirmed rows counted, one shown.","key_references":[{"PMID":"28325905","why":"C1q binding of LAIR-1 and CD33"}],"covers":["LR002198","LR005512"]},"LR002209":{"pair":"C1QC -> CD33","headline":"Assembled C1q binds CD33 on human monocytes and triggers its inhibitory signalling; one human paper, chain-level row.","interaction_type":"direct binding","direction_and_effect":"C1q treatment increased phosphorylated CD33 (2-5 fold versus controls, n >= 6), i.e. activation of CD33 inhibitory ITIM signalling in human monocytes; gC1q did the same, CLR did not [PMID:28325905].","molecular_requirements":"Whole C1q is required to crosslink CD33 and LAIR-1; the globular head (gC1q) binds CD33 while the collagen-like region (CLR) does not [PMID:28325905]. This row encodes one chain (C1QC) of the C1q complex; the paper used assembled C1q, so chain-alone sufficiency is not shown.","affinity_potency":[],"species_and_systems":"Human proteins and cells: slot blots with purified proteins, C1q binding to CD33-transfected HEK293T cells and lysates, immunoblots and proximity ligation assay in freshly isolated human monocytes [PMID:28325905]. IntAct lists a surface plasmon resonance record from the same paper [DB:IntAct].","localisation_and_range":"C1q is secreted (ligand flag) [flag]; CD33 acts on the monocyte surface, with C1q bridging CD33 and LAIR-1 on the same cell [PMID:28325905].","caveats":"Abstract-level curation, but full-text excerpts were available. Sialic acid masking of CD33 C2 domains reduces C1q-CD33 interaction [PMID:28325905]. Single paper; chain-level attribution (C1QC) is inherited from the complex.","key_references":[{"PMID":"28325905","why":"C1q binds CD33, activates its ITIM and crosslinks CD33/LAIR-1 on human monocytes"}],"covers":["LR002209"]},"LR005530":{"pair":"C1QL3 -> ADGRB3","headline":"C1QL3 binds ADGRB3 with high affinity and forms a proposed trans-synaptic complex with NPTX1/NPTXR; two abstract-level papers, one with excerpts.","interaction_type":"direct binding","direction_and_effect":"C1ql proteins decrease synapse density in cultured neurons, blocked by the BAI3 thrombospondin-repeat fragment [PMID:21262840]. A second paper reports that C1QL3 mediates a cell-cell adhesion complex involving ADGRB3 and neuronal pentraxins NPTX1 and NPTXR [PMID:33337553].","molecular_requirements":"Binding is via the globular C1q domain to the BAI3 thrombospondin-repeat domain [PMID:21262840]. C1QL3 co-precipitated NPTX1 and NPTXR, and gC1QL3 alone bound NPTX1, so C1QL3 may be part of a larger complex [PMID:33337553].","affinity_potency":[],"species_and_systems":"Species not stated in the 2011 abstract. The 2020 study used an in vivo interactome (mass spectrometry) and cortical single-cell RNA-Seq; the species is not stated in our excerpts. BioGRID lists Affinity Capture-MS and Reconstituted Complex [DB:BioGRID]; UniProt also [DB:UniProt].","localisation_and_range":"Presynaptically secreted C1QL3, NPTX1 and NPTXR are proposed to bind postsynaptic ADGRB3 across the synapse [PMID:33337553]; flags: ligand secreted, receptor transmembrane [flag].","caveats":"The trans-synaptic complex is a suggestion ('suggest the possibility'), not demonstrated. First paper covers all four C1ql proteins together; no affinity number.","key_references":[{"PMID":"21262840","why":"All four C1ql proteins bind the BAI3 thrombospondin-repeat domain with high affinity via the gC1q domain"},{"PMID":"33337553","why":"C1QL3 with NPTX1/NPTXR and ADGRB3 in a proposed trans-synaptic complex"}],"covers":["LR002217","LR005530"]},"LR002218":{"pair":"C1QL4 -> ADGRB3","headline":"C1QL4 binds the ADGRB3 (BAI3) thrombospondin-repeat domain with high affinity; one abstract-level paper plus UniProt.","interaction_type":"direct binding","direction_and_effect":"C1ql proteins bind BAI3 and decrease synapse density in cultured neurons, prevented by the soluble BAI3 thrombospondin-repeat fragment, which binds C1ql proteins and acts as a decoy [PMID:21262840].","molecular_requirements":"Binding is to the extracellular thrombospondin-repeat domain, via the ligand's globular C1q domain [PMID:21262840].","affinity_potency":[],"species_and_systems":"Species and cell system not stated in the abstract (curator labels human/human; both interactions ortholog-inferred). UniProt records the interaction [DB:UniProt].","localisation_and_range":"C1QL4 secreted and ADGRB3 transmembrane per flags [flag].","caveats":"Abstract only; the paper covers all four C1ql proteins collectively; no affinity number.","key_references":[{"PMID":"21262840","why":"All four C1ql proteins bind the BAI3 thrombospondin-repeat domain with high affinity via the gC1q domain"}],"covers":["LR002218","LR005531"]},"LR003703":{"pair":"C1QTNF5 -> MFRP","headline":"Binding of CTRP5 to MFRP rests on database records (co-IP, pull-down); the curated paper treats it as background.","interaction_type":"database-asserted only","direction_and_effect":"Direction not reported. In Mfrp(174delG) mutant mice, CTRP5 mRNA and protein were upregulated while MFRP was undetectable by Western blot [PMID:21810984].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse (Mfrp(174delG) mutant) in the paper [PMID:21810984]. IntAct lists co-immunoprecipitation and pull-down records (PMIDs 17122143, 24531000, 16600989) [DB:IntAct]; UniProt says CTRP5 interacts with MFRP [DB:UniProt]. Human pair ortholog-inferred.","localisation_and_range":"Ligand flagged secreted [flag]; MFRP flagged as receptor, topology not stated.","caveats":"The curated paper characterises a mouse mutant and describes the binding as established, not tested; the upregulation despite MFRP loss suggests regulation is not co-dependent. Abstract only. No affinity.","key_references":[{"PMID":"21810984","why":"Mouse Mfrp null model; CTRP5 upregulated (binding mentioned as background)"}],"covers":["LR000154","LR003703"]},"LR000157":{"pair":"C3 -> CR1","headline":"C3b binds CR1 (complement receptor 1); supported by mapping and functional papers plus database records.","interaction_type":"direct binding","direction_and_effect":"CR1 interacts with C3b, acting as a cofactor for factor I cleavage of C3b-like C3 [PMID:10382758]. Mutagenesis of C3 residues 727-767 affected sCR1 cofactor activity [PMID:9988761]. UniProt and Reactome record the interaction [DB:UniProt][DB:Reactome].","molecular_requirements":"The N-terminal CR1 SCR1-3 fragment kept C3b interaction and cofactor activity; SCR3 was key [PMID:10382758]. UniProt: C3 binds CR1 via Sushi 8 and 9 [DB:UniProt]. Binding assay surrogate was cofactor activity [PMID:9988761].","affinity_potency":[{"value":"IH50% 4.8 microM","assay":"inhibition of classical pathway haemolysis by SCR3","system":"recombinant CR1 SCR3 from E. coli","cite":"PMID:10382758"}],"species_and_systems":"Human proteins; recombinant CR1 fragments or soluble CR1 [PMID:10382758][PMID:9988761]. Mouse pair is ortholog-inferred.","localisation_and_range":"CR1 is a membrane receptor; contact-dependent by annotation [flag].","caveats":"Both papers read as abstracts; evidence is functional or mapping rather than isolated binding. The ligand is C3b/C3(H2O), not intact C3. The IH50% is an inhibitory potency, not a Kd. IntAct lists SPR records [DB:IntAct].","key_references":[{"PMID":"9988761","why":"C3 residues affecting CR1 cofactor activity"},{"PMID":"10382758","why":"CR1 SCR structure-activity for C3b interaction"}],"covers":["LR000157"]},"LR005053":{"pair":"C3 -> NRP1","headline":"NRP1 binds C3 fragments (C3d, iC3b) in one full-text paper; the C4d Kd is the only measured affinity.","interaction_type":"direct binding","direction_and_effect":"A cDNA library screen with C4d identified NRP1, which also strongly bound recombinant C3d and iC3b, but only weakly C3b [PMID:31572401]. A solid-phase assay with NRP1-Ig confirmed binding to immobilized split products [PMID:31572401].","molecular_requirements":"Binding maps to the NRP1 b1 domain per the curator's assay detail [PMID:31572401]. Co-receptors not reported.","affinity_potency":[{"value":"KD 0.71 \u03bcM","assay":"dose-dependent saturable binding of C4d (not C3 fragments)","system":"NRP1-expressing cells","cite":"PMID:31572401"}],"species_and_systems":"Human proteins; NRP1 expressed on monocyte-derived dendritic cells, not monocytes [PMID:31572401].","localisation_and_range":"NRP1 is flagged transmembrane and secreted [flag]; binds surface-deposited fragments (contact).","caveats":"The measured Kd is for C4d, not for C3 fragments. Ligand forms are C3d and iC3b, not intact C3; C3b bound only weakly.","key_references":[{"PMID":"31572401","why":"NRP1 as receptor for complement split products"}],"covers":["LR001676","LR005053"]},"LR000166":{"pair":"C4B -> CD46","headline":"CD46 binds C4b (C4B-derived) in domain-mapping work; supported by one 1991 abstract plus Reactome and UniProt.","interaction_type":"direct binding","direction_and_effect":"CD46 binds C4b and acts as a cofactor for its cleavage, protecting cells from complement injury [PMID:1717583]. This is a regulatory receptor role rather than classical signalling.","molecular_requirements":"SCR3 and SCR4 of CD46 were important for both C4b binding and cofactor activity; deleting SCR2 abolished C4b binding; SCR1 deletion reduced C4b binding efficiency [PMID:1717583].","affinity_potency":[],"species_and_systems":"Human proteins; ELISA with SCR deletion mutants [PMID:1717583]. Reactome and UniProt also list CD46 binding C4b [DB:Reactome] [DB:UniProt].","localisation_and_range":"CD46 is flagged transmembrane (membrane-bound, contact-dependent) [flag]; ligand is flagged secreted [flag].","caveats":"Paper read as abstract only. The ligand is the cleaved/activated form C4b, not intact C4B. No affinity reported in our evidence.","key_references":[{"PMID":"1717583","why":"SCR deletion mapping of CD46 binding to C4b"}],"covers":["LR000166"]},"LR003712":{"pair":"C4bp -> Lrp1","headline":"Mouse pair inferred from human data: C4BP alpha chains bind LRP1, which mediates C4BP clearance.","interaction_type":"direct binding","direction_and_effect":"Plasma C4BP and recombinant alpha-chain C4BP bound immobilized LRP by SPR; RAP, heparin and an anti-C4BP antibody inhibited binding. LRP acts as a catabolic receptor, not a signalling one [PMID:11705989].","molecular_requirements":"The alpha chains suffice (rC4BPalpha binds); LRP clusters II and IV each associated with rC4BPalpha [PMID:11705989].","affinity_potency":[],"species_and_systems":"SPR and fibroblast degradation used human-derived proteins; delayed clearance of C4BP upon RAP co-injection was seen in mice in vivo. The mouse pair here is ortholog-inferred [PMID:11705989].","localisation_and_range":"Not reported in our evidence beyond flags: C4bp secreted [flag]; clearance is endocytic.","caveats":"Abstract only. LRP-deficient fibroblasts showed 4-fold diminished degradation of 125I-rC4BPalpha [PMID:11705989]. The curated assay_class for the mouse row is functional_in_vitro while the paper is also direct binding.","key_references":[{"PMID":"11705989","why":"SPR binding, cellular degradation and mouse clearance"}],"covers":["LR003712"]},"LR002227":{"pair":"CADM1 -> CADM4","headline":"Direct heterophilic CADM1-CADM4 binding by SPR, with a cell-spreading readout; single primary paper.","interaction_type":"direct binding","direction_and_effect":"CADM1-Fc bound CADM4 in SPRi, an interaction the paper calls new [PMID:30131958]. ATN1 adult T-cell leukemia cells spread on CADM4-Fc-coated glass; CADM1 knockdown or a neutralizing anti-CADM1 antibody blocked spreading, so CADM1 on the cell engages CADM4 [PMID:30131958]. Adhesion rather than classical agonism.","molecular_requirements":"Whole ectodomains were used; no co-receptor or extra subunit is reported as required. SPRi detects only direct two-molecule binding [PMID:30131958].","affinity_potency":[{"value":"Kd 192.7 nM","assay":"SPRi, CADM1-Fc analyte on immobilised CADM4-Fc","system":"purified Fc fusions from 293-F cells","cite":"PMID:30131958"}],"species_and_systems":"Human proteins; recombinant SPRi, 293FT co-culture immunoprecipitation (CADM4-FLAG with CADM1-GFP) and ATN1 cell assays [PMID:30131958]. Mouse pair is projected from human.","localisation_and_range":"Both partners are flagged membrane-bound, not secreted [flag]; this fits contact-dependent (juxtacrine) signalling, with trans interaction between neighbouring cells shown by co-culture immunoprecipitation [PMID:30131958].","caveats":"Single paper. The curated sentence here is abstract-level; the full-text excerpts support it. The paper notes earlier affinity chromatography and cell-adhesion studies did not detect this interaction, and suggests it may give weak adhesion [PMID:30131958]. Weakest affinity of the CADM1 partners tested.","key_references":[{"PMID":"30131958","why":"SPRi binding, Kd and cell-spreading assay"}],"covers":["LR002227","LR005537"]},"LR002236":{"pair":"CADM4 -> CADM3","headline":"CADM4 and CADM3 interact by SPRi (family-wide screen); direct binding, one paper, no pair-specific affinity.","interaction_type":"direct binding","direction_and_effect":"SPRi detected homophilic and heterophilic interactions of CADM2, CADM3 and CADM4 with all CADM family proteins [PMID:30131958]. No functional effect or direction is reported for this pair.","molecular_requirements":"SPRi only detects direct two-molecule interactions [PMID:30131958]. No accessory subunit reported.","affinity_potency":[],"species_and_systems":"Recombinant Fc-fusion ectodomains in SPRi (human proteins) [PMID:30131958]. Mouse pair is projected from human evidence (ortholog_inferred), not tested.","localisation_and_range":"Both flagged transmembrane [flag]; adhesion between cells is described for the CADM family [PMID:30131958].","caveats":"Family-level statement from a single paper; the tabulated Kd values are for CADM1 only. CADM3 interactions with Nectins 1 and 3 were not detected by SPRi, though reported elsewhere [PMID:30131958]. Affinity for CADM4-CADM3 not reported in our evidence.","key_references":[{"PMID":"30131958","why":"SPRi screen of CADM-family pairwise interactions, with Kd table and cell assays"}],"covers":["LR002236","LR005546"]},"LR000175":{"pair":"CALCB -> CALCRL","headline":"beta-CGRP acts through CALCRL in complex with RAMP1; support is functional and from GtoPdb, with CALCRL alone not sufficient.","interaction_type":"functional only","direction_and_effect":"CALCRL associated predominantly with RAMP1 to form a CALCB receptor in rat uterine artery smooth muscle cells, and only minimally with RAMP2 or RAMP3; CALCB increased ERK1/2 phosphorylation and reversed TNF-alpha-induced loss of CALCRL/RAMP1 association [PMID:27784654]. CRLR acts as a CGRP receptor when paired with RAMP1 [PMID:9620797]. GtoPdb lists full agonist [DB:GtoPdb].","molecular_requirements":"CALCRL needs a RAMP; RAMP1 gives the CGRP receptor, RAMP2 an adrenomedullin receptor [PMID:9620797][PMID:27784654]. CALCRL alone is not a CGRP receptor in this evidence.","affinity_potency":[{"value":"pKi 7.3 to 7.7","assay":"GtoPdb agonist record","system":"database record","cite":"DB:GtoPdb"},{"value":"pIC50 7.0 to 7.5","assay":"GtoPdb agonist record","system":"database record","cite":"DB:GtoPdb"}],"species_and_systems":"Rat uterine artery smooth muscle cells with proximity ligation assay [PMID:27784654]; [PMID:9620797] used transfected mammalian cells, species unspecified. Mouse and human pairs are projected from other evidence.","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Both papers read as abstracts (the first with full-text excerpts). Experimental species is rat, not human, although the curator table says human [PMID:27784654]. [PMID:9620797] does not name CALCB specifically, only CGRP.","key_references":[{"PMID":"27784654","why":"CALCB with CALCRL/RAMP1 in rat uterine artery cells"},{"PMID":"9620797","why":"RAMP1 makes CRLR a CGRP receptor"}],"covers":["LR000175","LR003720"]},"LR003721":{"pair":"CALCB -> RAMP1","headline":"beta-CGRP acts at CALCRL/RAMP1 receptors; RAMP1 is a subunit, with one functional paper and database records.","interaction_type":"functional only","direction_and_effect":"CALCRL predominantly associates with RAMP1 to form a CALCB receptor in rat uterine artery smooth muscle cells; CALCB reversed TNF-alpha-induced loss of CALCRL/RAMP1 association via ERK1/2 [PMID:27784654]. GtoPdb lists full agonist [DB:GtoPdb].","molecular_requirements":"Receptor is the CALCRL:RAMP1 heterodimer [PMID:27784654][DB:UniProt]; RAMP1 alone is not shown to bind CALCB.","affinity_potency":[{"value":"pKi 9.9 to 11.0","assay":"GtoPdb agonist record","system":"database record","cite":"DB:GtoPdb"}],"species_and_systems":"Rat uterine artery smooth muscle cells, proximity ligation assay [PMID:27784654]. Mouse pair is projected from human evidence.","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Only one confirmed paper, read as abstract with full-text excerpts; it concerns CALCRL/RAMP1 association, not CALCB binding to RAMP1. Curator table lists human, but the cells were rat.","key_references":[{"PMID":"27784654","why":"CALCB engages the CALCRL/RAMP1 receptor in rat cells"}],"covers":["LR000176","LR003721"]},"LR002245":{"pair":"CBLN1 -> NRXN3","headline":"CBLN1 signals with NRXN3 splice variant in cerebellum; UniProt notes only weak binding to one isoform.","interaction_type":"conflicting","direction_and_effect":"In cerebellum, Nrxn3SS4+-Cbln1 signalling regulated AMPA-receptors, whereas Nrxn1SS4+-Cbln1 had no manifest effect [PMID:36205393].","molecular_requirements":"Splice variant matters: the SS4+ form of Nrxn3 is used, and UniProt says Cbln1 weakly interacts with the NRXN3 short isoform and not at all with the long isoform [DB:UniProt].","affinity_potency":[],"species_and_systems":"Mouse genetic models (conditional and constitutive knockouts) in cerebellum and brain slices [PMID:36205393]; curators recorded human.","localisation_and_range":"CBLN1 is flagged secreted and NRXN3 transmembrane [flag].","caveats":"The paper's headline sentence is about Cbln2; the Cbln1 result is a secondary finding. Binding between CBLN1 and NRXN3 is weak or isoform-dependent per UniProt. Abstract only. A second confirmed paper was not shown.","key_references":[{"PMID":"36205393","why":"Nrxn3SS4+-Cbln1 regulates AMPA receptors in cerebellum"}],"covers":["LR002245","LR005555"]},"LR000184":{"pair":"CCL11 -> CCR2","headline":"Conflicting reports: CCL11 (eotaxin) antagonizes CCR2 in one study and acts as an agonist in another; abstract-only evidence.","interaction_type":"conflicting","direction_and_effect":"Eotaxin did not trigger CCR2 even at 1 microM, displaced 125I-MCP-1 and inhibited MCP-1-induced chemotaxis, so is a CCR2 antagonist [PMID:11264152]. A second study states eotaxin-1 acts as a CCR2 agonist and eotaxin-3 as an antagonist [PMID:15207250]. GtoPdb lists a partial agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"pIC50 7.1-7.7","assay":"GtoPdb record","system":"database","cite":"PMID:15207250"}],"species_and_systems":"Human monocytes and transfected cells [PMID:11264152]; CHO cell lines expressing CCR2 [PMID:15207250]. Mouse pair is projected.","localisation_and_range":"CCL11 flagged secreted, CCR2 transmembrane [flag].","caveats":"The two papers disagree on agonism versus antagonism; abstracts only. Eotaxin triggered CCR5 at 100 nM [PMID:11264152].","key_references":[{"PMID":"11264152","why":"Eotaxin as CCR2 antagonist and CCR5 agonist"},{"PMID":"15207250","why":"CHO lines: eotaxin-1 agonist of CCR2"}],"covers":["LR000184","LR003729"]},"LR003730":{"pair":"CCL11 -> CCR3","headline":"CCL11 (eotaxin) binds CCR3 with sub-nanomolar Kd and acts as an agonist; strongly supported by binding and functional papers.","interaction_type":"direct binding","direction_and_effect":"CCL11 is an agonist of CCR3: it drives eosinophil and basophil chemotaxis through CCR3 [PMID:9276730][PMID:9005985]. GtoPdb lists a full agonist [DB:GtoPdb]. A structural paper reports eotaxin binds only CCR3 among the receptors compared [PMID:9712872].","molecular_requirements":"CCR3 alone expressed in cells is sufficient for binding and signalling in the transfectant studies; no co-receptor requirement is reported in our evidence [PMID:8642344][PMID:8676064].","affinity_potency":[{"value":"Kd 0.1 nM","assay":"radioligand binding","system":"human CCR3 stably expressed in AML14.3D10 cells","cite":"PMID:8642344"},{"value":"IC50 7.6 nM","assay":"competition of CCL11 binding by antagonist YM-355179","system":"CCR3-expressing B300-19 cells","cite":"PMID:16339911"}],"species_and_systems":"Human ligand and receptor in transfected cells and primary human eosinophils and basophils [PMID:8642344][PMID:9005985][PMID:9276730]. The dossier also covers a mouse pair, which is not ortholog-inferred, but the cited experiments are human.","localisation_and_range":"Secreted ligand, transmembrane receptor [flag]: paracrine signalling by annotation.","caveats":"Most papers were read as abstracts only. CCL11 also binds other receptors (see CCR5 and CXCR3 pairs); CCR3 binds other chemokines such as RANTES and MCP-3 [PMID:8642344].","key_references":[{"PMID":"8642344","why":"Cloning of CCR3 with eotaxin Kd 0.1 nM"},{"PMID":"8676064","why":"CKR-3 transfectants bind radiolabelled eotaxin with high affinity"},{"PMID":"9005985","why":"More than 95% of eosinophil response to eotaxin via CCR3"}],"covers":["LR000185","LR003730"]},"LR002254":{"pair":"CCL13 -> ACKR1","headline":"CCL13 binds the Duffy antigen (ACKR1) with a Ki of 32.8 nM on human erythrocytes; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Binding only; ACKR1 is a chemokine-binding receptor and signalling is not reported in our evidence [PMID:15358176].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Ki 32.8 nM","assay":"125I-CXCL8 displacement binding","system":"human erythrocytes","cite":"PMID:15358176"}],"species_and_systems":"Human erythrocytes, native receptor [PMID:15358176].","localisation_and_range":"Secreted ligand, transmembrane receptor [flag].","caveats":"Only one paper; the paper classes Ki below 100 nM as strong binding. Radioligand is CXCL8, so this is competition, not direct labelling of CCL13.","key_references":[{"PMID":"15358176","why":"Duffy antigen chemokine binding profile"}],"covers":["LR002254"]},"LR000193":{"pair":"CCL13 -> CXCR3","headline":"MCP-4 competes with IP10 for CXCR3 binding with moderate affinity; agonism is not shown.","interaction_type":"direct binding","direction_and_effect":"Several CC chemokines, particularly eotaxin and MCP-4, compete with moderate affinity for IP10 binding to CXCR3; agonism was not demonstrated [PMID:9660793]. GtoPdb labels it a full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"pKi 7.2","assay":"competition binding against IP10","system":"CXCR3-transfected cells","cite":"PMID:9660793"}],"species_and_systems":"Human, transfected cells [PMID:9660793].","localisation_and_range":"Secreted ligand, transmembrane receptor [flag].","caveats":"Related eotaxin work found it blocks rather than activates CXCR3 [PMID:9660793], so the record's Stimulatory label is unsupported. The pKi 7.2 appears under eotaxin in the same paper's abstract context and may not be CCL13-specific. One abstract-only paper.","key_references":[{"PMID":"9660793","why":"CC chemokines incl. MCP-4 compete at CXCR3"}],"covers":["LR000193"]},"LR005062":{"pair":"CCL17 -> ACKR2","headline":"CCL17 competes for ACKR2-mediated chemokine uptake; ACKR2 is a scavenger, with UniProt support.","interaction_type":"functional only","direction_and_effect":"Decoy/scavenger role: unlabeled CCL17 in 10-fold excess reduced CCL2 uptake by HEK-ACKR2 cells and trophoblasts [PMID:25297873]. UniProt lists CCL17 among ACKR2 chemokines [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human HEK-ACKR2 cells and primary human trophoblasts; mouse Ackr2 deficiency used elsewhere in the paper [PMID:25297873].","localisation_and_range":"Secreted ligand and transmembrane receptor according to entity annotation flags [flag]; paracrine/endocrine range implied by the secreted flag only.","caveats":"Indirect evidence (competition of a CCL2 uptake assay), no direct binding or affinity; browser-read quote not spot-checked.","key_references":[{"PMID":"25297873","why":"Competition of ACKR2 uptake by CCL17"}],"covers":["LR001686","LR005062"]},"LR000238":{"pair":"CCL2 -> CCR4","headline":"Functional-only evidence: one abstract-read paper in a human melanoma-CTL migration model.","interaction_type":"functional only","direction_and_effect":"CTL migration toward tumour cells was mediated by CCR4 on the CTL and CCL2 secreted by tumour cells; blocking with CCL2 or anti-CCL2 or anti-CCR4 antibodies prevented migration, and anti-CCR4 inhibited migration toward isolated CCL2 in Transwell [PMID:16421945].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human melanoma patient CTL and autologous tumour cells; 3D organotypic culture and Transwell [PMID:16421945]. Both listed interactions are flagged ortholog-inferred.","localisation_and_range":"Ligand is flagged as secreted and not transmembrane [flag], so signalling is presumably paracrine or endocrine; receptor is flagged transmembrane [flag].","caveats":"No binding assay; antibody blockade only. One paper, abstract only. No database records.","key_references":[{"PMID":"16421945","why":"CCL2-CCR4-dependent CTL migration toward melanoma cells"}],"covers":["LR000238","LR003759"]},"LR000229":{"pair":"CCL28 -> ACKR2","headline":"No support for ACKR2: the verified paper shows CCL28 binds CCR10, and ACKR2 is never mentioned.","interaction_type":"conflicting","direction_and_effect":"Verified negative: CCL28 induced calcium mobilisation in CCR10 transfectants and desensitised CCL27 responses; ACKR2 is not mentioned [PMID:10781587]. A 2026 porcine study reports CCR10 only interacts with CCL28 and CCL28 is chemotactic for T cells [PMID:41860221].","molecular_requirements":"Not reported in our evidence for ACKR2.","affinity_potency":[],"species_and_systems":"Human and mouse CCR10 transfectants [PMID:10781587]; the 2026 study used porcine cells [PMID:41860221].","localisation_and_range":"Ligand flagged secreted, receptor flag [flag].","caveats":"The ACKR2 pairing appears to be a source mis-attribution. The confirmed 2026 row concerns CCR10 in pigs, not ACKR2. Abstracts only.","key_references":[{"PMID":"10781587","why":"CCL28 binds CCR10; no ACKR2 data"}],"covers":["LR000229"]},"LR002263":{"pair":"CCL28 -> ACKR5","headline":"CCL28 is bound and scavenged by GPR182 (proposed name ACKR5) in one in vitro/mouse paper; no signalling reported. Human pair is ortholog-inferred.","interaction_type":"direct binding","direction_and_effect":"GPR182 binds and efficiently scavenges CCL28; the paper reports no classical G-protein signalling on ligand stimulation, so this is a scavenging (atypical receptor) role rather than activation [PMID:37554323]. The curator label is 'agonist', which does not fit a scavenger receptor. UniProt says GPR182 is the only atypical receptor for CCL28 and CXCL13 [DB:UniProt].","molecular_requirements":"Beta-arrestins are required for ligand-independent internalisation and scavenging [PMID:37554323]. Other subunits or co-receptors: not reported in our evidence.","affinity_potency":[{"value":"Kd 28 nM","assay":"competition binding, mCCL28 on hGPR182","system":"cells expressing human GPR182","cite":"PMID:37554323"},{"value":"Kd 52 nM","assay":"competition scavenging, mCCL28 on hGPR182","system":"cells expressing human GPR182","cite":"PMID:37554323"}],"species_and_systems":"The curated human pair has no direct human-ligand experiment in our evidence: the affinities above used mouse CCL28 on human GPR182, and mGPR182 gave Kd 10 nM (binding) and 14 nM (scavenging) [PMID:37554323]. GPR182-deficient mice show elevated chemokine levels in serum and secondary lymphoid organs [PMID:37554323].","localisation_and_range":"CCL28 is flagged as secreted [flag]; the receptor is flagged as a receptor but no localisation flag is given [flag].","caveats":"One paper only (full text available, curated from abstract); the human pair is projected by orthology. 'ACKR5' is a name proposed by the authors, not an established nomenclature [PMID:37554323].","key_references":[{"PMID":"37554323","why":"Binding and scavenging of CCL28 by GPR182 with Kd values"}],"covers":["LR002263"]},"LR000247":{"pair":"CCL3 -> CCR3","headline":"Mouse CCR3 binds mouse MIP-1 alpha in COS cells (abstract); human pair is projected from this and is thinly supported.","interaction_type":"direct binding","direction_and_effect":"Murine CCR-3 binds murine MIP-1 alpha and murine MIP-1 alpha is a potent chemoattractant for murine eosinophils [PMID:7594543].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse ligand and mouse receptor in transiently transfected COS cells [PMID:7594543]; the human pair is ortholog-inferred, with no human experiment in our evidence.","localisation_and_range":"CCL3 is flagged as secreted and CCR3 as transmembrane [flag].","caveats":"One paper, read as abstract only; no affinity given for CCR3 (the Kd values in the abstract belong to CCR-1). A review-only paper is not shown.","key_references":[{"PMID":"7594543","why":"Cloning of murine CCR-3 which binds murine MIP-1 alpha"}],"covers":["LR000247","LR003763"]},"LR000256":{"pair":"CCL5 -> CCR1","headline":"Well established: CCL5 (RANTES) binds and activates CCR1, shown by binding, mutagenesis and functional assays; direct affinity for CCL5 is not given.","interaction_type":"direct binding","direction_and_effect":"RANTES binds CCR1-expressing transfectants specifically [PMID:7545673]; Arg17 in the N-loop is needed for binding, while P2, D6 and T7 contribute to activation [PMID:9289016]. CCL5 induced chemotaxis of mast cells, partly blocked by anti-CCR1 and anti-CCR4 antibodies and fully blocked by both [PMID:12270118]. GtoPdb records it as Full agonist [DB:GtoPdb].","molecular_requirements":"Mutating the 44RKNR47 BBXB motif of RANTES reduced CCR1 binding (80-fold lower affinity in the triple 40s mutant) while CCR5 binding was normal [PMID:11116158]. Syndecan-1, syndecan-4 and CD44 co-precipitate with RANTES on macrophages [PMID:14637022].","affinity_potency":[{"value":"pKi 6.8 to 8.2","assay":"GtoPdb interaction record","system":"not stated","cite":"DB:GtoPdb"}],"species_and_systems":"Human receptor and ligand: transfected 293 cells [PMID:7545673], mast cells from cord blood [PMID:12270118], monocyte-derived macrophages [PMID:14637022]. The mouse pair is inferred from human evidence.","localisation_and_range":"CCL4/CCL5 carry a secreted flag [flag], so paracrine or endocrine range is implied; the receptor carries receptor and transmembrane flags [flag]. RANTES also binds glycosaminoglycans [PMID:11116158].","caveats":"All papers were abstract-only reads. PMID:14637022 co-IP is weaker for CCR1 than CCR5. BioGRID lists reconstituted-complex records [DB:BioGRID]. The mast-cell result cannot separate CCR1 from CCR4.","key_references":[{"PMID":"9289016","why":"Mutagenesis maps RANTES residues for CCR1 binding"},{"PMID":"7545673","why":"Specific 125I-RANTES binding to CCR1 transfectants"},{"PMID":"12270118","why":"RANTES-induced mast cell chemotaxis via CCR1 and CCR4"}],"covers":["LR000256","LR003766"]},"LR000265":{"pair":"CCL7 -> ACKR4","headline":"One paper measures MCP-3 binding to a receptor named CCR11 (ACKR4) at IC50 4.1 nM, but the interpretation of MCP-family ligands is contested.","interaction_type":"direct binding","direction_and_effect":"Competition binding showed MCP-3 recognised the receptor with IC50 4.1 nM, though MCP-3 acted as an agonist in chemotaxis only at concentrations about 100-fold higher [PMID:10734104]. The best ligand there was MCP-4 (IC50 0.14 nM) [PMID:10734104].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"IC50 4.1 nM","assay":"competition binding vs radiolabelled MCP-4","system":"receptor-transfected murine L1.2 cells (human receptor)","cite":"PMID:10734104"}],"species_and_systems":"Human ligand and receptor expressed in murine L1.2 cells [PMID:10734104]; mouse pair is ortholog-inferred.","localisation_and_range":"CCL7 flagged secreted; ACKR4 flagged transmembrane receptor [flag].","caveats":"Abstract only. Curator notes record that the paper calls the receptor CCR11 and that ACKR4's currently accepted ligands differ, so MCP claims were not upheld. No database records.","key_references":[{"PMID":"10734104","why":"MCP-3 binds CCR11/ACKR4, IC50 4.1 nM"}],"covers":["LR000265","LR003775"]},"LR000274":{"pair":"CCL8 -> CCR1","headline":"CCL8 (MCP-2) binds and activates CCR1 in transfected human cells; supported by binding and migration data and GtoPdb.","interaction_type":"direct binding","direction_and_effect":"CCL8 acts as an agonist: CCR1-transfected HEK293 cells migrated in response to MCP-2 [PMID:9115216], and GtoPdb lists it as an agonist [DB:GtoPdb]. In a second study, MCP-2 displaced radiolabelled MIP-1alpha from CCR1 but, unlike the other chemokines tested, was not a full agonist in [35S]-GTPgammaS exchange [PMID:12381680].","molecular_requirements":"CCR1 alone was sufficient in transfected cells; no co-receptor or subunit requirement is reported in our evidence.","affinity_potency":[],"species_and_systems":"Human CCL8 and human CCR1 in recombinant cells (HEK293 [PMID:9115216]; Ba/F3-hCCR1 membranes [PMID:12381680]). The mouse pair is projected from human evidence (ortholog-inferred).","localisation_and_range":"CCL8 is flagged secreted and CCR1 is flagged transmembrane [flag], so signalling is paracrine via a soluble ligand acting on a cell-surface GPCR.","caveats":"Both papers were read as abstracts only. CCL8 binds CCR1 promiscuously with other chemokines. Efficacy is partial rather than full in one assay [PMID:12381680]. No affinity value is reported in our evidence. No mouse experiment is in the dossier.","key_references":[{"PMID":"9115216","why":"Radiolabelled MCP-2 binding to CCR1-transfected cells, displaced by other CCR1 ligands, plus migration"},{"PMID":"12381680","why":"MCP-2 displaces 125I-MIP-1alpha at hCCR1 but is not a full agonist in GTPgammaS exchange"}],"covers":["LR000274","LR003784"]},"LR002272":{"pair":"CCN2 -> FGFR1","headline":"CCN2 binds FGFR1 with a reported Kd of 362 nM; abstract-level evidence from one paper.","interaction_type":"direct binding","direction_and_effect":"Full-length CCN2 bound FGF receptor 1, while its C-terminal (CT) module did not [PMID:21914781]. Whether CCN2 activates or modulates FGFR1 signalling is not reported in our evidence; the CT module reduced FGF2-induced ERK, p38 and JNK phosphorylation in chondrocytic cells [PMID:21914781].","molecular_requirements":"The CT module alone is not sufficient for FGFR1 binding [PMID:21914781]. Other requirements are not reported in our evidence.","affinity_potency":[{"value":"Kd 362 nM","assay":"binding of CCN2 to FGFR1 (solid-phase binding and SPR)","system":"species unspecified","cite":"PMID:21914781"}],"species_and_systems":"Species of the proteins is not specified; signalling work used chondrocytic HCS-2/8 cells [PMID:21914781].","localisation_and_range":"CCN2 is flagged as secreted [flag], so paracrine or autocrine action is plausible; this is annotation, not shown by the papers.","caveats":"Abstract read only. Primary focus of the paper is CCN2 CT module binding to FGF2 (Kd 5.5 nM), not to the receptor [PMID:21914781]. Which assay produced the 362 nM value is not stated.","key_references":[{"PMID":"21914781","why":"Kd of CCN2 binding to FGFR1"}],"covers":["LR002272","LR005573"]},"LR000382":{"pair":"CCN2 -> ITGA5","headline":"CCN2-mediated adhesion and migration depend on integrin alpha5beta1, but direct binding is not shown; functional evidence only.","interaction_type":"functional only","direction_and_effect":"CTGF modules I and IV promoted adhesion of oval cells, stellate cells and sinusoidal endothelial cells, and adhesion required integrin alpha5beta1 and heparan sulfate proteoglycan; CTGF promoted alpha5beta1-dependent migration of Thy1+ oval cells [PMID:18167060].","molecular_requirements":"Adhesion required both heparan sulfate proteoglycan and integrin alpha5beta1 [PMID:18167060]. The receptor is the alpha5beta1 heterodimer, so ITGB1 is needed alongside ITGA5.","affinity_potency":[],"species_and_systems":"Rat liver regeneration model (oval cells); recombinant CTGF modules [PMID:18167060]. The pair is ortholog-inferred to human.","localisation_and_range":"CCN2 is flagged as secreted [flag], so paracrine or autocrine action is plausible; this is annotation, not shown by the papers.","caveats":"Abstract read only. The main biochemical finding is CTGF binding to fibronectin; CTGF may act through a fibronectin bridge rather than binding the integrin directly [PMID:18167060].","key_references":[{"PMID":"18167060","why":"Integrin alpha5beta1-dependent CTGF adhesion and migration in oval cells"}],"covers":["LR000382"]},"LR005071":{"pair":"CD160 -> TNFRSF14","headline":"CD160 binds HVEM (TNFRSF14) directly with structural and SPR support; engagement is co-inhibitory in CD4+ T cells.","interaction_type":"direct binding","direction_and_effect":"CD160 engagement of HVEM acts as a bidirectional switch for T-cell activation; CD160 crosslinking inhibited CD3/CD28 activation of human CD4+ T cells [PMID:18193050]. UniProt notes CD160 interacts with TNFRSF14 and down-regulates CD28 costimulation [DB:UniProt].","molecular_requirements":"CD160 binds HVEM cysteine-rich domains 1-3 and competes with BTLA, while LIGHT binds a distinct site [PMID:21959263]. Deleting cysteine-rich domain 1 abolished inhibition [PMID:18193050]. The CD160 extracellular domain is mainly a monomer [PMID:21959263].","affinity_potency":[],"species_and_systems":"Human proteins and human CD4+ T cells; the mouse pair is also listed but its experiments are not described [PMID:18193050][PMID:21959263].","localisation_and_range":"CD160 is flagged secreted, receptor and transmembrane [flag]; the papers describe a GPI-anchored membrane protein engaging HVEM on a partner cell [PMID:18193050].","caveats":"Both papers were read as abstracts only. Inhibition by HVEM-transfected cells depended on both CD160 and BTLA, so effects are shared with BTLA [PMID:18193050]. Structures exist [DB:PDB 6NG3][DB:PDB 7MSG].","key_references":[{"PMID":"21959263","why":"SPR: CD160 binds HVEM CRD1-3, competes with BTLA"},{"PMID":"18193050","why":"HVEM as bidirectional switch; CD160 inhibits CD4+ T cells"}],"covers":["LR001702","LR005071"]},"LR001705":{"pair":"CD2 -> CD48","headline":"Direct low-affinity CD2-CD48 binding shown with murine proteins; the human pair is ortholog-inferred.","interaction_type":"direct binding","direction_and_effect":"Force measurements showed head-to-head adhesion between murine CD2 and CD48 extracellular domains [PMID:12356317]. UniProt says CD48 interacts with CD2 [DB:UniProt].","molecular_requirements":"Full-length extracellular domains of both proteins suffice; no other subunit is reported in our evidence [PMID:12356317].","affinity_potency":[],"species_and_systems":"Experiments used mouse proteins (surface force apparatus); the human record is ortholog-inferred [PMID:12356317].","localisation_and_range":"Both flagged membrane receptors [flag]; the bond is low-affinity and needs receptor mobility for avidity [PMID:12356317].","caveats":"Human support is only by ortholog inference from murine data. No affinity value reported here. Abstract-only read.","key_references":[{"PMID":"12356317","why":"Direct force measurement of murine CD2-CD48 adhesion"}],"covers":["LR001705","LR005073"]},"LR002281":{"pair":"CD2 -> CD58","headline":"Well-established direct CD2-CD58 binding with a low affinity (Kd 9-22 microM), supported by structure, SPR and databases.","interaction_type":"direct binding","direction_and_effect":"Human CD2 binds CD58 with very low affinity and extremely fast dissociation, mediating transient adhesion [PMID:7520278]. A zebrafish study confirmed Cd2-Cd58 by co-immunoprecipitation and soluble Cd2 competition, with blockade impairing CD4+ T and B-cell activation [PMID:29904386].","molecular_requirements":"A 1:1 CD2-CD58 pair is sufficient in SPR with soluble recombinant proteins [PMID:7520278]; no further subunits reported.","affinity_potency":[{"value":"Kd 9-22 microM","assay":"surface plasmon resonance","system":"soluble recombinant human CD2 and CD58","cite":"PMID:7520278"}],"species_and_systems":"Human recombinant proteins for binding [PMID:7520278]; the second paper used zebrafish homologs [PMID:29904386]. Co-crystal structure [DB:PDB 1QA9][DB:BioGRID].","localisation_and_range":"Both flagged membrane receptors [flag]; contact-dependent adhesion between T cells and partner cells [PMID:7520278].","caveats":"Binding is very weak and gains function through avidity [PMID:7520278]. Both papers were abstract-read. The zebrafish study is not a human experiment.","key_references":[{"PMID":"7520278","why":"SPR Kd 9-22 microM, fast koff"},{"PMID":"29904386","why":"Cd58-Cd2 co-IP and function in zebrafish"}],"covers":["LR002281"]},"LR005080":{"pair":"CD274 -> CD80","headline":"PD-L1 binds CD80 (B7-1) with intermediate affinity, with multiple direct-binding papers and an in vivo mouse study of trans interactions.","interaction_type":"direct binding","direction_and_effect":"B7-1 and PD-L1 interacted and the interaction inhibited T cell activation and cytokine production, a bidirectional inhibitory interaction [PMID:17629517]. Human B7-1 interacts with human PD-L1 with affinity greater than B7-1:CD28 but less than B7-1:CTLA-4 or PD-L1:PD-1 [PMID:18585785]. In mice, blocking PD-L1/CD80 interactions augmented antitumour CD8 T cell immunity [PMID:37036990].","molecular_requirements":"The PD-L1:B7-1 interface overlaps with the B7-1:CTLA-4 and PD-L1:PD-1 interfaces [PMID:17629517]. Trans effects between tumour and T cells required tumour MHC-I and T cell CD28 [PMID:37036990]. UniProt notes the interaction blocks PD-L1/PD-1 binding [DB:UniProt]. PDB 7TPS has a structure [DB:PDB 7TPS].","affinity_potency":[],"species_and_systems":"Human recombinant and cell assays [PMID:17629517][PMID:18585785][PMID:20587542]; mouse tumour models (MC38, B16 in C57BL/6) [PMID:37036990].","localisation_and_range":"Both flagged membrane-bound and also secreted [flag]. Cis and trans configurations are discussed: earlier reports found only cis interactions, while this study reports that trans interactions between tumour and T cells exist [PMID:37036990].","caveats":"Three papers are abstract-only. No numeric affinity in our evidence. Cis and trans PD-L1/CD80 interactions may have opposite effects on antitumour immunity [PMID:37036990].","key_references":[{"PMID":"17629517","why":"First report of PD-L1:B7-1 binding and inhibitory function"},{"PMID":"18585785","why":"Human B7-1 and PD-L1 affinity ranking, blocking antibodies"},{"PMID":"37036990","why":"Trans PD-L1/CD80 in vivo; blockade augments antitumour immunity"}],"covers":["LR001713","LR005080"]},"LR001714":{"pair":"CD274 -> PDCD1","headline":"Well established PD-L1 binding to PD-1: crystal structure, SPR and MST, with inhibitory signalling noted in UniProt.","interaction_type":"direct binding","direction_and_effect":"PD-1 binds PD-L1; signalling through PD-1 upon PD-L1 binding suppresses immune responses [PMID:18287011]. UniProt says PD-1 delivers inhibitory signals on binding CD274 [DB:UniProt]. PD-L1 and PD-L2 compete for PD-1, and an antagonist PD-1 mAb blocked both and enhanced T-cell proliferation [PMID:20587542]. Structure: crystal of murine PD-1 with human PD-L1 [PMID:18287011]; PDB 4ZQK and 5IUS [DB:PDB 4ZQK].","molecular_requirements":"Binding is through the Ig variable domains of both proteins; some loss-of-binding mutations disrupt folding instead [PMID:18287011]. No additional subunit needed in our evidence.","affinity_potency":[{"value":"Kd 8.5 \u00b5M","assay":"microscale thermophoresis","system":"mouse PD-L1 with mPD-1-eGFP in CHO-K1 lysate","cite":"PMID:29247197"}],"species_and_systems":"Murine PD-1 with human PD-L1 in the crystal [PMID:18287011]; human proteins by SPR [PMID:20587542]; the MST data use mouse proteins [PMID:29247197].","localisation_and_range":"PD-L1 flagged membrane-bound and also secreted, PD-1 transmembrane [flag]; contact-dependent signalling.","caveats":"PD-L1 and PD-L2 bound with comparable affinities; PD-L1 shows delayed association [PMID:20587542]. GtoPdb lists binding with no affinity [DB:GtoPdb]. Only abstracts read for the three curated papers.","key_references":[{"PMID":"18287011","why":"Crystal structure of PD-1 with PD-L1"},{"PMID":"20587542","why":"SPR kinetics and competition between PD-L1 and PD-L2"},{"PMID":"29247197","why":"MST protocol measuring Kd"}],"covers":["LR001714","LR005081"]},"LR000283":{"pair":"CD34 -> SELP","headline":"Human CD34 on HSPCs is described as a major vascular selectin ligand; single abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"CD34-positive HSPC fractions bound E- and P-selectin whereas CD34-negative ones did not; a proteomics screen identified CD34 as a major vascular selectin ligand [PMID:29296932].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human HSPC-enriched fractions [PMID:29296932]; mouse pair projected from human.","localisation_and_range":"CD34 flagged transmembrane, not secreted; SELP membrane-bound [flag].","caveats":"Abstract only; selectin results are pooled for E- and P-selectin and no P-selectin-specific data appear in the abstract. IntAct solid-phase record also exists [DB:IntAct]. No affinity reported.","key_references":[{"PMID":"29296932","why":"CD34 as vascular selectin ligand on HSPCs"}],"covers":["LR000283","LR003793"]},"LR002290":{"pair":"CD40LG -> ITGAV","headline":"CD40L binds integrin alphavbeta3 in two papers (abstract-only) and UniProt; ITGAV is a chain of that receptor.","interaction_type":"direct binding","direction_and_effect":"Integrin alphavbeta3 bound CD40L in a KGD-independent manner, suggesting a new CD40L receptor; integrin-binding-defective CD40L mutants were defective in NF-kB and B cell activation and suppressed wild-type CD40L signalling while still binding CD40 [PMID:31331973]. Soluble CD40L activated soluble alphavbeta3, alpha5beta1 and alpha4beta1 in cell-free conditions, and cell-surface integrins in CD40-negative CHO cells [PMID:33571526]. UniProt lists ITGAV:ITGB3 as a receptor for CD40LG [DB:UniProt].","molecular_requirements":"Evidence is for the alphav:beta3 heterodimer; ITGAV alone is not tested. Binding to a site-2 cyclic peptide and docking place the site-2 residues outside the trimer interface [PMID:33571526].","affinity_potency":[],"species_and_systems":"Human ligand and receptor per curators; recombinant and cell-line systems (CHO cells) [PMID:31331973][PMID:33571526]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand carries secreted and transmembrane flags [flag]; the studies used soluble CD40L [PMID:33571526].","caveats":"Both papers read as abstracts only; no affinity reported. Two more confirmed papers are not shown.","key_references":[{"PMID":"31331973","why":"alphavbeta3 binds CD40L; integrin-binding-defective mutants"},{"PMID":"33571526","why":"Soluble CD40L activates alphavbeta3 and other integrins"}],"covers":["LR002290","LR005589"]},"LR001723":{"pair":"CD48 -> CD244","headline":"Inhibitory NK-cell self-recognition pair rests on one functional paper plus database records; no binding measurement in our papers.","interaction_type":"functional only","direction_and_effect":"2B4 (CD244) and CD48 form a system for murine NK-cell self-recognition; 2B4 acts nonredundantly with MHC class I receptors to inhibit NK lysis of syngeneic tumour cells, and a bone marrow rejection assay gave in vivo evidence [PMID:15870174]. The curator-recorded effect is antagonist (inhibitory), while the interaction record carries a 'Stimulatory' label, so direction labels disagree.","molecular_requirements":"Not reported in our evidence (no subunit or co-receptor information).","affinity_potency":[],"species_and_systems":"The study is described as murine NK-cell self-recognition [PMID:15870174]; the curator species fields say human, which conflicts with the abstract. The human pair is ortholog-inferred. Databases (IntAct, Reactome) record CD48 binding CD244 [DB:IntAct][DB:Reactome].","localisation_and_range":"Both are membrane proteins by annotation flags (CD48 also flagged secreted) [flag]; the NK-target recognition in the paper implies cell-contact signalling [PMID:15870174].","caveats":"Single paper, abstract only, and it shows an effect rather than binding. The binding evidence comes only from database records [DB:IntAct][DB:Reactome][DB:UniProt]. Two further papers were judged review-only and are not shown.","key_references":[{"PMID":"15870174","why":"Murine NK cells: 2B4-CD48 inhibits NK lysis independently of MHC class I"}],"covers":["LR001723"]},"LR001732":{"pair":"CD86 -> CD28","headline":"CD86 binds and activates CD28, supported by binding comparisons, functional studies and databases; the evidence is mixed in species.","interaction_type":"direct binding","direction_and_effect":"CD86 is a stimulatory CD28 ligand: human CD86 kept binding and costimulation within about 2- to 3-fold of CD80 [PMID:7534620]. In memory CD4 T cells, CD86 was the dominant ligand for Treg proliferation, survival and phenotype [PMID:33363541]. In mouse T cells CD86 alone costimulated IL-4 and IL-10 [PMID:9184909]. CD80/CD86-CD28 interactions were implicated in CD8+CD122+ regulatory T-cell action [PMID:18205792].","molecular_requirements":"CD86 and CD80 use different binding determinants and kinetics for CD28 and CTLA-4 [PMID:7534620]. CD80-CD28 interactions were compromised by CTLA-4 on Treg cells, CD86-CD28 was not similarly affected [PMID:33363541].","affinity_potency":[],"species_and_systems":"Human cells and proteins [PMID:7534620] [PMID:33363541]; murine T cells for PMID:9184909; species not listed for PMID:18205792. Both human and mouse pairs are in the dossier. Databases show surface plasmon resonance and Reactome binding reactions [DB:IntAct] [DB:Reactome].","localisation_and_range":"CD86 is membrane-bound on antigen-presenting cells, with a transmembrane flag [flag].","caveats":"Papers were read as abstracts, with excerpts for PMID:33363541. No numeric affinity for CD86-CD28 in our evidence. PMID:21530327 mainly concerns B7-H2. Several readouts use blocking antibodies or CHO/P815 transfectants [PMID:33363541] [PMID:9184909].","key_references":[{"PMID":"7534620","why":"Quantitative comparison of CD86 and CD80 receptor binding"},{"PMID":"33363541","why":"CD86 is the dominant CD28 ligand for Treg homeostasis"},{"PMID":"9184909","why":"CD86 costimulation drives Th2 responses"}],"covers":["LR001732","LR005097"]},"LR000292":{"pair":"CDH1 -> KLRG1","headline":"E-cadherin is a structurally defined, very weak-affinity ligand for the inhibitory receptor KLRG1; well supported.","interaction_type":"direct binding","direction_and_effect":"KLRG1 inhibits NK cell cytotoxicity: binding by E-cadherin prevents NK lysis of E-cadherin-expressing targets [PMID:16461340]. The curators classify E-cadherin as an antagonist-direction ligand of this inhibitory receptor, i.e. it blocks cytotoxicity [PMID:19604491].","molecular_requirements":"Crystal structures of KLRG1 with the N-terminal Ig-like domain of E-cadherin (hEC1) exist for human and mouse KLRG1 [PMID:19604491][DB:PDB 3FF7]. The KLRG1 site overlaps the cadherin-cadherin adhesion interface but is distinct from the alphaEbeta7 site, so co-engagement is suggested [PMID:19604491]. KLRG1 also binds N- and R-cadherins [PMID:16461340].","affinity_potency":[{"value":"KD 100-200 \u00b5M","assay":"SPR, hEC1 or EC1-EC2, with or without Ca2+","system":"human and mouse KLRG1 with human E-cadherin EC1","cite":"PMID:19604491"}],"species_and_systems":"Expression cloning with mouse KLRG1 tetramer found human E-cadherin as a xenogeneic ligand and mouse E-cadherin as a syngeneic one [PMID:16461340]. Structures used human and mouse KLRG1 with human E-cadherin EC1 [PMID:19604491].","localisation_and_range":"Both are membrane proteins (flagged transmembrane) [flag]; avidity through multipoint attachment on target cells is proposed [PMID:19604491].","caveats":"Monomeric affinity is exceptionally weak, so function depends on avidity [PMID:19604491]. The cloning paper was read as abstract plus full text but the effect-direction label comes from curator notes. One further paper pending, one review-only.","key_references":[{"PMID":"19604491","why":"Crystal structure and SPR affinity of KLRG1-E-cadherin"},{"PMID":"16461340","why":"Identification of cadherins as KLRG1 ligands"}],"covers":["LR000292","LR003801"]},"LR002308":{"pair":"CDH11 -> CDH8","headline":"Cadherin-11 and cadherin-8 are a preferred heterophilic type II cadherin pair in SPR on mouse proteins.","interaction_type":"direct binding","direction_and_effect":"On the cadherin-8 surface, cadherin-11 gave the strongest observed interaction, followed by homophilic cadherin-8 binding [PMID:29742438].","molecular_requirements":"They form one specificity group and prefer heterophilic binding to each other over all other cadherins [PMID:29742438].","affinity_potency":[],"species_and_systems":"Type II cadherin binding was measured by SPR and AUC on purified mouse EC1-EC2 fragments, with A431D cell co-culture; the human pair is inferred by orthology [PMID:29742438].","localisation_and_range":"Membrane-bound adhesion molecules, so contact-dependent (juxtacrine); neither partner is flagged secreted [flag].","caveats":"Single paper; SPR heterophilic affinities could not be determined because of competing homodimerization, so only relative response levels are available [PMID:29742438]. Human result is ortholog-projected, not measured.","key_references":[{"PMID":"29742438","why":"Heterophilic cadherin-8/-11 SPR"}],"covers":["LR002308","LR005606"]},"LR005611":{"pair":"CDH3 -> CDH3","headline":"P-cadherin homophilic adhesion in human, studied via blocking antibodies; evidence is structural and functional.","interaction_type":"direct binding","direction_and_effect":"P-cadherin forms homophilic adhesion; antibody TSP7 abolished adhesion by disabling the X-dimer intermediate as well as the strand-swap dimer [PMID:28045038]. Curators label the antibody effect as antagonist.","molecular_requirements":"The EC1 domain carries the epitopes for TSP5, TSP7 and TSP11, and all three bind with high affinity, but only TSP7 blocks adhesion [PMID:28045038].","affinity_potency":[],"species_and_systems":"Human P-cadherin, abstract only; the mouse pair is ortholog-inferred [PMID:28045038]. BioGRID also lists CDH3-CDH3 co-purification and Affinity Capture-Western [DB:BioGRID] [PMID:10910767].","localisation_and_range":"Membrane-bound homophilic adhesion, contact-dependent [flag].","caveats":"The confirming paper concerns antibody blockade, so homophilic binding is inferred rather than directly quantified; no affinity for the cadherin pair reported.","key_references":[{"PMID":"28045038","why":"X-dimer and strand-swap dimer in P-cadherin adhesion"}],"covers":["LR002313","LR005611"]},"LR002317":{"pair":"CDH6 -> CDH10","headline":"Type II cadherin heterophilic pair: cadherin-6 binds cadherin-10 in SPR on mouse proteins.","interaction_type":"direct binding","direction_and_effect":"On cadherin-6 surfaces cadherin-6 analyte was strongest, followed by cadherin-9 and cadherin-10 [PMID:29742438].","molecular_requirements":"Cadherin-6, -9 and -10 form one specificity group [PMID:29742438].","affinity_potency":[],"species_and_systems":"Type II cadherin binding was measured by SPR and AUC on purified mouse EC1-EC2 fragments, with A431D cell co-culture; the human pair is inferred by orthology [PMID:29742438].","localisation_and_range":"Membrane-bound adhesion molecules, so contact-dependent (juxtacrine); neither partner is flagged secreted [flag].","caveats":"Single paper; SPR heterophilic affinities could not be determined because of competing homodimerization, so only relative response levels are available [PMID:29742438]. Human result is ortholog-projected, not measured.","key_references":[{"PMID":"29742438","why":"SPR matrix of type II cadherin binding"}],"covers":["LR002317","LR005615"]},"LR005620":{"pair":"CDH9 -> CDH6","headline":"Type II cadherin heterophilic pair: cadherin-9 and cadherin-6 interact in SPR on mouse proteins.","interaction_type":"direct binding","direction_and_effect":"On surfaces of cadherin-6, -9 or -10, cadherin-6 analyte was strongest, followed by cadherin-9 and cadherin-10 [PMID:29742438].","molecular_requirements":"Cadherin-6, -9 and -10 form one specificity group [PMID:29742438].","affinity_potency":[],"species_and_systems":"Type II cadherin binding was measured by SPR and AUC on purified mouse EC1-EC2 fragments, with A431D cell co-culture; the human pair is inferred by orthology [PMID:29742438].","localisation_and_range":"Membrane-bound adhesion molecules, so contact-dependent (juxtacrine); neither partner is flagged secreted [flag].","caveats":"Single paper; SPR heterophilic affinities could not be determined because of competing homodimerization, so only relative response levels are available [PMID:29742438]. Human result is ortholog-projected, not measured.","key_references":[{"PMID":"29742438","why":"SPR matrix of type II cadherin binding"}],"covers":["LR002322","LR005620"]},"LR012442":{"pair":"CDON -> PTCH1:SMO","headline":"Co-IP shows CDON associates with PTCH1; SMO as a partner is not supported by our evidence.","interaction_type":"direct binding","direction_and_effect":"Wild-type CDON associates with PTCH1 (and GAS1), and HPE-associated variants do so inefficiently, paralleling their activity in cell-based assays [PMID:21802063]. Curated modulatory effect is Stimulatory [flag]. Reactome has a Hh-Npp:CDON:PTCH ciliary membrane complex [DB:Reactome R-HSA-5632590].","molecular_requirements":"Evidence concerns PTCH1 only; no evidence in our dossier that SMO binds CDON or is needed. A complex-based tool would score by SMO, so this may under- or over-state the pair.","affinity_potency":[],"species_and_systems":"Abstract-level evidence; species/system not stated beyond cell-based assays [PMID:21802063]. IntAct records anti-bait coimmunoprecipitation from the same paper [DB:IntAct].","localisation_and_range":"Not reported in our evidence.","caveats":"Abstract only. Pair is entered as a CDON-to-PTCH1:SMO complex although the evidence supports CDON-PTCH1 association only. CDON is itself flagged as a receptor [flag].","key_references":[{"PMID":"21802063","why":"CDON associates with PTCH1; variants impair this"}],"covers":["LR012442"]},"LR002326":{"pair":"CEACAM1 -> CEACAM8","headline":"Soluble CEACAM8 binds epithelial CEACAM1 and dampens TLR2 responses; one paper, abstract-level, plus BioGRID and IntAct.","interaction_type":"direct binding","direction_and_effect":"Soluble recombinant CEACAM8-Fc binds CEACAM1 on human airway epithelium and reduces TLR2-dependent inflammatory responses, with CEACAM1 ITIM tyrosine phosphorylation and SHP-1 recruitment [PMID:24743304]. Inhibitory effect.","molecular_requirements":"CEACAM1 ITIM signalling (SHP-1 recruitment) is involved [PMID:24743304]. UniProt lists CEACAM1 isoform 1 as interacting with CEACAM8 [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human granulocytes, primary bronchial epithelial cells and recombinant CEACAM8-Fc [PMID:24743304]. BioGRID lists a reconstituted complex [DB:BioGRID].","localisation_and_range":"CEACAM8 is released by granulocytes (TLR9-dependent) and acts as a soluble ligand on epithelium, so paracrine [PMID:24743304].","caveats":"Curated as abstract-only; full-text excerpts support the functional effect on NHBE cells. No affinity reported.","key_references":[{"PMID":"24743304","why":"Soluble CEACAM8 binds CEACAM1 and inhibits TLR2 signalling"}],"covers":["LR002326"]},"LR001741":{"pair":"CEACAM6 -> CEACAM8","headline":"Heterophilic CEACAM6-CEACAM8 adhesion with N-domain mapping, supported by IntAct ITC and PDB structures.","interaction_type":"direct binding","direction_and_effect":"The CEACAM6 N-domain on a CHO cell was suggested to bind the N-domain of CEACAM8 on the opposing cell; CEACAM8 shows only heterophilic adhesion to CEACAM6 [PMID:11590190]. IntAct records isothermal titration calorimetry [DB:IntAct]; PDB has structures with a chain of each [DB:PDB 4WTZ] [DB:PDB 4YIQ].","molecular_requirements":"N-terminal domain critical sequences overlap for homophilic and heterophilic adhesion [PMID:11590190].","affinity_potency":[],"species_and_systems":"Human proteins, CHO transfectants [PMID:11590190].","localisation_and_range":"Trans cell-cell adhesion on neutrophils [PMID:11590190].","caveats":"Paper curated as functional_in_vitro, abstract only. ITC values are not given in our evidence.","key_references":[{"PMID":"11590190","why":"CEACAM6-CEACAM8 heterophilic adhesion N-domain mapping"}],"covers":["LR001741"]},"LR003802":{"pair":"CEL -> CXCR4","headline":"CEL (BSDL) acts through platelet CXCR4 in one paper; binding is inferred, not directly measured.","interaction_type":"functional only","direction_and_effect":"BSDL and a V3-loop-like peptide induced calcium mobilization and enhanced thrombin-mediated platelet aggregation in human platelets, abolished by CXCR4 inhibition; classed as agonist [PMID:18037996]. In mice, thrombus formation depended on BSDL and was blocked by CXCR4 antagonism [PMID:18037996].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human platelets and endothelial cells in vitro, plus a mouse thrombosis model and BSDL-knockout mice [PMID:18037996]. Human pair is ortholog-inferred for the mouse record.","localisation_and_range":"CEL is flagged secreted [flag]; range not reported in the paper excerpt.","caveats":"Curator notes that binding is inferred from homology of a BSDL region to the HIV-1 V3 loop plus functional blockade, not a direct binding assay; abstract only [PMID:18037996]. No database records.","key_references":[{"PMID":"18037996","why":"BSDL activates platelets in a CXCR4-dependent manner in vitro and in mice"}],"covers":["LR000293","LR003802"]},"LR002335":{"pair":"CELSR3 -> CELSR3","headline":"Homophilic CELSR3 interaction implied by one neurite-growth paper; no direct binding assay in our evidence.","interaction_type":"functional only","direction_and_effect":"Celsr3 was activated by homophilic interaction but suppressed neurite growth, opposite to Celsr2 [PMID:17618280]. Effect direction differs between the two paralogues [PMID:17618280].","molecular_requirements":"Opposite functions of Celsr2 and Celsr3 trace to a single amino acid difference in the transmembrane domain; signalling may involve second messengers [PMID:17618280].","affinity_potency":[],"species_and_systems":"Rat neuron coculture and gene silencing; the curator labels the experiment species as mouse, which conflicts with the rat neurons named in the assay text [PMID:17618280].","localisation_and_range":"Membrane-bound seven-pass cadherin, so homophilic contact (juxtacrine) [flag] [PMID:17618280].","caveats":"Abstract only; no binding measurement or database record. One additional review-only row not shown. Paralog issue: the same paper covers CELSR2 and CELSR3 with opposing effects.","key_references":[{"PMID":"17618280","why":"Celsr2 and Celsr3 homophilic activation with opposing neurite effects"}],"covers":["LR002335","LR005624"]},"LR002344":{"pair":"CIRBP -> LY96","headline":"Extracellular CIRP binds MD2 (LY96) by surface plasmon resonance; one paper, abstract-level read.","interaction_type":"direct binding","direction_and_effect":"Human CIRP residues 106-125 bind MD2 with high affinity; CIRP is a danger signal acting on the TLR4-MD2 complex [PMID:24097189]. Recombinant CIRP stimulates TNF-alpha and HMGB1 release from macrophages [PMID:24097189].","molecular_requirements":"MD2 binding is mapped to CIRP residues 106-125 [PMID:24097189]; TLR4 is the partner in the TLR4-MD2 complex.","affinity_potency":[],"species_and_systems":"Surface plasmon resonance with human CIRP peptide; macrophage and rodent hemorrhage/sepsis models [PMID:24097189].","localisation_and_range":"CIRP flagged secreted [flag]; released into circulation from cells [PMID:24097189].","caveats":"Abstract read; no Kd value reported in our evidence, only 'high affinity'.","key_references":[{"PMID":"24097189","why":"CIRP binds TLR4-MD2, TLR4 and MD2 by SPR"}],"covers":["LR002344","LR005627"]},"LR005107":{"pair":"CLEC11A -> ITGB1","headline":"ITGB1 is the beta partner of the alpha11beta1 Osteolectin receptor; same single paper as ITGA11, with the alpha chain being the one named.","interaction_type":"direct binding","direction_and_effect":"alpha11beta1 integrin binds Osteolectin with high affinity and the alpha11 chain is required for bone-mass maintenance; Osteolectin acts as an agonist [PMID:30632962].","molecular_requirements":"ITGB1 acts as the partner of alpha11 in the heterodimer; the curator note says the paper's title names the alpha11 row [PMID:30632962]. Whether beta1 alone binds is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cells are LepR+ skeletal stem cells and osteoblasts; curated species human/human, mouse pair is ortholog-inferred [PMID:30632962].","localisation_and_range":"CLEC11A flagged secreted; ITGB1 flagged a receptor, not secreted [flag].","caveats":"Single paper, with the abstract-level evidence naming alpha11 specifically. Binding of beta1 alone is not reported in our evidence. No database records.","key_references":[{"PMID":"30632962","why":"alpha11beta1 binds Osteolectin"}],"covers":["LR001747","LR005107"]},"LR001750":{"pair":"CLEC2D -> KLRB1","headline":"LLT1 (CLEC2D) is a ligand for CD161 (KLRB1) in human cells, with inhibitory NK effect; also structural and SPR records.","interaction_type":"functional only","direction_and_effect":"LLT1 engagement of CD161 inhibited NK-cell cytotoxicity and IFN-gamma secretion, but enhanced IFN-gamma production by T cells together with a TCR signal, so the effect depends on cell type [PMID:16339512]. UniProt describes CLEC2D as a receptor for KLRB1 that protects target cells from NK lysis [DB:UniProt].","molecular_requirements":"Not reported in our evidence beyond the two partners.","affinity_potency":[],"species_and_systems":"Human cells; abstract-level [PMID:16339512]. Structure [DB:PDB 5MGT]; SPR and solid phase assay records [DB:IntAct]; Reactome complex [DB:Reactome].","localisation_and_range":"Both partners are membrane-bound (flags), so contact-dependent [flag]. In NSCLC, LLT1 was restricted to germinal-center B cells in tertiary lymphoid structures [PMID:29721382].","caveats":"Both papers abstract only. Four further papers were judged abstract_insufficient and one review-only. PMID 29721382 treats the pair as background and reports expression, not interaction. No affinity in our evidence.","key_references":[{"PMID":"16339512","why":"LLT1 identified as CD161 ligand; opposite effects on NK and T cells"}],"covers":["LR001750"]},"LR002353":{"pair":"CLEC4M -> ICAM3","headline":"L-SIGN (CLEC4M) binds ICAM-3 with high affinity in cell-based adhesion assays; one full-text paper plus an IntAct record.","interaction_type":"direct binding","direction_and_effect":"K562 cells transfected with L-SIGN were shown to bind ICAM-3 with high affinity; binding was inhibited by mAbs AZN-D2 and AZN-D3, mannan or EGTA [PMID:11257134]. ICAM-3 is the bound partner; effect on signalling is not reported.","molecular_requirements":"Ca2+ dependent (EGTA inhibits) and mannose-binding C-type lectin behaviour [PMID:11257134]. No co-receptor reported.","affinity_potency":[],"species_and_systems":"Human; K562 flow cytometry-based adhesion assay [PMID:11257134]. IntAct lists a solid phase assay [DB:IntAct Q9H2X3-P32942].","localisation_and_range":"CLEC4M is flagged secreted, receptor and transmembrane [flag]; paper shows L-SIGN expressed on liver sinusoidal endothelial cells, so membrane-bound adhesion [PMID:11257134].","caveats":"The affinity is called 'high' but no value is reported. L-SIGN is a close paralog of DC-SIGN (77% identity), so the evidence should be kept distinct from DC-SIGN [PMID:11257134]. The pair's direction (CLEC4M as ligand) is a convention; both are adhesion molecules.","key_references":[{"PMID":"11257134","why":"L-SIGN binds ICAM-3 with high affinity"}],"covers":["LR002353"]},"LR002362":{"pair":"CNIH2 -> GRIA1","headline":"CNIH2 is an AMPA receptor auxiliary partner; GluA1 specifically required, shown by knockout and co-IP; one full-text paper.","interaction_type":"functional only","direction_and_effect":"CNIH-2 and CNIH-3 deletion eliminated surface GluA1-containing AMPARs and reduced synaptic transmission; CNIH-2 knock-down had no effect in GluA1 KO slices [PMID:23522044]. This is an auxiliary-subunit trafficking relationship, not a secreted ligand.","molecular_requirements":"GluA1 is required: CNIH-2 co-immunoprecipitated with GluA1 from GluA2 KO lysates but not with GluA2 from GluA1 KO lysates; TARP \u03b3-8 probably prevents CNIH association with non-GluA1 subunits [PMID:23522044].","affinity_potency":[],"species_and_systems":"Mouse hippocampal slices and neurons; rat dissociated neurons for shRNA; HEK cells [PMID:23522044]. Dossier lists the species as human; mouse pair is the non-inferred one.","localisation_and_range":"Neither partner flagged secreted [flag]; intracellular and membrane trafficking partnership in neurons, not intercellular signalling.","caveats":"The dossier effect 'agonist' reflects the full text: CNIH slows AMPAR deactivation in heterologous cells [PMID:23522044]. BioGRID, Reactome and UniProt records exist [DB:BioGRID 3339420][DB:UniProt P42261]. Should not be treated as a cell-cell ligand-receptor pair.","key_references":[{"PMID":"23522044","why":"CNIH-2/-3 determine surface GluA1-containing AMPARs"}],"covers":["LR002362","LR005642"]},"LR003811":{"pair":"CNTF -> CNTFR","headline":"CNTF is the canonical agonist of CNTFR (with gp130/LIFR); direct binding shown in vitro; three abstract-only papers plus GtoPdb and PDB.","interaction_type":"direct binding","direction_and_effect":"GtoPdb lists CNTF as an agonist at CNTFR [DB:GtoPdb]. CNTFR is a non-signaling alpha chain and signals through gp130 and LIFR [PMID:10966616].","molecular_requirements":"CNTFR alone does not signal; gp130 and LIFR are the signalling beta chains [PMID:10966616]. The CNTF/CNTFR heterocomplex bound gp130 with an affinity of 3-5 x 10(-10)M [PMID:8627290]. Tools scoring this by the least-expressed subunit should use CNTFR plus both gp130 and LIFR.","affinity_potency":[{"value":"IC50 29 nM (human CNTF)","assay":"nonradioactive competitive binding vs biotinylated CNTF","system":"soluble gp130 and soluble CNTFR","cite":"PMID:7810882"},{"value":"IC50 2 nM (rat CNTF)","assay":"nonradioactive competitive binding vs biotinylated CNTF","system":"soluble gp130 and soluble CNTFR","cite":"PMID:7810882"},{"value":"3-5 x 10(-10)M","assay":"binding of CNTF/alpha CNTF receptor heterocomplex to gp130","system":"transfected cells, human cell lines","cite":"PMID:8627290"}],"species_and_systems":"Human cell lines and recombinant soluble receptors; rat CNTF was also tested [PMID:7810882][PMID:8627290]. Mouse pair is ortholog-inferred.","localisation_and_range":"CNTF is flagged secreted [flag]; soluble paracrine cytokine.","caveats":"All three papers read as abstracts only. The 29 and 2 nM values are IC50s from a competition assay, not Kd. The Nat Neurosci paper concerns the CLF/CLC complex as a second CNTFR ligand and does not test CNTF itself [PMID:10966616]. PDB 8D74 has CNTF and CNTFR chains [DB:PDB 8D74].","key_references":[{"PMID":"7810882","why":"Competitive binding of human and rat CNTF to soluble CNTFR/gp130"},{"PMID":"8627290","why":"CNTF/CNTFR heterocomplex binds gp130 with 3-5 x 10(-10)M"},{"PMID":"10966616","why":"CNTFR as non-signaling alpha chain with gp130 and LIFR"}],"covers":["LR000305","LR003811"]},"LR002371":{"pair":"CNTN5 -> PTPRG","headline":"Direct structural evidence that PTPRG binds CNTN5; one abstract-level paper, with a co-crystal only for mouse CNTN4.","interaction_type":"direct binding","direction_and_effect":"Crystal structures show the carbonic-anhydrase-like domain of PTPRG interacts directly with the second and third Ig repeats of contactins; PTPRG binds CNTN3, 4, 5 and 6, whereas PTPRZ binds only CNTN1 [PMID:20133774]. The effect on signalling is not reported in our evidence.","molecular_requirements":"Binding uses the PTPRG carbonic-anhydrase-like domain and the contactin Ig repeats 2-3 region; the binding site is conserved among CNTN3, 4, 5 and 6 [PMID:20133774].","affinity_potency":[],"species_and_systems":"Crystal structures used mouse CNTN4 (four N-terminal Ig repeats) with mouse PTPRG carbonic-anhydrase-like domain; the specificity result covers the CNTN family [PMID:20133774]. Curator species labels are human for this pair.","localisation_and_range":"CNTN5 is annotated secreted and PTPRG non-secreted [flag].","caveats":"Abstract-only read. The co-crystal structure is for CNTN4-PTPRG; CNTN5 binding is stated in the abstract as a specificity result, with no detail on assay or affinity in our evidence [PMID:20133774].","key_references":[{"PMID":"20133774","why":"Crystal structures and contactin specificity of PTPRG"}],"covers":["LR002371","LR005651"]},"LR003820":{"pair":"COL11A1 -> ITGA2","headline":"Only a cell-based report that integrin a2b1/DDR2 bind collagen XI; abstract-level and not chain-specific for COL11A1.","interaction_type":"functional only","direction_and_effect":"Integrin a2b1 and DDR2, but not a11b1, mediated high-affinity binding of cancer-associated fibroblasts to collagen type XI [PMID:36233024].","molecular_requirements":"The a2b1 heterodimer, not ITGA2 alone, is what the paper names [PMID:36233024].","affinity_potency":[],"species_and_systems":"CAFs; species not reported in our evidence [PMID:36233024]. The human pair is ortholog-inferred.","localisation_and_range":"COL11A1 is annotated secreted and not transmembrane [flag].","caveats":"Abstract-only; the paper says collagen type XI without naming a chain, and does not isolate individual integrin subunits [PMID:36233024].","key_references":[{"PMID":"36233024","why":"Integrin a2b1 and DDR2 binding to collagen XI in CAFs"}],"covers":["LR000314","LR003820"]},"LR002380":{"pair":"COL13A1 -> ITGB1","headline":"ITGB1 support comes via the a11b1 heterodimer; the b1 chain alone was not tested.","interaction_type":"direct binding","direction_and_effect":"Integrin a11b1 binds collagen XIII (SPR, pull-down, cell adhesion) [PMID:33306155].","molecular_requirements":"ITGB1 acts as the partner of a11; the a11-I domain recognises the motifs, and b1-only binding is not reported in our evidence [PMID:33306155].","affinity_potency":[],"species_and_systems":"C2C12 cells expressing human a11b1; mouse genetic crosses. The mouse pair is ortholog-inferred [PMID:33306155].","localisation_and_range":"COL13A1 is annotated non-secreted and transmembrane [flag].","caveats":"Chain-level assignment: the evidence concerns the a11b1 heterodimer, not ITGB1 alone [PMID:33306155].","key_references":[{"PMID":"33306155","why":"a11b1 as collagen XIII receptor"}],"covers":["LR002380","LR005659"]},"LR009130":{"pair":"COL16A1 -> ITGB1","headline":"Supported only by a UniProt subunit annotation; no primary paper in our evidence.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states COL16A1 interacts with integrins ITGA1/ITGB1 and ITGA2/ITGB1 [DB:UniProt Q07092]. Direction and effect are not reported in our evidence.","molecular_requirements":"ITGB1 is named only as the partner of ITGA1 or ITGA2 [DB:UniProt Q07092].","affinity_potency":[],"species_and_systems":"Not reported in our evidence; the UniProt record cites PMID 15165854, which is not among our judged papers [DB:UniProt Q07092].","localisation_and_range":"COL16A1 is annotated secreted and not transmembrane [flag].","caveats":"Database assertion only; judged papers were review-only, so no primary evidence was verified.","key_references":[],"covers":["LR009130"]},"LR000319":{"pair":"COL18A1 -> ITGA5","headline":"Endostatin, a collagen XVIII fragment, binds alpha5beta1 integrin on human endothelial cells; two abstract-read papers.","interaction_type":"direct binding","direction_and_effect":"Recombinant human endostatin interacts with alpha5 and alphaV integrins on human endothelial cells; immobilised endostatin supports survival and migration, whereas soluble endostatin inhibits integrin-dependent migration [PMID:11158588]. Human endostatin competes with fibronectin and RGD cyclic peptide for alpha5beta1 binding and inhibits endothelial migration, not proliferation [PMID:12682293].","molecular_requirements":"The binder is the alpha5beta1 heterodimer; the receptor entry names ITGA5 alone [PMID:12682293]. Ligand is endostatin, the proteolytic C-terminal fragment of collagen XVIII, not intact COL18A1 [PMID:11158588].","affinity_potency":[],"species_and_systems":"Human endostatin and human endothelial cells; both papers read as abstracts only [PMID:11158588] [PMID:12682293]. BioGRID and IntAct list COL18A1-ITGB1 records [DB:BioGRID] [DB:IntAct].","localisation_and_range":"Ligand is a secreted proteolytic fragment (paracrine/autocrine); receptor is membrane-bound.","caveats":"Immobilised and soluble endostatin have opposite functional effects [PMID:11158588]. Both papers read as abstracts only. No affinity reported.","key_references":[{"PMID":"11158588","why":"Endostatin interacts with alpha5 and alphaV integrins on human endothelial cells"},{"PMID":"12682293","why":"Endostatin competes with RGD peptide to bind alpha5beta1"}],"covers":["LR000319","LR003825"]},"LR000328":{"pair":"COL1A1 -> ITGAV","headline":"One abstract-level paper: an alphav-containing complex on neuroblastoma cells mediates binding to type I collagen.","interaction_type":"direct binding","direction_and_effect":"An alphav-beta complex mediates binding to fibronectin and type I collagen in human neuroblastoma cells [PMID:1693626]. Annotated effect is stimulatory.","molecular_requirements":"The complex named in the abstract is alphav with a novel beta1-related subunit ('beta n'), not beta3; alphavbeta3 is reported to bind vitronectin [PMID:1693626]. ITGAV is annotated as integrin alphaVbeta3 [flag], which does not match.","affinity_potency":[],"species_and_systems":"Human neuroblastoma cell lines [PMID:1693626].","localisation_and_range":"COL1A1 is flagged secreted and not transmembrane [flag]; type I collagen is an extracellular matrix ligand, so signalling is by cell contact with matrix (inferred from the flag; not stated in the papers read).","caveats":"Abstract excerpt only (full text listed available). The collagen-binding complex is alphav-beta n, not alphavbeta3. No database support.","key_references":[{"PMID":"1693626","why":"alphav-containing integrin binds type I collagen on neuroblastoma cells"}],"covers":["LR000328","LR003834"]},"LR005116":{"pair":"COL1A2 -> GP6","headline":"Recombinant GPVI binds collagen; evidence is for collagen generally, from one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Recombinant GPVI bound collagen and convulxin, and soluble GPVI blocked collagen-induced platelet aggregation [PMID:10961879]. Annotated effect is stimulatory.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Recombinant human and mouse GPVI [PMID:10961879].","localisation_and_range":"GP6 is a platelet receptor; collagen is matrix [flag].","caveats":"Abstract-only. Evidence is for collagen generically, not resolved to COL1A2; type I collagen is a heterotrimer. No database support.","key_references":[{"PMID":"10961879","why":"GPVI binds collagen; soluble GPVI blocks aggregation"}],"covers":["LR001758","LR005116"]},"LR000337":{"pair":"COL2A1 -> ITGA10","headline":"Alpha10 was isolated from chondrocytes by collagen II affinity purification and cloned; strong binding evidence for the beta1 partnered chain, abstract-read.","interaction_type":"direct binding","direction_and_effect":"A novel collagen type II-binding integrin alpha subunit was isolated from bovine chondrocytes by collagen II affinity purification; the human alpha10 was cloned from a chondrocyte library [PMID:9685391]. Direction: collagen to integrin; 'Stimulatory' label in dossier [flag].","molecular_requirements":"Alpha10 is described as a new member of the beta1-integrin family, so ITGB1 pairing is expected; whether alpha10 alone binds is not reported in our evidence [PMID:9685391].","affinity_potency":[],"species_and_systems":"Bovine chondrocytes for purification, human cDNA for sequence [PMID:9685391]; mouse pair is ortholog-inferred.","localisation_and_range":"Matrix ligand, cell-surface receptor (flags); contact signalling inferred.","caveats":"Abstract read only; no affinity reported. Two further papers were abstract-insufficient.","key_references":[{"PMID":"9685391","why":"Alpha10 purified on collagen II and cloned"}],"covers":["LR000337","LR003843"]},"LR000346":{"pair":"COL4A1 -> ITGB1","headline":"Alpha1beta1 integrin recognition of collagen IV mapped structurally; ITGB1 stands for the heterodimer.","interaction_type":"direct binding","direction_and_effect":"A collagen IV fragment binds integrin alpha1beta1, and altering Arg(461) of alpha2(IV) and Asp(461) of alpha1(IV) abolished binding [PMID:8223488]. Database effect label is stimulatory.","molecular_requirements":"ITGB1 acts as the partner of alpha1 (alpha1beta1); both collagen chains contribute residues [PMID:8223488].","affinity_potency":[],"species_and_systems":"Purified type IV collagen fragments; species not stated in our evidence [PMID:8223488].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Abstract only; the paper concerns alpha1beta1, so ITGB1 alone is not shown to be sufficient. No affinity reported. Two other papers were abstract_insufficient.","key_references":[{"PMID":"8223488","why":"Maps alpha1beta1 recognition site on collagen IV"}],"covers":["LR000346","LR003852"]},"LR002407":{"pair":"COL4A3 -> ITGB3","headline":"COL4A3 NC1 binds alphaVbeta3 in two abstract-only papers; ITGB3 is the beta chain of that integrin.","interaction_type":"direct binding","direction_and_effect":"alpha3NC1 is bound by alpha(v)beta(3) and alpha(v)beta(5), predominantly via the RGD site [PMID:14610079]; alpha(v)beta(3) was identified as a receptor for the alpha3(IV) chain on tumour cells [PMID:10493512]. UniProt lists an ITGB3 interaction [DB:UniProt].","molecular_requirements":"The receptor is the alphaV:beta3 heterodimer [PMID:10493512]; the domain tested is NC1 or a peptide [PMID:14610079].","affinity_potency":[],"species_and_systems":"Recombinant human domain in HEK293 [PMID:14610079]; tumour cells, species unspecified [PMID:10493512].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Both abstract only; non-RGD peptides about 10-fold less potent than native protein [PMID:14610079]. One other paper abstract_insufficient.","key_references":[{"PMID":"14610079","why":"RGD site of alpha3NC1 binds alphaVbeta3"},{"PMID":"10493512","why":"alpha(v)beta(3) and CD47 as alpha3(IV) receptors"}],"covers":["LR002407","LR005686"]},"LR005701":{"pair":"COL5A3 -> DDR1","headline":"COL5A3-DDR1 binding reported in one 2026 TNBC paper; the 1997 DDR paper does not test it.","interaction_type":"direct binding","direction_and_effect":"A direct binding between DDR1 and COL5A3 was reported in MDA-MB-231 cells, with a DDR1/FAK/PI3K/AKT pathway [PMID:42310796]. The 1997 paper never tests COL5A3 [PMID:9659900].","molecular_requirements":"Not reported in our evidence beyond DDR1 as the receptor.","affinity_potency":[],"species_and_systems":"Human triple-negative breast cancer cell line MDA-MB-231 [PMID:42310796].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Single cell-line paper; the 1997 judged row is pair_absent; another review-only row. No affinity reported.","key_references":[{"PMID":"42310796","why":"COL5A3 binds DDR1 in TNBC cells"}],"covers":["LR002422","LR005701"]},"LR002425":{"pair":"COL8A1 -> SLC4A11","headline":"Mass spectrometry of an SLC4A11 extracellular-loop pull-down identified COL8A1 and COL8A2 peptides; supports binding but not shown with purified proteins.","interaction_type":"direct binding","direction_and_effect":"A GST fusion of SLC4A11 extracellular loop 3 (EL3) pulled down COL8A1 and COL8A2 peptides as the predominant interacting proteins by mass spectrometry [PMID:31691803]. SLC4A11 promoted cell adhesion to Descemet's membrane components, and an anti-EL3 antibody suppressed adhesion [PMID:31691803]. Here SLC4A11 acts as an adhesion receptor.","molecular_requirements":"EL3 of SLC4A11 is the Descemet's membrane binding site [PMID:31691803].","affinity_potency":[],"species_and_systems":"Transfected HEK293 cells and primary human corneal endothelial cells for adhesion; mouse pair is ortholog-inferred [PMID:31691803].","localisation_and_range":"Ligand flagged secreted [flag]; the receptor binds a basement membrane (Descemet's membrane), so adhesion to matrix rather than soluble signaling [PMID:31691803].","caveats":"Pull-down/mass spectrometry only; no affinity. SLC4A11 is a solute transporter, so its role as signaling receptor is not established in our evidence. Two other papers were abstract-insufficient.","key_references":[{"PMID":"31691803","why":"SLC4A11-EL3 pull-down identifies COL8A1/COL8A2; EL3 mediates adhesion"}],"covers":["LR002425","LR005704"]},"LR011182":{"pair":"COL9A1 -> SDC4","headline":"One 2026 abstract names COL9A1-SDC4 as a CAF-to-gastric-cancer-cell interaction; functional only.","interaction_type":"functional only","direction_and_effect":"ACTA2+ cancer-associated fibroblasts are reported to sustain metastasis-initiating cell identity through a COL9A1-SDC4 ligand-receptor interaction; functional assays confirmed that the axis drives migratory and invasive phenotypes of GC cells [PMID:41999506].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human gastric cancer cells and CAFs; single-cell and spatial transcriptomics with co-culture assays; abstract only [PMID:41999506].","localisation_and_range":"Ligand is flagged secreted and not transmembrane [flag]; collagen deposited in matrix is not addressed in our evidence beyond that. The interaction is described as fibroblast-to-tumor-cell signaling [PMID:41999506].","caveats":"Abstract only; binding not shown and the pair was first derived from cell-cell communication inference. No database support.","key_references":[{"PMID":"41999506","why":"COL9A1-SDC4 axis between CAFs and gastric cancer cells"}],"covers":["LR011182"]},"LR010615":{"pair":"COL9A2 -> MAG","headline":"Old solid-phase study shows soluble MAG binds collagen type IX; COL9A2 chain-level specificity is not resolved.","interaction_type":"direct binding","direction_and_effect":"Soluble MAG binds several collagens including type IX, with a kd of 5.7 X 10(-8) M for collagen type IX [PMID:2446864]. Binding of labelled MAG to collagen G was inhibited by unlabeled MAG and collagen G but not heat-denatured collagen [PMID:2446864]. Direction is receptor-to-collagen binding; signaling effect is not reported.","molecular_requirements":"The paper tested collagen type IX as a whole; whether the COL9A2 chain, or the intact heterotrimer, is required is not reported in our evidence [PMID:2446864].","affinity_potency":[{"value":"kd of 5.7 X 10(-8) M","assay":"solid-phase binding of soluble MAG to purified collagen type IX","system":"MAG from adult mouse brain","cite":"PMID:2446864"}],"species_and_systems":"Soluble MAG from adult mouse brain with purified collagens; the pair is listed as human [PMID:2446864].","localisation_and_range":"MAG flagged secreted and receptor [flag]; soluble MAG binds heparin and collagens, consistent with matrix binding [PMID:2446864].","caveats":"Single 1987 abstract; binding to type IX, not specific chains. Heparin and sulfated polysaccharides blocked MAG-collagen binding [PMID:2446864].","key_references":[{"PMID":"2446864","why":"Solid-phase binding of soluble MAG to collagens incl. type IX, with kd"}],"covers":["LR010615"]},"LR000364":{"pair":"COLQ -> MUSK","headline":"Single abstract-level report of ColQ binding MuSK at the neuromuscular junction; part of a proposed ternary complex.","interaction_type":"direct binding","direction_and_effect":"ColQ binds MuSK by cross-linking/immunoprecipitation and transfection of MuSK constructs; the authors propose MuSK helps anchor acetylcholinesterase (AChE) at the synapse. Effect on MuSK signalling is not reported in our evidence [PMID:15159418].","molecular_requirements":"ColQ clustering needs two heparin-binding sites in its collagen domain and its COOH terminus; a ColQ-perlecan-MuSK ternary complex is proposed, so this is not a simple pairwise interaction [PMID:15159418].","affinity_potency":[],"species_and_systems":"Cross-linking and immunoprecipitation in Torpedo postsynaptic membranes, plus MuSK constructs in MuSK-deficient myotubes or COS-7 cells; the curation lists human for both partners, and the mouse pair is ortholog-inferred [PMID:15159418].","localisation_and_range":"ColQ carries a secreted flag and is anchored in the synaptic basal lamina per the paper [flag][PMID:15159418].","caveats":"Only one paper, read as abstract-based; described by the authors as the first evidence of ColQ-MuSK binding; no affinity reported.","key_references":[{"PMID":"15159418","why":"First evidence that ColQ binds MuSK; ternary complex with perlecan proposed"}],"covers":["LR000364","LR003870"]},"LR005710":{"pair":"COMP -> CD36","headline":"COMP acts through CD36 to drive liver cancer cell proliferation and metastasis; functional evidence only, no binding shown.","interaction_type":"functional only","direction_and_effect":"Recombinant COMP increased HCC cell proliferation, invasion and migration; CD36 knockdown attenuated these effects and abrogated rCOMP-induced P-ERK and P-AKT upregulation, so CD36 is essential for COMP-driven MEK/ERK and PI3K/AKT signalling (agonist-like effect) [PMID:30231922].","molecular_requirements":"No co-receptor or subunit requirement reported in our evidence.","affinity_potency":[],"species_and_systems":"Human HCC cell lines (Hep-3B, SMMC-7721), nude-mouse orthotopic tumour model and patient sera; hepatic stellate cell (LX2) COMP was knocked down to show a paracrine source [PMID:30231922].","localisation_and_range":"COMP carries a secreted flag [flag]; the paper reports COMP secreted by hepatic stellate cells acting on HCC cells (paracrine) [PMID:30231922].","caveats":"Evidence is CD36 knockdown, not binding; physical COMP-CD36 binding is not shown, and the authors say further studies are needed. One paper.","key_references":[{"PMID":"30231922","why":"CD36 knockdown blocks rCOMP effects in HCC cells and in vivo"}],"covers":["LR002431","LR005710"]},"LR002434":{"pair":"COMP -> NOTCH1","headline":"COMP N-terminus binds the EGF11-12 region of Notch1 and activates it; one abstract-level paper using co-IP and two-hybrid.","interaction_type":"direct binding","direction_and_effect":"COMP's N-terminus directly interacted with Notch1 EGF11-12 and activated Notch1 signalling (co-immunoprecipitation, mammalian two-hybrid); Notch inhibition attenuated COMP-directed differentiation, and COMP deficiency inhibited Notch activation in mice [PMID:29981303].","molecular_requirements":"Notch1 was the main mediator among Notch receptors tested by silencing; no co-ligand requirement reported in our evidence [PMID:29981303].","affinity_potency":[],"species_and_systems":"Mouse embryonic stem cells differentiating to vascular smooth muscle, and COMP-deficient mice; human pair is ortholog-inferred [PMID:29981303].","localisation_and_range":"COMP carries a secreted flag [flag]; Notch1 is a transmembrane receptor [flag].","caveats":"Single paper read as abstract only; no affinity reported; effect shown in mouse systems.","key_references":[{"PMID":"29981303","why":"COMP N-terminus binds Notch1 EGF11-12 and activates signalling"}],"covers":["LR002434","LR005713"]},"LR000373":{"pair":"CRH -> CRHR2","headline":"CRH activates CRHR2 as an agonist with lower affinity than at CRHR1; supported by functional and binding papers.","interaction_type":"direct binding","direction_and_effect":"CRH is a full agonist at CRHR2 [DB:GtoPdb]. Human CRF2 receptor cells responded to rat/human CRF and sauvagine with increased cAMP [PMID:8536644]. Both hCRF1 and hCRF2(a) mobilised calcium in HEK293 cells but not in SK-N-MC cells [PMID:15450949]. UniProt says CRH acts on CRHR1 and to a lower extent CRHR2 [DB:UniProt].","molecular_requirements":"Not reported in our evidence beyond receptor-alone assays. The CRF2alpha form is the one tested; no human CRF2beta homolog evidence is reported [PMID:8536644].","affinity_potency":[{"value":"EC50 approximately 20 nM","assay":"cAMP accumulation with rat/human CRF","system":"cells transfected with human CRF2 receptor","cite":"PMID:8536644"},{"value":"pKd 6.5 to 7.400000095367432","assay":"GtoPdb curated affinity range","system":"GtoPdb record","cite":"DB:GtoPdb"},{"value":"pKd 5.9 to 6.9","assay":"GtoPdb curated affinity range","system":"GtoPdb record","cite":"DB:GtoPdb"}],"species_and_systems":"Human receptors in transfected cells (HEK293, others) [PMID:8536644, PMID:15450949]. The mouse pair is inferred from human evidence.","localisation_and_range":"CRH is flagged secreted and CRHR2 a receptor [flag].","caveats":"All papers read as abstracts only. CRH is less potent than sauvagine at CRF2 (EC50 approximately 1 nM) [PMID:8536644].","key_references":[{"PMID":"8536644","why":"Human CRF2 cloning with CRF cAMP response"},{"PMID":"11123370","why":"Binding to hCRF2alpha with different radioligands"},{"PMID":"15450949","why":"Calcium signalling by hCRF2(a) depends on cell type"}],"covers":["LR000373","LR003879"]},"LR001426":{"pair":"CRIPTO -> ACVR1C","headline":"Cripto reported to interact with ALK7 (ACVR1C) as a Nodal co-receptor; one abstract-level paper plus Reactome complexes.","interaction_type":"direct binding","direction_and_effect":"Cripto can independently interact with ALK7, and its expression greatly enhances ALK7 and ActRIIB responses to Nodal ligands [PMID:11485994]. Cripto acts as co-receptor, not as a signalling ligand [PMID:11485994].","molecular_requirements":"Reactome lists an ACVR1C:ACVR2B:EGF-CFC complex [DB:Reactome]. ALK7 responses to Nodal are enhanced by Cripto expression [PMID:11485994].","affinity_potency":[],"species_and_systems":"The paper used vertebrate developmental models (mouse tagged) [PMID:11485994]. The human pair is inferred from other species.","localisation_and_range":"CRIPTO is flagged secreted [flag]. Cripto is described as a co-receptor/co-factor for Nodal [PMID:11485994].","caveats":"Single paper, read as abstract only. No affinity. Not tested here in isolation from Nodal.","key_references":[{"PMID":"11485994","why":"Cripto interacts with ALK7 and enhances Nodal response"}],"covers":["LR001426","LR004821"]},"LR011209":{"pair":"CRLF1 -> LIFR","headline":"CRLF1 to LIFR rests on database records only; no confirmed paper evidence.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists CRLF1 as an agonist of LIFR with no affinity given [DB:GtoPdb]. UniProt says the CRLF1-CLCF1 heterodimer engages CNTFR, IL6ST and LIFR [DB:UniProt].","molecular_requirements":"The UniProt record describes CRLF1-CLCF1 acting at the CNTFR complex, which includes LIFR [DB:UniProt, DB:Reactome].","affinity_potency":[],"species_and_systems":"Human, as listed; no experiments in our evidence.","localisation_and_range":"CRLF1 is flagged secreted [flag].","caveats":"Papers are still pending and none is confirmed. Direct CRLF1-LIFR binding is not reported in our evidence; LIFR is a chain of the composite receptor.","key_references":[],"covers":["LR011209"]},"LR002443":{"pair":"CRP -> FCGR2A","headline":"SPR shows direct low-affinity CRP binding to Fc\u03b3RIIa; one paper plus one IntAct record.","interaction_type":"direct binding","direction_and_effect":"CRP bound immobilised Fc\u03b3RIIa in SPR sensorgrams [PMID:33790888]. Fc\u03b3RII blocking also affected IgG1-mediated cytotoxicity in neutrophil assays, though that readout overlaps with IgG binding [PMID:33790888]. IntAct lists a co-immunoprecipitation record for this pair [DB:IntAct].","molecular_requirements":"Single chain; both Fc\u03b3RIIa H/R131 variants bound similarly [PMID:33790888].","affinity_potency":[{"value":"KD 3.4\u20134.9 \u03bcM","assay":"SPR array (shared range for Fc\u03b3RIa, IIa/b, IIIa)","system":"recombinant human proteins","cite":"PMID:33790888"}],"species_and_systems":"Human recombinant receptors and human effector cells [PMID:33790888]. IntAct experiment details beyond the method are not reported [DB:IntAct].","localisation_and_range":"CRP is flagged as secreted and the receptor as a receptor [flag]; CRP would act as a soluble (paracrine/endocrine) ligand on receptor-bearing cells (inferred from flags only).","caveats":"Single primary paper. The KD range is given for several receptors together, not Fc\u03b3RIIa alone [PMID:33790888]. Database record is IntAct only [DB:IntAct].","key_references":[{"PMID":"33790888","why":"SPR array showing CRP binding to Fc\u03b3RIIa"}],"covers":["LR002443"]},"LR008203":{"pair":"CSPG4 -> ITGA4:ITGB1","headline":"Database-asserted only: UniProt notes CSPG4 chondroitin sulfate interacting with ITGA4; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt records that ITGA4 interacts with CSPG4 through its chondroitin sulfate glycosaminoglycan, and CSPG4 with ITGA4 likewise [DB:UniProt]. Effect not reported in our evidence.","molecular_requirements":"The interaction is described via the CSPG4 glycosaminoglycan chain [DB:UniProt]; need for ITGB1 is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence.","localisation_and_range":"CSPG4 flagged secreted and transmembrane [flag].","caveats":"No confirmed papers; one paper was abstract_insufficient. Support rests on UniProt annotations only [DB:UniProt].","key_references":[],"covers":["LR008203"]},"LR002452":{"pair":"CTLA4 -> CD86","headline":"CTLA4 targets CD86 for transendocytosis; co-crystal structure and database support; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"CTLA-4 removes CD86 from donor cells by transendocytosis; with CD86, CTLA-4 detaches pH-dependently and recycles to the cell surface to permit further transendocytosis [PMID:35999394]. UniProt describes CTLA4 as a decoy receptor binding CD80 and CD86 more strongly than CD28 [DB:UniProt].","molecular_requirements":"Autoimmune-disease mutations selectively disrupt CD86 transendocytosis by affecting CTLA-4 recycling or CD86 binding [PMID:35999394]. A co-crystal structure exists [DB:PDB 1I85].","affinity_potency":[],"species_and_systems":"CHO cells, Jurkat T cells and human Treg cells [PMID:35999394]; mouse pair ortholog-inferred.","localisation_and_range":"Both partners flagged receptor/transmembrane [flag]; transendocytosis requires cell-cell contact between donor and CTLA-4 recipient cells [PMID:35999394].","caveats":"Paper's assay is functional (transendocytosis), not a binding measurement; its curated direction label is agonist although CTLA-4 acts here as a ligand-removing inhibitory receptor. No affinity in our evidence.","key_references":[{"PMID":"35999394","why":"CD86 transendocytosis by CTLA-4 with recycling"}],"covers":["LR002452","LR005728"]},"LR008500":{"pair":"CTSG -> F2R","headline":"Cathepsin G activates PAR1 on human platelets at low dose per one abstract-read paper; UniProt says effect depends on cleavage site.","interaction_type":"functional only","direction_and_effect":"At 0.05 U/mL cathepsin G activated washed human platelets via PAR1; at 0.35 U/mL aggregation occurred via PAR4 [PMID:35054930]. UniProt says cathepsin G cleaves F2R and acts as an agonist or an inhibitor depending on the cleavage site [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Washed human platelets; no aggregation by cathepsin G in Swiss mouse platelet-rich plasma at 0.4 U/mL [PMID:35054930].","localisation_and_range":"CTSG flagged secreted [flag]; acts as a protease on a cell-surface receptor.","caveats":"Abstract only. In human and murine blood, aggregation at 0.05-0.1 U/mL was not PAR-mediated and was attributed to released ADP [PMID:35054930]. Another paper was different_entity and two were abstract_insufficient. Dose in U/mL, no affinity.","key_references":[{"PMID":"35054930","why":"Cathepsin G activates platelets via PAR1 at 0.05 U/mL"}],"covers":["LR008500"]},"LR000391":{"pair":"CX3CL1 -> CX3CR1","headline":"Well-supported direct binding and agonism of CX3CR1 by the CX3CL1 chemokine domain, shown by mutagenesis, NMR and binding assays in human systems.","interaction_type":"direct binding","direction_and_effect":"CX3CL1 is an agonist of CX3CR1; it induces adhesion and migration, with migration needing pertussis toxin-sensitive G protein signalling and adhesion not [PMID:9390561]. Mutants separate binding from signalling: R48A binds but cannot induce chemotaxis, F50A shows no detectable binding [PMID:11432858]. An NMR titration with an N-terminal CX3CR1 peptide showed this receptor region contacts the chemokine domain [PMID:9931005]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"The chemokine domain alone is sufficient for signalling and binds CX3CR1 [PMID:23125415]. That paper also reports that integrins alphavbeta3 and alpha4beta1 form a ternary complex with CX3CL1 and CX3CR1, and that an integrin-binding-defective mutant is an antagonist of CX3CR1 (title) [PMID:23125415]. Three CX3CR1 isoforms (standard and two N-terminally extended) bound CX3CL1 with similar steady-state affinity but different kinetics [PMID:14607932].","affinity_potency":[{"value":"pIC50 8.9","assay":"affinity value recorded by curators for the CX3CR1 isoform study; GtoPdb lists pIC50 units","system":"human CX3CR1 isoforms in HEK-293 cells","cite":"PMID:14607932"}],"species_and_systems":"Experiments are human ligand and human receptor, using recombinant proteins and transfected cells; mouse pair is projected from human evidence (ortholog inferred). Structures are listed in PDB 7XBX [DB:PDB 7XBX].","localisation_and_range":"Ligand carries both secreted and transmembrane flags [flag]; papers describe fractalkine as membrane-tethered with a chemokine domain atop a mucin stalk, acting in adhesion and migration (juxtacrine) [PMID:9390561].","caveats":"Four of the five shown papers were read as abstract only. The pIC50 value is a curator field not quoted in the abstract text. No mouse-specific experiments are reported in our evidence.","key_references":[{"PMID":"9390561","why":"Original identification of the high-affinity receptor mediating adhesion and migration"},{"PMID":"11432858","why":"Mutagenesis separating binding from signalling residues"},{"PMID":"23125415","why":"Integrin co-receptor ternary complex with CX3CR1"}],"covers":["LR000391","LR003897"]},"LR003901":{"pair":"CXCL11 -> ACKR3","headline":"CXCL11 binds and signals via arrestin at ACKR3, an atypical scavenger receptor; supported by binding, mutagenesis and functional papers, mostly abstract-read.","interaction_type":"direct binding","direction_and_effect":"ACKR3 (CXCR7) binds CXCL11 with high affinity as a second ligand beside CXCL12; 125I-labelled CXCL11 and CXCL12 compete each other on cells [PMID:16940167]. ACKR3 does not trigger G-protein activation but recruits arrestin and internalises and degrades CXCL11, so it scavenges the chemokine [PMID:29180449][PMID:20161793]. Ca2+ mobilisation or migration was not caused by ligand activation [PMID:16940167]. CXCL11 caused beta-arrestin 2 recruitment comparable in efficacy to CXCL12 [PMID:29386406]. GtoPdb lists CXCL11 as a full agonist [DB:GtoPdb].","molecular_requirements":"Single receptor chain. CXCL11 primary binding depends on the ACKR3 N terminus and some extracellular-loop positions, with a binding mode different from CXCL12 [PMID:27875312]. An N-terminally truncated CXCL11 (3-73) had reduced potency and efficacy for arrestin recruitment [PMID:29386406].","affinity_potency":[{"value":"EC50 2.9 nM","assay":"beta-arrestin 2 recruitment (PRESTO-Tango)","system":"human ACKR3, cell system","cite":"PMID:29386406"},{"value":"IC50 39.1 nM","assay":"125I-CXCL12 displacement by unlabelled CXCL11 (wild-type ACKR3, table)","system":"cells expressing ACKR3-YFP","cite":"PMID:29180449"}],"species_and_systems":"Human ligand and receptor in transfected or cultured cells (MCF-7, MDA MB 435s transfectants, 293 cells) [PMID:16940167][PMID:29386406]; the mouse interaction is listed but no mouse-specific experiment is shown.","localisation_and_range":"CXCL11 is flagged secreted and ACKR3 as a transmembrane receptor [flag], so paracrine action on membrane ACKR3.","caveats":"Four of five papers were read as abstracts only. ACKR3 is atypical: no G-protein signalling, mainly scavenging and arrestin recruitment. Little CXCR7 down-regulation was seen on cells after CXCL12 in one paper [PMID:20161793]. The 29386406 data are CXCL11 (3-73) comparisons within a vascular study.","key_references":[{"PMID":"16940167","why":"Shows CXCL11 binds CXCR7 with high affinity by competition binding (full text)"},{"PMID":"27875312","why":"Mutational mapping of CXCL11 binding to ACKR3"},{"PMID":"29386406","why":"Arrestin recruitment EC50 for CXCL11 at ACKR3"}],"covers":["LR000395","LR003901"]},"LR002461":{"pair":"CXCL11 -> CCR5","headline":"CXCL11 (I-TAC) antagonises CCR5 in one abstract-read paper; single-source evidence.","interaction_type":"direct binding","direction_and_effect":"I-TAC inhibited binding of MIP-1alpha/CCL3 to CCR5-transfected cells and monocytes, and inhibited cell migration evoked by RANTES/CCL5 and MIP-1beta/CCL4; it reduced CCR5-mediated calcium release and actin polymerization to minimal levels [PMID:15178708]. Antagonist, not agonist.","molecular_requirements":"Sequence and structure analyses suggest K17, K49 and Q51 of I-TAC may contribute to CCR5 binding; not tested directly in the abstract [PMID:15178708].","affinity_potency":[],"species_and_systems":"Human ligand and receptor; CCR5-transfected cells and monocytes [PMID:15178708].","localisation_and_range":"CXCL11 flagged secreted, CCR5 transmembrane [flag]; paracrine.","caveats":"One paper, read as abstract only; no affinity reported; no database support in our evidence.","key_references":[{"PMID":"15178708","why":"Reports CXCL11 antagonism of CCR5"}],"covers":["LR002461"]},"LR005125":{"pair":"CXCL12 -> ITGA4","headline":"One abstract-only 2018 paper: CXCL12 binds integrin allosteric site 2 and activates integrin alpha4beta1 independently of CXCR4.","interaction_type":"direct binding","direction_and_effect":"Integrin activation was shown by direct binding to the allosteric site 2: SDF1 activated soluble integrin alphavbeta3 in cell-free conditions and the site 2 peptide bound SDF1 [PMID:29301984]. SDF1 activated integrin alpha4beta1 on CXCR4-negative CHO cells, suppressed by site 2 peptide and not by AMD3100 [PMID:29301984]. Effect is activating. UniProt agrees [DB:UniProt].","molecular_requirements":"The binding unit appears to be the alpha/beta heterodimer, not ITGA4 alone; the paper tested alphavbeta3, alpha4beta1 and alpha5beta1 [PMID:29301984]. Proteoglycan binding of SDF1 is proposed to facilitate activation. Mutations in SDF1's predicted site 2 binding region suppressed activation.","affinity_potency":[],"species_and_systems":"Cell-free soluble integrin and CHO cells; species labelled human by the curator, not stated in the abstract. The mouse pair is projected from human.","localisation_and_range":"CXCL12 is flagged secreted [flag]; activation was proposed for SDF1 presented on proteoglycans [PMID:29301984].","caveats":"Abstract only; one paper from one group; no affinity reported. Receptor is a heterodimer and CCC tools may score subunits separately.","key_references":[{"PMID":"29301984","why":"Only paper: CXCL12 site 2 integrin activation"}],"covers":["LR001768","LR005125"]},"LR003910":{"pair":"CXCL16 -> CXCR6","headline":"Well-established pair: CXCL16 binds CXCR6 with high affinity and drives chemotaxis and signalling, across several papers.","interaction_type":"direct binding","direction_and_effect":"Expression cloning identified Bonzo (CXCR6) as a CXCL16 receptor [PMID:11017100]. Recombinant CXCL16 gave chemotaxis, high-affinity binding and calcium mobilisation only in Bonzo transfectants, negative on all other chemokine receptor transfectants tested [PMID:11290797]. In human aortic smooth muscle cells CXCL16 activated NF-kappa B through Gi, PI3K and Akt [PMID:14625285]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"CXCR6 alone suffices in transfectants [PMID:11290797]. CXCL16 binds CXCR6 and scavenger-receptor ligands through overlapping motifs in the chemokine domain [PMID:15128749].","affinity_potency":[{"value":"pKd 9.0","assay":"binding to Bonzo (CXCR6) transfectants","system":"transfected cells","cite":"PMID:11290797"}],"species_and_systems":"Human cells in the cited work; mouse pair is projected from human. T cells and tonsil CD4+ lymphocytes migrated to CXCL16 [PMID:11290797]; smooth muscle cells in [PMID:14625285].","localisation_and_range":"CXCL16 is a transmembrane chemokine with membrane-bound and soluble shed forms [PMID:11017100]; flagged secreted and transmembrane [flag]. Juxtacrine and paracrine action are both possible.","caveats":"All papers read as abstracts only. Five of eight confirmed papers shown. The scavenger-receptor overlap [PMID:15128749] is a different activity. Reactome records binding [DB:Reactome].","key_references":[{"PMID":"11017100","why":"Identifies CXCR6 as CXCL16 receptor by expression cloning"},{"PMID":"11290797","why":"High-affinity binding, chemotaxis and calcium flux with panel specificity"},{"PMID":"14625285","why":"CXCL16-CXCR6 signalling to NF-kappa B in smooth muscle cells"}],"covers":["LR000405","LR003910"]},"LR002470":{"pair":"CXCL2 -> ACKR1","headline":"One abstract-only mouse intravital paper shows neutrophil junctional breaching by CXCL2 depends on ACKR1; no binding data.","interaction_type":"functional only","direction_and_effect":"In cytokine-stimulated mouse cremaster muscle, neutrophil-derived CXCL2 was critical for breaching endothelial junctions, and this activity depended on ACKR1, enriched within endothelial junctions [PMID:30446388]. Transmigrating neutrophils created a junctional chemokine depot of ACKR1-presented CXCL2, enabling unidirectional luminal-to-abluminal migration [PMID:30446388].","molecular_requirements":"Not reported in our evidence; ACKR1 acts as a presenting receptor, with no signalling reported.","affinity_potency":[],"species_and_systems":"Mouse in vivo (confocal intravital microscopy); the human pair is projected from mouse [PMID:30446388].","localisation_and_range":"Soluble chemokine presented on endothelial junctions by a transmembrane receptor [PMID:30446388]; CXCL2 flagged secreted [flag].","caveats":"Single paper read as abstract; no direct binding or affinity reported in our evidence. The human pair is inferred, not tested.","key_references":[{"PMID":"30446388","why":"Intravital evidence of ACKR1-dependent CXCL2 activity at endothelial junctions"}],"covers":["LR002470","LR005744"]},"LR000409":{"pair":"CXCL2 -> CXCR1","headline":"Weak or indirect support: low-affinity binding and a functional readout, with an explicit report that CXCR1 is selective for IL-8.","interaction_type":"conflicting","direction_and_effect":"CXCL2 acts as an agonist for ASMC migration; in asthmatic cells migration is mainly PI3K-mediated through CXCR1, whereas normal-cell CXCL2 migration depended on p38 MAPK and CXCR2 [PMID:23904157].","molecular_requirements":"Not reported in our evidence beyond receptor-dependence by neutralizing antibody/siRNA [PMID:23904157].","affinity_potency":[{"value":"Kd > 120 nM","assay":"binding of recombinant murine MIP-2 to human type A IL-8 receptor","system":"recombinant, human receptor","cite":"PMID:9260277"}],"species_and_systems":"Human primary airway smooth muscle cells (normal and asthmatic) [PMID:23904157]; HEK293 transfectants for the other papers. Murine MIP-2 was tested on human receptors [PMID:9260277].","localisation_and_range":"Ligand is flagged secreted and receptor flagged transmembrane [flag], so paracrine signalling to a cell-surface receptor is implied; paper text does not address range.","caveats":"An abstract-read paper states IL-8RA (CXCR1) is selective only for IL-8 and counted as a verified negative for this pair [PMID:8550564]. GRO-family chemokines competed only weakly at IL8RA [PMID:8702798]. The mouse ligand showed low-affinity binding to type A receptor [PMID:9260277]. The positive CXCR1 evidence for CXCL2 is a functional, abstract-only report. All papers abstract-only.","key_references":[{"PMID":"23904157","why":"CXCL2 migration of ASMCs; CXCR1 role in asthmatic cells"},{"PMID":"9260277","why":"Kd > 120 nM at type A receptor"},{"PMID":"8550564","why":"Reports CXCR1 selective only for IL-8"}],"covers":["LR000409","LR003911"]},"LR000922":{"pair":"CXCL8 -> CXCR2","headline":"CXCL8 (IL-8) binds and activates CXCR2 with high affinity; strongly supported by binding, potency data, structures and database records.","interaction_type":"direct binding","direction_and_effect":"CXCL8 is an agonist of CXCR2 (stimulatory). In HEK293 cells CXCR2 responded to IL-8 in calcium flux, and all six ELR+ chemokines tested competed for 125I-IL-8 binding at CXCR2 [PMID:8702798]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"CXCR2 alone suffices in transfected cells; no co-receptor reported in our evidence. CXCR2 binds IL-8 and other ELR+ chemokines (broader than CXCR1 for GROalpha) [PMID:8702798].","affinity_potency":[{"value":"pKi 9.27","assay":"[125I]-IL-8 competition binding","system":"CHO cells expressing HA-tagged human CXCR2","cite":"PMID:10188995"},{"value":"EC50 4 nM","assay":"calcium flux, IL-8","system":"receptor-transfected HEK293 cells","cite":"PMID:8702798"},{"value":"Kd ~2 nM","assay":"IL-8 binding","system":"IL-8R-B expressed in mammalian cells","cite":"PMID:1379593"}],"species_and_systems":"Human ligand and receptor; recombinant cells (CHO, HEK293, Jurkat, Xenopus oocytes) and one neutrophil study [PMID:11511101]. Mouse not reported.","localisation_and_range":"Soluble chemokine acting on a transmembrane receptor [flag].","caveats":"All papers were abstract-only reads. PMID:11511101 used neutrophils expressing both CXCR1 and CXCR2, so receptor resolution is indirect. PMID:15282370 mentions the pair only as background. A BioGRID reconstituted-complex record, IntAct SPR and scintillation proximity records, and PDB structures (6LFM, 8XWN) also exist [DB:BioGRID] [DB:IntAct] [DB:PDB 6LFM].","key_references":[{"PMID":"10188995","why":"competition binding in CHO cells"},{"PMID":"8702798","why":"potency rank order at CXCR2 in HEK293"},{"PMID":"1891716","why":"expression cloning of the receptor"}],"covers":["LR000922"]},"LR000418":{"pair":"CXCL9 -> CCR3","headline":"CXCL9 (Mig) acts as an antagonist of CCR3, binding and blocking eotaxin responses, not activating it; abstract-level evidence.","interaction_type":"direct binding","direction_and_effect":"Antagonist. Mig, I-TAC and IP10 competed for eotaxin binding to CCR3-bearing cells and inhibited eotaxin-induced migration and Ca2+ changes; none of the three induced CCR3 internalisation, so they act as pure antagonists [PMID:11110785]. GtoPdb lists an antagonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human chemokines on CCR3-bearing cells; human experiment species per curators [PMID:11110785]. Mouse pair is ortholog-inferred.","localisation_and_range":"Secreted ligand, transmembrane receptor [flag].","caveats":"Abstract-only reads. No affinity for CXCL9 at CCR3 is reported in our evidence. The paper's abstract names I-TAC, Mig and IP10 together, so CXCL9-specific numbers are not reported. One additional paper was review-only.","key_references":[{"PMID":"11110785","why":"CXCR3 agonists compete with eotaxin at CCR3, pure antagonists"}],"covers":["LR000418","LR003915"]},"LR000427":{"pair":"DCN -> MET","headline":"Decorin binds Met directly with high affinity and drives Met degradation; one paper with excerpts.","interaction_type":"direct binding","direction_and_effect":"Antagonist overall: transient Met activation, c-Cbl recruitment and rapid Met degradation, suppression of beta-catenin and of Met-mediated migration and growth [PMID:19433454].","molecular_requirements":"Not reported in our evidence beyond Met itself.","affinity_potency":[{"value":"Kd~1.5 nM","assay":"direct binding, displaced by HGF","system":"decorin-Met","cite":"PMID:19433454"}],"species_and_systems":"Human HeLa cells (100 nM recombinant decorin) with phospho-RTK arrays [PMID:19433454]. Mouse pair is ortholog-projected.","localisation_and_range":"Decorin flagged secreted; MET transmembrane receptor [flag].","caveats":"Single paper; also displaced less efficiently by internalin B. BioGRID records affinity capture and reconstituted complex [DB:BioGRID 677024]. One abstract-insufficient row not shown.","key_references":[{"PMID":"19433454","why":"High-affinity Met binding and degradation"}],"covers":["LR000427","LR003924"]},"LR000436":{"pair":"DHH -> CDON","headline":"Structural evidence (PDB 3N1Q) that DHH binds CDON; positive modulator role, abstract-level.","interaction_type":"direct binding","direction_and_effect":"x-ray structures of Sonic, Indian and Desert Hh alone and in complex with the active domains of CDO and BOC show all mammalian Hh proteins bind CDO and BOC in the same manner [PMID:20519495]. Database records agree: PDB 3N1Q (DhhN bound to CDOFn3) [DB:PDB 3N1Q], IntAct x-ray crystallography [DB:IntAct], UniProt subunit annotation [DB:UniProt]. The abstract notes that CDO and BOC positively regulate Hh signalling, but this is background and not measured for DHH here [PMID:20519495].","molecular_requirements":"The N-terminal signalling domain of DHH (DhhN) binds the CDON fibronectin domain in the structure [DB:PDB 3N1Q]. Whether Patched is also needed is not reported for this pair.","affinity_potency":[],"species_and_systems":"Mammalian proteins in a crystal; the species of the recombinant proteins is not stated in the abstract [PMID:20519495]. The mouse row is projected by orthology (ortholog_inferred) [flag].","localisation_and_range":"DHH is flagged both secreted and transmembrane [flag]; membrane tethering is therefore suggested only by an annotation flag, and contact-dependent versus diffusible action is not reported in our evidence.","caveats":"Abstract only. Affinity for DHH is not given in the abstract; micromolar affinities are cited for Ihog and for CDO with Sonic Hh as background [PMID:20519495]. Crystal binding does not show signalling effect for DHH.","key_references":[{"PMID":"20519495","why":"Crystal structures of Hh proteins with CDO and BOC"}],"covers":["LR000436","LR003928"]},"LR005134":{"pair":"DKK2 -> KREMEN1","headline":"Direct Kremen1-Dkk2 interaction implied in zebrafish; one abstract-only paper, indirect evidence.","interaction_type":"functional only","direction_and_effect":"EpCAM directly binds Kremen1 and disrupts the Kremen1-Dickkopf2 (Dkk2) interaction, which prevents Kremen1-Dkk2-mediated removal of Lrp6 from the cell surface [PMID:23484855].","molecular_requirements":"Kremen1-Dkk2 acts to remove Lrp6 from the surface; EpCAM antagonises this [PMID:23484855].","affinity_potency":[],"species_and_systems":"Zebrafish (hi2151/epcam mutants) [PMID:23484855]; human and mouse pairs are both ortholog-inferred.","localisation_and_range":"DKK2 flagged secreted; KREMEN1 flagged receptor [flag].","caveats":"The direct binding reported in the abstract is EpCAM-Kremen1; Dkk2-Kremen1 interaction is stated as background to the model. Abstract only; one further row also confirmed from the same context.","key_references":[{"PMID":"23484855","why":"EpCAM disrupts Kremen1-Dkk2 interaction in zebrafish"}],"covers":["LR001778","LR005134"]},"LR000445":{"pair":"DKK2 -> LRP6","headline":"DKK2 binds LRP6 and can act as antagonist or agonist depending on context; supported by binding and functional papers, mostly abstract-read.","interaction_type":"direct binding","direction_and_effect":"One paper reports LRP6 as a specific, high-affinity receptor for Dkk1 and Dkk2, with Dkk1 blocking Wnt/beta-catenin signalling [PMID:11357136]. Dkk2 itself is context-dependent: it activates LRP6 signalling in human 293 cells [PMID:12527209], its second cysteine-rich domain stimulates the canonical pathway when LRP-6 is ectopically expressed and this is blocked by an anti-LRP-5/6 antibody [PMID:11742004], and Dkk2 knockdown in Xenopus embryos loses neural crest, rescued by Lrp6 [PMID:30035713].","molecular_requirements":"Kremen2 co-transfection blocks Dkk2 activation of LRP6 and turns Dkk2 into a Wnt inhibitor; Krm2 interaction is mediated by the second cysteine-rich domain of Dkks [PMID:12527209]. Which cofactor is present therefore changes the sign of the effect.","affinity_potency":[],"species_and_systems":"Human and mouse pair entries. Experiments: human/mouse proteins in mammalian cells and Xenopus embryos [PMID:11357136]; human 293 cells [PMID:12527209]; NIH3T3 cells [PMID:11742004]; Xenopus embryos [PMID:30035713]. IntAct also lists a bio-layer interferometry record [DB:IntAct].","localisation_and_range":"DKK2 is flagged secreted and LRP6 as a transmembrane receptor [flag], so paracrine action on cell-surface LRP6 is implied.","caveats":"Three of four shown papers were read as abstract only. Direction conflicts across papers (antagonist vs agonist). The Xenopus paper shows genetic rescue, not binding. No affinity value reported in our evidence.","key_references":[{"PMID":"11357136","why":"LRP6 as high-affinity receptor for Dkk1 and Dkk2"},{"PMID":"12527209","why":"Dkk2 agonist on LRP6; switched by Kremen2"},{"PMID":"11742004","why":"Dkk-2 second cysteine-rich domain stimulates via LRP-6"}],"covers":["LR000445","LR003937"]},"LR000454":{"pair":"DLL4 -> NOTCH4","headline":"Two functional abstract-only papers in human endothelial cells; no binding data.","interaction_type":"functional only","direction_and_effect":"Delta4 functioned as an activating ligand for endogenous Notch4 in an in vitro co-culture assay in primary human dermal microvascular endothelial cells [PMID:12814948]. Dll4 is described as a membrane-bound ligand for Notch1 and Notch4 [PMID:16219802].","molecular_requirements":"Notch4 on these cells is a heterodimeric form [PMID:12814948]. Reactome lists a DLL4:NOTCH4 complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Primary human endothelial cells (HMVECd, HUVEC) [PMID:12814948][PMID:16219802].","localisation_and_range":"Both partners annotated transmembrane, DLL4 not secreted [flag]; the assay was a cell-cell co-culture [PMID:12814948].","caveats":"Abstracts only. The second paper (PMID 16219802) states Notch4 as a ligand target in its background sentence while its experiments concern Dll4 overexpression and Notch pathway output generally. Two papers are still pending.","key_references":[{"PMID":"12814948","why":"Delta4 activates Notch4 in co-culture"},{"PMID":"16219802","why":"Dll4 overexpression in endothelial cells"}],"covers":["LR000454"]},"LR005143":{"pair":"Dsc2 -> Dsg1a","headline":"Mouse pair projected from human data; SPR on human ectodomains showed heterophilic Dsg-Dsc binding.","interaction_type":"direct binding","direction_and_effect":"Dsg passed over a Dsc surface, or a Dsc over a Dsg surface, showed binding responses indicative of strong heterophilic interaction [PMID:27298358].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"KD 3.6-43.9 uM","assay":"SPR (Biacore T100), all pairwise human Dsg/Dsc combinations; range across pairs, not specific to this pair","system":"human ectodomains","cite":"PMID:27298358"}],"species_and_systems":"Human proteins; the mouse pair is ortholog-inferred [PMID:27298358].","localisation_and_range":"Not annotated for these mouse entities in our evidence.","caveats":"Browser-read full text, quote unverifiable, spot-check pending. Affinity is a range over all pairs; no mouse experiments.","key_references":[{"PMID":"27298358","why":"SPR of Dsc/Dsg ectodomains"}],"covers":["LR005143"]},"LR005152":{"pair":"DSG2 -> DSC1","headline":"DSG2 -> DSC1: heterophilic desmosomal cadherin binding, supported by a single family-wide paper.","interaction_type":"direct binding","direction_and_effect":"The paper reports that all desmogleins form adhesive dimers with all desmocollins, with affinities characteristic of each Dsg:Dsc pair, so this pair is covered by the family-wise heterophilic result [PMID:27298358]. Binding is trans-cellular and heterodimers are called the fundamental adhesive unit of desmosomes [PMID:27298358].","molecular_requirements":"Ectodomains of one Dsg and one Dsc are sufficient for dimer formation in the reported solution biophysics and bead aggregation; binding uses a strand-swap mechanism with charge-based heterophilic preference [PMID:27298358]. No further subunits or co-receptors reported.","affinity_potency":[],"species_and_systems":"Experiments used human proteins (solution biophysics, SPR and coated-bead aggregation) [PMID:27298358]. Pair is recorded for: human, mouse (ortholog-projected). The mouse entry is projected from human evidence.","localisation_and_range":"Membrane-bound desmosomal cadherins acting in trans between adjacent cells (juxtacrine/contact) [PMID:27298358]; entity flags mark both as receptors and transmembrane where set [flag].","caveats":"Curators read only the abstract; the paper's family-wide statement is applied to this pair, one of 25 companion rows, and no pair-specific affinity is in our dossier. The crystal structures cited cover Dsg2, Dsg3, Dsc1 and Dsc2 only [PMID:27298358]. Database records also exist (BioGRID, IntAct), which are not independent of the evidence above. [DB:BioGRID] [DB:IntAct]","key_references":[{"PMID":"27298358","why":"Family-wise Dsg:Dsc heterophilic binding by biophysics, SPR, bead aggregation and crystal structures"}],"covers":["LR001796","LR005152"]},"LR002506":{"pair":"DSG4 -> DSC1","headline":"Heterophilic DSG4:DSC1 binding by SPR from one paper; full text read by browser, quote unverifiable.","interaction_type":"direct binding","direction_and_effect":"SPR of human Dsg and Dsc ectodomains in all pairwise combinations showed strong heterophilic binding when a Dsg was passed over a Dsc surface or vice versa [PMID:27298358].","molecular_requirements":"Ectodomain-level binding; strand-swap mechanism and charge-based heterophilic preference described in the abstract [PMID:27298358].","affinity_potency":[{"value":"KD 3.6-43.9 uM","assay":"SPR (Biacore T100), all pairwise Dsg/Dsc combinations","system":"human ectodomains","cite":"PMID:27298358"}],"species_and_systems":"Human recombinant ectodomains; mouse pair is ortholog-inferred.","localisation_and_range":"Both partners are flagged as non-secreted receptors, so this is membrane-bound, contact-dependent (juxtacrine) adhesion [flag].","caveats":"The KD range spans all pairwise combinations, not DSG4:DSC1 alone. The curator note says the browser-read quote is unverifiable with spot-check pending.","key_references":[{"PMID":"27298358","why":"SPR of Dsg:Dsc heterophilic binding"}],"covers":["LR002506","LR005774"]},"LR000463":{"pair":"EDN2 -> EDNRB","headline":"ET-2 binds the non-selective ETB receptor by inference from one cloning paper; little else.","interaction_type":"direct binding","direction_and_effect":"The cloning paper defines ETB as binding ET-1, ET-2 and ET-3 with comparable affinity [PMID:2175397]; the effect is recorded as agonist.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human receptor cloned and expressed in cells [PMID:2175397]. Both species pairs are ortholog-inferred. Reactome lists EDNRA/EDNRB binding EDNs [DB:Reactome R-HSA-388560].","localisation_and_range":"ET-2 is annotated secreted and EDNRB transmembrane [flag].","caveats":"Single paper, read as abstract only; the ET-2 statement is a class statement about all three isopeptides rather than an ET-2 measurement shown in the dossier.","key_references":[{"PMID":"2175397","why":"ETB cloned as binding all three endothelins"}],"covers":["LR000463","LR003954"]},"LR000472":{"pair":"EFNA1 -> EPHA6","headline":"Database-asserted only: UniProt lists EphA receptors including EPHA6 as EFNA1 binders; no papers judged.","interaction_type":"database-asserted only","direction_and_effect":"UniProt SUBUNIT states EFNA1 binds EPHA2, EPHA3, EPHA4, EPHA5, EPHA6 and EPHA7 [DB:UniProt PMID:18794797]. Effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experimental species not reported in our evidence; human pair is ortholog-inferred, mouse is not.","localisation_and_range":"EFNA1 annotated secreted and transmembrane [flag]; no paper text on localisation.","caveats":"No curated paper evidence; support is a single UniProt annotation.","key_references":[],"covers":["LR000472","LR003963"]},"LR000481":{"pair":"EFNA2 -> EPHA7","headline":"Ephrin-A2 binds EphA7 in rat striatal lysates; one abstract-read paper plus BioGRID.","interaction_type":"direct binding","direction_and_effect":"Ephrin-A2, ephrin-A3 and ephrin-A5 bind EphA7 but not EphA4 in striatal tissue binding assays [PMID:10366629].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Rat striatal lysates [PMID:10366629]; BioGRID affinity capture-western [DB:BioGRID]. Human pair ortholog-inferred.","localisation_and_range":"EFNA2 annotated transmembrane, EPHA7 secreted and transmembrane [flag].","caveats":"One paper, read as abstract only; no affinity values.","key_references":[{"PMID":"10366629","why":"ephrin-A2 binds EphA7 in rat striatum"}],"covers":["LR000481","LR003972"]},"LR002515":{"pair":"EFNA4 -> EPHA10","headline":"Exogenous ephrin-A4 drives EPHA10-dependent migration and stemness in oral cancer cells; functional only.","interaction_type":"functional only","direction_and_effect":"Among EPHA10 ligands, exogenous EFNA4 induced the most OSCC cell migration and sphere formation and up-regulated SNAIL, NANOG and OCT4; EPHA10 was required for these effects, which were abolished by ERK inhibition [PMID:33436772].","molecular_requirements":"EPHA10 required for EFNA4-induced effects [PMID:33436772]; other subunits not reported.","affinity_potency":[],"species_and_systems":"Human oral squamous cell carcinoma cells, including an in vivo tumour model for EPHA10 [PMID:33436772]. Mouse pair is ortholog-inferred.","localisation_and_range":"EFNA4 is flagged both secreted and transmembrane; EPHA10 flagged secreted [flag].","caveats":"No direct binding assay in our evidence; read as an abstract only. Only one confirmed paper (two further judgements were review-only).","key_references":[{"PMID":"33436772","why":"EFNA4 induces EPHA10-dependent OSCC migration and stemness"}],"covers":["LR002515","LR005783"]},"LR000508":{"pair":"EFNB1 -> EPHA4","headline":"No curator-verified paper; support is one IntAct surface plasmon resonance record.","interaction_type":"database-asserted only","direction_and_effect":"not reported in our evidence.","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct SPR record from PMID 35922511; species not given [DB:IntAct]. Pair listed for human (ortholog-inferred) and mouse.","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine).","caveats":"No confirmed papers: judged rows are review_only (6) and abstract_insufficient (4). Rests on a database record alone [DB:IntAct].","key_references":[],"covers":["LR000508","LR003999"]},"LR004009":{"pair":"EFNB2 -> EPHB1","headline":"Ligand activity reported in a 1995 cloning paper and a neurite-outgrowth study; no affinity data.","interaction_type":"direct binding","direction_and_effect":"LERK-5 (ephrin-B2) is a ligand for elk and hek and induces receptor phosphorylation [PMID:8559144]. Ephrin-B2 inhibited neurite outgrowth of substantia nigra dopaminergic neurons, which express high EphB1, but not ventral tegmental neurons with low EphB1 [PMID:10066262]. Annotated stimulatory.","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human and murine cDNAs [PMID:8559144]; neuron work species not reported in our evidence [PMID:10066262]. Pair listed for human and mouse (ortholog-inferred).","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine).","caveats":"Both abstract level; the neurite result is correlative with receptor expression, and its quote was browser-read and unverified. Elk to EPHB1 is a curator mapping.","key_references":[{"PMID":"8559144","why":"LERK-5 binds elk/hek and induces phosphorylation"},{"PMID":"10066262","why":"Ephrin-B2/EphB1 inhibit nigral dopaminergic neurites"}],"covers":["LR000518","LR004009"]},"LR000526":{"pair":"EFNB3 -> EPHB1","headline":"EphB1 acts on ephrin-B3 reverse signalling in mouse neuron migration; ELISA shows weak binding.","interaction_type":"direct binding","direction_and_effect":"EphB1 prevents cortical interneurons entering the striatum via ephrin-B3 reverse signalling, and acts as a stop signal for striatal neurons [PMID:25100946]. Ephrin-B3 Fc binds most weakly of the ephrin-Bs to all EphB receptors [PMID:22568954].","molecular_requirements":"Opposite outcomes come from different Src/FAK phosphorylation: reduced pSrc/pFAK in striatal neurons, increased in interneurons [PMID:25100946].","affinity_potency":[],"species_and_systems":"Curator annotated human for the migration paper; striatal anlage context and ELISA with species unspecified [PMID:25100946] [PMID:22568954]. Pair listed for human (ortholog-inferred) and mouse.","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine). Reverse (ephrin-side) signalling is reported.","caveats":"ELISA quote unverified. No numeric affinity. Four confirmed rows, two shown. Species annotation of the migration paper is uncertain; the excerpt describes an EphB1-Fc binding assay on neurons [PMID:25100946].","key_references":[{"PMID":"25100946","why":"EphB1-ephrin-B3 reverse signalling in neuron migration"},{"PMID":"22568954","why":"ELISA of ephrin-B Fc binding to EphB receptors"}],"covers":["LR000526","LR004017"]},"LR004018":{"pair":"EFNB3 -> EPHB2","headline":"Weak binding in ELISA plus a synapse-density paper in which ephrin-B3 acts via intracellular Erk1/2.","interaction_type":"direct binding","direction_and_effect":"A trans-synaptic EphB2 (presynaptic) to ephrin-B3 (postsynaptic) interaction regulates synapse density and spine formation [PMID:20410461]. Ephrin-B3 Fc binds most weakly to all EphB receptors [PMID:22568954].","molecular_requirements":"Ephrin-B3 is said to bind Erk1/2 directly to inhibit postsynaptic Ras/MAPK signalling [PMID:20410461].","affinity_potency":[],"species_and_systems":"Cultured cortical neurons [PMID:20410461]; ELISA species unspecified. Pair listed for human (ortholog-inferred) and mouse.","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine).","caveats":"Abstract level; binding of EphB2 to ephrin-B3 is assumed, not measured, in the synapse paper. ELISA quote unverified.","key_references":[{"PMID":"20410461","why":"EphB2/ephrin-B3 regulates synapse density"},{"PMID":"22568954","why":"ELISA weak binding of ephrin-B3 Fc"}],"covers":["LR000527","LR004018"]},"LR002524":{"pair":"EGF -> NRP1","headline":"One airway-cell study reports EGF binding to NRP1, enhanced by secretoneurin; thinly supported.","interaction_type":"direct binding","direction_and_effect":"In human airway epithelial cells, radioactive binding assays detected EGF binding to NRP1, enhanced by secretoneurin [PMID:24556756]. NRP1 is described there as a co-receptor of EGFR [PMID:24556756].","molecular_requirements":"EGFR co-receptor context; whether NRP1 alone mediates EGF signalling is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human airway epithelial cell lines 16HBE and NCI-H292 [PMID:24556756]. No database records.","localisation_and_range":"EGF is secreted; NRP1 flagged both secreted and transmembrane [flag].","caveats":"Abstract only; no affinity. Binding is described as an enhancement induced by secretoneurin, so basal binding is unclear. The curator note describes it as an indirect potentiation mechanism.","key_references":[{"PMID":"24556756","why":"EGF-NRP1 binding enhanced by secretoneurin in airway cells"}],"covers":["LR002524","LR005792"]},"LR000535":{"pair":"EPGN -> EGFR","headline":"Epigen binds EGFR and is a partial agonist of receptor dimerization; supported by a structural study and database records.","interaction_type":"direct binding","direction_and_effect":"EPGN stabilises a different dimeric EGFR extracellular conformation than EGF and induces less stable dimers, making it a partial agonist of EGFR dimerization; this gives more sustained EGFR signalling and differentiation-associated responses in breast cancer cells [PMID:28988771]. GtoPdb records the action as binding [DB:GtoPdb].","molecular_requirements":"Acts on the EGFR extracellular region as a dimer; co-receptors not reported in our evidence [PMID:28988771].","affinity_potency":[],"species_and_systems":"Human ligand and receptor are recorded [PMID:28988771]; crystallography plus cell work in breast cancer cells. The mouse pair is ortholog-inferred. PDB 5WB8 is a structure of the pair [DB:PDB 5WB8].","localisation_and_range":"EPGN is flagged secreted, non-transmembrane, and EGFR is a transmembrane receptor [flag].","caveats":"One verified paper (full text available but no affinity values extracted). One additional row was judged as a different entity. UniProt lists EPGN among known EGFR ligands [DB:UniProt].","key_references":[{"PMID":"28988771","why":"Crystal structures and kinetics of EPGN-induced EGFR dimers"}],"covers":["LR000535","LR004026"]},"LR005800":{"pair":"EPHA1 -> EFNA3","headline":"EPHA1-EFNA3 rests on a single UniProt statement of low-affinity binding; no verified papers.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states that EPHA1 binds EFNA3 with low affinity, and that EFNA1 is its probable cognate ligand [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence.","localisation_and_range":"Flags: EPHA1 non-secreted transmembrane receptor; EFNA3 non-secreted transmembrane [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Two review-only rows, no verified primary paper. Low affinity only per UniProt; no values.","key_references":[],"covers":["LR002532","LR005800"]},"LR002533":{"pair":"EPHA1 -> EFNA4","headline":"EPHA1-EFNA4 rests on a single UniProt statement of low-affinity binding; no verified papers.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states that EPHA1 binds EFNA4 with low affinity, and that EFNA1 is its probable cognate ligand [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence.","localisation_and_range":"Flags: EPHA1 non-secreted transmembrane receptor; EFNA4 flagged both secreted and transmembrane, which is inconsistent [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Two review-only rows, no verified primary paper. Low affinity only per UniProt; no values.","key_references":[],"covers":["LR002533","LR005801"]},"LR002542":{"pair":"EPHA2 -> EFNA3","headline":"EPHA2-EFNA3 has only BioGRID affinity-capture records; no verified papers.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists EFNA3-EPHA2 by affinity capture-MS and affinity capture-Western from one study [DB:BioGRID]. Effect: not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence.","localisation_and_range":"Neither partner is flagged secreted [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Ten judged rows were review-only or abstract-insufficient; both BioGRID records come from the same study, so they are not independent. No affinity data.","key_references":[],"covers":["LR002542","LR005810"]},"LR002551":{"pair":"EPHA4 -> EFNA2","headline":"EPHA4-EFNA2 is supported by a crystal structure and pull-down records; no verified papers.","interaction_type":"direct binding","direction_and_effect":"A crystal structure of the EphA4-ephrinA2 complex is recorded [DB:PDB 2WO3]; IntAct lists a pull-down [DB:IntAct]. UniProt states EFNA2 binds EPHA3, EPHA4 and EPHA5 [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence.","localisation_and_range":"Neither partner is flagged secreted [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Database evidence only; two review-only rows. No affinity data.","key_references":[],"covers":["LR002551","LR005819"]},"LR001804":{"pair":"EPO -> CRLF3","headline":"Functional only: the Epo splice variant EV-3, not Epo itself, protects human iPSC neurons via CRLF3 in knock-out experiments.","interaction_type":"functional only","direction_and_effect":"EV-3, a natural Epo splice variant, prevented rotenone-induced apoptosis in wild-type human iPSC-derived neurons, but this protection was absent in CRLF3 knock-out neurons, so CRLF3 mediates the effect (agonist action) [PMID:37168680].","molecular_requirements":"EpoR but not betacR was reported expressed in these neurons (data not shown) [PMID:37168680]. Whether other subunits are needed: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human iPSC-derived neurons with CRISPR CRLF3 knock-out lines, in vitro [PMID:37168680].","localisation_and_range":"Not reported in our evidence; no annotation flags are listed for this pair.","caveats":"No direct binding of EV-3 or Epo to CRLF3 is shown in the abstract or excerpts; the sentence on binding in insect neurons is background citing other work. The experiments used EV-3, not full-length Epo. Rotenone stress model only.","key_references":[{"PMID":"37168680","why":"CRLF3 knock-out iPSC neurons lose EV-3 neuroprotection."}],"covers":["LR001804","LR005160"]},"LR005161":{"pair":"EPO -> EPHB4","headline":"One paper proposes EphB4 as an alternative Epo receptor in cancer cells; binding and tumour-growth data, but a single study.","interaction_type":"direct binding","direction_and_effect":"EphB4 is reported as an Epo receptor that triggers downstream STAT3 signalling and promotes rhEpo-induced tumour growth and progression (agonist) [PMID:26481148]. The paper assessed rhEpo binding to EphB4 by microscale thermophoresis and surface plasmon resonance [PMID:26481148].","molecular_requirements":"No direct EpoR-EphB4 interaction was detected by EpoR immunoprecipitation in A2780 cells, so EpoR did not appear to be required for the complex [PMID:26481148].","affinity_potency":[],"species_and_systems":"Recombinant human Epo and human ovarian and breast cancer cell lines and samples; Cos-1 cells in control experiments [PMID:26481148].","localisation_and_range":"Not reported in our evidence beyond cell-based assays; no annotation flags are listed.","caveats":"Only one confirming paper. Affinity values are not in the abstract or excerpts shown. Clinical correlation is with decreased survival in rhEpo-treated patients. IntAct lists anti bait coimmunoprecipitation from the same paper [DB:IntAct P01588-P54760].","key_references":[{"PMID":"26481148","why":"Identifies EphB4 as an Epo receptor driving STAT3 signalling and tumour growth."}],"covers":["LR001805","LR005161"]},"LR004027":{"pair":"EPO -> EPOR","headline":"Canonical, well supported EPO-EPOR agonist interaction: structures, binding mutagenesis and signalling studies in human and mouse systems.","interaction_type":"direct binding","direction_and_effect":"EPO binding to EPOR induces receptor dimerization and JAK2 activation [DB:UniProt]; GtoPdb lists it as an agonist [DB:GtoPdb]. Epo binding initiates tyrosine phosphorylation and AP-1 induction [PMID:9442088], and minimal receptor forms retaining Tyr-343 relay Epo bioresponses [PMID:11124255].","molecular_requirements":"Receptor dimerization is the principal extracellular activation step; a crystal structure with an antagonist peptide shows dimerization still occurs but with altered orientation [PMID:9808045]. Phe93 and Phe205 of the EPOR extracellular domain are important for EPO binding [PMID:10318834]. An EpoR with only Tyr-343 or Tyr-464 supported maximal AP-1 activation [PMID:9442088]. Co-signalling with c-Kit enhances bcl-x(L) transcription [PMID:11124255].","affinity_potency":[],"species_and_systems":"Human receptor in COS cells with cross-linked 125I-EPO giving 66 and 100 Kd bands [PMID:2163696]; mouse FDCER cell lines [PMID:11124255]; human systems in [PMID:10318834], [PMID:9442088], [PMID:9808045].","localisation_and_range":"Not reported in our evidence; no annotation flags are listed.","caveats":"All five shown papers were read as abstracts only. The crystal-structure paper concerns EPOR with an antagonist EPO-mimetic peptide, not EPO itself [PMID:9808045]. No Kd or EC50 value is given in our evidence; GtoPdb lists pIC50 units without a value. Two further papers are pending and not shown. PDB structures [DB:PDB 1CN4], [DB:PDB 1EER] contain EPO and EPOR chains.","key_references":[{"PMID":"2163696","why":"Cloned human EPOR; 125I-EPO cross-linking in COS cells."},{"PMID":"10318834","why":"Mutagenesis of EPOR residues for EPO and mimetic-peptide binding."},{"PMID":"9808045","why":"Structure of EPOR with an antagonist peptide; dimer orientation matters."}],"covers":["LR000536","LR004027"]},"LR002605":{"pair":"ESAM -> ESAM","headline":"ESAM mediates homophilic cell adhesion in CHO aggregation assays; self-pair, abstract-level.","interaction_type":"functional only","direction_and_effect":"ESAM-expressing CHO cells show cell-cell adhesion through homophilic interactions in aggregation assays [PMID:11279107]. Direction is not applicable; the pair is self-binding.","molecular_requirements":"Structure is V-type and C2-type immunoglobulin domains with a single transmembrane region [PMID:11279107]. Subunit needs: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human and murine ESAM cloned; adhesion assay in CHO cells [PMID:11279107]. IntAct lists ESAM-ESAM in protein array and solid phase assays [DB:IntAct].","localisation_and_range":"Membrane-bound adhesion molecule, juxtacrine contact [flag; PMID:11279107].","caveats":"Abstract-only; functional adhesion, not purified binding. No affinity.","key_references":[{"PMID":"11279107","why":"Homophilic ESAM adhesion in CHO aggregation assays"}],"covers":["LR002605","LR005872"]},"LR000544":{"pair":"F2 -> F2R","headline":"Thrombin (F2) cleaves the PAR1 exodomain at Arg41-Ser42 and binds it in SPR; recombinant evidence plus structures.","interaction_type":"direct binding","direction_and_effect":"Thrombin cleaved recombinant PAR1E at the Arg41-Ser42 activation site at concentrations known to induce cellular activation [PMID:10978167]. SPR on immobilised PAR1E and PAR1E S42P determined thrombin affinities [PMID:10978167]. Annotated stimulatory [flag].","molecular_requirements":"Activation is by proteolytic cleavage of the exodomain [PMID:10978167]. PDB 1NRN etc. show thrombin with PAR1 chain [DB:PDB 1NRN].","affinity_potency":[],"species_and_systems":"Human proteins; recombinant PAR1 exodomain expressed in E. coli, SPR in vitro, not live cells [PMID:10978167]. Mouse pair is ortholog-inferred [flag].","localisation_and_range":"F2 flagged secreted, not transmembrane; F2R transmembrane [flag].","caveats":"Abstract-only; affinity values are not shown in the abstract excerpt. Three rows were different_entity. Enzyme-substrate rather than a classical agonist-receptor binding.","key_references":[{"PMID":"10978167","why":"SPR and MALDI cleavage mapping of thrombin on PAR1 exodomain"}],"covers":["LR000544","LR004035"]},"LR004036":{"pair":"F2 -> F2RL1","headline":"Thrombin-PAR2 has no positive evidence; one paper states PAR2 exodomain showed no thrombin effect.","interaction_type":"conflicting","direction_and_effect":"MALDI mass spectrometry of recombinant PAR2E predicted no effect of thrombin; PAR2 is preferentially cleaved by trypsin [PMID:10978167]. Direction effect not supported.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Recombinant PAR2 exodomain from E. coli, human sequences [PMID:10978167]. Reactome records generic PAR-thrombin binding [DB:Reactome].","localisation_and_range":"F2 flagged secreted, not transmembrane [flag].","caveats":"The one verified row is a negative (pair_absent); five rows were abstract_insufficient, one review_only and one pending. Database support is generic to PARs. Annotated stimulatory despite this [flag].","key_references":[{"PMID":"10978167","why":"Verified negative: no thrombin effect on PAR2E"}],"covers":["LR000545","LR004036"]},"LR000553":{"pair":"F9 -> LRP1","headline":"Activated factor IXa binds LRP in vitro; FIXa only, as a clearance receptor interaction.","interaction_type":"direct binding","direction_and_effect":"Purified soluble LRP and full-length LRP showed similar binding to factor IXa [PMID:12522212]. A recombinant LRP cluster IV fragment interfered with factor IXa amidolytic activity [PMID:12522212]. Annotation lists effect as stimulatory.","molecular_requirements":"Binding involves the factor IXa surface loop Phe(342)-Asn(346) near the active site; variants showed reduced sLRP binding, and Asn(346)Asp had slower association to sLRP [PMID:12522212]. Curator notes say only activated IXa, not the zymogen, is bound.","affinity_potency":[],"species_and_systems":"Purified proteins, solid-phase and SPR; species not stated in the abstract [PMID:12522212]; BioGRID record [DB:BioGRID 301580].","localisation_and_range":"F9 annotated secreted [flag].","caveats":"Abstract-only; no numeric affinity in our evidence. The zymogen factor IX is not shown to bind.","key_references":[{"PMID":"12522212","why":"Factor IXa binding to LRP and loop mapping"}],"covers":["LR000553","LR004044"]},"LR004045":{"pair":"Fasl -> Fas","headline":"Mouse Fasl-Fas pair rests on human-protein mutagenesis binding studies projected to mouse, plus database records.","interaction_type":"direct binding","direction_and_effect":"Fas is activated by FasL and triggers apoptosis; FasL-mediated Jurkat apoptosis was inhibited by Fas-Ig fusion proteins [PMID:9126929]. Mutating R86 and R87 in Fas to serine totally abolished interaction with FasL [PMID:9126929]. FasL mutants P206R, P206D and P206F showed reduced cytotoxicity and lower binding affinity for Fas-Fc [PMID:9228058].","molecular_requirements":"Binding involves residues in two Fas domains (D2 and D3) [PMID:9126929]. FasL acts as a homotrimer in a model with three Fas molecules; F275L could not bind Fas [PMID:9228058].","affinity_potency":[],"species_and_systems":"Both papers used human proteins (Fas-Ig mutants, human soluble FasL in HEK293 cells); the mouse pair is ortholog-inferred. Conservation between murine and human Fas is stated in the abstract [PMID:9126929]. Y218F induced apoptosis in murine but not human cells [PMID:9228058]. BioGRID, IntAct and Reactome records exist [DB:BioGRID] [DB:IntAct] [DB:Reactome].","localisation_and_range":"FasL is flagged secreted [flag]; the paper describes it as a type II membrane protein, with a soluble extracellular form used experimentally [PMID:9228058].","caveats":"Mouse evidence is projected from human experiments. Both papers were read as abstracts only. One further paper was judged abstract_insufficient. Database records listed are mainly for the human proteins.","key_references":[{"PMID":"9126929","why":"Serine-scanning of Fas maps residues needed for FasL binding."},{"PMID":"9228058","why":"FasL-side mutations affecting Fas binding and cytotoxicity."}],"covers":["LR004045"]},"LR002614":{"pair":"FBLN2 -> ITGA2B","headline":"Fibulin-2 binds integrin alpha IIb beta 3 in purified-protein assays; mouse fibulin-2 binds strongly, RGD-dependent.","interaction_type":"direct binding","direction_and_effect":"Mouse fibulin-2 bound alpha IIb beta 3 almost as strongly as fibrinogen, and an RGD peptide (SVPRGDLDG) antagonized binding [PMID:7543056]. Mouse fibulin-2 also promoted adhesion of thrombin-stimulated platelets, inhibited by RGD peptides [PMID:7543056].","molecular_requirements":"Binding was to the alpha IIb beta 3 heterodimer, not a single chain; the RGD site of fibulin-2 is involved [PMID:7543056].","affinity_potency":[],"species_and_systems":"Recombinant proteins from kidney cell clones and five purified integrins [PMID:7543056]. Human fibulin-2, in which RGD is changed to RSS, bound less strongly and showed no cell-adhesion activity [PMID:7543056]. The human pair is therefore weaker; the mouse pair is ortholog-inferred.","localisation_and_range":"FBLN2 is flagged secreted [flag]; the paper says fibulins occur in basement membranes and vessel walls [PMID:7543056], so it is a matrix ligand.","caveats":"Single paper, abstract only. No affinity number for fibulin-2 itself. The entity here is ITGA2B but the assay used the integrin heterodimer; no ITGB3 role is separated.","key_references":[{"PMID":"7543056","why":"Fibulin-2 binds alpha IIb beta 3, RGD-dependent."}],"covers":["LR002614","LR005881"]},"LR000562":{"pair":"FBN1 -> ITGB6","headline":"Fibrillin-1 binds integrin alphaVbeta6 directly (SPR, Kd about 0.45 uM); database records agree.","interaction_type":"direct binding","direction_and_effect":"Integrin alphaVbeta6 is identified as a cellular receptor for human fibrillin-1 [PMID:17158881]; UniProt states ITGAV:ITGB6 mediates RGD-dependent cell adhesion to FBN1 [DB:UniProt] and Reactome lists fibrillin-1 binding integrins [DB:Reactome R-HSA-2328037]. Effect on signalling not reported in our evidence.","molecular_requirements":"Receptor is the alphaV:beta6 heterodimer [DB:UniProt]. The TB4 domain carries an RGD loop; module requirements for alphaVbeta6 differ from alphaVbeta3, and a linked N-terminal calcium-binding EGF-like domain can modulate alphaV integrin specificity [PMID:17158881].","affinity_potency":[{"value":"Kd approximately 0.45 uM","assay":"surface plasmon resonance","system":"recombinant human fibrillin-1 fragments with alphaVbeta6","cite":"PMID:17158881"}],"species_and_systems":"Human fibrillin-1 fragments and human integrin; mouse pair is ortholog-inferred, not tested.","localisation_and_range":"Fibrillin-1 is flagged secreted [flag]; matrix microfibril component per paper text [PMID:17158881].","caveats":"Single primary paper, read as abstract only. A further judged paper was review-only.","key_references":[{"PMID":"17158881","why":"SPR identification of alphaVbeta6 as fibrillin-1 receptor, Kd about 0.45 uM"}],"covers":["LR000562","LR004053"]},"LR004054":{"pair":"FGA -> ITGA2B","headline":"Fibrinogen binds platelet alphaIIb-beta3; functional and in vivo mouse evidence, BioGRID peptide record; chain-level evidence is indirect.","interaction_type":"direct binding","direction_and_effect":"Mouse platelets with an activated alphaIIbbeta3 (R560beta3) bound fibrinogen continuously, detected by a conformation-specific antibody [PMID:23551977]. Effect direction recorded as agonist [PMID:15031111].","molecular_requirements":"Evidence concerns the alphaIIb-beta3 heterodimer with whole fibrinogen; ITGA2B alone and the FGA chain alone were not separated.","affinity_potency":[],"species_and_systems":"Mouse in vivo platelet model with human beta3 lentivirus [PMID:23551977]; mouse trophoblast with human fibrinogen [PMID:15031111]. Human interaction is ortholog-inferred; BioGRID lists a protein-peptide record [DB:BioGRID].","localisation_and_range":"FGA flagged secreted; ITGA2B flagged receptor [flag].","caveats":"One paper is abstract only. A function-blocking anti-alphaIIb antibody disrupted fibrinogen-dependent outgrowth of mouse trophoblast; its statement that fibrinogen is recognised by alphaVbeta3 and alphaIIbbeta3 is a background citation [PMID:15031111]. Another paper was abstract_insufficient and one review_only (not shown).","key_references":[{"PMID":"23551977","why":"fibrinogen-bound alphaIIbbeta3 in vivo"},{"PMID":"15031111","why":"trophoblast adhesion assays"}],"covers":["LR000564","LR004054"]},"LR000571":{"pair":"FGA -> ITGB3","headline":"Fibrinogen engages beta3 integrins alphaVbeta3 and alphaIIbbeta3; three papers, direct binding for alphaVbeta3 at abstract level.","interaction_type":"direct binding","direction_and_effect":"alphaVbeta3 recognises fibrinogen gamma and alphaE C-terminal domains; two gammaC peptides block alphaVbeta3 binding and clot retraction but not fibrinogen binding to alphaIIbbeta3 [PMID:10747940]. Mouse platelets bound fibrinogen continuously via active alphaIIbbeta3 [PMID:23551977].","molecular_requirements":"beta3 pairs with alphaV or alphaIIb. The gammaC sites (190-202 and 346-358) lie on the gamma chain, not FGA; alphaEC binding concerns the extended alpha chain [PMID:10747940].","affinity_potency":[],"species_and_systems":"Human proteins (PMID:10747940); mouse platelets (PMID:23551977); human fibrinogen on mouse trophoblast (PMID:15031111). BioGRID lists FGA - ITGB3 protein-peptide [DB:BioGRID].","localisation_and_range":"FGA flagged secreted; ITGB3 not secreted [flag].","caveats":"Two papers abstract only; PMID:15031111 statement is background. No affinity. Mouse interaction listed separately.","key_references":[{"PMID":"10747940","why":"alphaVbeta3 binding sites in fibrinogen gammaC"},{"PMID":"23551977","why":"in vivo fibrinogen-alphaIIbbeta3 binding"}],"covers":["LR000571","LR004055"]},"LR002623":{"pair":"FGB -> CDH5","headline":"Fibrin(ogen) betaN-domains bind VE-cadherin domain 3 by ELISA and SPR; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"The VE-cadherin-binding site is in the fibrin betaN-domains (N-terminal regions of beta chains); betaN-domains are the only fibrin(ogen) regions involved [PMID:19413351].","molecular_requirements":"The complementary site is the third extracellular VE-cadherin domain, unaffected by neighbouring domains; calcium does not influence binding [PMID:19413351].","affinity_potency":[],"species_and_systems":"Recombinant fragments; species not recorded in our evidence. Mouse pair is ortholog-inferred [PMID:19413351].","localisation_and_range":"FGB flagged secreted; CDH5 transmembrane [flag].","caveats":"Abstract only; no affinity in our evidence. Fibrin and fibrinogen are not distinguished beyond betaN-domains.","key_references":[{"PMID":"19413351","why":"betaN-domain binds VE-cadherin domain 3"}],"covers":["LR002623","LR005889"]},"LR001813":{"pair":"FGF1 -> CSPG4","headline":"Cell-surface FGF1 interaction with CSPG4 from one abstract-read proximity-labelling study; proposed as a reservoir.","interaction_type":"direct binding","direction_and_effect":"An APEX2-FGF1 proximity-labelling screen in RPE1 cells identified CSPG4 (NG2) and CD44 as FGF1 interactors, co-localized with FGF1 at the cell surface [PMID:29812912]. They are proposed as storage molecules forming an FGF1 reservoir rather than direct signalling receptors [PMID:29812912].","molecular_requirements":"Not reported in our evidence beyond FGF1's heparin-binding moiety being implicated for the companion CD44 interaction [PMID:29812912].","affinity_potency":[],"species_and_systems":"Human FGF1 and human RPE1 cells [PMID:29812912]. Mouse record is ortholog-inferred.","localisation_and_range":"CSPG4 is flagged secreted, receptor and transmembrane [flag]; the paper describes cell-surface localisation [PMID:29812912].","caveats":"Abstract only; proximity labelling is indirect and no affinity is reported. Shared paper with the CD44 pair. No database records.","key_references":[{"PMID":"29812912","why":"Proximity labelling identifies CSPG4 and CD44 as FGF1 interactors"}],"covers":["LR001813","LR005168"]},"LR004081":{"pair":"FGF1 -> FGFR4","headline":"Well-supported direct FGF1-FGFR4 binding by cross-linking, SPR and cell binding; FGF1 activates the receptor.","interaction_type":"direct binding","direction_and_effect":"FGFR4 in liver parenchymal cells binds only FGF-1 in a heparan sulfate binding assay [PMID:10336501]. Purified human FGFR4 extracellular domain formed complexes with FGF-1 and FGF-2 in solution, with and without heparin [PMID:10736564]. FGF1 binds FGFR4 directly without KLB and is curated as agonist [PMID:22442730]. FGF1 activates all seven FGFR-expressing BaF3 lines [PMID:8663044].","molecular_requirements":"Heparan sulfate is a co-factor for binding specificity [PMID:10336501], but FGFR4 extracellular domain binding is heparin-independent [PMID:10736564]. KLB is not required [PMID:22442730].","affinity_potency":[],"species_and_systems":"Recombinant human FGFR4 ectodomain (cross-linking, biosensor) [PMID:10736564]; 125I-FGF1 binding to receptor-expressing 293 cells [PMID:22442730]; BaF3 species unspecified [PMID:8663044]. Human and mouse records exist, neither ortholog-inferred.","localisation_and_range":"FGF1 secreted; FGFR4 transmembrane receptor, also flagged secreted [flag].","caveats":"Most papers are abstract level, BaF3 papers browser-read with quotes pending spot-check [PMID:16597617][PMID:8663044]. No affinity values in our evidence. One review-only paper. Database: BioGRID reconstituted complexes [DB:BioGRID].","key_references":[{"PMID":"10736564","why":"FGFR4 ectodomain complexes with FGF-1 by cross-linking and biosensor"},{"PMID":"22442730","why":"FGF1 binds FGFR4 directly, KLB-independent"},{"PMID":"10336501","why":"FGFR4 binds only FGF-1 in liver cells"}],"covers":["LR000597","LR004081"]},"LR004072":{"pair":"Fgf15 -> Fgfr1","headline":"Mouse Fgf15 (ortholog of FGF19) binds FGFR1 with comparable affinity to FGFR4, but only with KLB; evidence is one abstract.","interaction_type":"direct binding","direction_and_effect":"FGF19 bound FGFR1 and FGFR4 in the presence of KLB with comparable affinity, and bound FGFR1 alone not at all [PMID:22442730]. FGF19 mainly activated liver responses and, to a lesser extent, adipose tissue in mice [PMID:22442730].","molecular_requirements":"KLB is required: FGF19 bound equally well to FGFR1-KLB and FGFR4-KLB but not to FGFR1 alone; about 10% binding to FGFR4 alone [PMID:22442730]. Complex: FGFR1 plus KLB.","affinity_potency":[],"species_and_systems":"Evidence is written for human FGF19, the ortholog of mouse Fgf15; the mouse pair is projected from human. Binding kinetics and in vivo mouse administration [PMID:22442730].","localisation_and_range":"Fgf15 is flagged secreted, FGFR1 a membrane receptor [flag]; FGF19 acts as an endocrine hormone in the paper's framing but range is not directly tested.","caveats":"The curated evidence sentence concerns tissue response, not FGFR1 binding itself. The paper uses FGF19 nomenclature throughout. Another judged paper was abstract-insufficient. Affinity values are not in the dossier.","key_references":[{"PMID":"22442730","why":"FGF19 binds FGFR1 and FGFR4 with KLB"}],"covers":["LR004072"]},"LR004063":{"pair":"FGF16 -> FGFR4","headline":"FGF16 activates FGFR4-expressing BaF3 cells with high activity; functional evidence from one panel study.","interaction_type":"functional only","direction_and_effect":"FGF9, FGF16 and FGF20 activated FGFR4 and FGFRc isoforms with high activity [PMID:16597617]. Agonist.","molecular_requirements":"not reported in our evidence beyond the BaF3 FGFR4 line [PMID:16597617].","affinity_potency":[],"species_and_systems":"BaF3 mitogenic panel [PMID:16597617]; species of FGFR constructs not reported. Mouse pair projected from human.","localisation_and_range":"FGF16 flagged secreted; FGFR4 flagged secreted and transmembrane, hence possibly membrane and soluble forms [flag].","caveats":"Single functional paper, read as full text in a browser (quote unverified); activity is mitogenesis in BaF3 cells, not binding. Two other judged rows were review-only.","key_references":[{"PMID":"16597617","why":"BaF3 panel, FGFR4"}],"covers":["LR000579","LR004063"]},"LR000580":{"pair":"FGF17 -> FGFR1","headline":"FGF17 activates FGFR1c in BaF3 cells and transforms 3T3 cells, consistent with FGFR1c or FGFR2c activation.","interaction_type":"functional only","direction_and_effect":"FGF8, FGF17 and FGF18 specifically activated FGFR1c, 2c, 3c and the two Ig-domain form of FGFR4 [PMID:16597617]. Mouse FGF17 transformed 3T3 fibroblasts, indicating it can activate the c form of FGFR1 or FGFR2 [PMID:10381577]. Agonist.","molecular_requirements":"c splice forms; FGFR1c is not distinguished from FGFR2c in the transformation assay [PMID:10381577].","affinity_potency":[],"species_and_systems":"BaF3 panel [PMID:16597617]; mouse FGF17 in mouse 3T3 fibroblasts [PMID:10381577]. Human and mouse pairs both listed (not projected).","localisation_and_range":"FGF17 flagged secreted [flag].","caveats":"Mitogenic activity in BaF3 cells, not binding; browser-read full text, quote unverified [PMID:16597617]. Transformation result is abstract-only. Two other papers were abstract-insufficient.","key_references":[{"PMID":"16597617","why":"BaF3 panel"},{"PMID":"10381577","why":"FGF17 transformation of 3T3 cells"}],"covers":["LR000580","LR004064"]},"LR000607":{"pair":"FGF2 -> CD44","headline":"Heparan-sulfate-modified CD44 isoforms bind FGF2 in one 1995 paper; no affinity or signalling data.","interaction_type":"direct binding","direction_and_effect":"HS-modified CD44 isoforms were able to bind b-FGF (FGF2) and HB-EGF, but not amphiregulin [PMID:7532176]. Effect on signalling is not reported in our evidence.","molecular_requirements":"Binding required CD44 isoforms containing alternatively spliced exon V3 carrying heparan sulfate [PMID:7532176]; the binding is therefore likely HS-mediated.","affinity_potency":[],"species_and_systems":"COS cell transfectants and keratinocyte-derived CD44; species not stated in our evidence [PMID:7532176]. Mouse pair is ortholog-inferred.","localisation_and_range":"Both partners are annotated secreted and transmembrane-capable [flag]; CD44 acts as a membrane growth-factor presenter.","caveats":"Single paper. CD44 appears to act as an HS-bearing presenter rather than a signalling receptor; no affinity reported. Full-text excerpts shown concern CD44 expression in skin, not binding.","key_references":[{"PMID":"7532176","why":"HS-modified CD44 binds bFGF in COS cells and keratinocytes"}],"covers":["LR000607","LR004091"]},"LR002632":{"pair":"FGF2 -> LYVE1","headline":"FGF2 binds LYVE-1 in several in vitro formats and LYVE-1 loss impairs FGF2 function; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"FGF2 binds LYVE-1 by AlphaScreen, on immobilised protein and in solution, and also when LYVE-1 is overexpressed in CHO cells. Soluble LYVE-1 or LYVE-1 knockdown impaired FGF2 signalling, and FGF2-induced (not VEGF-C-induced) lymphangiogenesis in vivo was inhibited [PMID:23264596].","molecular_requirements":"LYVE-1 glycosylation is important for FGF2 binding [PMID:23264596]. Subunit or co-receptor requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and receptor recorded; CHO cells and lymphatic endothelial cells, with an in vivo lymphangiogenesis assay [PMID:23264596]. Mouse pair is ortholog-inferred.","localisation_and_range":"FGF2 is flagged secreted and LYVE-1 a receptor [flag]; LYVE-1 location is not otherwise described.","caveats":"Single paper read as abstract only; the abstract says FGF2 binds LYVE-1 with higher affinity than hyaluronan or PDGF-BB but gives no value. FGF2 also modulates LYVE-1 expression [PMID:23264596].","key_references":[{"PMID":"23264596","why":"FGF2 binds LYVE-1; LYVE-1 needed for FGF2 lymphangiogenesis"}],"covers":["LR002632","LR005898"]},"LR000616":{"pair":"FGF2 -> SDC2","headline":"FGF2 binds syndecan-2 via heparan sulfate in a pull-down, and syndecan-2 raises FGF2 binding to FGFR1 in cells.","interaction_type":"direct binding","direction_and_effect":"FGF2-GST bound human SDC2 via heparitinase-cleavable HS in HEK293T cells [PMID:16982797]. Cotransfected syndecan-2 with FGFR1 raised specific 125I-bFGF binding two- to three-fold in K562 cells [PMID:8609172]. BioGRID and IntAct list co-purification, affinity-capture and co-IP records [DB:BioGRID; DB:IntAct].","molecular_requirements":"Binding is via HS chains [PMID:16982797]; syndecans contribute to FGF2-FGFR1 complex formation [PMID:8609172].","affinity_potency":[],"species_and_systems":"Human cells (HEK293T, K562) [PMID:16982797; PMID:8609172]. Mouse pair is ortholog-inferred.","localisation_and_range":"SDC2 is flagged transmembrane, FGF2 secreted [flag].","caveats":"FGF2 was a positive-control ligand in one paper; binding is to HS chains, which is not specific to SDC2. Several other papers were abstract_insufficient or review_only, and one is pending.","key_references":[{"PMID":"16982797","why":"FGF2-GST pull-down of SDC2 via HS"},{"PMID":"8609172","why":"Syndecan-2 cotransfection increases FGF2 binding"}],"covers":["LR000616","LR004100"]},"LR005170":{"pair":"FGF20 -> FGFR1","headline":"FGF20 activating FGFR1 is supported only indirectly: a family-wide mitogenic screen and mouse heart genetics.","interaction_type":"functional only","direction_and_effect":"In the BaF3 mitogenic screen, FGF9, 16 and 20 activated FGFRc isoforms and FGFR4 with high activity [PMID:16597617]. In mouse heart, endocardial/epicardial FGF signals, with Fgf9, Fgf16 and Fgf20 expressed, were received by FGFR1 and FGFR2 acting redundantly [PMID:15621532].","molecular_requirements":"FGFR1 and FGFR2 act redundantly in cardiomyoblasts [PMID:15621532]. Heparan sulfate or other co-factors are not reported in our evidence for FGF20.","affinity_potency":[],"species_and_systems":"BaF3 cell lines, species unspecified [PMID:16597617]; knockout mice and embryonic mouse heart organ culture [PMID:15621532].","localisation_and_range":"FGF20 is flagged secreted and FGFR1 transmembrane [flag]; paracrine signalling in heart is described [PMID:15621532].","caveats":"No FGF20-FGFR1 binding data. The screen quote does not name FGFR1 specifically, and the mouse pairing is inferred from joint Fgf9/16/20 knockout and redundant Fgfr1/Fgfr2 requirement, not isolated FGF20 data. The first paper's quote was browser-read and flagged unverifiable. Review, pending and abstract_insufficient rows are not shown.","key_references":[{"PMID":"16597617","why":"Mitogenic receptor-specificity screen of FGF9/16/20"},{"PMID":"15621532","why":"Mouse heart FGF signals via FGFR1/FGFR2"}],"covers":["LR001815","LR005170"]},"LR004090":{"pair":"FGF23 -> FGFR4","headline":"FGF23 binds and activates FGFR4 in SPR/mitogenesis and BaF3 assays; stimulatory.","interaction_type":"direct binding","direction_and_effect":"FGF23 binds and activates FGFR4 and the c isoforms of FGFR1-3 [PMID:16081635, PMID:16597617]. Curated as agonist [PMID:16081635].","molecular_requirements":"Highly sulfated, longer GAGs, not standard heparan sulfate, promote activity; removal of cell surface GAGs abolishes it [PMID:16081635].","affinity_potency":[],"species_and_systems":"Human reagents per curators; opossum kidney cells for signaling [PMID:16081635]; BaF3 screen species unspecified [PMID:16597617].","localisation_and_range":"FGF23 secreted [flag]; paper describes circulation to kidney [PMID:16081635].","caveats":"Abstract-only reading; mouse pair is ortholog-inferred. PDB 7YSW lists FGF23 and FGFR4 chains [DB:PDB 7YSW].","key_references":[{"PMID":"16081635","why":"SPR and mitogenesis for FGF23"},{"PMID":"16597617","why":"BaF3 screen"}],"covers":["LR000606","LR004090"]},"LR004108":{"pair":"FGF4 -> FGFR4","headline":"Weakly supported and partly contradicted: papers say FGF4 shows little activity toward FGFR4.","interaction_type":"conflicting","direction_and_effect":"The pair is annotated stimulatory, but the FGF4 structure/mutagenesis paper states FGF4 shows little activity towards FGFR4 [PMID:11486033]. The BaF3 survey reports FGF4 activating c splice forms of receptors [PMID:8663044]; FGFR4 is not named in the evidence sentence.","molecular_requirements":"Specificity is described as arising from FGF/FGFR sequence differences and the IIIb/IIIc alternative exons; heparin binding sites were mapped on FGF4 [PMID:11486033].","affinity_potency":[],"species_and_systems":"Human ligand and receptor in the mutagenesis paper (abstract only) [PMID:11486033]; BaF3 assays with unspecified species [PMID:8663044]. Mouse pair is projected from human.","localisation_and_range":"FGF4 is flagged secreted and non-transmembrane [flag]; FGFR4 is flagged as a transmembrane receptor [flag].","caveats":"No paper shows FGF4 binding or activating FGFR4; the main abstract says the opposite. Papers were read as abstracts (PMID:8663044 as a browser-read quote pending spot-check).","key_references":[{"PMID":"11486033","why":"States FGF4 has little activity towards FGFR4; maps receptor and heparin sites"},{"PMID":"8663044","why":"BaF3 survey, FGF4 activates c splice forms"}],"covers":["LR000624","LR004108"]},"LR001822":{"pair":"FGF4 -> FGFRL1","headline":"FGF4 binds FGFRL1 with high affinity; FGFRL1 acts as a decoy that antagonises FGF signalling.","interaction_type":"direct binding","direction_and_effect":"Soluble and membrane-bound FGFRL1 bind FGF4 (among FGF2, FGF3, FGF8, FGF10, FGF22), and FGFRL1 expressed in Xenopus embryos antagonised FGFR signalling, supporting a decoy role [PMID:19920134].","molecular_requirements":"FGFRL1 has an FGFR-like extracellular domain but lacks the split tyrosine kinase domain needed for signal transduction [PMID:19920134]. Heparin dependence is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Binding shown by ligand dot blot, cell-based binding and surface plasmon resonance; shed ectodomain from C2C12 myoblasts and HEK293 cells; antagonism tested in Xenopus embryos [PMID:19920134]. Mouse pair is projected from human.","localisation_and_range":"FGFRL1 ectodomain is shed from the cell membrane by an unidentified protease, so both soluble and membrane-bound forms exist [PMID:19920134]. FGF4 is flagged secreted [flag].","caveats":"Abstract-only reading. The abstract gives \"high affinity\" without a number; no Kd is reported in our evidence. Binding is not resolved per ligand in the abstract.","key_references":[{"PMID":"19920134","why":"Shows FGFRL1 shedding, FGF binding (incl. FGF4) and antagonism of FGFR signalling"}],"covers":["LR001822","LR005177"]},"LR000625":{"pair":"FGF4 -> NRP1","headline":"FGF4 binds immobilised NRP1 in a biosensor, apparently via heparin-mimetic site; functional relevance unproven.","interaction_type":"direct binding","direction_and_effect":"FGF4 interacts with immobilised neuropilin-1 and in a solution assay [PMID:15695515]. Npn-1 potentiated FGF-2 (not FGF4) growth stimulation of HUVEC [PMID:15695515]; any FGF4 effect is not reported in our evidence.","molecular_requirements":"Binding is ionic-strength dependent and inhibited by heparin, suggesting a heparin-mimetic site on Npn-1 [PMID:15695515]. Co-receptor requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Optical biosensor and solution assays with human proteins [PMID:15695515]. Both human and mouse pairs are ortholog-inferred.","localisation_and_range":"NRP1 is flagged as a transmembrane receptor with a secreted form [flag]; FGF4 is flagged secreted [flag].","caveats":"The curator notes the binding is largely electrostatic and heparin-competable, so specificity and signalling relevance for FGF4 are not established. Association rate constants of 270,000-1,600,000 M-1s-1 are given for FGF-2, FGF-4 and HGF/SF together, not FGF4 alone.","key_references":[{"PMID":"15695515","why":"Biosensor and solution binding of FGF4 to NRP1"}],"covers":["LR000625","LR004109"]},"LR004117":{"pair":"FGF6 -> FGFR4","headline":"FGF6 binds FGFR4 in a ligand competition experiment, but weaker than aFGF and K-FGF; limited data.","interaction_type":"direct binding","direction_and_effect":"FGF-6 bound FGFR-4 in ligand competition experiments, and ligand binding to FGFR-4 induced receptor autophosphorylation [PMID:1385111]. The pair is annotated stimulatory.","molecular_requirements":"FGFR-4 is not alternatively spliced in the region that determines specificity in FGFR-1/2 [PMID:1385111]. Heparin requirement is not reported for FGF6 in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and receptor; abstract-only reading [PMID:1385111]; BaF3 survey with unspecified species [PMID:8663044]. Mouse pair is projected from human.","localisation_and_range":"FGFR4 is flagged as a transmembrane receptor [flag]; localisation of FGF6 is not reported in our evidence.","caveats":"FGF-6 was not the highest-affinity ligand (aFGF, then K-FGF/hst-1, then bFGF are stronger) [PMID:1385111]. No affinity value is given for FGF6. The BaF3 sentence cited concerns c splice forms and does not name FGFR4 [PMID:8663044].","key_references":[{"PMID":"1385111","why":"FGF-6 binds FGFR-4 in competition experiments"},{"PMID":"8663044","why":"BaF3 survey (c forms; FGFR4 not named)"}],"covers":["LR000633","LR004117"]},"LR000634":{"pair":"FGF7 -> FGFR1","headline":"Reported only in an organoid study where FGF7 acts through FGFR2 and FGFR1; no direct binding.","interaction_type":"functional only","direction_and_effect":"In hESC-derived islet organoids FGF7 interacts with FGFR2 and FGFR1 to upregulate ACE2, and FGFR inhibition counteracted the induction [PMID:38654010].","molecular_requirements":"FGFR2 and FGFR1 are named together; the relative contribution of FGFR1 is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human embryonic stem cell-derived islet organoids, with animal models and COVID-19 patient serum mentioned in the abstract [PMID:38654010].","localisation_and_range":"Localisation is not reported in our evidence.","caveats":"Abstract-only reading; the word \"interacts\" is not backed by a binding assay in the dossier, and an FGFR inhibitor does not distinguish receptors. Seven further papers were abstract-insufficient.","key_references":[{"PMID":"38654010","why":"FGF7 acts via FGFR2 and FGFR1 in islet organoids"}],"covers":["LR000634","LR004118"]},"LR004126":{"pair":"FGF9 -> FGFR2","headline":"FGF9 efficiently activates FGFR2c, shown by direct binding and mitogenesis; broader BaF3 support.","interaction_type":"direct binding","direction_and_effect":"FGF-9 efficiently activates the c splice form of FGFR2 and FGFR3 [PMID:8576175]. FGF9 subfamily members activated FGFRc isoforms with high activity [PMID:16597617]. Agonist.","molecular_requirements":"c splice form of FGFR2 is the efficiently activated one [PMID:8576175]. BioGRID has a protein-peptide record [DB:BioGRID]; Reactome records concern FGFR2 mutant binding generally [DB:Reactome].","affinity_potency":[],"species_and_systems":"Murine FGF-9 expressed in mammalian cells and E. coli, tested by direct binding to soluble and cell-surface FGFR splice variants and mitogenesis (abstract only) [PMID:8576175]; BaF3 cells with unspecified species [PMID:16597617][PMID:8663044]. Both human and mouse pairs are non-inferred.","localisation_and_range":"Localisation is not reported in our evidence.","caveats":"No affinity value in our evidence. The cited 1996 paper used murine ligand; the curator's species label of human may not match. BaF3 quotes are browser-read and pending spot-check.","key_references":[{"PMID":"8576175","why":"Direct binding and mitogenesis; FGF-9 activates FGFR2c"},{"PMID":"16597617","why":"FGF9 subfamily activates FGFRc isoforms"}],"covers":["LR000642","LR004126"]},"LR000643":{"pair":"FGF9 -> FGFR3","headline":"FGF9 binds and activates FGFR3 (c and b splice forms); several binding and mitogenic papers plus BioGRID support.","interaction_type":"direct binding","direction_and_effect":"FGF9 is an agonist of FGFR3: it binds and activates the c splice form and also the b form [PMID:8576175]. FGF9 stimulated DNA synthesis in FGFR3-expressing stromal cells, with epithelial FGF9 signalling to stromal FGFR3 [PMID:15231666]. FGF9 bound FGFR3 well but FGFR2/FGFR1 poorly in soluble receptor assays [PMID:10574949].","molecular_requirements":"Splice form matters: c forms are preferred, with some activity on FGFR3b [PMID:8663044][PMID:16597617]. Binding specificity maps to Ig domain II and sequences N-terminal to it [PMID:10574949]. Co-factor requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Binding assays used human receptor constructs for two papers [PMID:10574949][PMID:8576175]; the prostate tumour paper used rat Dunning R3327 tumour cells [PMID:15231666]; BaF3 mitogenic assays did not specify species [PMID:8663044][PMID:16597617]. Human and mouse records share this dossier; mouse is not inferred.","localisation_and_range":"FGF9 is flagged as secreted and FGFR3 as transmembrane [flag]; the prostate paper describes epithelium-to-stroma paracrine signalling [PMID:15231666].","caveats":"Several papers were read as abstracts only. BaF3 assays measure mitogenesis, not binding. BioGRID lists reconstituted complex and affinity capture records [DB:BioGRID], and IntAct an SPR record [DB:IntAct]. No affinity values reported.","key_references":[{"PMID":"8576175","why":"FGF9 binds and activates FGFR3c and FGFR3b"},{"PMID":"15231666","why":"Epithelial FGF9 to stromal FGFR3 paracrine binding and mitogenesis"},{"PMID":"10574949","why":"Soluble FGFR3 binds FGF9; domain mapping"}],"covers":["LR000643","LR004127"]},"LR002641":{"pair":"FGL2 -> FCGR2B","headline":"FGL2 binds Fcgr2b-transfected cells by flow cytometry in mouse; one paper.","interaction_type":"direct binding","direction_and_effect":"Fgl2 binding to Fcgr2b-transfected cells was confirmed by flow cytometry and abrogated by anti-FcgRIIB [PMID:38902261]. Fgl2 is immunosuppressive; T cell Fgl2 deletion improved tumour control [PMID:38902261].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse proteins and cells; B16 tumour and LCMV models [PMID:38902261]. Human pair listed but not inferred.","localisation_and_range":"FGL2 is flagged secreted [flag]; it is produced by CD8+ T cells [PMID:38902261].","caveats":"Single paper; binding shown on transfected cells only, no affinity. Human relevance not shown in our evidence. No database records.","key_references":[{"PMID":"38902261","why":"Fgl2 binds Fcgr2b-transfected cells; T cell exhaustion"}],"covers":["LR002641","LR005907"]},"LR007204":{"pair":"FLRT1:TENM3 -> ADGRL3","headline":"Complex-as-ligand pair supported only by database records; no curated paper has judged it.","interaction_type":"database-asserted only","direction_and_effect":"No curated paper. UniProt says ADGRL3 interacts via its olfactomedin-like domain with the FLRT1 extracellular domain, marked 'By similarity' [DB:UniProt, PMID:26235030]. IntAct lists an anti-tag coimmunoprecipitation association [DB:IntAct EBI-54534689, PMID:33961781].","molecular_requirements":"The ligand is a FLRT1:TENM3 complex; whether both subunits are required together is not reported in our evidence. The olfactomedin-like domain of ADGRL3 is the stated FLRT1-binding region [DB:UniProt, PMID:26235030].","affinity_potency":[],"species_and_systems":"Experimental species not reported in our evidence; pair listed as human.","localisation_and_range":"Complex flagged membrane-bound, not secreted [flag].","caveats":"Database-only; the UniProt statement is by similarity and concerns FLRT1 alone, not the TENM3 complex. No TENM3-specific record is shown.","key_references":[],"covers":["LR007204"]},"LR002650":{"pair":"FLRT2 -> FLRT2","headline":"FLRT2 homophilic interaction is suggested by one abstract-level paper on FLRT proteins generally.","interaction_type":"functional only","direction_and_effect":"FLRT proteins can physically interact and FLRT-transfected cells sort out from non-transfected cells, a calcium-dependent homotypic adhesion effect [PMID:16440004]. This is a self-interaction, so ligand and receptor are the same protein.","molecular_requirements":"Cell sorting requires the LRR domains and is independent of the cytoplasmic domain [PMID:16440004].","affinity_potency":[],"species_and_systems":"Cultured transfected cells, Xenopus embryos and tissue aggregates; species of the proteins is unspecified in the curated row [PMID:16440004].","localisation_and_range":"Membrane-mediated homotypic adhesion (contact); FLRT2 is also flagged secreted [flag].","caveats":"Read on abstract only. The abstract speaks of FLRT proteins generally, not FLRT2 specifically. Both human and mouse versions are ortholog-inferred.","key_references":[{"PMID":"16440004","why":"FLRT cells sort homotypically; physical FLRT-FLRT interaction."}],"covers":["LR002650","LR005916"]},"LR004144":{"pair":"FN1 -> ITGA5","headline":"Fibronectin binds integrin alpha5beta1; supported by epitope mapping and a mouse in vivo study, plus curated databases.","interaction_type":"direct binding","direction_and_effect":"FN1 acts as an agonist ligand of alpha5beta1; muscle-secreted FN1 drives hepatic autophagy through alpha5beta1 and IKKalpha/beta-JNK1-BECN1 signalling [PMID:36812915]. Annotated stimulatory [flag].","molecular_requirements":"High-affinity binding to the fibronectin central cell-binding domain needs both the RGD site and the adjacent synergy site; the synergy site is recognised mainly by the alpha5 N-terminal repeats and RGD binding mainly by beta1 [PMID:9211865]. The receptor is the alpha5beta1 heterodimer, so ITGB1 is needed alongside ITGA5. Reactome lists an alpha5beta1:FN1 dimer complex [DB:Reactome]; UniProt says ITGA5:ITGB1 is a receptor for FN1 with R-G-D-dependent adhesion [DB:UniProt].","affinity_potency":[],"species_and_systems":"Binding mapping with human proteins/antibodies [PMID:9211865]; hESC integrin screen [PMID:23154389]; mouse exercise model [PMID:36812915]. The mouse pair is ortholog-inferred, not separately tested.","localisation_and_range":"FN1 is flagged secreted and as a receptor, not transmembrane [flag]; the dossier gives no range beyond that. Muscle-secreted circulating FN1 acts on liver, i.e. endocrine-type signalling [PMID:36812915].","caveats":"All three papers were read as abstracts (two with partial full-text excerpts). PMID:23154389 only names FN-binding ITGA5 and shows integrin expression changes, so it is weak. Structures with a P02751 and a P05556 chain exist [DB:PDB 7NWL].","key_references":[{"PMID":"9211865","why":"Maps the RGD and synergy sites to beta1 and alpha5"},{"PMID":"36812915","why":"In vivo functional role of FN1-alpha5beta1 in liver autophagy"}],"covers":["LR000660","LR004144"]},"LR000661":{"pair":"FN1 -> ITGA8","headline":"Fibronectin is a ligand of integrin alpha8beta1 in two independent 1995 papers; no database records.","interaction_type":"direct binding","direction_and_effect":"FN1 is annotated stimulatory [flag]. Alpha8beta1 mediates cell adhesion to fibronectin, and alpha8beta1 binds fibronectin-Sepharose, eluted by GRGDSP [PMID:7559467]; it is a fibronectin receptor promoting attachment, spreading and neurite outgrowth, binding the RGD site [PMID:7626807].","molecular_requirements":"The binding entity is the alpha8beta1 heterodimer (alpha8 associates with beta1) [PMID:7559467]; ITGB1 is therefore needed with ITGA8.","affinity_potency":[],"species_and_systems":"293 cells transfected with alpha8 cDNA [PMID:7559467]; K562 transfectants [PMID:7626807]. The second paper's ligand/receptor species are unspecified in the dossier; the first is labelled human. Mouse pair is ortholog-inferred.","localisation_and_range":"FN1 is flagged secreted and as a receptor, not transmembrane [flag]; the dossier gives no range beyond that.","caveats":"Abstract-only evidence. No database records support this pair. No affinity data reported in our evidence. One further paper is pending.","key_references":[{"PMID":"7559467","why":"Affinity chromatography and adhesion: alpha8beta1 binds fibronectin"},{"PMID":"7626807","why":"K562 alpha8beta1 transfectants adhere and spread on fibronectin via RGD"}],"covers":["LR000661","LR004145"]},"LR004153":{"pair":"FN1 -> MAG","headline":"Fibronectin was pulled down with MAG-Fc from rat/mouse neural cells; a single abstract-level binding study.","interaction_type":"direct binding","direction_and_effect":"A 210-kDa protein precipitated with MAG-Fc from NG108-15 cells was identified as fibronectin by peptide microsequencing, and confirmed in N2A cells, rat brain and spinal cord [PMID:11423128]. Effect direction not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Rat/mouse cell lines and rat tissue; human pair is ortholog-inferred [PMID:11423128].","localisation_and_range":"MAG is flagged secreted and receptor [flag]; the paper describes MAG as mediating glia-neuron cell-cell interactions [PMID:11423128].","caveats":"Affinity precipitation cannot exclude an indirect association; no affinity constant; abstract only. Different fibronectin isoforms were found in young and adult rat brain [PMID:11423128].","key_references":[{"PMID":"11423128","why":"Fibronectin identified as MAG binding partner"}],"covers":["LR000669","LR004153"]},"LR000670":{"pair":"FN1 -> SDC2","headline":"Syndecan-2 heparan sulfate chains bind fibronectin and cooperate with alpha5beta1; mouse cell evidence, human inferred.","interaction_type":"direct binding","direction_and_effect":"Syndecan-2 heparan sulfate side chains bound the fibronectin substrate; antisense knockdown of syndecan-2 prevented stress-fibre formation on fibronectin [PMID:10772816].","molecular_requirements":"Acts in cooperation with integrin alpha5beta1; the heparan sulfate chains mediate binding [PMID:10772816].","affinity_potency":[],"species_and_systems":"Mouse Lewis lung carcinoma P29 cells; human and mouse pairs both ortholog-inferred [PMID:10772816].","localisation_and_range":"Receptor flagged transmembrane [flag]; fibronectin flagged secreted, substrate-bound in the assay [flag].","caveats":"One paper, abstract only; no affinity. Binding is via glycosaminoglycan chains, so it depends on proteoglycan glycosylation. BioGRID lists a reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"10772816","why":"Syndecan-2 heparan sulfate binds fibronectin"}],"covers":["LR000670","LR004154"]},"LR011056":{"pair":"FRAS1:FREM1:NPNT -> ITGA8:ITGB1","headline":"Database-asserted: nephronectin binds integrin alpha8beta1; the FRAS1/FREM partners are not shown.","interaction_type":"database-asserted only","direction_and_effect":"UniProt says NPNT is probably the functional ligand of the integrin in kidney genesis [DB:UniProt]. Direction or effect is otherwise not reported in our evidence.","molecular_requirements":"BioGRID lists NPNT-ITGA8 in reconstituted complex and affinity capture-western assays [DB:BioGRID]; Reactome has an NPNT:ITGA8:ITGB1 complex [DB:Reactome R-HSA-9830935]. A role for FRAS1 or FREM1 in the complex is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"No curator-verified papers (three pending). Database evidence concerns NPNT with ITGA8 only; the ligand complex as a unit is unsupported.","key_references":[],"covers":["LR011056"]},"LR011164":{"pair":"FST -> INHBE","headline":"Weak: one BioGRID reconstituted-complex record; curated papers were off-target or uninformative.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists INHBE-FST as a reconstituted complex [DB:BioGRID]. Direction or effect not reported in our evidence beyond the Inhibitory flag [flag].","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"not reported in our evidence.","localisation_and_range":"Receptor-side flagged secreted [flag].","caveats":"No verified papers: five abstract_insufficient and two different_entity. Single database record only.","key_references":[],"covers":["LR011164"]},"LR004162":{"pair":"GAL -> GALR3","headline":"Galanin binds GALR3 with lower affinity than GALR1/2 in human and rat receptor assays; supported by two abstracts.","interaction_type":"direct binding","direction_and_effect":"Galanin acts as an agonist at GALR3; GtoPdb lists a full agonist action [DB:GtoPdb]. Human GALR3 signals predominantly by inhibiting adenylate cyclase [PMID:9832121], and functional confirmation by GIRK-channel activation is reported [PMID:9722565].","molecular_requirements":"Subunit or co-receptor requirements are not reported in our evidence.","affinity_potency":[{"value":"rat KD = 0.98 nM and human KD = 2.23 nM","assay":"125I-galanin saturation binding","system":"stably expressed rat and human GALR3","cite":"PMID:9722565"},{"value":"IC50 of 75 nM","assay":"competition binding by human galanin","system":"human GALR3","cite":"PMID:9832121"}],"species_and_systems":"Experiments used rat and human GALR3 expressed in cells. The mouse pair is projected from human evidence.","localisation_and_range":"GAL is flagged as secreted and GALR3 as a transmembrane receptor [flag]. Reactome also records a galanin-receptor binding reaction [DB:Reactome].","caveats":"The two papers report different affinities (KD 2.23 nM versus IC50 75 nM for human galanin) from different assay formats and are not directly comparable. Both were read as abstracts only. One further paper is pending.","key_references":[{"PMID":"9722565","why":"Cloning of GALR3 with rat and human galanin binding affinities"},{"PMID":"9832121","why":"Human GALR3 pharmacology: IC50 75 nM for human galanin"}],"covers":["LR000678","LR004162"]},"LR007213":{"pair":"GAL -> GALR3:GPR151","headline":"No primary evidence for a GALR3:GPR151 complex; only GALR3 alone is supported by databases.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence for the complex. GtoPdb lists galanin as a full agonist at GALR3 alone [DB:GtoPdb].","molecular_requirements":"Whether GPR151 is needed is not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experiments for this complex are in our evidence; two papers were judged review-only.","localisation_and_range":"GAL is flagged as secreted; the receptor entry is flagged as a transmembrane receptor [flag].","caveats":"Support rests on GALR3 records in GtoPdb and Reactome (galanin receptors binding galanin) [DB:GtoPdb] [DB:Reactome], not on evidence for GPR151 participation.","key_references":[],"covers":["LR007213"]},"LR007222":{"pair":"GDF10 -> ACVR1B:ACVR2B","headline":"Database-asserted only: GtoPdb lists GDF10 as agonist at both chains; no verified paper evidence for this complex.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb records GDF10 as agonist for ACVR1B and for ACVR2B separately [DB:GtoPdb].","molecular_requirements":"Complex of ACVR1B and ACVR2B; each chain only asserted individually [DB:GtoPdb].","affinity_potency":[],"species_and_systems":"Species of experiments not reported in our evidence.","localisation_and_range":"GDF10 is flagged secreted and non-transmembrane [flag], so signalling would be paracrine or autocrine; range not studied in our evidence.","caveats":"No judged papers; the screened papers were review-only or abstract-insufficient. Affinity not reported.","key_references":[],"covers":["LR007222"]},"LR004171":{"pair":"GDF11 -> ACVR1B","headline":"Database-asserted only: UniProt says GDF11 interacts with ACVR1B in an ACVR2B-dependent manner (by similarity).","interaction_type":"database-asserted only","direction_and_effect":"UniProt: GDF11 interacts with ACVR1B, TGFBR1 and ACVR1C in an ACVR2B-dependent manner (By similarity) [DB:UniProt].","molecular_requirements":"ACVR2B is required for the type I interaction per UniProt [DB:UniProt].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"GDF11 flagged secreted [flag].","caveats":"No judged papers; the annotation is by similarity, and two screened rows were different-entity.","key_references":[],"covers":["LR000687","LR004171"]},"LR011218":{"pair":"GDF3 -> TGFBR1","headline":"GDF3 activates ALK5 (TGFBR1) in reporter assays; no binding data and the abstract-only curation understates the evidence.","interaction_type":"functional only","direction_and_effect":"GDF3 is called an ALK5, ALK7, ACVR2A and ACVR2B agonist [PMID:40360531]. With SB-resistant receptors, rmGDF3 raised reporter activation through ALK5 by 70-fold, versus minimal for ALK4 and some for ALK7 [PMID:40360531].","molecular_requirements":"ALK5 and ACVR2A/2B are suggested as prominent receptors for SMAD2/3 activation; the authors do not exclude cell-type effects or required co-receptors [PMID:40360531]. GDF3 did not bind TGFBR2 by SPR [PMID:40360531].","affinity_potency":[],"species_and_systems":"Recombinant mouse GDF3 in reporter cells; curators label read depth abstract only [PMID:40360531].","localisation_and_range":"GDF3 is flagged secreted [flag]; range not reported otherwise in our evidence.","caveats":"No direct GDF3-ALK5 binding reported in our evidence. Reporter cell type is not stated in the excerpts. Two other judged rows were not shown.","key_references":[{"PMID":"40360531","why":"ALK5-dependent SMAD2/3 reporter activation by GDF3"}],"covers":["LR011218"]},"LR004180":{"pair":"GDF5 -> ACVR2A","headline":"GDF-5 binds ActR-II (ACVR2A) in COS-1 transfectants; one abstract-level paper plus a BioGRID record.","interaction_type":"direct binding","direction_and_effect":"GDF-5 bound ActR-II when type II receptor cDNAs were transfected into COS-1 cells [PMID:8702914]. Listed as stimulatory in the interaction record.","molecular_requirements":"Not reported in our evidence beyond type II binding; GDF-5 did not bind TGF-beta type II receptor [PMID:8702914].","affinity_potency":[],"species_and_systems":"COS-1 transfectants, curators label human [PMID:8702914]. The mouse pair is projected from human.","localisation_and_range":"The ligand is flagged secreted and the receptor transmembrane [flag].","caveats":"Abstract only; second confirmed row not shown. BioGRID is the Affinity Capture-Western record of the same paper [DB:BioGRID].","key_references":[{"PMID":"8702914","why":"GDF-5 binds ActR-II in transfected COS-1 cells"}],"covers":["LR000696","LR004180"]},"LR007231":{"pair":"GDF5 -> ACVR2A:BMPR1B","headline":"GDF-5 binds ActR-II in COS-1 cells and signals through BMPR-IB with it; the complex is inferred from separate observations.","interaction_type":"direct binding","direction_and_effect":"GDF-5 bound ActR-II in COS-1 transfectants [PMID:8702914]. UniProt says GDF5 binds BMPR1B with high affinity [DB:UniProt]. Stimulatory in the interaction record.","molecular_requirements":"The curated paper shows type II binding; signalling through BMPR-IB in the presence of the type II receptor is in the curators' assay description [PMID:8702914].","affinity_potency":[],"species_and_systems":"COS-1 transfectants; curators label human [PMID:8702914].","localisation_and_range":"The receptor complex is flagged transmembrane [flag].","caveats":"Abstract only. The evidence sentence concerns the type II subunit only. Four other rows were review-only.","key_references":[{"PMID":"8702914","why":"GDF-5 type II receptor binding and BMPR-IB signalling"}],"covers":["LR007231"]},"LR007240":{"pair":"GDF7 -> ACVR2A:BMPR1A","headline":"GDF7 -> ACVR2A:BMPR1A: functional evidence only, from one abstract-only paper; chains not shown together.","interaction_type":"functional only","direction_and_effect":"ALK3 overexpression conferred GDF7 signalling in COS7 cells; ActRIIA shRNA suppressed GDF7 signalling in MC3T3 cells [PMID:16049014]. GtoPdb lists agonist records for the individual chains [DB:GtoPdb].","molecular_requirements":"Complex of ACVR2A and BMPR1A (ALK3). Evidence comes from separate manipulations (receptor overexpression or shRNA of one chain), not from a test of the assembled pair [PMID:16049014]. Whether one chain alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"COS7 transfectants and MC3T3 cells with shRNA and Smad1/5/8 reporters; curator species fields are blank or human, abstract-only [PMID:16049014].","localisation_and_range":"Ligand is flagged secreted and the receptor complex as transmembrane [flag], implying paracrine signalling to a cell-surface receptor; not otherwise reported in our evidence.","caveats":"Single abstract-only paper. No binding or affinity data for the assembled complex in our evidence. Direct binding of GDF7 to the individual chains is documented in other rows, not this one.","key_references":[{"PMID":"16049014","why":"Receptor overexpression and shRNA define the type I and type II requirements for GDF7."}],"covers":["LR007240"]},"LR000706":{"pair":"GDF7 -> BMPR1A","headline":"GDF7 binds BMPR1A (ALK3) directly with high affinity and functional support.","interaction_type":"direct binding","direction_and_effect":"Binding: rhBMP12 (GDF7) bound ALK3 (BMPR1A) with high affinity, similar to rhBMP13 (GDF6) (numeric KD not in our excerpts) [PMID:21702718]. ALK3 overexpression in COS7 cells conferred GDF7 signalling, and ALK3 shRNA suppressed signalling by all three orphan ligands [PMID:16049014]. GtoPdb lists an agonist record [DB:GtoPdb].","molecular_requirements":"Type I receptor; a type II receptor partner is implicated: BMPRII and ActRIIA shRNA suppressed GDF7 signalling [PMID:16049014].","affinity_potency":[],"species_and_systems":"Recombinant human BMP12 and receptor ectodomains in binding assays; musculoskeletal marker assays in C3H10T1/2 cells and rat ectopic implants [PMID:21702718]. Signalling studies in COS7 and MC3T3 cells [PMID:16049014]. The mouse pair is projected from human evidence.","localisation_and_range":"Ligand is flagged secreted and the receptor chain(s) as receptor [flag], which would imply paracrine signalling to a membrane receptor; localisation is not otherwise reported in our evidence.","caveats":"Binding is not the same as activation: rhBMP12 gave no detectable SMAD1/5/8 activation in C3H10T1/2 cells at low dose [PMID:21702718], whereas Smad1/5/8 reporters were activated in MC3T3 cells [PMID:16049014]. Numeric affinities are not in the excerpts. rhBMP12 is mapped to GDF7 via alternate names [PMID:16049014]. Both papers are abstract-only reads.","key_references":[{"PMID":"21702718","why":"Kinetic binding of rhBMP12 (GDF7) to type I and II receptors."},{"PMID":"16049014","why":"Receptor requirements for GDF7 signalling."}],"covers":["LR000706","LR004190"]},"LR000715":{"pair":"GH2 -> GHR","headline":"Placental GH variant (GH2) binds the GH-binding protein (soluble GHR ectodomain) as potently as pituitary GH; evidence is one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"hGH-V was equipotent with pituitary hGH as a ligand for the GH-binding protein; GtoPdb lists it as an agonist [PMID:1955498][DB:GtoPdb].","molecular_requirements":"Binding was tested on the soluble GHR ectodomain (GH-BP). The exon-3-encoded region (residues 32-71) is exchangeable with hGH-N, whereas an hGH-N/rat prolactin chimera had 25-fold reduced affinity [PMID:1955498]. Subunit requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human GH-variant and human plasma GH-BP [PMID:1955498].","localisation_and_range":"Ligand is flagged secreted and the receptor transmembrane [flag]; the paper describes secretion into maternal circulation in pregnancy [PMID:1955498].","caveats":"One paper, read as abstract only; no affinity value given. The assay used the soluble binding protein, not full-length membrane GHR. Reactome records are of GH-activated GHR-JAK2 complexes, not specific to GH2 [DB:Reactome].","key_references":[{"PMID":"1955498","why":"GH-V equipotent with GH-N for GH-BP binding"}],"covers":["LR000715"]},"LR007033":{"pair":"GJA3 -> GJC1","headline":"GJA3 - GJC1 rests on database records only; no curator-confirmed paper.","interaction_type":"database-asserted only","direction_and_effect":"IntAct lists an association by anti-tag coimmunoprecipitation [DB:IntAct][PMID:33961781]. Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Both partners are flagged transmembrane (gap-junction class) [flag].","caveats":"The single judged paper was different_entity; none confirmed.","key_references":[],"covers":["LR007033"]},"LR001831":{"pair":"GLG1 -> SELE","headline":"E-selectin binds ESL-1 (GLG1) with very low affinity in mouse SPR data; two confirmed rows share one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Monomeric E-selectin binds ESL-1 from mouse bone marrow cells by surface plasmon resonance, with Kd 62 uM and koff 4.6 s-1 [PMID:11404363]. Recombinant ESL-1 from alpha1,3-fucosyltransferase IV CHO cells gave Kd 66 uM [PMID:11404363]. Reactome has an E-selectin-ligand binding reaction [DB:Reactome].","molecular_requirements":"Fucosylation-linked: recombinant ESL-1 from fucosyltransferase IV CHO cells binds [PMID:11404363]. Other requirements not reported in our evidence.","affinity_potency":[{"value":"Kd 62 microm","assay":"surface plasmon resonance","system":"mouse E-selectin and ESL-1 from mouse bone marrow cells","cite":"PMID:11404363"}],"species_and_systems":"Mouse proteins; the human pair is ortholog-inferred and the mouse pair is the experimental one [PMID:11404363].","localisation_and_range":"Receptor flagged transmembrane [flag]; ligand not secreted [flag]; adhesion between cells is implied by selectin rolling in curator notes.","caveats":"One paper, abstract only. Fast off-rate and very low affinity are consistent with transient adhesion rather than stable binding (curator interpretation).","key_references":[{"PMID":"11404363","why":"SPR kinetics of E-selectin binding ESL-1"}],"covers":["LR001831","LR005186"]},"LR000724":{"pair":"GPHA2 -> TSHR","headline":"Thyrostimulin (GPHA2/GPHB5 heterodimer) binds with high affinity and activates the TSH receptor; one recombinant-protein paper plus database support.","interaction_type":"direct binding","direction_and_effect":"Agonist, stimulatory [flag]. Recombinant A2/B5 heterodimer activated human TSH receptors, but not LH and FSH receptors, and showed high affinity in a radioligand receptor assay; it stimulated cAMP and thymidine incorporation in cultured thyroid cells and raised serum thyroxine in TSH-suppressed rats [PMID:12045258]. UniProt and Reactome agree [DB:UniProt][DB:Reactome].","molecular_requirements":"The GPHA2/GPHB5 heterodimer (alpha2/beta5) is the ligand; the heterodimerisation was shown by yeast two-hybrid and immunology [PMID:12045258]. The GPHA2 chain alone is not shown to act. Our evidence inherits the heterodimer's activity for GPHA2.","affinity_potency":[],"species_and_systems":"Human TSH receptors with recombinant human proteins, cultured thyroid cells, rats in vivo [PMID:12045258]. Mouse pair is ortholog-inferred.","localisation_and_range":"GPHA2 is annotated secreted [flag]; the authors infer a paracrine mechanism from pituitary co-expression [PMID:12045258].","caveats":"Abstract only; no numeric affinity in our evidence. The GPHB5 partner is needed for the ligand, so expression of both chains matters in CCC scoring. Reactome pools TSH and thyrostimulin in one reaction.","key_references":[{"PMID":"12045258","why":"Thyrostimulin activates TSH receptor; radioligand binding"}],"covers":["LR000724","LR004206"]},"LR004207":{"pair":"Gpi1 -> Amfr","headline":"Mouse pair projected from the human GPI -> AMFR evidence; all experiments in our dossier used human proteins.","interaction_type":"direct binding","direction_and_effect":"The mouse pair is inferred from human evidence. In human protein experiments, GPI/AMF binds gp78/AMF-R and acts as a cytokine [PMID:12527360], and AMF mutants with lower AMFR binding lost motility stimulation [PMID:16563432]. Agonist.","molecular_requirements":"Enzymatic activity is not required for receptor binding [PMID:12527360]; AMFR N-sugar chain and the AMF C-terminal region are needed [PMID:16563432].","affinity_potency":[],"species_and_systems":"Experiments used recombinant human AMF/PGI; no mouse experiment is reported in our evidence [PMID:12527360] [PMID:16563432].","localisation_and_range":"Gpi1 is flagged as secreted [flag].","caveats":"Ortholog-inferred only; both papers abstract-only; no affinity values reported in our evidence.","key_references":[{"PMID":"12527360","why":"Human PGI binds gp78/AMF-R independent of enzyme activity"},{"PMID":"16563432","why":"Human AMF mutants and receptor glycan requirement"}],"covers":["LR004207"]},"LR002704":{"pair":"GPNMB -> EGFR","headline":"GPNMB binds the EGFR C-terminus and activates mutated EGFR without EGF in NSCLC cells; one paper plus database records.","interaction_type":"direct binding","direction_and_effect":"GPNMB activated mutated EGFR without ligand stimulation, bound the EGFR C-terminus, assisted Y845 phosphorylation, turned on STAT3 signalling and promoted metastasis [PMID:33706413]. Agonist-like, ligand-independent. A different model has GPNMB in a complex with EGFR under HB-EGF stimulation [DB:Reactome].","molecular_requirements":"N134 glycosylation of GPNMB is crucial: depleting it greatly reduced binding to mutated EGFR [PMID:33706413]. Binding to mutated EGFR (especially L858R) was stronger than to wild-type EGFR [PMID:33706413].","affinity_potency":[],"species_and_systems":"Human NSCLC cells with EGFR mutations, plus in vivo metastasis experiments [PMID:33706413]. Wild-type EGFR binding was weaker.","localisation_and_range":"GPNMB is flagged as secreted [flag]; the paper treats it as a transmembrane glycoprotein [PMID:33706413], so contact-dependent action is plausible but not tested here.","caveats":"Effect is largely specific to mutated EGFR. The paper itself contrasts its model with a reported HB-EGF-dependent complex in breast cancer [PMID:33706413]. BioGRID, IntAct and Reactome records rest on PMID 26751287 [DB:BioGRID] [DB:IntAct] [DB:Reactome].","key_references":[{"PMID":"33706413","why":"N-glycosylated GPNMB binds and activates mutated EGFR"}],"covers":["LR002704","LR005969"]},"LR000733":{"pair":"GZMB -> IGF2R","headline":"Granzyme B uptake via CI-MPR/IGF2R is reported in one 2000 paper; the model is contested.","interaction_type":"functional only","direction_and_effect":"Inhibiting the granzyme B-CI-MPR interaction prevented granzyme B cell-surface binding, uptake and apoptosis; CI-MPR was essential for cytotoxic T cell-mediated apoptosis in vitro and allogeneic rejection in vivo [PMID:11081635].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse (ligand and receptor) in vitro and in vivo [PMID:11081635]. Human pair is ortholog-inferred in the mouse direction.","localisation_and_range":"GZMB is flagged secreted; IGF2R as a transmembrane receptor [flag].","caveats":"Curator notes that the uptake-receptor model was substantially challenged by later work (not in this dossier). Abstract-only reading; a pending row exists.","key_references":[{"PMID":"11081635","why":"CI-MPR as granzyme B receptor"}],"covers":["LR000733","LR004215"]},"LR004216":{"pair":"HBEGF -> CD44","headline":"HB-EGF binds heparan sulfate-modified CD44 isoforms in COS-cell transfectants; binding depends on the sugar chain.","interaction_type":"direct binding","direction_and_effect":"HS-modified CD44 isoforms bound HB-EGF and b-FGF but not amphiregulin; binding was eliminated by heparitinase or free heparin [PMID:7532176]. CD44 here presents the growth factor; signalling effect is not reported in our evidence.","molecular_requirements":"Requires CD44 isoforms containing exon V3 that carry heparan sulfate; CD44H lacking V3 on activated endothelial cells showed no detectable HS modification [PMID:7532176]. BioGRID lists a reconstituted complex [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Human cells: COS transfectants and keratinocytes; HB-EGF binding shown for the transfectants [PMID:7532176]. Mouse pair is ortholog-inferred.","localisation_and_range":"Both partners are flagged secreted and transmembrane [flag]; presentation at cell surfaces during inflammation is the authors' proposal [PMID:7532176].","caveats":"Binding is heparan sulfate-mediated, so it may not be a protein-protein ligand-receptor interaction. One paper; no affinity.","key_references":[{"PMID":"7532176","why":"HS-modified CD44 V3 isoforms bind HB-EGF"}],"covers":["LR000734","LR004216"]},"LR000742":{"pair":"HEBP1 -> FPR3","headline":"The HEBP1-derived peptide F2L binds and activates FPR3 (FPRL2) in the low nanomolar range; one full-text primary paper plus database support.","interaction_type":"direct binding","direction_and_effect":"F2L, an acetylated N-terminal peptide from cleavage of human heme-binding protein, binds and activates FPRL2 (FPR3), causing calcium release, cAMP inhibition and ERK1/2 phosphorylation through Gi [PMID:15623572]. Agonist [DB:GtoPdb].","molecular_requirements":"The acting ligand is the cleaved F2L peptide (21 residues, acetylated), not full-length HEBP1 [PMID:15623572]. Saturation and competition binding on FPRL2 cells used iodinated F2L [PMID:15623572]. Pertussis-toxin sensitivity indicates Gi [PMID:15623572]. Receptor chains or co-receptors: not reported in our evidence.","affinity_potency":[{"value":"pEC50 8.02","assay":"aequorin calcium","system":"CHO-K1 cells expressing FPRL2","cite":"PMID:15623572"},{"value":"pEC50 8.24","assay":"cAMP accumulation","system":"CHO-K1 cells expressing FPRL2","cite":"PMID:15623572"},{"value":"pIC50 7.48","assay":"competition binding","system":"CHO-K1 cells expressing FPRL2","cite":"PMID:15623572"},{"value":"EC50 567 nM","assay":"aequorin, F2L at FPRL1 (selectivity)","system":"CHO-K1 cells expressing FPRL1","cite":"PMID:15623572"}],"species_and_systems":"Natural peptide purified from porcine spleen; synthetic peptide tested on CHO-K1 cells expressing human FPRL2, and on monocytes and monocyte-derived dendritic cells [PMID:15623572].","localisation_and_range":"HEBP1 is described as an intracellular protein [PMID:15623572], although the entity flags list it as transmembrane and not secreted [flag]; the peptide acts on the cell surface as a chemoattractant after cleavage.","caveats":"Only one primary paper. F2L is much weaker at FPRL1 and gave only partial cAMP inhibition at FPR [PMID:15623572]. Relevance depends on HEBP1 cleavage and release, which expression-based CCC tools will not capture.","key_references":[{"PMID":"15623572","why":"Isolation and characterisation of F2L as FPRL2 agonist"}],"covers":["LR000742"]},"LR004225":{"pair":"HGF -> MET","headline":"Canonical HGF-MET pair with direct binding, a crystal structure and receptor-activation data; very well supported.","interaction_type":"direct binding","direction_and_effect":"HGF acts as an agonist: it binds MET and induces tyrosine phosphorylation of the Met beta subunit [PMID:1655405][PMID:1846706]. UniProt describes HGF as an activating ligand that promotes MET dimerization [DB:UniProt]. A shed soluble Met fragment can bind HGF and act as a decoy that blocks HGF/c-Met signalling [PMID:22689693].","molecular_requirements":"Only the proteolytically mature HGF beta-chain, not the single-chain precursor, binds Met in the crystal structure with the Sema/PSI domains [PMID:15167892]. Mature HGF is an alpha/beta heterodimer: a high-affinity site in HGF-alpha binds Met IPT domains 3 and 4, and a low-affinity site in HGF-beta binds the Sema domain [PMID:18495663]. Pro-HGF binds but does not activate Met [PMID:18495663].","affinity_potency":[],"species_and_systems":"Experiments used human proteins and human cells; the dossier covers both the human and mouse pair, and no mouse-specific experiments are reported in our evidence [PMID:1655405][PMID:15167892]. Structures are listed in PDB, for example [DB:PDB 1SHY].","localisation_and_range":"HGF is annotated as secreted and MET as a transmembrane receptor [flag], so signalling is paracrine or autocrine.","caveats":"No affinity values for HGF-MET are given in our evidence. Several papers were read as abstracts only. Soluble Met may dampen HGF signalling [PMID:22689693].","key_references":[{"PMID":"1846706","why":"HGF cross-linked to c-met; c-met is the cell-surface HGF receptor"},{"PMID":"15167892","why":"Crystal structure of HGF beta-chain with Met Sema/PSI"},{"PMID":"18495663","why":"High-affinity HGF-alpha site on Met IPT 3/4"}],"covers":["LR000744","LR004225"]},"LR002713":{"pair":"HGFAC -> LRP1","headline":"Direct LRP1 binding of HGFAC shown in a chondrocyte ligandome study (abstract only); a scavenger-type endocytic receptor interaction.","interaction_type":"direct binding","direction_and_effect":"Purified LRP1 binds HGFAC directly, one of ten ligands confirmed in this way; LRP1 affinity correlated with endocytosis rate across these ligands [PMID:36028175]. This indicates LRP1 acts as an endocytic receptor, not a signalling agonist target; the paper's effect label was agonist, which is not clearly supported [PMID:36028175].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human chondrocytes and purified proteins, with a conditional Lrp1-knockout mouse model used for the wider ligandome; the dossier does not say that HGFAC itself was tested in mice [PMID:36028175].","localisation_and_range":"HGFAC and LRP1 are annotated as secreted and as a receptor respectively [flag].","caveats":"One paper read as an abstract; HGFAC is one of ten ligands covered in a single sentence and no HGFAC-specific affinity is reported. No database records.","key_references":[{"PMID":"36028175","why":"Direct LRP1 binding of HGFAC among ten chondrocyte ligands"}],"covers":["LR002713","LR005978"]},"LR000751":{"pair":"HLA-B -> KIR3DL1","headline":"Supported by allele-specific tetramer binding and early functional work; binding depends on the HLA-B allele and the bound peptide.","interaction_type":"direct binding","direction_and_effect":"KIR3DL1 recognises certain HLA-B alleles. NKB1 (later designated KIR3DL1 in the curator notes) was described as a receptor for HLA-B*5101 and -B*5801; DX9 mAb inhibited NK-clone interaction with targets bearing certain HLA-B alleles [PMID:8046332]. Only KIR3DL1*005 bound both HLA-A*2402 and HLA-B*5703 tetramers [PMID:17182537].","molecular_requirements":"Binding is allele-specific on both sides and peptide-dependent per the title [PMID:17182537].","affinity_potency":[],"species_and_systems":"Human NK clones and B-LCL targets [PMID:8046332]; human KIR3DL1 alleles with HLA tetramers [PMID:17182537].","localisation_and_range":"Both partners are flagged transmembrane [flag]; contact-dependent.","caveats":"The 1994 paper is functional (cytotoxicity blocking), not physical binding [PMID:8046332]. Both papers were read as abstracts. Evidence covers only some alleles. Two review-only, one abstract-insufficient and one pending row are not counted. No database records.","key_references":[{"PMID":"17182537","why":"Allele-specific KIR3DL1 binding to HLA-A and HLA-B tetramers"},{"PMID":"8046332","why":"NKB1 identified as NK receptor for certain HLA-B alleles"}],"covers":["LR000751"]},"LR002722":{"pair":"HLA-C -> CD8A","headline":"One SPR study shows weak, direct binding of CD8alpha-alpha to classical MHC class I including HLA-C*0702.","interaction_type":"direct binding","direction_and_effect":"CD8 acts as a co-receptor binding the same MHC molecules as the T-cell receptor and enhancing antigen recognition sensitivity [PMID:10809759].","molecular_requirements":"The CD8alpha-alpha homodimer was tested in SPR [PMID:10809759]; role of CD8beta is not reported in our evidence.","affinity_potency":[{"value":"Kd 90-220 \u03bcM","assay":"surface plasmon resonance, CD8alpha-alpha binding to HLA-A*0201, -A*1101, -B*3501 and -C*0702","system":"recombinant proteins","cite":"PMID:10809759"}],"species_and_systems":"Recombinant proteins in SPR with human HLA allele names [PMID:10809759]; experiment species fields are not given in the dossier.","localisation_and_range":"Both are annotated transmembrane (CD8A also carries a secreted flag) [flag]; the abstract describes co-receptor binding on the cell surface [PMID:10809759].","caveats":"Single paper read as an abstract; the 90-220 \u03bcM range pools several alleles, so the HLA-C-specific value is not separable. Very low affinity.","key_references":[{"PMID":"10809759","why":"SPR affinity of CD8alpha-alpha for classical MHC class I"}],"covers":["LR002722"]},"LR000760":{"pair":"HLA-E -> KLRC1","headline":"Well-established direct binding of HLA-E to inhibitory KLRC1 (NKG2A), always studied with CD94.","interaction_type":"direct binding","direction_and_effect":"HLA-E binds the inhibitory NKG2A/CD94 receptor; surface HLA-E protected targets from lysis by CD94/NKG2A+ NK clones [PMID:9486650]. NKG2A bound HLA-E with high affinity, indistinguishable from NKG2E and higher than NKG2C [PMID:15728498].","molecular_requirements":"Studied as CD94/NKG2A heterodimer [PMID:15728498][PMID:9486650]; KLRC1 alone not tested in our evidence. UniProt says KLRC1 plays a prominent role in directly interacting with HLA-E [DB:UniProt]. HLA-E must present a leader-sequence peptide; peptide identity influenced affinity, HLA-E allelic differences did not [PMID:15728498].","affinity_potency":[],"species_and_systems":"Human proteins and NK cells: tetramer on transfectants and NK clones; purified receptor/HLA-E complexes [PMID:9486650][PMID:15728498]. Structures PDB 3CDG, 3CII [DB:PDB 3CDG].","localisation_and_range":"Annotation flags: HLA-E secreted and transmembrane, KLRC1 transmembrane [flag]; HLA-E acts at cell contact.","caveats":"No numeric affinity in our evidence. Both papers abstract only. One further paper was review-only.","key_references":[{"PMID":"9486650","why":"HLA-E tetramer binds CD94/NKG2A; protects from NK lysis"},{"PMID":"15728498","why":"Affinities of NKG2A/CD94 vs NKG2C and NKG2E for HLA-E"}],"covers":["LR000760"]},"LR001840":{"pair":"HLA-F -> KIR3DL2","headline":"HLA-F open conformers bind KIR3DL2 with intermediate affinity; direct binding, plus database function notes of inhibition.","interaction_type":"direct binding","direction_and_effect":"HLA-F OCs bound KIR3DL2-Fc and triggered KIR3DL2zeta Jurkat reporter cells [PMID:27455421]. UniProt states that interaction with KIR3DL2 inhibits NK and T cell effector functions [DB:UniProt].","molecular_requirements":"Binding is to peptide-free, beta2m-free HLA-F open conformers [PMID:27455421]; UniProt says peptide-free OC acts as ligand for KIR3DS1 and KIR3DL2 [DB:UniProt].","affinity_potency":[{"value":"KD = (118 \u00b1 1) nM","assay":"surface plasmon resonance","system":"HLA-F OCs with KIR3DL2-Fc","cite":"PMID:27455421"}],"species_and_systems":"Human recombinant proteins and Jurkat reporter cells [PMID:27455421].","localisation_and_range":"Not reported in our evidence; HLA-F flagged transmembrane [flag].","caveats":"One primary paper; the Jurkat reporter readout (CD69) was activating, whereas UniProt describes inhibition, so the functional sign is unclear. IntAct also lists SPR records [DB:IntAct].","key_references":[{"PMID":"27455421","why":"HLA-F OCs bind KIR3DS1, KIR3DL1, KIR3DL2 with SPR affinities"}],"covers":["LR001840"]},"LR002731":{"pair":"HLA-G -> CD160","headline":"Soluble HLA-G1 reported to bind CD160 on endothelial cells and induce apoptosis; one abstract.","interaction_type":"direct binding","direction_and_effect":"sHLA-G1 induced endothelial cell apoptosis through binding to CD160; anti-CD160 mAb CL1-R2 mimicked tube-formation inhibition and apoptosis [PMID:16809620]. UniProt describes CD160 as inhibitory on endothelial cells controlling angiogenesis [DB:UniProt].","molecular_requirements":"Soluble HLA-G1 isoform [PMID:16809620].","affinity_potency":[],"species_and_systems":"Human endothelial cells in vitro; rabbit corneal neovascularisation model for the angiogenesis effect [PMID:16809620].","localisation_and_range":"Soluble isoform sHLA-G1, so paracrine; HLA-G and CD160 both flagged secreted [flag].","caveats":"Abstract only; no affinity or binding assay detail in the dossier.","key_references":[{"PMID":"16809620","why":"sHLA-G1 binds CD160, inhibits angiogenesis"}],"covers":["LR002731"]},"LR002740":{"pair":"HMGB1 -> TLR4","headline":"HMGB1 is reported to act through TLR4 (proconvulsant in mice); database records include direct-binding assays, but the paper evidence is functional.","interaction_type":"functional only","direction_and_effect":"HMGB1 released from neurons and glia interacts with TLR4 in a proconvulsant pathway; antagonists of HMGB1 and TLR4 reduce seizures, and TLR4-defective C3H/HeJ mice are resistant to kainate-induced seizures [PMID:20348922]. The annotated modulatory effect is stimulatory [flag].","molecular_requirements":"Reactome describes HMGB1 binding the TLR4:LY96 complex [DB:Reactome]; UniProt says signalling through TLR4 seems to implicate LY96/MD-2 [DB:UniProt].","affinity_potency":[],"species_and_systems":"C57BL/6 mice and TLR4-defective C3H/HeJ mice; increased HMGB1 and TLR4 expression also seen in human epileptogenic tissue [PMID:20348922].","localisation_and_range":"HMGB1 is flagged as secreted [flag]; released from neurons and glia in tissue [PMID:20348922].","caveats":"The paper was read as an abstract only and does not report binding. Binding support comes from IntAct (co-immunoprecipitation, surface plasmon resonance) [DB:IntAct] and Reactome. One further judged row is still pending.","key_references":[{"PMID":"20348922","why":"Mouse seizure models: HMGB1-TLR4 pathway, antagonists and TLR4-mutant mice"}],"covers":["LR002740","LR005988"]},"LR004234":{"pair":"HSPG2 -> COL13A1","headline":"Human recombinant binding of the type XIII collagen ectodomain to perlecan, measured by SPR in the nanomolar range; adhesion partner, not a signalling pair.","interaction_type":"direct binding","direction_and_effect":"Recombinant COL13A1 ectodomain interacted with immobilised perlecan, fibronectin and nidogen-2 by surface plasmon resonance; no signalling was shown [PMID:11956183]. Curators note the usual direction is inverted, because COL13A1 is the transmembrane partner [PMID:11956183]. UniProt also records the interaction [DB:UniProt].","molecular_requirements":"Perlecan and nidogen-2 binding resides in the pepsin-sensitive portions of the ectodomain; the ectodomain forms 240-kDa trimers [PMID:11956183].","affinity_potency":[{"value":"K(D) in the nanomolar range","assay":"surface plasmon resonance, ectodomain vs immobilised perlecan","system":"recombinant COL13A1 ectodomain from insect cells","cite":"PMID:11956183"}],"species_and_systems":"Recombinant human proteins in vitro [PMID:11956183]. Mouse pair is ortholog-inferred.","localisation_and_range":"COL13A1 is flagged transmembrane and HSPG2 secreted [flag]; the ectodomain is shed in cell culture, and the paper links it to cell-adhesion sites [PMID:11956183]. This is a matrix or contact interaction.","caveats":"Abstract only; no exact K(D). Binding of a shed ectodomain to matrix does not show receptor signalling.","key_references":[{"PMID":"11956183","why":"SPR binding of COL13A1 ectodomain to perlecan, fibronectin and nidogen-2"}],"covers":["LR000776","LR004234"]},"LR008023":{"pair":"IAPP -> CALCRL:RAMP2","headline":"Weakly supported: only GtoPdb and structure records, mostly describing RAMP2 with CALCR; no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists IAPP-RAMP2 full agonist records [DB:GtoPdb]. UniProt describes RAMP2 together with CALCR as an amylin receptor complex [DB:UniProt].","molecular_requirements":"PDB 9BQ3 is the human Amylin2 receptor (CALCR-based) with Gs and cagrilintide [DB:PDB 9BQ3]; a CALCRL requirement is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and experimental system are not reported in our evidence.","localisation_and_range":"IAPP is flagged secreted and the complex transmembrane [flag].","caveats":"No curated paper; the only judged row was review_only. Records support CALCR:RAMP2 rather than CALCRL:RAMP2.","key_references":[],"covers":["LR008023"]},"LR004243":{"pair":"ICAM1 -> ITGAM","headline":"ICAM-1 engages Mac-1 (ITGAM:ITGB2) in cell adhesion assays; evidence is functional and activation-dependent.","interaction_type":"functional only","direction_and_effect":"ICAM-1-expressing CHO cells adhered to immobilized purified Mac-1, and CDR-derived peptides blocked this at 10-100 muM [PMID:9488691]. An activating anti-alphaM antibody induced alphaMbeta2-transfected CHO cell adhesion to ICAM-1 [PMID:11073102]. UniProt says ITGAM/ITGB2 is also a receptor for ICAM1 [DB:UniProt].","molecular_requirements":"Requires the alphaM-beta2 integrin and an activated conformation; resting leukocyte beta2 integrins do not bind ligands [PMID:11073102].","affinity_potency":[],"species_and_systems":"Human proteins in transfected CHO cells and purified Mac-1 [PMID:9488691, PMID:11073102].","localisation_and_range":"ITGAM is not flagged secreted; cell-contact adhesion between cells [PMID:9488691].","caveats":"Both papers were abstract-only. The adhesion readout shows involvement, not affinity. One additional row was different_entity.","key_references":[{"PMID":"9488691","why":"ICAM-1 CHO cell adhesion to purified Mac-1"},{"PMID":"11073102","why":"Activation-dependent adhesion to ICAM-1"}],"covers":["LR000785","LR004243"]},"LR007042":{"pair":"ICAM3 -> ITGAD:ITGB2","headline":"alphaD/CD18 recognises ICAM-3 preferentially over ICAM-1 in the discovery paper; one abstract plus BioGRID and UniProt.","interaction_type":"direct binding","direction_and_effect":"The alphaD/CD18 molecule recognises ICAM-3 preferentially over ICAM-1 [PMID:8777714]; UniProt describes ITGAD:ITGB2 as a receptor for ICAM3 and VCAM1 [DB:UniProt].","molecular_requirements":"The complex alphaD with CD18 is the receptor [PMID:8777714].","affinity_potency":[],"species_and_systems":"Human myelomonocytic cell lines and peripheral blood leukocytes [PMID:8777714].","localisation_and_range":"Membrane-bound; contact-dependent. alphaD was strongly expressed on aortic foam cells [PMID:8777714].","caveats":"Abstract only; no affinity. The preference is relative to ICAM-1 [PMID:8777714]. BioGRID has a reconstituted-complex record [DB:BioGRID].","key_references":[{"PMID":"8777714","why":"alphaD/CD18 prefers ICAM-3 over ICAM-1"}],"covers":["LR007042"]},"LR004252":{"pair":"ICAM4 -> ITGAM","headline":"Human studies show Mac-1 (alphaMbeta2) binding to ICAM-4-Fc; first and second Ig domains are involved; mouse pair is ortholog-inferred.","interaction_type":"direct binding","direction_and_effect":"alphaMbeta2 transfectants bind recombinant ICAM-4-Fc specifically and dose dependently [PMID:15355350]; antibodies to CD11b or CD18 blocked L-cell adhesion to ICAM-4-Fc, which was sensitive to Ca2+ and Mg2+ [PMID:10846180]. UniProt lists ITGAM:ITGB2 as an ICAM4 partner in vitro [DB:UniProt].","molecular_requirements":"The complex alphaM/beta2 (Mac-1) is the receptor. The Mac-1 binding site encompasses both the first and second Ig-like domains of ICAM-4 [PMID:10846180].","affinity_potency":[],"species_and_systems":"Human ICAM-4-Fc with human integrin transfectants and L-cells [PMID:15355350, PMID:10846180].","localisation_and_range":"ICAM4 carries both secreted and transmembrane flags [flag], so range is unclear; the papers used recombinant ICAM-4-Fc and cell-surface ICAM-4, consistent with contact-dependent adhesion.","caveats":"Both papers abstract only; one is an adhesion assay. A fifth judged row was abstract-insufficient. Affinity not reported.","key_references":[{"PMID":"15355350","why":"Dose-dependent alphaMbeta2 binding to ICAM-4-Fc"},{"PMID":"10846180","why":"Mac-1 binding spans ICAM-4 domains 1 and 2"}],"covers":["LR000798","LR004252"]},"LR006007":{"pair":"ICAM4 -> ITGB5","headline":"Weak support: alphaVbeta5 is suggested by antibody inhibition of cell adhesion to ICAM-4-Fc in one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"Adhesion of alpha4beta1-negative non-haemopoietic cells to ICAM-4-Fc was RGD-inhibitable and, by antibody inhibition, mediated by alphaV integrins, notably alphaVbeta1 and alphaVbeta5 [PMID:11435317]. UniProt lists ITGA5:ITGB5 among ICAM4 partners in vitro [DB:UniProt].","molecular_requirements":"beta5 would act with alphaV; no beta5-alone evidence. Neither the LETS nor LDV motif in domain 1 was critical [PMID:11435317].","affinity_potency":[],"species_and_systems":"Human cell lines with an ICAM-4-Fc construct [PMID:11435317]; mouse pair ortholog-inferred.","localisation_and_range":"ICAM4 carries both secreted and transmembrane flags [flag], so range is unclear; the papers used recombinant ICAM-4-Fc and cell-surface ICAM-4, consistent with contact-dependent adhesion.","caveats":"One paper, abstract only; beta5 is named only as one of two notable alphaV partners. Affinity not reported.","key_references":[{"PMID":"11435317","why":"alphaV-family integrins including alphaVbeta5 mediate adhesion to ICAM-4-Fc"}],"covers":["LR002761","LR006007"]},"LR000814":{"pair":"IFNA1 -> IFNAR2","headline":"Direct binding of IFNA1 to IFNAR2, but notably weak (220 nM) compared with other alpha subtypes.","interaction_type":"direct binding","direction_and_effect":"IFNA1 is an agonist of IFNAR2 in GtoPdb [DB:GtoPdb].","molecular_requirements":"IFNAR2 is one chain of the IFNAR1/IFNAR2 receptor [PMID:17174979]. Chain-level evidence.","affinity_potency":[{"value":"220 nM (IFN-alpha1)","assay":"binding affinity of isolated receptor chain","system":"human, isolated IFNAR2","cite":"PMID:21856167"},{"value":"0.4-5 nM (other alpha-IFNs)","assay":"as above","system":"human","cite":"PMID:21856167"}],"species_and_systems":"Human recombinant systems [PMID:21856167] [PMID:17174979]. A docking study used IFN-alpha 2 [PMID:11698684].","localisation_and_range":"IFNA1 is flagged secreted [flag].","caveats":"IFNA1 shows a substantial decrease in affinity for ifnar2 [PMID:17174979]. 11698684 is computational and studies IFN-alpha 2. Two papers are abstract only.","key_references":[{"PMID":"21856167","why":"Reports the 220 nM IFN-alpha1 outlier"},{"PMID":"17174979","why":"IFN\u03b11 reduced ifnar2 affinity"}],"covers":["LR000814","LR004266"]},"LR000805":{"pair":"IFNA10 -> IFNAR1","headline":"Direct binding of the IFNAR1 chain by alpha-IFN subtypes, supported by one class-wide abstract.","interaction_type":"direct binding","direction_and_effect":"IFNA10 is a stimulatory agonist at IFNAR1 [PMID:21856167] [DB:GtoPdb].","molecular_requirements":"Chain-only evidence: affinity measured on isolated IFNAR1 [PMID:21856167].","affinity_potency":[{"value":"0.5-5 \u03bcM","assay":"binding to isolated receptor chain","system":"12 human alpha-IFN subtypes","cite":"PMID:21856167"}],"species_and_systems":"Human isolated receptor chains [PMID:21856167].","localisation_and_range":"IFNA10 flagged secreted [flag].","caveats":"Abstract only; IFNA10 is not named in the abstract and rests on a class statement for 12 subtypes [PMID:21856167].","key_references":[{"PMID":"21856167","why":"Affinities of alpha-IFN subtypes for IFNAR1/2"}],"covers":["LR000805"]},"LR011713":{"pair":"IFNA14 -> IFNA2:IFNAR1:IFNAR2","headline":"Entity looks spurious; one in vivo paper compares IFN-alpha2 and alpha14 effects, but does not test this complex.","interaction_type":"functional only","direction_and_effect":"Human IFN-alpha2 and alpha14 gave different JAK-STAT activation and immune responses in IFNAR-hEC mice and isolated cells [PMID:37994664]. GtoPdb lists IFNA14 as agonist of each chain [DB:GtoPdb].","molecular_requirements":"IFNAR1/IFNAR2 are the shared receptor subunits [PMID:37994664]. The entity includes IFNA2 as a member.","affinity_potency":[],"species_and_systems":"Mice with extracellular-humanized IFNAR1/2 on C57BL/6N and isolated cells [PMID:37994664].","localisation_and_range":"IFNA14 flagged secreted [flag].","caveats":"Abstract only [PMID:37994664]. The paper compares two ligands rather than testing a ligand-complex containing IFNA2.","key_references":[{"PMID":"37994664","why":"IFNA2 vs IFNA14 signalling in humanised IFNAR mice"}],"covers":["LR011713"]},"LR000823":{"pair":"IFNA6 -> IFNAR1","headline":"IFNA6 binds IFNAR1 as a type I interferon agonist; support is a class-wide binding study plus GtoPdb.","interaction_type":"direct binding","direction_and_effect":"IFNA6 acts as an agonist on the type I interferon receptor; the curator-verified study reports binding of human alpha-IFN subtypes to isolated receptor chains [PMID:21856167]. GtoPdb lists this as an agonist interaction with no affinity units [DB:GtoPdb].","molecular_requirements":"IFNAR2 is the tight-binding chain (0.4-5 nM) and IFNAR1 the weak one (0.5-5 \u03bcM) for alpha-IFNs [PMID:21856167]. Whether the pair needs both chains for signalling is not reported in our evidence beyond this binding comparison.","affinity_potency":[{"value":"0.5-5 \u03bcM","assay":"affinity and rate-constant determination, 12 human alpha-IFN subtypes collectively, isolated IFNAR1 chain","system":"human proteins","cite":"PMID:21856167"}],"species_and_systems":"Human ligand and human receptor chains, isolated recombinant chains (abstract-level reading) [PMID:21856167]. The mouse pair is projected from human evidence (ortholog-inferred); no mouse experiment is in our evidence.","localisation_and_range":"Ligand is flagged secreted and not transmembrane [flag], so it acts as a diffusible paracrine or endocrine signal.","caveats":"The affinity range is stated for 'Alpha-IFNs' as a class, not IFNA6 individually; only IFN-alpha1 (220 nM) is singled out as weaker, and the paper was read as an abstract only [PMID:21856167].","key_references":[{"PMID":"21856167","why":"binding of 12 human alpha-IFN subtypes to isolated IFNAR1 and IFNAR2"}],"covers":["LR000823","LR004267"]},"LR011722":{"pair":"IFNA8 -> IFNA2:IFNAR1:IFNAR2","headline":"IFNA8 to an IFNA2:IFNAR1:IFNAR2 complex rests only on GtoPdb records for the individual chains.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists IFNA8 as an agonist at IFNAR1 and at IFNAR2 separately [DB:GtoPdb]. No paper in our evidence supports the complex as defined.","molecular_requirements":"The receptor entity contains IFNA2 (flagged secreted, not a receptor) plus IFNAR1 and IFNAR2 [flag]; subunit requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human; no experiments in our evidence.","localisation_and_range":"Ligand is flagged secreted and not transmembrane [flag], so it acts as a diffusible paracrine or endocrine signal.","caveats":"No curator-verified paper; all six judged papers were abstract_insufficient. Support is database-only and the complex composition looks unusual.","key_references":[],"covers":["LR011722"]},"LR004261":{"pair":"Ifna9 -> Ifnar1","headline":"Mouse Ifna9 to Ifnar1 is projected from human alpha-IFN binding data; no mouse experiment, no database records.","interaction_type":"direct binding","direction_and_effect":"Human alpha-IFN subtypes bind isolated human receptor chains [PMID:21856167]. No database records are listed. Effect direction for the mouse pair is not reported in our evidence.","molecular_requirements":"IFNAR2 is the tight-binding chain (0.4-5 nM) and IFNAR1 the weak one (0.5-5 \u03bcM) for alpha-IFNs [PMID:21856167]. Whether the pair needs both chains for signalling is not reported in our evidence beyond this binding comparison.","affinity_potency":[{"value":"0.5-5 \u03bcM","assay":"affinity and rate-constant determination, 12 human alpha-IFN subtypes collectively, isolated IFNAR1 chain","system":"human proteins","cite":"PMID:21856167"}],"species_and_systems":"Experiments used human proteins [PMID:21856167]; the mouse pair is ortholog-inferred.","localisation_and_range":"Ligand is flagged secreted [flag].","caveats":"Support is an orthology projection from a class-wide human study read as abstract only; Ifna9 is not individually tested [PMID:21856167].","key_references":[{"PMID":"21856167","why":"binding of 12 human alpha-IFN subtypes to isolated IFNAR1 and IFNAR2"}],"covers":["LR004261"]},"LR004270":{"pair":"IFNB1 -> IFNAR2","headline":"IFNB1 binds IFNAR2 directly; supported by several binding and functional papers plus Reactome.","interaction_type":"direct binding","direction_and_effect":"IFN-beta is an agonist at IFNAR2 [DB:GtoPdb]. Reactome lists the binding reaction IFN alpha/beta binds to IFNAR2 [DB:Reactome]. In mouse L929 cells expressing human IFNAR2 with mutations at E78, W101, I104 or D105, cells were unresponsive to hIFN-alpha2 but remained responsive to hIFN-beta [PMID:10395669].","molecular_requirements":"IFN-beta responsiveness persisted despite alpha2-binding-site mutations in IFNAR2, suggesting a distinct interface [PMID:10395669]. A glycan on IFN-\u03b2 mutein R27T at the IFNAR2 interface destabilised IFNAR2 binding and enhanced IFNAR1 binding [PMID:30733680]. Ternary complex formation with ifnar1-EC and ifnar2-EC was studied [PMID:17174979].","affinity_potency":[],"species_and_systems":"Human IFN and receptor ectodomains in vitro [PMID:17174979][PMID:30733680]; human IFNAR2 in mouse L929 cells [PMID:10395669]. Human and mouse pairs both listed.","localisation_and_range":"Ligand is flagged secreted and not transmembrane [flag], so it acts as a diffusible paracrine or endocrine signal.","caveats":"All three papers were read as abstracts or partial excerpts. The functional paper mainly characterises IFN-alpha2 and uses IFN-beta as a control [PMID:10395669]. No numeric affinity values are reported in our evidence.","key_references":[{"PMID":"17174979","why":"real-time binding of type I IFNs to ifnar1-EC and ifnar2-EC"},{"PMID":"30733680","why":"binary and ternary receptor-binding kinetics of IFN-\u03b2-1a and R27T"},{"PMID":"10395669","why":"IFNAR2 mutants responsive to IFN-beta but not IFN-alpha2"}],"covers":["LR000830","LR004270"]},"LR000832":{"pair":"IFNL1 -> IFNLR1","headline":"IFN-lambda1 (IL-29) binds the IFNLR1 (IL-28Ralpha) receptor chain; binding paper plus structures.","interaction_type":"direct binding","direction_and_effect":"IFN-lambda1 is an agonist; GtoPdb lists Agonist [DB:GtoPdb]. IL-28 and IL-29 interacted with a heterodimeric class II receptor of IL-10Rbeta plus IL-28Ralpha and, like type I IFNs, were induced by viral infection and showed antiviral activity [PMID:12469119].","molecular_requirements":"The functional receptor is a heterodimer of IFNLR1 (IL-28Ralpha) and IL-10Rbeta [PMID:12469119]; Reactome describes IFNL1 binding IL10RB:TYK2 and IFNLR1:JAK1 [DB:Reactome]. A PDB structure (3OG4, 3OG6) with chains of IFNL1 and IFNLR1 accessions is recorded [DB:PDB 3OG4].","affinity_potency":[],"species_and_systems":"Human proteins, human cells [PMID:12469119].","localisation_and_range":"IFNL1 is flagged secreted and non-transmembrane [flag].","caveats":"Single abstract-only paper; the IFNLR1-alone contribution is not separated from the heterodimer in our evidence.","key_references":[{"PMID":"12469119","why":"identifies the IL-28/IL-29 receptor IL-28Ralpha with IL-10Rbeta"}],"covers":["LR000832"]},"LR000841":{"pair":"IGF2 -> IGF1R","headline":"IGF2 is a recorded IGF1R agonist with structures; our one verified paper uses the interaction only as an assay.","interaction_type":"direct binding","direction_and_effect":"GtoPdb lists IGF2 as an agonist of IGF1R [DB:GtoPdb]; the interaction is annotated stimulatory. The verified paper describes IGF-II binding IGF-1R with high affinity and used it in binding assays of Q18 mutants [PMID:35304516].","molecular_requirements":"Structures contain chains of IGF2 and IGF1R [DB:PDB 6VWG]. Subunit requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Immunocaptured IGF-1R in competition binding with europium-labelled IGF-II; the IGF-II analogues were made in E. coli [PMID:35304516].","localisation_and_range":"IGF2 is flagged secreted and IGF1R transmembrane [flag].","caveats":"The quoted evidence is a background statement; the paper's own measurements are for IGF-II Q18 analogues (for example Q18I IC50 0.45 nM), not wild-type affinity, so none is given here. Abstract read, with excerpts. Three review-only rows were excluded.","key_references":[{"PMID":"35304516","why":"IGF-II analogue binding to IGF-1R"}],"covers":["LR000841","LR004273"]},"LR006016":{"pair":"IGF2 -> ITGAV","headline":"Integrin alphavbeta3 binds IGF2 in one verified study; ITGAV is the alpha chain.","interaction_type":"direct binding","direction_and_effect":"IGF2 specifically bound integrins alphavbeta3 and alpha6beta4 and induced proliferation of IGF1R-positive CHO cells expressing either integrin [PMID:28873464]. Integrin-binding-defective IGF2 mutants (Arg to Glu at 24, 34, 37 and/or 38) suppressed wild-type IGF2 proliferation, suggesting dominant-negative IGF1R antagonism [PMID:28873464]. UniProt agrees [DB:UniProt].","molecular_requirements":"The alphavbeta3 heterodimer was tested; ITGAV alone is not shown. Blocking antibody 7E3 (anti-beta3) and cyclic RGDfV reduced cell adhesion to IGF2 [PMID:28873464].","affinity_potency":[],"species_and_systems":"CHO cells expressing recombinant integrins, ELISA-type binding with soluble alphavbeta3, and adhesion assays; anchorage-independent conditions [PMID:28873464]. Mouse pair is ortholog-inferred.","localisation_and_range":"IGF2 is flagged secreted [flag].","caveats":"The single supporting paper is the same for several integrin chain rows; evidence concerns the heterodimer. No affinity is reported in our evidence.","key_references":[{"PMID":"28873464","why":"IGF2 binds alphavbeta3 and alpha6beta4; C-domain Arg mutants"}],"covers":["LR002770","LR006016"]},"LR006025":{"pair":"IGHE -> FCER1A","headline":"Crystal structure at 3.5 A shows human IgE-Fc bound to the Fc epsilon RI alpha chain, supported by PDB and Reactome.","interaction_type":"direct binding","direction_and_effect":"IgE binds its high-affinity receptor; UniProt says IgE stimulates the FCER1A:MS4A2:FCGR1A receptor complex on mast cells, basophils and eosinophils, leading to mediator release [DB:UniProt][PMID:10917520].","molecular_requirements":"One receptor binds one dimeric IgE-Fc asymmetrically through two sites, each involving one C epsilon3 domain [PMID:10917520]. The full receptor complex includes MS4A2 and FCGR1A [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human IgE-Fc with the human Fc epsilonRI alpha extracellular domains, crystal structure [PMID:10917520]; PDB entries include 1F6A [DB:PDB 1F6A].","localisation_and_range":"IGHE is annotated as secreted [flag]; the receptor chain is on the surface of effector cells per UniProt [DB:UniProt].","caveats":"Abstract-only read, truncated in the dossier. Other receptor subunits were not part of the structure described in the abstract. No affinity reported.","key_references":[{"PMID":"10917520","why":"Crystal structure of human IgE-Fc with Fc epsilonRI alpha"}],"covers":["LR002779","LR006025"]},"LR000850":{"pair":"IHH -> HHIP","headline":"HIP binds all three mammalian Hedgehog proteins with an affinity comparable to Ptc-1; abstract only.","interaction_type":"direct binding","direction_and_effect":"Hip encodes a membrane glycoprotein that binds all three mammalian Hedgehog proteins with an affinity comparable to that of Ptc-1 [PMID:10050855]. The curator lists the interaction as inhibitory in the database annotation [flag]; the abstract excerpt does not describe the effect on signalling.","molecular_requirements":"Other requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse ligand and receptor per the curator [PMID:10050855]; the human pair is ortholog-inferred. IntAct lists a solid-phase assay between Q96QV1 and Q14623 [DB:IntAct].","localisation_and_range":"HHIP is flagged non-transmembrane in our annotation [flag] although the paper describes a membrane glycoprotein [PMID:10050855]; Hip-expressing cells lie next to Hh-expressing cells [PMID:10050855].","caveats":"Abstract only. IHH is covered by the phrase 'all three mammalian Hedgehog proteins', not individually resolved. No numeric affinity is given.","key_references":[{"PMID":"10050855","why":"Hip binds all three mammalian Hedgehog proteins"}],"covers":["LR000850","LR004280"]},"LR011731":{"pair":"IL18 -> IL18:IL18R1:IL18RAP","headline":"IL-18 signals through IL18R1 with IL18RAP, supported by databases only; the pair is odd because IL18 is also a complex member.","interaction_type":"database-asserted only","direction_and_effect":"Agonist: GtoPdb lists IL18 with IL18R1 and IL18RAP as agonist [DB:GtoPdb]. Reactome lists IL18 binding IL18R1 and the IL18:IL18R1 complex then binding IL18RAP [DB:Reactome].","molecular_requirements":"IL18R1 is responsible for IL18 binding; IL18RAP does not mediate IL18 binding but is needed for signal transduction, leading to NF-kappa-B and JNK activation [DB:UniProt]. PDB 3WO3, 3WO4 and 4R6U contain IL18 and IL18R1 chains [DB:PDB 3WO3]. IntAct lists x-ray crystallography [DB:IntAct].","affinity_potency":[],"species_and_systems":"Species of the experiments is not reported in our evidence.","localisation_and_range":"IL18 is annotated as secreted [flag]. Reactome places the signalling complex at the plasma membrane [DB:Reactome].","caveats":"No verified paper; two curated rows are pending. Structures cover IL18 with IL18R1, not the three-chain complex.","key_references":[],"covers":["LR011731"]},"LR004306":{"pair":"IL19 -> IL20RA","headline":"IL-19 signals through IL20RA as part of the IL20RA/IL20RB heterodimer; binding and signalling shown in human transfected cells.","interaction_type":"functional only","direction_and_effect":"IL-19 acts as an agonist: it binds the IL-20R complex (IL-20Ralpha/IL-20Rbeta, type I) and this gives STAT3 phosphorylation and STAT-promoter activation [PMID:11564763]. IL-19 signals only through the type I complex, not IL-22R/IL-20Rbeta [PMID:11564763]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"IL20RB is also required: IL-19 signals through the IL-20RA/IL-20RB heterodimer [PMID:12351624, PMID:11564763]. Evidence is for the complex, not IL20RA alone.","affinity_potency":[],"species_and_systems":"Human ligand and receptors in transfected cell lines [PMID:11564763, PMID:12351624]; Reactome lists IL19:IL20RA:JAK1:IL20RB [DB:Reactome]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand carries the secreted annotation flag [flag], which implies paracrine/endocrine range; receptor localisation beyond the receptor flag is not reported in our evidence.","caveats":"Both papers were read as abstracts. The single-chain row inherits complex-level evidence. In one cell line growth inhibition by IL-19 needed cytokine levels two orders of magnitude above those for STAT activation [PMID:12351624]. IntAct lists a surface plasmon resonance record for Q6UXL0-Q9UHD0 [DB:IntAct]. Binding to IL20RA alone is not shown separately.","key_references":[{"PMID":"11564763","why":"IL-19 binds the type I IL-20R complex and activates STAT3"},{"PMID":"12351624","why":"IL-19 signals through IL-20RA/IL-20RB"}],"covers":["LR000876","LR004306"]},"LR007303":{"pair":"IL1A -> IL1R2:IL1RAP","headline":"Database-asserted only: no verified paper for IL-1alpha with the IL1R2:IL1RAP complex.","interaction_type":"database-asserted only","direction_and_effect":"UniProt calls IL1R2 a non-signaling receptor for IL1A, IL1B and IL1RN [DB:UniProt]; GtoPdb lists IL1A-IL1RAP as agonist [DB:GtoPdb]; Reactome lists IL1R2 binding IL1 [DB:Reactome].","molecular_requirements":"IL1RAP with IL1R2 is not tested for IL1A in our evidence; IntAct has a co-immunoprecipitation record for P01583-P27930 (IL1A-IL1R2) [DB:IntAct].","affinity_potency":[],"species_and_systems":"No experiments in our evidence.","localisation_and_range":"Ligand carries the secreted annotation flag [flag], which implies paracrine/endocrine range; receptor localisation beyond the receptor flag is not reported in our evidence.","caveats":"No curator-verified paper in our evidence; support rests on database records only. Two papers were judged review-only and not used.","key_references":[],"covers":["LR007303"]},"LR006034":{"pair":"IL1B -> ITGB1","headline":"IL-1beta binds integrin alpha5beta1 directly according to one abstract-level paper; UniProt repeats that paper.","interaction_type":"direct binding","direction_and_effect":"IL-1beta specifically bound integrins alphavbeta3 and alpha5beta1, and the authors propose this binding is primarily important for agonistic IL-1beta signalling [PMID:29030430]. Agonist direction is the curators' label.","molecular_requirements":"The integrin heterodimer is the binding unit named in the paper (integrin alpha5beta1); this pair record is for one subunit only, and which subunit contacts IL-1beta is not reported in our evidence [PMID:29030430]. UniProt: ITGA5:ITGB1 is a receptor for IL1B and binding is essential for IL1B signaling [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human IL-1beta and human integrins in binding and signalling assays; the mouse pair is inferred from human evidence [PMID:29030430].","localisation_and_range":"IL1B is flagged secreted [flag]; the integrin is a membrane receptor, so ligand acts at the cell surface.","caveats":"Read as abstract only. The E128K mutation in the IL1R-binding site enhanced integrin binding, and Lys-to-Glu substitutions reduced but did not abolish agonistic action, so integrin binding is not the only route [PMID:29030430]. No affinity reported. UniProt support derives from the same paper.","key_references":[{"PMID":"29030430","why":"IL-1beta binds alphavbeta3 and alpha5beta1; role in agonism"}],"covers":["LR002791","LR006034"]},"LR005206":{"pair":"IL1RAPL1 -> PTPRD","headline":"IL1RAPL1 extracellular domains interact with PTPdelta to induce excitatory presynapse formation; structure in PDB.","interaction_type":"direct binding","direction_and_effect":"The IgG-like extracellular domains of IL1RAPL1 induce excitatory pre-synapse formation by interacting with PTPdelta, and the complex recruits RhoGAP2 to drive dendritic spine formation [PMID:21926414].","molecular_requirements":"Extracellular Ig-like domains are needed; IL1RAPL1 TIR domains interact with RhoGAP2 intracellularly [PMID:21926414]. A PDB structure has chains of both proteins [DB:PDB 5WY8]. BioGRID has affinity capture-western [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Species of the experiments is not stated in the dossier; neuron culture assays [PMID:21926414]. Both human and mouse pairs are projected from other evidence.","localisation_and_range":"Both flagged transmembrane [flag]; trans-synaptic action.","caveats":"Abstract read only for the binding statement; the full-text excerpts shown cover figures on spines, not the binding. No affinity reported.","key_references":[{"PMID":"21926414","why":"IL1RAPL1 ectodomain interacts with PTPdelta for presynapse formation"}],"covers":["LR001860","LR005206"]},"LR004315":{"pair":"IL1RN -> IL1R1","headline":"IL1RA (IL1RN) binds IL1R1 as an antagonist, shown by a 2.7 A crystal structure; abstract-level.","interaction_type":"direct binding","direction_and_effect":"The crystal structure of soluble type-I IL1R complexed with IL1RA shows contacts from all three Ig domains; the 'receptor trigger site' important for IL-1beta function is not in direct contact in the IL1RA complex [PMID:9062194]. GtoPdb lists it as antagonist [DB:GtoPdb].","molecular_requirements":"Soluble extracellular IL1R1 alone was crystallised; a role for the accessory chain is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Crystal structure of the soluble extracellular receptor complexed with IL1RA; species not stated in the abstract (curated as human). Mouse pair is inferred.","localisation_and_range":"IL1RN is flagged secreted [flag].","caveats":"Abstract only; no affinity values in our evidence. Two further papers are pending.","key_references":[{"PMID":"9062194","why":"Crystal structure of IL1R1 with IL1RA"}],"covers":["LR000885","LR004315"]},"LR011227":{"pair":"IL1RN -> IL2RB","headline":"Only a GtoPdb antagonist record asserts this pair; no paper evidence, and judged papers named a different entity.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists the interaction as Antagonist [DB:GtoPdb]; no affinity is given.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human; no experimental system in our evidence.","localisation_and_range":"IL1RN flagged secreted [flag].","caveats":"No verified papers; judged rows were different_entity. The pair rests on one database record and may be spurious.","key_references":[],"covers":["LR011227"]},"LR000904":{"pair":"IL2 -> IL2RB","headline":"IL-2 binds IL2RB directly but weakly alone; in cells IL2RB works with IL2RG, and papers include a mimetic-peptide study.","interaction_type":"direct binding","direction_and_effect":"IL-2 binds the beta chain with low affinity in soluble ectodomain assays [PMID:8049354]. A second human IL-2 binding protein (Mr ~70K, later IL2RB per the curator) is identified [PMID:3108674]. GtoPdb lists Agonist [DB:GtoPdb]; annotated Stimulatory.","molecular_requirements":"Beta binds IL-2 weakly, gamma only very weakly without beta [PMID:8049354]. Intermediate affinity receptor is beta plus gamma; high affinity adds alpha [PMID:8049354]. Reactome shows IL2RA:IL2RB binding IL2RG [DB:Reactome].","affinity_potency":[{"value":"KI-KD = 3 microM","assay":"soluble ectodomain binding and neutralization","system":"insect-cell-expressed IL-2R beta ectodomain","cite":"PMID:8049354"}],"species_and_systems":"Human proteins: soluble ectodomains from insect cells [PMID:8049354]; human T/B lymphocytes [PMID:3108674]. A mimetic-peptide paper used murine TS1beta cells transfected with human IL-2Rbeta [PMID:11035066]. Mouse pair is projected.","localisation_and_range":"IL-2 flagged secreted [flag].","caveats":"All papers abstract only. PMID:15265897 is background for composition. PMID:11035066 is about the p1-30 mimetic, so IL-2 binding to IL2RB is the reference system rather than the finding.","key_references":[{"PMID":"8049354","why":"Soluble IL-2R beta binds IL-2 with low affinity"},{"PMID":"3108674","why":"Identifies a second IL-2 binding protein, p70"}],"covers":["LR000904","LR004333"]},"LR004333":{"pair":"IL2 -> IL2RB","headline":"IL-2 binds IL2RB directly but weakly alone; in cells IL2RB works with IL2RG, and papers include a mimetic-peptide study.","interaction_type":"direct binding","direction_and_effect":"IL-2 binds the beta chain with low affinity in soluble ectodomain assays [PMID:8049354]. A second human IL-2 binding protein (Mr ~70K, later IL2RB per the curator) is identified [PMID:3108674]. GtoPdb lists Agonist [DB:GtoPdb]; annotated Stimulatory.","molecular_requirements":"Beta binds IL-2 weakly, gamma only very weakly without beta [PMID:8049354]. Intermediate affinity receptor is beta plus gamma; high affinity adds alpha [PMID:8049354]. Reactome shows IL2RA:IL2RB binding IL2RG [DB:Reactome].","affinity_potency":[{"value":"KI-KD = 3 microM","assay":"soluble ectodomain binding and neutralization","system":"insect-cell-expressed IL-2R beta ectodomain","cite":"PMID:8049354"}],"species_and_systems":"Human proteins: soluble ectodomains from insect cells [PMID:8049354]; human T/B lymphocytes [PMID:3108674]. A mimetic-peptide paper used murine TS1beta cells transfected with human IL-2Rbeta [PMID:11035066]. Mouse pair is projected.","localisation_and_range":"IL-2 flagged secreted [flag].","caveats":"All papers abstract only. PMID:15265897 is background for composition. PMID:11035066 is about the p1-30 mimetic, so IL-2 binding to IL2RB is the reference system rather than the finding.","key_references":[{"PMID":"8049354","why":"Soluble IL-2R beta binds IL-2 with low affinity"},{"PMID":"3108674","why":"Identifies a second IL-2 binding protein, p70"}],"covers":["LR000904","LR004333"]},"LR007312":{"pair":"IL20 -> IL20RA:IL20RB","headline":"IL-20 forms a ternary complex with IL20RA and IL20RB, giving type I IL-20R STAT signalling; well supported by binding and cell assays.","interaction_type":"direct binding","direction_and_effect":"IL-20 and ligand form stable ternary 1:1:1 complexes with sIL-20R1 and sIL-20R2 [PMID:14580208]; IL-20 signals through IL-20RA/IL-20RB and induces STAT activation [PMID:12351624] [PMID:11564763]. GtoPdb: Agonist [DB:GtoPdb].","molecular_requirements":"Both chains are needed: sIL-20R1 has no independent binding, ligand binds receptor II first then recruits receptor I [PMID:14580208]. IL-20 can alternatively use IL22RA1:IL20RB [PMID:11564763]. A crystal structure of IL20 with IL20RA exists [DB:PDB 4DOH].","affinity_potency":[],"species_and_systems":"Human soluble ectodomains in S2 cells [PMID:14580208]; transfected cell lines [PMID:12351624] [PMID:11564763].","localisation_and_range":"IL-20 flagged secreted; complex flagged transmembrane [flag].","caveats":"All three papers abstract only. Signalling readouts show function, not affinity; no affinity values reported in our evidence.","key_references":[{"PMID":"14580208","why":"Ternary complex by size-exclusion chromatography"},{"PMID":"11564763","why":"Type I and type II IL-20R complexes, STAT3 activation"},{"PMID":"12351624","why":"IL-20RA/IL-20RB signalling by IL-19, IL-20, IL-24"}],"covers":["LR007312"]},"LR004324":{"pair":"IL22 -> IL22RA2","headline":"IL22RA2 (IL-22BP) is a soluble decoy receptor that binds IL-22 and neutralises it; well supported.","interaction_type":"direct binding","direction_and_effect":"IL-22RA2 binds IL-22 specifically and neutralises IL-22-induced BaF3 proliferation [PMID:11481447]; the recombinant protein binds IL-22 and inhibits it on hepatocytes and intestinal epithelial cells [PMID:11390453]. Antagonist, not a signalling receptor.","molecular_requirements":"A single chain is sufficient; IL-22RA2 lacks transmembrane and cytoplasmic domains [PMID:11390453]. Structure of the pair exists [DB:PDB 3G9V].","affinity_potency":[],"species_and_systems":"Human proteins; BaF3 cells expressing IL-22 receptor subunits, hepatocytes and intestinal epithelial cells [PMID:11481447][PMID:11390453].","localisation_and_range":"Naturally expressed soluble receptor [PMID:11481447]; acts in the extracellular space.","caveats":"Both papers read as abstracts only. A signalling-oriented CCC tool would misread direction here.","key_references":[{"PMID":"11481447","why":"IL-22RA2 is a naturally occurring soluble IL-22 antagonist"},{"PMID":"11390453","why":"cloning of IL-22 binding protein"}],"covers":["LR000894","LR004324"]},"LR007321":{"pair":"IL33 -> IL1RAP:IL1RL1","headline":"IL-33 signals through ST2 plus IL1RAP; IL1RAP is required for signalling in one abstract-level paper, backed by UniProt and Reactome.","interaction_type":"direct binding","direction_and_effect":"IL-33 specifically binds ST2 and IL-1 receptor accessory protein (AcP) associates with ST2 in a ligand-dependent manner; IL-33 stimulated IL-6 secretion from wild-type mast cells but had no effect on AcP-deficient mast cells (agonist) [PMID:18450470].","molecular_requirements":"Both chains are needed: ST2 binds IL-33, and AcP is the co-receptor essential for signalling [PMID:18450470]. UniProt describes a 1:1:1 heterotrimer of IL33, IL1RL1 and IL1RAP [DB:UniProt O95760]. Soluble ST2-Fc and soluble AcP-Fc acted synergistically to inhibit IL-33 [PMID:18450470].","affinity_potency":[{"value":"4-fold","assay":"increase in mouse IL-33 affinity for ST2 in presence of AcP (receptor binding measurement)","system":"mouse IL-33, ST2","cite":"PMID:18450470"}],"species_and_systems":"Experiments combined mouse IL-33 and mouse mast cells with immunoprecipitation [PMID:18450470]; the curator record lists human. Reactome and UniProt records are human [DB:Reactome].","localisation_and_range":"IL-33 is flagged secreted and non-transmembrane; the complex is flagged transmembrane [flag].","caveats":"Abstract only; no absolute Kd given in our evidence. The soluble forms of ST2 and AcP act as inhibitors [PMID:18450470].","key_references":[{"PMID":"18450470","why":"AcP is required for IL-33 signalling through ST2."}],"covers":["LR007321"]},"LR006043":{"pair":"IL36A -> IL1RAP","headline":"IL1RAP is a required co-receptor for IL-36 signalling in one functional paper; no direct ligand binding shown.","interaction_type":"functional only","direction_and_effect":"Antibodies against IL-1RAcP and a cytoplasmically deleted IL-1RAcP blocked NF-kappaB activation by IL-1F6, IL-1F8 and IL-1F9, so IL-1RAcP is required alongside IL-1Rrp2 [PMID:14734551]. GtoPdb lists an agonist record [DB:GtoPdb].","molecular_requirements":"IL1RAP acts as co-receptor with IL-1Rrp2 (IL1RL2); IL1RAP alone is not shown to bind the ligand [PMID:14734551].","affinity_potency":[],"species_and_systems":"Human cell lines (Jurkat, NCI/ADR-RES) [PMID:14734551].","localisation_and_range":"Ligand annotated as secreted [flag]; receptor-side localisation not otherwise reported.","caveats":"Single abstract-only paper. It names the ligands IL-1F6/F8/F9; the abstract does not state which is IL36A. Reactome entry links the paper to IL36:IL1RL2 binding IL1RAP [DB:Reactome].","key_references":[{"PMID":"14734551","why":"IL-1RAcP required for IL-1F6/F8/F9 signalling"}],"covers":["LR002801","LR006043"]},"LR002803":{"pair":"IL36B -> IL1RL2","headline":"IL36B signalling through IL1RL2 is supported by one functional abstract-only paper plus databases.","interaction_type":"functional only","direction_and_effect":"IL-1F6/F8/F9 activate NF-kappaB IL-1Rrp2 (IL1RL2)-dependently, and anti-IL-1Rrp2 antibodies block it in Jurkat and NCI/ADR-RES cells [PMID:14734551]. GtoPdb: Agonist [DB:GtoPdb].","molecular_requirements":"Requires the IL-1Rrp2/IL-1RAcP heterodimer per the curator note [PMID:14734551].","affinity_potency":[],"species_and_systems":"Human and mouse cell lines [PMID:14734551].","localisation_and_range":"Ligand annotated as secreted [flag]; receptor-side localisation not otherwise reported.","caveats":"One paper, abstract only; it names IL-1F6/F8/F9, not IL36B. No binding or affinity data.","key_references":[{"PMID":"14734551","why":"IL-1Rrp2-dependent signalling"}],"covers":["LR002803","LR006045"]},"LR011740":{"pair":"IL4 -> IL13:IL13RA1:IL4R","headline":"Database-asserted only complex entry; the receptor complex contains IL13, which looks malformed.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists IL4 agonist records for IL13RA1 and IL4R [DB:GtoPdb]. UniProt says IL4R dimerizes with IL13RA1 to form the type 2 complex [DB:UniProt].","molecular_requirements":"Members listed are IL13, IL13RA1, IL4R. IntAct and PDB records show structures and ITC of IL4 with chains [DB:IntAct][DB:PDB 3BPL].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand annotated secreted [flag].","caveats":"No judged papers (two pending).","key_references":[],"covers":["LR011740"]},"LR000913":{"pair":"IL4 -> IL2RG","headline":"IL2RG (common gamma chain) is a functional component of the IL4 receptor, shown by cross-linking and signalling in a 1993 paper.","interaction_type":"direct binding","direction_and_effect":"IL-2R gamma augments IL-4 binding affinity and is required for IL-4-mediated IRS-1 phosphorylation, i.e. it acts as a signalling subunit with agonist effect [PMID:8266078]; GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"IL2RG acts together with IL4R: UniProt describes IL4R dimerising with IL2RG to form the type 1 complex [DB:UniProt]; a ternary IL4-IL4R-gamma structure exists [DB:PDB 3BPL].","affinity_potency":[],"species_and_systems":"The curated rows give the experiment species as mouse for ligand and receptor [PMID:8266078]; the mouse pair is the ortholog-projected one. The same paper is recorded as human lymphoid cells in another dossier (see flag).","localisation_and_range":"IL4 is flagged secreted and non-transmembrane [flag], so it acts as a diffusible ligand on receptor-bearing cells; the receptor is flagged as a transmembrane receptor [flag].","caveats":"IL2RG alone is not a primary IL4 binder: evidence shows it augments IL4 binding to IL4R. Paper read as abstract only. Affinity not reported in our evidence.","key_references":[{"PMID":"8266078","why":"Cross-linking, affinity augmentation and IRS-1 requirement for IL-2R gamma in IL-4 receptor"}],"covers":["LR000913","LR004341"]},"LR004342":{"pair":"Il4 -> Il4ra","headline":"Mouse Il4-Il4ra pair projected from human evidence: IL4 binds IL4R-alpha at 150 pM KD in human experiments.","interaction_type":"direct binding","direction_and_effect":"Human IL4 binds the IL4R-alpha ectodomain with high affinity [PMID:11786020]; IL4 mutants keep 60-100% of IL4R binding [PMID:7918378]. BioGRID records a co-crystal structure [DB:BioGRID].","molecular_requirements":"IL4R pairs with IL2RG or IL13RA1 for signalling [DB:UniProt]; structures of IL4-IL4R exist [DB:PDB 1IAR].","affinity_potency":[{"value":"KD 150 pM","assay":"mutational binding analysis of IL4-BP","system":"human recombinant IL4R extracellular domain","cite":"PMID:11786020"}],"species_and_systems":"All experiments were human (ligand and receptor); the mouse pair is ortholog-inferred, with no mouse experiments in our evidence.","localisation_and_range":"IL4 is flagged secreted [flag]; the receptor is flagged as a receptor [flag].","caveats":"Mouse relevance is inferred from human data; abstracts only.","key_references":[{"PMID":"11786020","why":"Human IL4-IL4R KD 150 pM"},{"PMID":"7918378","why":"Human IL4 mutants retain IL4R binding"}],"covers":["LR004342"]},"LR007330":{"pair":"IL6 -> IL6R:IL6ST","headline":"IL6 binds IL6R then engages IL6ST; structural evidence for the hexameric complex, human, abstract-level reads.","interaction_type":"direct binding","direction_and_effect":"IL-6 is first engaged by IL-6Ralpha and then presented to gp130 in a hexameric assembly [PMID:12829785]. GtoPdb lists IL6-IL6R and IL6-IL6ST as agonist [DB:GtoPdb].","molecular_requirements":"Both chains are needed for the signalling-competent hexamer: IL-6 first binds IL6R, then gp130 (IL6ST) [PMID:12829785]. UniProt says IL6ST associates with IL6:IL6R but does not interact with IL6 itself [DB:UniProt]. The IL6R membrane-proximal fibronectin-like domain accounts for more than 90% of binding energy to IL-6 [PMID:14557255]. For complex scoring, both IL6R and IL6ST are required.","affinity_potency":[],"species_and_systems":"Human proteins in NMR and crystallography [PMID:14557255][PMID:12829785]. PDB 1P9M and 8D82 contain IL6 and IL6ST chains [DB:PDB 1P9M].","localisation_and_range":"IL6/IL7/IL9 are flagged secreted [flag], so signalling is paracrine or endocrine; the receptor is flagged transmembrane [flag]. Annotation flags only.","caveats":"All three confirmed papers were read as abstracts only. PMID:3136546 is IL6R cloning and does not evidence IL6ST. IL6 alone does not bind IL6ST per UniProt [DB:UniProt].","key_references":[{"PMID":"12829785","why":"Hexameric IL-6/IL-6Ralpha/gp130 structure, sequential assembly"},{"PMID":"14557255","why":"NMR mapping of IL-6 binding epitope on IL6R D3"},{"PMID":"3136546","why":"IL6R cDNA cloning (IL6R half only)"}],"covers":["LR007330"]},"LR004351":{"pair":"INHA -> ACVR2A","headline":"Inhibin competes with BMPs for type II activin receptors; one confirmed paper but a conflicting verified negative.","interaction_type":"conflicting","direction_and_effect":"Inhibin competes with BMPs for type II activin receptors, blocking BMP-Smad signalling [PMID:12493742]. A pair_absent judgement on the same paper says the ACVR2A-INHA mention was not a positive finding [PMID:12493742]. GtoPdb: agonist [DB:GtoPdb].","molecular_requirements":"The curators' note says inhibin is an INHA-containing complex acting on type II activin receptors (ACVR2A/ACVR2B) [PMID:12493742].","affinity_potency":[],"species_and_systems":"Species and cells not reported beyond BMP-responsive cell types [PMID:12493742]. Mouse and human pairs are ortholog-inferred. BioGRID: ACVR2A-INHA affinity capture-western [DB:BioGRID 275207].","localisation_and_range":"Secreted ligand [flag].","caveats":"Confirmed and pair_absent rows coexist for the same paper; the absent row was an automated propagation from a text mention. Evidence is inhibin as a complex, not INHA alone. Two papers abstract_insufficient.","key_references":[{"PMID":"12493742","why":"Inhibin competes with BMPs for type II activin receptors"}],"covers":["LR000928","LR004351"]},"LR000931":{"pair":"INHBA -> ACVR1","headline":"Activin A binds ACVR1 to form a non-signaling complex; one verified paper (full text) supports binding with an antagonist-like sequestering effect.","interaction_type":"direct binding","direction_and_effect":"Activin A binds ACVR1 to form a non-signaling complex (NSC) rather than activating Smad1/5/8; the curator labels the effect antagonist [PMID:32515349]. The ACVR1-Activin A-type II receptor complex did not induce phosphorylation of the proteins on a phosphokinase array [PMID:32515349]. UniProt describes an apparent inhibition of ACVR1-mediated BMP signalling [DB:UniProt].","molecular_requirements":"The complex includes a type II receptor (ACVR1-Activin A-type II receptor) [PMID:32515349]. The finger 2 tip loop of activin A is required: muteins that lost it could not form the NSC [PMID:32515349].","affinity_potency":[],"species_and_systems":"Human ACVR1 overexpressed in HEK293 cells and mouse embryonic stem cells with Acvr1b knockout; mouse pair is projected from human [PMID:32515349].","localisation_and_range":"Ligand carries a secreted flag [flag]; the receptor is a membrane receptor, with range otherwise not reported in our evidence.","caveats":"Effect is non-signaling sequestration, not activation, even though the interaction record is labelled Stimulatory. Binding was inferred from signalling and dimerization readouts; affinity not reported. Curated from abstract level, with full text supporting.","key_references":[{"PMID":"32515349","why":"Shows activin A forms a non-signaling complex with ACVR1 and type II receptors."}],"covers":["LR000931","LR004354"]},"LR000940":{"pair":"INHBB -> ACVR2A","headline":"Activin B binds ACVR2A: crystal-structure-level evidence for the activin/ACVR2A mode, plus ALK4/ALK7 context; mouse pair ortholog-inferred.","interaction_type":"direct binding","direction_and_effect":"ACVR2A high-affinity growth factors include activin A and activin B; effect recorded as agonist [PMID:35643319]. A second paper shows activin B signalling via ActRIIA/ALK7 [PMID:15196700].","molecular_requirements":"Structures were solved for BMPR2 with activin B and ACVR2A with activin A, not activin B with ACVR2A itself [PMID:35643319]. Signalling needs a type I partner (ALK7 or ALK4) [PMID:15196700].","affinity_potency":[],"species_and_systems":"Human ligand and receptor per curator fields [PMID:35643319]; the second paper used mouse reconstitution [PMID:15196700]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted and receptor transmembrane [flag].","caveats":"Both papers read as abstract only. The binding spectrum claim for activin B/ACVR2A is stated at group level in the abstract [PMID:35643319]. No affinity values reported in our evidence.","key_references":[{"PMID":"35643319","why":"Structures and binding spectrum of ACVR2A/BMPR2"},{"PMID":"15196700","why":"Activin B receptor combinations"}],"covers":["LR000940","LR004363"]},"LR002812":{"pair":"INHBB -> BMPR2","headline":"Activin B binds BMPR2, shown by crystal structure; abstract-level reading, mouse pair ortholog-inferred.","interaction_type":"direct binding","direction_and_effect":"Crystal structure of BMPR2 in complex with activin B was solved; BMPR2 binds the growth factor with a conserved hydrophobic hot spot [PMID:35643319]. A PDB record exists [DB:PDB 7U5O].","molecular_requirements":"BMPR2 binds activin B at its knuckle epitope; the receptor engages an activin B protomer, buried surface 710 \u00c52 [PMID:35643319]. Type I partner requirement not reported.","affinity_potency":[],"species_and_systems":"Human ligand and receptor per curator fields [PMID:35643319]; structural, recombinant system.","localisation_and_range":"Ligand flagged secreted [flag]; receptor transmembrane flag not set.","caveats":"Abstract plus excerpts read; binding is structural, no signalling effect is shown here. The excerpts note activin B may not interact with type I receptors in the observed form [PMID:35643319]. BioGRID adds a reconstituted-complex record [PMID:28126904].","key_references":[{"PMID":"35643319","why":"Structure of BMPR2 with activin B"}],"covers":["LR002812","LR006052"]},"LR006052":{"pair":"INHBB -> BMPR2","headline":"Activin B binds BMPR2, shown by crystal structure; abstract-level reading, mouse pair ortholog-inferred.","interaction_type":"direct binding","direction_and_effect":"Crystal structure of BMPR2 in complex with activin B was solved; BMPR2 binds the growth factor with a conserved hydrophobic hot spot [PMID:35643319]. A PDB record exists [DB:PDB 7U5O].","molecular_requirements":"BMPR2 binds activin B at its knuckle epitope; the receptor engages an activin B protomer, buried surface 710 \u00c52 [PMID:35643319]. Type I partner requirement not reported.","affinity_potency":[],"species_and_systems":"Human ligand and receptor per curator fields [PMID:35643319]; structural, recombinant system.","localisation_and_range":"Ligand flagged secreted [flag]; receptor transmembrane flag not set.","caveats":"Abstract plus excerpts read; binding is structural, no signalling effect is shown here. The excerpts note activin B may not interact with type I receptors in the observed form [PMID:35643319]. BioGRID adds a reconstituted-complex record [PMID:28126904].","key_references":[{"PMID":"35643319","why":"Structure of BMPR2 with activin B"}],"covers":["LR002812","LR006052"]},"LR002821":{"pair":"ISG15 -> ITGAL","headline":"ISG15 binds the alphaI domain of ITGAL (CD11a) and signals through LFA-1; direct binding plus knockout support, full text read.","interaction_type":"direct binding","direction_and_effect":"ISG15 acts as an agonist: it stimulates IFN-gamma and IL-10 secretion and activates SRC family kinases via LFA-1 [PMID:29100055]. CD11a-/- mouse splenocytes did not respond to ISG15 [PMID:29100055].","molecular_requirements":"ISG15 bound the alphaI domain of CD11a in vitro [PMID:29100055]. In HEK293T cells binding required CD11a and CD18 together; CD11b/CD18 or CD11c/CD18 did not confer binding [PMID:29100055]. Score as the ITGAL:ITGB2 complex.","affinity_potency":[],"species_and_systems":"Human NK-92 cells and PBMC assays, in vitro binding to the alphaI domain, HEK293T transfection, and CD11a-/- mouse splenocytes [PMID:29100055]. Mouse and human interactions are both listed.","localisation_and_range":"ISG15 is flagged secreted and ITGAL transmembrane [flag]; signalling is outside-in on cells [PMID:29100055].","caveats":"ISG15 binding was separable from ICAM1 binding to LFA-1 in this paper [PMID:29100055]. The curator row was read as abstract only, though full text was available. No affinity reported.","key_references":[{"PMID":"29100055","why":"Direct binding and knockout validation of LFA-1 as the ISG15 receptor"}],"covers":["LR002821","LR006060"]},"LR006061":{"pair":"ISG15 -> ITGB2","headline":"ITGB2 (CD18) is the obligate partner of CD11a in the LFA-1 receptor that ISG15 engages; the binding evidence is on ITGAL.","interaction_type":"direct binding","direction_and_effect":"ISG15 is an agonist at LFA-1, stimulating IFN-gamma secretion [PMID:29100055].","molecular_requirements":"ISG15 binding to HEK293T cells needed CD11a and CD18 expressed together [PMID:29100055]. The direct binding to the alphaI domain concerns CD11a, not CD18 [PMID:29100055].","affinity_potency":[],"species_and_systems":"Human NK-92 and HEK293T cells; CD11a-/- mouse splenocytes [PMID:29100055].","localisation_and_range":"ISG15 flagged secreted [flag]; ITGB2 is a membrane receptor chain.","caveats":"This row inherits evidence from the ITGAL row; the dossier shows no direct test of CD18 alone. Curators read it as abstract only.","key_references":[{"PMID":"29100055","why":"Shows ISG15 binding needs CD11a plus CD18"}],"covers":["LR002822","LR006061"]},"LR008005":{"pair":"ITGA5:ITGB1 -> ADGRE5","headline":"The alpha5beta1 complex is reported as a high-affinity counterreceptor for CD97; abstract-level evidence.","interaction_type":"direct binding","direction_and_effect":"Integrin-dependent HUVEC migration and invasion are induced by soluble CD97 [PMID:15576472].","molecular_requirements":"Both chains are present in the complex; coengagement with chondroitin sulfate proteoglycan is synergistic [PMID:15576472].","affinity_potency":[],"species_and_systems":"Human HUVEC and in vivo angiogenesis assay (DIVAA) [PMID:15576472].","localisation_and_range":"Soluble CD97 acts as chemoattractant [PMID:15576472].","caveats":"Abstract only; no affinity number reported. The row is stored integrin to CD97.","key_references":[{"PMID":"15576472","why":"Alpha5beta1 as first high-affinity counterreceptor for CD97"}],"covers":["LR008005"]},"LR002830":{"pair":"ITGB3 -> THY1","headline":"Thy-1 and alphavbeta3 integrin interact, with slip-bond kinetics measured by optical tweezers; abstract only.","interaction_type":"direct binding","direction_and_effect":"Thy-1/alphavbeta3 interactions stimulate astrocyte migration and retraction of neuronal prolongations; both partners signal [PMID:29212879].","molecular_requirements":"Alphavbeta3 as Fc fusion with nonpurified integrin; ITGB3 chain-only row [PMID:29212879].","affinity_potency":[],"species_and_systems":"Recombinant Thy-1-Fc and alphavbeta3-Fc, human per record; pair projected by orthology to both species [PMID:29212879].","localisation_and_range":"Trans interaction between neurons and astrocytes [PMID:29212879].","caveats":"Force accelerated dissociation (slip bond) [PMID:29212879]; no rate or Kd values in the dossier. Nonspecific events were detected even with purified proteins [PMID:29212879]. Both interactions listed are ortholog-inferred.","key_references":[{"PMID":"29212879","why":"Single-molecule force measurement of Thy-1/alphavbeta3 binding"}],"covers":["LR002830","LR006067"]},"LR006070":{"pair":"JAM2 -> ITGB1","headline":"JAM2 engages alpha4beta1 in T cells; evidence concerns the heterodimer, not beta1 alone.","interaction_type":"functional only","direction_and_effect":"Neutralizing integrin antibodies defined a JAM2-alpha4beta1 interaction in T cells [PMID:12070135]. Reactome records it [DB:Reactome].","molecular_requirements":"The partner subunit alpha4 is required; engagement occurred only after JAM2-JAM3 adhesion [PMID:12070135].","affinity_potency":[],"species_and_systems":"Human T cell line [PMID:12070135].","localisation_and_range":"JAM2 flagged as not secreted [flag].","caveats":"Chain-only: beta1 alone was not tested. Abstract-only; no direct binding.","key_references":[{"PMID":"12070135","why":"JAM2-alpha4beta1 in T cells"}],"covers":["LR002833","LR006070"]},"LR005215":{"pair":"JAM3 -> JAM2","headline":"JAM-B/JAM-C heterophilic interaction supported by one in vivo and human-cell functional paper plus UniProt, Reactome and IntAct records.","interaction_type":"functional only","direction_and_effect":"JAM-B/JAM-C engagement is required for hematopoietic stem and progenitor cell homing and reconstitution: a blocking anti-Jam-c antibody inhibited reconstitution and homing and induced mobilisation in a Jam-b-dependent manner [PMID:24357068]. UniProt describes JAM2 and JAM3 as mediating heterotypic cell-cell interactions with each other [DB:UniProt].","molecular_requirements":"Single chains on each side; no co-receptor requirement reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse in vivo (antibody treatment, reconstitution, homing), translated to human cells where an adhesive JAM-B/JAM-C interaction was found between human HSPC and mesenchymal stem cells, but not with endothelial cells or osteoblasts [PMID:24357068].","localisation_and_range":"Cell-cell adhesion between neighbouring cells (juxtacrine); JAM2 is flagged transmembrane [flag]. JAM3 also carries a secreted flag [flag].","caveats":"Abstract-only read. Evidence is antibody blockade rather than direct binding; IntAct protein array and solid phase assay and Reactome binding records add database support [DB:IntAct, DB:Reactome]. The interaction was cell-type restricted in human cells [PMID:24357068].","key_references":[{"PMID":"24357068","why":"Jam-b/Jam-c in HSPC homing and mobilisation, mouse and human"}],"covers":["LR001870","LR005215"]},"LR010714":{"pair":"KRTAP4-12 -> LINGO1","headline":"Only a yeast two-hybrid IntAct record; no evidence that this is a ligand-receptor interaction.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct lists a two-hybrid physical association from a large-scale screen; species and system not reported in our evidence [DB:IntAct].","localisation_and_range":"Not reported in our evidence.","caveats":"The only judged paper was review_only, so no curator-verified evidence exists. A two-hybrid hit does not show a ligand-receptor relationship, and KRTAP4-12 is a keratin-associated protein, so this is likely a screening artefact.","key_references":[],"covers":["LR010714"]},"LR010705":{"pair":"LAMA1 -> ITGA2:ITGB1","headline":"Laminin alpha1 LN module binds purified alpha2beta1 integrin, with a negative control fragment; abstract-only.","interaction_type":"direct binding","direction_and_effect":"Fragment alpha1VI/V bound purified alpha2beta1 integrin, heparin and perlecan heparan sulfate domains; fragment alpha1V alone did not bind [PMID:9688542]. Effect not reported.","molecular_requirements":"Complex receptor (ITGA2 plus ITGB1); the purified heterodimer bound, localising the activity to the LN module [PMID:9688542].","affinity_potency":[],"species_and_systems":"Human recombinant laminin fragments and purified integrins per curator fields [PMID:9688542].","localisation_and_range":"Ligand flagged secreted [flag]; matrix ligand.","caveats":"Abstract only; fragment tested, not full-length LAMA1. The fragment also binds heparin and perlecan heparan sulfate, so non-integrin partners exist [PMID:9688542]. BioGRID has ITGA2 and ITGB1 reconstituted-complex records [DB:BioGRID].","key_references":[{"PMID":"9688542","why":"Fragment binds purified alpha2beta1"}],"covers":["LR010705"]},"LR004405":{"pair":"LAMA2 -> ITGA7","headline":"Recombinant alpha7X1beta1 binds laminin-211/221 with Kd 0.64 nM; full-text plus functional support.","interaction_type":"direct binding","direction_and_effect":"Recombinant alpha7beta1 binds laminin-211/221 [PMID:16413178]. Alpha7beta1 is described as a receptor for laminin-2 mediating myoblast migration [PMID:11278916]. Labelled Stimulatory [flag].","molecular_requirements":"The alpha7X1beta1 variant gave Kd 0.64 nM; the alpha7X2beta1 variant gave 2.6 nM [PMID:16413178]. The receptor is the alpha7beta1 heterodimer.","affinity_potency":[{"value":"Kd 0.64 nM","assay":"solid-phase saturation binding","system":"recombinant human alpha7X1beta1 ectodomain with laminin-211/221","cite":"PMID:16413178"}],"species_and_systems":"Human recombinant integrins [PMID:16413178]; human myoblasts and HEK293 transfectants [PMID:11278916]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted; matrix ligand.","caveats":"Evidence is for the assembled laminin heterotrimer, not the single alpha chain alone [PMID:16413178]. The second paper is abstract-only and the identity statement is background [PMID:11278916].","key_references":[{"PMID":"16413178","why":"Kd 0.64 nM for alpha7X1beta1 and laminin-211/221"},{"PMID":"11278916","why":"Alpha7beta1 mediates myoblast migration on laminin-2"}],"covers":["LR000985","LR004405"]},"LR010804":{"pair":"LAMA2 -> ITGA7:ITGB1","headline":"Alpha7beta1 is described as the major laminin-2 receptor in muscle; functional, abstract-only.","interaction_type":"functional only","direction_and_effect":"Alpha7beta1 mediates myoblast migration on laminin-1 and -2, and alpha7 splice variants induce motility on laminin in HEK293 cells [PMID:11278916].","molecular_requirements":"Complex receptor ITGA7:ITGB1; the alpha7 cytoplasmic domain is not needed for adhesion but is needed for motility [PMID:11278916].","affinity_potency":[],"species_and_systems":"Human HEK293 alpha7 transfectants and myoblasts [PMID:11278916].","localisation_and_range":"Ligand flagged secreted; complex flagged transmembrane [flag].","caveats":"Abstract only; the identity statement is background, and the experiments used laminin-1/E8 rather than LAMA2-specific ligand. No affinity reported.","key_references":[{"PMID":"11278916","why":"Alpha7beta1 on laminin-1 and -2"}],"covers":["LR010804"]},"LR004414":{"pair":"LAMA5 -> ITGA3","headline":"Laminin alpha5 (as laminin-511/521) binds integrin alpha3beta1 with nM affinity; shown as heterotrimer and heterodimer, not single chains.","interaction_type":"direct binding","direction_and_effect":"Laminin-511/521 binds recombinant integrin alpha3beta1 [PMID:16413178]; laminin-10/11 is a high-affinity alpha3beta1 ligand, and CD151 potentiates the binding [PMID:15677332]. Blocking antibodies against alpha3 or beta1 inhibited A549 adhesion to laminin-10/11 [PMID:9624186]. Marked as stimulatory in the interaction annotation.","molecular_requirements":"Laminin alpha5 acts within a beta/gamma heterotrimer, and ITGA3 acts with ITGB1 (alpha3beta1); neither single chain was tested alone [PMID:16413178]. CD151 sustains the activated integrin conformation [PMID:15677332].","affinity_potency":[{"value":"Kd 3.4 nM","assay":"solid-phase saturation binding, recombinant integrin ectodomain to purified laminin isoforms (laminin-511/521 vs alpha3beta1)","system":"human recombinant proteins","cite":"PMID:16413178"}],"species_and_systems":"Human recombinant integrin and purified laminin [PMID:16413178]; human A549 cells [PMID:9624186]. Mouse pair is projected from human evidence (ortholog-inferred).","localisation_and_range":"LAMA5 is flagged secreted [flag] and ITGA3 is flagged as a receptor [flag]; beyond these annotation flags, range is not reported in our evidence.","caveats":"Chain-level assignment is inferred from the heterotrimer. Two of the three supporting papers were read as abstracts only [PMID:15677332][PMID:9624186]; the latter is an antibody-blocking adhesion readout.","key_references":[{"PMID":"16413178","why":"Kd of recombinant alpha3beta1 for laminin-511/521"},{"PMID":"15677332","why":"Laminin-10/11 high-affinity alpha3beta1 ligand; CD151 role"},{"PMID":"9624186","why":"Antibody-blocked adhesion to laminin-10/11"}],"covers":["LR000995","LR004414"]},"LR011380":{"pair":"LAMA5 -> ITGA3:ITGB1","headline":"Complex row for laminin alpha5 and integrin alpha3beta1; no curated paper here, only a PDB record with the two chains.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence for this row. A PDB entry holds a chain of O15230 and a chain of P05556 [DB:PDB 7CEC].","molecular_requirements":"The receptor is the ITGA3:ITGB1 heterodimer per the entity record. Required ligand chains are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and experimental system not reported in our evidence.","localisation_and_range":"LAMA5 is flagged secreted [flag] and ITGA3:ITGB1 is flagged as a receptor [flag]; beyond these annotation flags, range is not reported in our evidence.","caveats":"No papers were judged for this row (two read attempts were abstract_insufficient). Support rests on one structure record. Related rows on the same laminin-integrin pair carry direct-binding data (see LAMA5 -> ITGA3) but that is not evidence for this row.","key_references":[],"covers":["LR011380"]},"LR004423":{"pair":"LAMB3 -> ITGA3","headline":"LAMB3 (in laminin-332) binds integrin alpha3 with Kd 14 nM, and keratinocyte adhesion to epiligrin depends on alpha3beta1.","interaction_type":"direct binding","direction_and_effect":"Laminin-332, which contains LAMB3, bound recombinant alpha3beta1 in solid-phase assays [PMID:16413178]. Cell adhesion to immunopurified epiligrin was inhibited with an anti-alpha3beta1 antibody [PMID:2032285]. Annotated effect is Stimulatory [flag]. Direction: laminin to integrin.","molecular_requirements":"Binder is the alpha3beta1 heterodimer; the ligand is the assembled heterotrimer, not LAMB3 alone [PMID:16413178]. Epiligrin has three disulfide-bonded subunits [PMID:2032285].","affinity_potency":[{"value":"Kd 14 nM","assay":"solid-phase saturation binding, recombinant integrin ectodomain to purified laminin isoform; alpha3beta1 vs laminin-332","system":"recombinant human integrin, purified laminin","cite":"PMID:16413178"}],"species_and_systems":"Recombinant human proteins [PMID:16413178]; human foreskin keratinocytes [PMID:2032285]. Mouse pair is projected from human.","localisation_and_range":"Ligand is annotated as secreted [flag]; the receptor is annotated as a receptor [flag]. Matrix versus soluble range is not reported in our evidence.","caveats":"Kd values are for the whole laminin heterotrimer, not the single chain. PMID:2032285 was read as abstract only; it is a functional adhesion result, not direct binding.","key_references":[{"PMID":"16413178","why":"Kd for alpha3beta1 vs laminin-332, full text"},{"PMID":"2032285","why":"Keratinocyte adhesion to epiligrin blocked by anti-alpha3beta1, abstract only"}],"covers":["LR001005","LR004423"]},"LR006106":{"pair":"LAMC1 -> PTPRF","headline":"Laminin-nidogen complex binds the PTPRF (LAR) FnIII domain 5 in GST pulldowns; LAMC1 is a chain-level proxy.","interaction_type":"direct binding","direction_and_effect":"Laminin-nidogen was identified as a ligand for LAR-FnIII domain 5 [PMID:9647658]. Cross-linking LAR with antibody inhibited laminin-nidogen-induced cell processes in HeLa cells by 97% [PMID:9647658].","molecular_requirements":"Binding needs the Fn5 domain without the alternatively spliced exon 13 (Fn5-); inclusion of the exon disrupted binding, though some low-affinity binding of Fn5+ was seen at high concentration [PMID:9647658]. Purified laminin-nidogen bound Fn5- dose-dependently; the authors say they cannot specify the binding site on the complex or whether laminin binds directly, rather than through a bridge, from the conditioned-media experiments alone [PMID:9647658].","affinity_potency":[],"species_and_systems":"GST-LAR fusion proteins with media from human U373 MG cells or purified laminin-nidogen; functional readout in human HeLa cells [PMID:9647658].","localisation_and_range":"PTPRF is flagged transmembrane and LAMC1 secreted [flag]; the ligand acts as an extracellular matrix complex.","caveats":"The evidence is for the laminin-nidogen complex, not LAMC1 alone; no affinity reported; abstract was the curated read though full text is available.","key_references":[{"PMID":"9647658","why":"Laminin-nidogen binds LAR-FnIII domain 5, splice-regulated"}],"covers":["LR002872","LR006106"]},"LR004432":{"pair":"LAMC2 -> ITGA3","headline":"Recombinant integrin alpha3beta1 binds laminin-332 (contains LAMC2) with Kd 14 nM; LAMC2 is a chain-level proxy.","interaction_type":"direct binding","direction_and_effect":"Recombinant alpha3beta1 showed clear specificity for laminin-332 in solid-phase binding [PMID:16413178]. Recorded effect: stimulatory [flag].","molecular_requirements":"The tested ligand is the assembled laminin-332 heterotrimer and the receptor the alpha3beta1 heterodimer; the paper never tests individual chains [PMID:16413178].","affinity_potency":[{"value":"Kd 14 nM","assay":"solid-phase saturation binding of recombinant integrin to laminin-332","system":"human recombinant alpha3beta1 ectodomain","cite":"PMID:16413178"}],"species_and_systems":"Human ligand and receptor, recombinant soluble proteins [PMID:16413178]. Mouse pair is ortholog-projected.","localisation_and_range":"LAMC2 flagged secreted [flag].","caveats":"Evidence is for laminin-332 and the integrin heterodimer, not LAMC2 and ITGA3 chains in isolation.","key_references":[{"PMID":"16413178","why":"Kd of recombinant laminin-binding integrins for laminin isoforms"}],"covers":["LR001014","LR004432"]},"LR006115":{"pair":"LGALS3 -> ENG","headline":"Galectin-3 co-immunoprecipitates and co-localises with endoglin; identified in a protein microarray screen, abstract read only.","interaction_type":"direct binding","direction_and_effect":"Soluble endoglin bound galectin-3 with high affinity in a microarray of more than 9000 human proteins; endoglin co-immunoprecipitated and co-localised with galectin-3 in endothelial and CHO cells [PMID:31540324]. Functional effect not reported in our evidence.","molecular_requirements":"Soluble endoglin used as bait; whether the membrane form or co-receptors matter is not reported in our evidence [PMID:31540324].","affinity_potency":[],"species_and_systems":"Human endothelial cells and Chinese hamster ovary cells; recombinant soluble endoglin [PMID:31540324]. Mouse pair ortholog-inferred.","localisation_and_range":"Galectin-3 flagged secreted; endoglin proteolytically released as soluble form per the paper [PMID:31540324].","caveats":"No affinity number or direction reported; co-IP and co-localisation do not prove direct contact; abstract-only read.","key_references":[{"PMID":"31540324","why":"Endoglin interactome screen identifies galectin-3 as binder"}],"covers":["LR002881","LR006115"]},"LR006124":{"pair":"LGALS3 -> TYRO3","headline":"Exogenous galectin-3 stimulates TYRO3 phosphorylation in human cancer cells, but not AXL; one paper, evidence is functional.","interaction_type":"functional only","direction_and_effect":"Exogenous Gal-3 rapidly stimulated Tyro3 phosphorylation to the same extent as ProS1, but not Axl; it also activated Erk and Akt, protected from staurosporine-induced apoptosis and stimulated migration (agonist) [PMID:32664510].","molecular_requirements":"Selective for TYRO3 over AXL in cells; no co-receptor requirement reported in our evidence [PMID:32664510].","affinity_potency":[],"species_and_systems":"Human cancer lines SCC-25 (Tyro3 and Axl) and MGH-U3 (Tyro3 only) [PMID:32664510]. Mouse pair is ortholog-inferred.","localisation_and_range":"Galectin-3 has a secreted flag [flag]; added as exogenous protein to cells [PMID:32664510].","caveats":"Curated as direct binding, but the abstract reports receptor phosphorylation, not a binding measurement; the full text was available but excerpts are not shown here. Gal-3 was previously reported as a MerTK ligand (background). No affinity reported.","key_references":[{"PMID":"32664510","why":"Gal-3 stimulates Tyro3 phosphorylation and Erk signalling in human cancer cells"}],"covers":["LR002890","LR006124"]},"LR004441":{"pair":"LGALS3BP -> ITGB1","headline":"Cell adhesion to recombinant LGALS3BP is blocked by anti-integrin beta1 antibodies, and a BioGRID record exists; indirect evidence for the pair.","interaction_type":"functional only","direction_and_effect":"Adhesion of cell lines to M2BP was inhibited by antibodies to integrin beta1 subunits but not alpha2 or alpha6 antibodies, RGD peptide or lactose; this excludes galectin-3 involvement [PMID:9501082].","molecular_requirements":"Beta1 subunit implicated by antibody blockade; the alpha partner is not identified in our evidence [PMID:9501082].","affinity_potency":[],"species_and_systems":"Recombinant human M2BP from 293 cells with cell lines; mouse pair is ortholog-inferred [PMID:9501082].","localisation_and_range":"M2BP is described as a protein of the extracellular matrix, forming oligomers of 1000-1500 kDa [PMID:9501082]; ligand has a secreted flag [flag].","caveats":"Abstract only. Antibody inhibition of adhesion is not direct binding; the paper's title mentions binding beta1 integrins but the abstract shows only the blockade. BioGRID lists a Reconstituted Complex record [DB:BioGRID]. No affinity reported.","key_references":[{"PMID":"9501082","why":"M2BP-mediated cell adhesion is inhibited by anti-integrin beta1 antibodies"}],"covers":["LR001023","LR004441"]},"LR002902":{"pair":"LGALS8 -> PDPN","headline":"Galectin-8 interacts with podoplanin in a glycosylation-dependent manner, found by protein array; functional effects on lymphatic endothelial cells.","interaction_type":"direct binding","direction_and_effect":"Galectin-8 promoted lymphatic endothelial cell adhesion and haptotactic migration when immobilized, but inhibited tube formation when incorporated into a collagen matrix [PMID:19268462].","molecular_requirements":"Interaction depends on podoplanin glycosylation, tested with Fc glycoforms from different cell lines; podoplanin's O-glycans matter [PMID:19268462].","affinity_potency":[],"species_and_systems":"Recombinant human galectin-8 with podoplanin-Fc; human lymphatic and blood endothelial cells. Mouse pair is ortholog-inferred [PMID:19268462].","localisation_and_range":"Podoplanin is a membrane glycoprotein; galectin-8 is secreted per flag [flag]. UniProt notes a possible role in connecting lymphatic endothelium to matrix [DB:UniProt].","caveats":"Abstract and full-text excerpts show a protein-array hit as the only interaction above threshold; other galectins on the array were negative [PMID:19268462]. Other glycoproteins probably cooperate. No affinity in the excerpts shown.","key_references":[{"PMID":"19268462","why":"Galectin-8 identified as glycosylation-dependent podoplanin partner"}],"covers":["LR002902","LR006131"]},"LR010606":{"pair":"LGALS9 -> BCR:CD22:PTPRC","headline":"Galectin-9 binds IgM-BCR and brings it with CD22 and CD45 together, inhibiting BCR signalling; the complex is inferred from one mouse paper.","interaction_type":"direct binding","direction_and_effect":"Galectin-9 relocalizes IgM-BCR with the inhibitory molecules CD45 and CD22, and exogenous galectin-9 nearly abolishes BCR signaling (inhibitory) [PMID:30120235].","molecular_requirements":"Evidence supports IgM-BCR as the ligand-bound chain; galectin-9 mediates close association of IgM and CD22 [PMID:30120235]. Whether all three chains are needed for binding is not reported in our evidence, which matters for min-subunit scoring.","affinity_potency":[],"species_and_systems":"Primary mouse B cells; the dossier pair is human [PMID:30120235].","localisation_and_range":"Galectin-9 is secreted by flag [flag]; the receptors are on the B cell membrane.","caveats":"Abstract only for binding; the three-member complex is a co-localisation, not a defined receptor. No affinity reported.","key_references":[{"PMID":"30120235","why":"Galectin-9 associates IgM-BCR with CD22 and CD45"}],"covers":["LR010606"]},"LR006133":{"pair":"LGALS9 -> CD180","headline":"Galectin-9 binds CD180 on mouse B-1a cells and restrains TLR responses; evidence is from one paper, abstract-level.","interaction_type":"functional only","direction_and_effect":"Galectin-9 regulates BCR and TLR responses in B-1a cells by regulating the interaction of TLRs with CD180, dampening signaling; Gal9-deficient mice develop autoimmunity [PMID:34369876].","molecular_requirements":"The full text states Gal9 binds TLR4 and CD180 and dampens signal transduction by altering nano-scale co-distribution; CD180 acts as a regulatory molecule [PMID:34369876].","affinity_potency":[],"species_and_systems":"Primary mouse B-1a and B-1b cells (pull-downs with rGal9-coated beads); human pair is ortholog-inferred [PMID:34369876].","localisation_and_range":"Galectin-9 has a secreted flag [flag].","caveats":"Effect was seen in B-1a cells but not B-1b cells. Curated as functional; the pull-down details are cut off in the excerpts shown. No affinity reported.","key_references":[{"PMID":"34369876","why":"Galectin-9 restrains B-1a cell BCR and TLR responses via CD5 and CD180"}],"covers":["LR002904","LR006133"]},"LR005224":{"pair":"LGALS9 -> HAVCR2","headline":"Galectin-9 reported as the Tim-3 ligand, with functional evidence and database support, but one UniProt entry notes a challenge.","interaction_type":"conflicting","direction_and_effect":"Galectin-9 induced Tim-3-dependent calcium flux, aggregation and death of Th1 cells in vitro, and in vivo administration selectively depleted IFN-gamma-producing cells and suppressed Th1 autoimmunity; curator labels it agonist [PMID:16286920]. Reactome lists the HAVCR2:LGALS9 complex at the plasma membrane [DB:Reactome].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human labelled for both partners by the curator; the abstract also reports in vivo administration, with species not stated in our evidence [PMID:16286920]. Mouse pair is separate and not ortholog-inferred.","localisation_and_range":"Galectin-9 flagged secreted, Tim-3 flagged transmembrane [flag]; Reactome places the complex at the plasma membrane [DB:Reactome].","caveats":"The paper is functional (Tim-3-dependent) and was read as abstract only. A UniProt entry on the HAVCR2 side-record says the function of Q8TDQ0 as a receptor for LGALS9 has been challenged [DB:UniProt]; note this accession is not identified in our evidence as HAVCR2. Two further rows were review-only.","key_references":[{"PMID":"16286920","why":"Identifies galectin-9 as the Tim-3 ligand"}],"covers":["LR001882","LR005224"]},"LR005233":{"pair":"LGI4 -> ADAM11","headline":"LGI4 binds ADAM11 moderately in cell-ELISA; ADAM22 is its strongest partner. Two confirming papers.","interaction_type":"direct binding","direction_and_effect":"LGI4 interacts with ADAM11 as well as ADAM22 and ADAM23 in cell-based binding assays [PMID:18974846]. Functional effect on ADAM11 is not reported in our evidence; the authors speculate ADAM11 may be supportive or a negative regulator and note ADAM11-deficient mice lacked myelination defects [PMID:18974846].","molecular_requirements":"Binding was measured with ADAM-expressing cells; no co-receptor requirement for ADAM11 is reported in our evidence. Reactome lists an LGI4:ADAM22,11,23 complex at the plasma membrane [DB:Reactome].","affinity_potency":[],"species_and_systems":"Cell-ELISA with mouse LGI4 and mouse ADAMs [PMID:18974846]; the dossier lists the experiment species as human. The human pair is ortholog-inferred, the mouse pair is not.","localisation_and_range":"LGI4 is secreted and ADAM11 is not flagged secreted [flag]; ADAM11 is a cell-surface receptor in the ADAM family.","caveats":"Binding to ADAM11 was moderate, weaker than to ADAM22 [PMID:18974846]. The main paper was read as an abstract plus full-text excerpts; the second is an unverified browser-read sentence [PMID:20220021]. No affinity value is reported.","key_references":[{"PMID":"18974846","why":"Cell-ELISA showing LGI4 binds ADAM11, ADAM22 and ADAM23"},{"PMID":"20220021","why":"Reports Lgi4 binding to Adam11 and Adam23 in addition to Adam22 (browser-read)"}],"covers":["LR001891","LR005233"]},"LR002911":{"pair":"LIF -> LRP1","headline":"LRP1 binds LIF directly in a chondrocyte ligandome study; single abstract-read paper, no database record.","interaction_type":"direct binding","direction_and_effect":"Direct LRP1 binding was confirmed for LIF among ten ligands [PMID:36028175]. The effect on signalling is not reported in our evidence; the dossier lists the effect as agonist but the study concerns endocytosis, with affinity correlating to endocytosis rate [PMID:36028175].","molecular_requirements":"No co-receptor or chain requirement reported.","affinity_potency":[],"species_and_systems":"Purified LRP1 binding assays, human chondrocytes, and a conditional Lrp1-knockout mouse model; the dossier labels species human [PMID:36028175]. Mouse pair is ortholog-inferred.","localisation_and_range":"LIF is flagged secreted [flag]; LRP1 is an endocytic receptor, so this is clearance rather than classical signalling (the abstract refers to endocytosis).","caveats":"One paper, abstract only; no affinity value for LIF in our evidence. A multi-ligand screen where LIF is one of ten. No database support.","key_references":[{"PMID":"36028175","why":"Direct LRP1 binding confirmed for LIF among ten chondrocyte ligands"}],"covers":["LR002911","LR006137"]},"LR006142":{"pair":"LRFN5 -> PTPRD","headline":"LRFN5 (SALM5) binds LAR-RPTPs including PTPRD via Ig domains; one paper, with 8.96 nM Kd measured for LAR.","interaction_type":"direct binding","direction_and_effect":"SALM5 interacts with the Ig domains of LAR-RPTPs (LAR, PTP-delta, PTP-sigma) [PMID:27225731]. PTP-delta and PTP-sigma interacted with SALM5 in cell aggregation assays [PMID:27225731]. Assay detail reports a stimulatory effect on presynaptic differentiation in contacting axons, with the interaction strongly inhibited by splice insert B [PMID:27225731].","molecular_requirements":"The three LAR Ig domains were sufficient for SALM5 binding; the FNIII region did not bind. The interaction was calcium-insensitive [PMID:27225731]. Other SALMs did not interact with LAR in cell aggregation assays [PMID:27225731].","affinity_potency":[{"value":"Kd 8.96 \u00b1 0.92 nM","assay":"Scatchard analysis of LAR-Ecto-Fc binding","system":"SALM5-expressing HEK293T cells; measured for LAR, not PTPRD","cite":"PMID:27225731"}],"species_and_systems":"HEK293T cell aggregation and soluble-binding assays, cocultured hippocampal neurons [PMID:27225731].","localisation_and_range":"Both partners flagged not secreted; transmembrane, so trans-synaptic contact adhesion [flag][PMID:27225731].","caveats":"Affinity was measured for LAR only; PTPRD was shown by cell aggregation only [PMID:27225731]. Record is labelled abstract-only although full-text excerpts exist.","key_references":[{"PMID":"27225731","why":"SALM5 binds LAR-RPTP Ig domains; Kd for LAR 8.96 nM"}],"covers":["LR002917","LR006142"]},"LR002920":{"pair":"LRIG1 -> EGFR","headline":"LRIG1 binds EGFR and a soluble LRIG1 ectodomain inhibits EGFR activity; the primary paper is abstract-only, with multiple interaction-database records.","interaction_type":"direct binding","direction_and_effect":"A soluble LRIG1 ectodomain of the LRRs inhibited ligand-independent EGFR activation and growth of A431, HeLa and MDA-468 cells; EGFR-negative cells were unresponsive until EGFR was reintroduced [PMID:16847455]. Excess EGF displaced up to 75% of LRIG1 binding on A431 cells, suggesting an overlapping binding region [PMID:16847455]. Effect is antagonist/inhibitory.","molecular_requirements":"UniProt says LRIG1 interacts via extracellular LRR and Ig-like domains with EGFR, ERBB2, ERBB3 and ERBB4 [DB:UniProt]. The soluble ectodomain with only the LRRs was active [PMID:16847455].","affinity_potency":[{"value":"Kd 10 nM","assay":"LRIG1 binding sites on A431 cells","system":"human A431 cells","cite":"PMID:16847455"}],"species_and_systems":"Human carcinoma cell lines [PMID:16847455]; mouse pair is ortholog-inferred.","localisation_and_range":"LRIG1 not flagged secreted or transmembrane in our entity flags [flag]; the active form tested was a soluble ectodomain [PMID:16847455].","caveats":"UniProt also notes LRIG1 may have low affinity for EGFR and interaction may occur only when both are at high levels [DB:UniProt]. Primary paper abstract only. BioGRID and IntAct list co-IP and affinity capture records [DB:BioGRID][DB:IntAct].","key_references":[{"PMID":"16847455","why":"Soluble LRIG1 ectodomain binds A431 cells (Kd 10 nM) and inhibits EGFR"}],"covers":["LR002920","LR006145"]},"LR010741":{"pair":"LRP1B -> PLAUR","headline":"An LRP1B minireceptor forms immunoprecipitable complexes with uPAR; thin evidence from one 2002 abstract.","interaction_type":"direct binding","direction_and_effect":"mLRP1B4 and uPAR form immunoprecipitable complexes on the cell surface in the presence of uPA/PAI-1 complexes; mLRP1B4 slows uPA.PAI-1 internalisation, increases surface uPAR and impairs uPAR regeneration and cell migration [PMID:12194987]. LRP1B acts as a negative regulator of uPAR regeneration [PMID:12194987].","molecular_requirements":"Complex formation was seen in the presence of uPA.PAI-1 complexes; whether uPAR binds LRP1B without them is not reported in our evidence [PMID:12194987].","affinity_potency":[],"species_and_systems":"Cells expressing an LRP1B minireceptor (mLRP1B4); species stated as human [PMID:12194987].","localisation_and_range":"Both are membrane proteins; uPAR is also flagged secreted [flag]. Range not otherwise reported.","caveats":"Pair class is Receptor-Receptor, not a classical ligand-receptor pair. Evidence uses a minireceptor construct, not full-length LRP1B, and abstract only. Co-IP may be indirect. Two other judged papers were abstract_insufficient or unresolvable.","key_references":[{"PMID":"12194987","why":"LRP1B minireceptor co-IPs with uPAR and impairs uPAR regeneration"}],"covers":["LR010741"]},"LR004450":{"pair":"LRPAP1 -> LRP1","headline":"RAP (LRPAP1) binds LRP1 with a KD of 14 nM and blocks ligand binding; well supported by papers, structure and databases.","interaction_type":"direct binding","direction_and_effect":"RAP binds two equivalent sites on alpha2MR/LRP and completely inhibits binding of 125I-activated alpha2M, so RAP occupancy sets receptor activity [PMID:1374383]. Recombinant 39-kDa RAP reversibly binds the 515-kDa subunit and inhibits uptake of apoE-enriched VLDL and activated alpha2M [PMID:1718973]. Curators label it an antagonist [PMID:1374383].","molecular_requirements":"RAP binds the 515-kDa subunit [PMID:1718973]. Each of three LDL receptor homology regions (sLRP2, sLRP3, sLRP4) bound human RAP, though not all ligand binding could be competed by RAP [PMID:14596620].","affinity_potency":[{"value":"KD 14 nM","assay":"titration and binding studies","system":"alpha2MR/LRP","cite":"PMID:1374383"},{"value":"Ki 23 nM","assay":"displacement of 125I-activated alpha2M","system":"human fibroblasts","cite":"PMID:1374383"},{"value":"Ki 26 nM","assay":"displacement of 125I-activated alpha2M","system":"purified LRP","cite":"PMID:1374383"}],"species_and_systems":"Human fibroblasts, purified receptor, and Pichia-expressed human receptor fragments [PMID:1374383] [PMID:14596620]. Databases: PDB structure [DB:PDB 2FYL], BioGRID [DB:BioGRID], IntAct [DB:IntAct], UniProt [DB:UniProt]. The mouse pair is ortholog-inferred.","localisation_and_range":"LRPAP1 is flagged secreted [flag]. The curators' note describes RAP as an intracellular chaperone that remains associated on the cell surface [PMID:1374383].","caveats":"RAP is a regulatory or chaperone ligand that blocks other ligands, not a conventional signalling ligand [PMID:1374383]. Papers were read as abstracts only.","key_references":[{"PMID":"1374383","why":"RAP binding to LRP, KD 14 nM, and ligand inhibition"},{"PMID":"1718973","why":"Original demonstration that recombinant RAP binds LRP and inhibits ligands"},{"PMID":"14596620","why":"RAP binds all three LRP LDL-receptor homology regions"}],"covers":["LR001036","LR004450"]},"LR008410":{"pair":"LRPAP1 -> VLDLR","headline":"RAP (LRPAP1) binds the VLDL receptor with a KD of 0.7 nM and inhibits VLDL binding; two papers plus database records.","interaction_type":"direct binding","direction_and_effect":"Purified VLDL receptor bound RAP and RAP completely inhibited 125I-VLDL binding [PMID:8083232]. Curators label RAP an antagonist [PMID:8083232]. The VLDL receptor in human aortic endothelial, umbilical vein endothelial and aortic smooth muscle cells bound RAP in ligand blotting [PMID:7592875].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"KD 0.7 nM","assay":"ELISA with purified VLDL receptor","system":"CHO cells transfected with VLDL receptor","cite":"PMID:8083232"}],"species_and_systems":"CHO cell extracts and human vascular cells [PMID:8083232] [PMID:7592875]. IntAct lists ELISA, far western and co-IP records [DB:IntAct]; BioGRID lists reconstituted complexes [DB:BioGRID].","localisation_and_range":"LRPAP1 is flagged secreted [flag]. Range not otherwise reported.","caveats":"RAP is a universal antagonist/chaperone for this receptor family rather than a physiological ligand. Both papers abstract only; one other row was a different entity and one unresolvable.","key_references":[{"PMID":"8083232","why":"RAP binds VLDL receptor, KD 0.7 nM, inhibits VLDL binding"},{"PMID":"7592875","why":"RAP ligand blotting detects VLDL receptor in human vascular cells"}],"covers":["LR008410"]},"LR006151":{"pair":"LRRC4C -> NTNG1","headline":"NGL-1 (LRRC4C) binds netrin-G1 through its LRR region; supported by binding, structural database records and mouse genetics, direction is conventional.","interaction_type":"direct binding","direction_and_effect":"NGL-1 specifically interacts with netrin-G1 through its LRR region [PMID:14595443]. Surface-bound NGL-1 stimulates, but soluble NGL-1 disrupts, growth of embryonic thalamic axons [PMID:14595443]. Netrin-G1/NGL1 interactions specify excitatory synapses in mouse hippocampus, and NGL-KO phenocopies netrin-G-KO plasticity phenotypes [PMID:25411505]. Trans-synaptic adhesion between presynaptic netrin-G1 and postsynaptic NGL-1 induces a cis interaction of netrin-G1 with LAR and promotes presynaptic differentiation [PMID:23986473].","molecular_requirements":"The LRR region of NGL-1 mediates netrin-G1 binding [PMID:14595443]. In synapses a tripartite NGL-1, netrin-G1 and LAR complex is described [PMID:23986473].","affinity_potency":[],"species_and_systems":"Human NGL-1 was identified, with netrin-G1 expression studied in mouse thalamic axons [PMID:14595443]. Other papers used neurons or mouse hippocampus with knockout mice [PMID:23986473, PMID:25411505]. Database records include BioGRID Affinity Capture-Western, Reconstituted Complex and Co-crystal Structure, IntAct SPR, and PDB 3ZYJ [DB:BioGRID, DB:IntAct, DB:PDB 3ZYJ].","localisation_and_range":"LRRC4C is flagged transmembrane and NTNG1 secreted [flag]; the papers describe netrin-G1 as lipid-anchored and membrane-bound, and the interaction as trans-synaptic adhesion [PMID:14595443, PMID:23986473].","caveats":"Ligand/receptor direction is a naming convention; the curator notes NGL-1 is functionally the signal-receiving partner. All three papers were read as abstracts only. No affinity value is reported in our evidence.","key_references":[{"PMID":"14595443","why":"identifies NGL-1 as netrin-G1 binding partner via LRR region"},{"PMID":"25411505","why":"in vivo KO evidence for netrin-G1/NGL1 synaptic specificity"},{"PMID":"23986473","why":"trans-synaptic adhesion and cis LAR interaction"}],"covers":["LR002926","LR006151"]},"LR006160":{"pair":"LRRTM4 -> GPC3","headline":"LRRTM4 binds glypicans in a heparan sulfate-dependent manner, with GPC3 covered by a class-level result; one paper, mouse glypicans in HEK293T.","interaction_type":"direct binding","direction_and_effect":"Glypican binds LRRTM4, but not LRRTM2, in an HS-dependent manner [PMID:23911103]. LRRTM4-Fc strongly bound all glypican isoforms tested, and GPC1 and GPC3-6 were detected in the LRRTM4-Fc sample [PMID:23911103].","molecular_requirements":"Heparan sulfate on the glypican is required for binding [PMID:23911103]. Whether the core protein alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cell surface binding used HA-tagged mouse glypican cDNAs in HEK293T cells; proteomics used rat brain [PMID:23911103]. Human and mouse pairs are orthology-projected. No database records.","localisation_and_range":"Glypican is described as a GPI-anchored HSPG [PMID:23911103]; GPC4 and LRRTM4 localise to pre- and postsynaptic membranes of excitatory synapses [PMID:23911103]. Annotation flag for GPC3 says not secreted [flag].","caveats":"Only one paper, read as abstract with excerpts. The curator notes the abstract names glypican generically, but the excerpts cover this paralog. No affinity reported.","key_references":[{"PMID":"23911103","why":"unbiased proteomics identifying glypican as LRRTM4 receptor"}],"covers":["LR002935","LR006160"]},"LR001039":{"pair":"LTA -> TNFRSF14","headline":"Secreted LT alpha binds HVEM; supported by one primary paper plus pull-down and curated database records.","interaction_type":"direct binding","direction_and_effect":"HVEM binds two cellular ligands, secreted LT alpha and LIGHT [PMID:9462508]. Curator labels this agonist; UniProt calls HVEM a receptor for LTA among four ligands in a stimulatory and inhibitory network [DB:UniProt].","molecular_requirements":"UniProt specifies the homotrimeric form of LTA binds TNFRSF14 [DB:UniProt]; Reactome lists an LTA trimer:TNFRSF1A,1B,14 complex [DB:Reactome]. LIGHT does not form complexes with LTalpha or LTbeta alone [PMID:9462508].","affinity_potency":[],"species_and_systems":"Human ligand and receptor per curator; abstract-only reading, assay specifics not reported [PMID:9462508]. IntAct lists a pull-down for this pair [DB:IntAct].","localisation_and_range":"LT alpha is flagged secreted and HVEM transmembrane [flag]; the paper calls LT alpha secreted [PMID:9462508].","caveats":"No affinity reported. Paper read as abstract only; two other judged rows are pending and not shown. GtoPdb lists the pair without type or action [DB:GtoPdb].","key_references":[{"PMID":"9462508","why":"Shows HVEM binds secreted LT alpha and LIGHT"}],"covers":["LR001039"]},"LR001048":{"pair":"MADCAM1 -> CD44","headline":"A 1989 binding study showing gp90Hermes, identical to or including CD44, binds MAdCAM; identity of CD44 rests on earlier work.","interaction_type":"direct binding","direction_and_effect":"Lymphocyte gp90Hermes binds in a saturable, reversible fashion to the mucosal vascular addressin (MAd) [PMID:2474557]. The abstract states the Hermes antigen is identical to or includes CD44 [PMID:2474557].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Abstract-only; tissue sections were human; assay was fluorescence energy transfer with purified MAd [PMID:2474557]. Curator species fields are blank.","localisation_and_range":"MAdCAM1 flagged transmembrane (endothelial adhesion molecule) and CD44 flagged both secreted and transmembrane [flag].","caveats":"Abstract-only; CD44 identity with gp90Hermes is cited as earlier work from the authors and others, not shown here. No affinity. Mouse pair is projected.","key_references":[{"PMID":"2474557","why":"gp90Hermes (CD44-related) binds mucosal addressin"}],"covers":["LR001048","LR004461"]},"LR005242":{"pair":"MCAM -> MCAM","headline":"Possible homophilic MCAM binding, suggested by adhesion data in a single abstract-only paper.","interaction_type":"functional only","direction_and_effect":"MCAM-l-transfected NKL1 cells and activated CD4 T cells adhered to recombinant MCAM under shear stress, blocked by anti-MCAM antibody, 'suggesting' homophilic MCAM-l-MCAM-l interactions [PMID:17982057].","molecular_requirements":"The long cytoplasmic isoform (MCAM-l) is needed; MCAM short or mock transfection had no effect on adhesion [PMID:17982057].","affinity_potency":[],"species_and_systems":"Human NK cell line NKL1, CD4 T cells, recombinant MCAM, under shear stress [PMID:17982057]. Mouse pair is ortholog-inferred.","localisation_and_range":"Annotation flags give not secreted and not transmembrane [flag], which does not settle localisation; adhesion data imply cell surface contact.","caveats":"The abstract describes homophilic binding only as possible; the paper's clearer finding is MCAM promoting VCAM-1 rolling. Antibody inhibition does not prove direct self-binding. BioGRID lists a co-purification [PMID:29741757][DB:BioGRID].","key_references":[{"PMID":"17982057","why":"MCAM-l adhesion to recombinant MCAM under shear"}],"covers":["LR001900","LR005242"]},"LR001057":{"pair":"MDK -> ITGA6","headline":"Midkine binds integrin alpha4beta1 and alpha6beta1 in mouse embryo and cell assays; evidence is for heterodimers, from one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Midkine binds these integrins; alpha4beta1 and alpha6beta1 are concluded to be functional midkine receptors. Anti-alpha4 antibody inhibited midkine-dependent migration of osteoblastic cells and anti-alpha6 inhibited neurite outgrowth of embryonic neurons; midkine raised paxillin tyrosine phosphorylation [PMID:15466886].","molecular_requirements":"Needs alpha6 with beta1: purified alpha6beta1 bound midkine [PMID:15466886].","affinity_potency":[],"species_and_systems":"Mouse embryo (13-day) extracts and cell assays; curated as human/human, but the experiments used mouse material [PMID:15466886]. Mouse pair is ortholog-inferred.","localisation_and_range":"MDK is flagged secreted, not transmembrane [flag]; paracrine growth factor.","caveats":"Single paper, abstract only. The integrins may cooperate with other midkine receptors (PTPRZ, LRP, ALK) [PMID:15466886]. UniProt records the interaction [DB:UniProt].","key_references":[{"PMID":"15466886","why":"midkine-integrin binding and function"}],"covers":["LR001057","LR004470"]},"LR001066":{"pair":"MFAP2 -> NOTCH1","headline":"MAGP-1 (MFAP2) binds Notch1 and activates it by ectodomain release in one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"MAGP-1 was shown to bind Notch1, cause release of the Notch1 extracellular domain and activate signalling, as an agonist [PMID:16492672].","molecular_requirements":"The paper maps MAGP-2 binding to the EGF-like repeats of Notch1 and its C-terminal domain; release needs prior furin-like cleavage but not the ADAM cleavage [PMID:16492672]. Whether these details hold for MAGP-1 is not stated.","affinity_potency":[],"species_and_systems":"Human proteins in co-expression cell assays [PMID:16492672]. Both species pairs are ortholog-inferred.","localisation_and_range":"MFAP2 is flagged secreted [flag]; the paper describes it as a microfibril protein [PMID:16492672].","caveats":"Most mechanistic work was on MAGP-2; MAGP-1 was 'predicted and further showed' from homology. Abstract only, no affinity. Non-canonical activation by ectodomain dissociation, not DSL-like ligand activation.","key_references":[{"PMID":"16492672","why":"MAGP-1/-2 bind Notch1 and induce ectodomain release and activation"}],"covers":["LR001066","LR004479"]},"LR001903":{"pair":"MICB -> KLRK1","headline":"MICB is an established activating NKG2D ligand per UniProt; the single paper concerns receptor trafficking, not binding.","interaction_type":"functional only","direction_and_effect":"MICB-expressing targets engage NKG2D on NK cells (agonist) and trigger degradation of about 50% of total NKG2D and lysosomal degradation of the DAP10 adaptor [PMID:19329438]. UniProt describes MICB as a ligand that stimulates the activating receptor KLRK1/NKG2D [DB:UniProt].","molecular_requirements":"The NKG2D/DAP10 complex is the receptor unit studied; DAP10 is an adaptor that traffics to secretory lysosomes and the immune synapse [PMID:19329438]. Whether KLRK1 alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human NK cells (primary activated and resting) and the NKL cell line, with MICB-expressing target cells; abstract only [PMID:19329438].","localisation_and_range":"UniProt calls MICB a membrane-bound protein [DB:UniProt]; the entity also carries a secreted flag [flag]. Contact-dependent engagement at the immune synapse is described [PMID:19329438].","caveats":"Our evidence has no direct binding data and no affinity. The paper was read as an abstract only and reports downstream receptor fate after chronic ligand exposure rather than the interaction itself [PMID:19329438].","key_references":[{"PMID":"19329438","why":"NKG2D/DAP10 degradation and synapse trafficking on MICB exposure"}],"covers":["LR001903"]},"LR001075":{"pair":"MMP7 -> CD151","headline":"proMMP-7 binds CD151 in human carcinoma cells; interaction maps to the propeptide and CD151 C-terminal loop; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"CD151 captures proMMP-7 at the cell membrane, and in situ zymography showed proteinase activity around CD151-expressing cells that anti-CD151 or anti-MMP-7 antibodies abolished [PMID:16200075]. This suggests CD151 supports pericellular proMMP-7 activation.","molecular_requirements":"Yeast two-hybrid deletion mapping placed the interaction between the propeptide of proMMP-7 and the COOH-terminal extracellular loop of CD151 [PMID:16200075].","affinity_potency":[],"species_and_systems":"Yeast two-hybrid, immunoprecipitation from CaR-1 human rectal carcinoma cells and CD151 stable transfectants, 125I-proMMP-7 binding, confocal colocalisation, and human lung adenocarcinoma tissue [PMID:16200075]. The mouse pair is ortholog-inferred.","localisation_and_range":"MMP7 is flagged as secreted [flag]; CD151 is a transmembrane protein, so this is a cell-surface docking interaction [PMID:16200075].","caveats":"CD151 is a tetraspanin-type partner that captures a protease rather than a classical signalling receptor. Abstract only. Mouse row inferred from human.","key_references":[{"PMID":"16200075","why":"Yeast two-hybrid, co-IP and membrane binding of proMMP-7 to CD151"}],"covers":["LR001075","LR004487"]},"LR005251":{"pair":"MSMP -> CCR2","headline":"PSMP/MSMP acts as a chemokine ligand for CCR2, shown functionally in mice with full text.","interaction_type":"functional only","direction_and_effect":"PSMP chemo-attracts Ly6Chi monocytes in a CCR2-dependent manner; this was lost in CCR2 knockout mice and CCR2 antagonist RS504393 reduced recruitment [PMID:28698550]. UniProt also states it acts as a ligand for CCR2 [DB:UniProt].","molecular_requirements":"No co-receptor or subunit requirement reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse in vivo (adoptive transfer, colitis models); human and mouse PSMP both attract mouse macrophages in a CCR2-dependent manner [PMID:28698550].","localisation_and_range":"Secreted chemokine [flag], acting at a distance as a chemoattractant [PMID:28698550].","caveats":"Direct binding not shown in the abstract or excerpts; evidence is CCR2-dependent chemotaxis. Abstract plus excerpts only.","key_references":[{"PMID":"28698550","why":"CCR2-dependent chemotaxis by PSMP in vivo"}],"covers":["LR001911","LR005251"]},"LR001912":{"pair":"MUC1 -> SIGLEC9","headline":"Sialylated cancer MUC1 binds Siglec-9 and activates myeloid cells; full-text supported.","interaction_type":"direct binding","direction_and_effect":"MUC1-ST bound recombinant Siglecs-3, 7, 9 and 10, most strongly Siglec-9; anti-Siglec-9 inhibited 80-95% of MUC1-ST binding to monocytes and macrophages [PMID:27595232]. Engagement induced calcium flux and MEK-ERK activation, not SHP-1 or SHP-2 [PMID:27595232].","molecular_requirements":"Requires sialic acid on MUC1; non-sialylated MUC1 did not induce the response [PMID:27595232].","affinity_potency":[],"species_and_systems":"Human primary monocytes and macrophages, recombinant proteins [PMID:27595232].","localisation_and_range":"MUC1 secreted flag [flag]; the tumour-associated sialylated glycoform engages myeloid cells in the microenvironment.","caveats":"Glycoform-dependent; MUC1-ST also bound other Siglecs; anti-Siglec-9 can act as an activating antibody; single paper.","key_references":[{"PMID":"27595232","why":"MUC1-ST binds Siglec-9 and signals"}],"covers":["LR001912"]},"LR001084":{"pair":"MYOC -> FZD3","headline":"Myocilin-AP fusion bound FZD3 in a browser-read Results sentence; modulates Wnt signalling.","interaction_type":"direct binding","direction_and_effect":"Myocilin-AP bound Fzd1, Fzd3, Fzd4, Fzd7, Fzd10 and sFRPs; myocilin modulated Wnt signalling and its stress fiber activity was blocked by sFRP1/sFRP3 and beta-catenin siRNA [PMID:19188438]. Effect of myocilin on the receptor (agonist versus modulator) is not clear from our evidence.","molecular_requirements":"Binding was to cysteine-rich domains of Frizzled receptors; sFRPs also bound, so Wnt pathway modulators are involved [PMID:19188438]. Co-receptor requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Myocilin expressed in HEK293 cells, tested on human trabecular meshwork and NIH 3T3 cells; construct species for the binding sentence not stated. Mouse pair is ortholog-inferred [PMID:19188438].","localisation_and_range":"Myocilin is flagged secreted [flag]; acts as a secreted modulator in conditioned medium [PMID:19188438].","caveats":"Binding sentence was browser-read and unverified (spot-check pending); dossier abstract only. Binding is AP-fusion to receptor CRDs, not full receptor, and shared across several Fzd paralogs, so paralog specificity is weak.","key_references":[{"PMID":"19188438","why":"Myocilin-AP binding to Fzd CRDs and Wnt signalling modulation"}],"covers":["LR001084","LR004495"]},"LR006205":{"pair":"NCAN -> L1CAM","headline":"L1 binds neurocan with high affinity; binding site mapped to the first Ig domain of human L1; abstract-only.","interaction_type":"direct binding","direction_and_effect":"L1 can bind with high affinity to neurocan, and neurocan can block homophilic L1 binding [PMID:10934197].","molecular_requirements":"The neurocan-binding site is in the first Ig-like domain of human L1, mapped by fusion proteins, mutagenesis and peptide blocking [PMID:10934197].","affinity_potency":[],"species_and_systems":"Human L1 fusion proteins in vitro; mouse pair is ortholog-inferred [PMID:10934197].","localisation_and_range":"Neurocan flagged secreted and L1 transmembrane [flag]; Reactome lists an L1:Neurocan plasma membrane complex [DB:Reactome R-HSA-443646].","caveats":"Abstract only; no affinity value in our evidence. The inhibition of homophilic binding was reported as prior literature in the abstract ('It has been reported'). BioGRID also lists a reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"10934197","why":"Neurocan-binding site mapped on L1 Ig1"}],"covers":["LR002980","LR006205"]},"LR001921":{"pair":"NECTIN2 -> PVRIG","headline":"Well supported high-affinity binding with inhibitory checkpoint function in human cells; mouse binding also shown in one paper.","interaction_type":"direct binding","direction_and_effect":"PVRIG (CD112R) is an inhibitory receptor for Nectin-2 (CD112). CD112-Fc bound CD112R transfectants and CD112R protein bound CD112-coated beads; blocking the interaction enhanced human T-cell response [PMID:26755705]. PVRL2's inhibitory effect on CD8+ T cells was mediated by PVRIG and not TIGIT [PMID:30659054]. PVRIG blockade enhanced NK killing of PVRL2+ AML cell lines [PMID:33147937].","molecular_requirements":"CD112R competes with CD226 for a shared binding site on CD112; CD226 inhibited CD112-CD112R binding and CD112R inhibited CD112-CD226 binding [PMID:26755705]. Single-chain receptor; no further subunits reported.","affinity_potency":[{"value":"Kd 0.088 \u00b5M","assay":"Biacore surface plasmon resonance, CD112R binding to CD112","system":"recombinant human proteins","cite":"PMID:26755705"}],"species_and_systems":"Human cells and recombinant protein for the main evidence [PMID:26755705] [PMID:30659054] [PMID:33147937]. Mouse CD112R fusion protein bound mouse CD112 on RMA-S cells [PMID:26755705].","localisation_and_range":"Membrane-bound receptor and ligand on T/NK and antigen-presenting or tumour cells; contact-dependent [PMID:26755705].","caveats":"Abstract-only reading for curator fields, though full-text excerpts were available. PVRIG-PVRL2 affinity of 88 nmol/L in another paper is a citation of earlier work [PMID:30659054]. PVRIG expression on NK cells falls on activation [PMID:33147937]. Two PDB structures exist [DB:PDB 8X6B].","key_references":[{"PMID":"26755705","why":"Identifies CD112 as ligand; Kd, competition with CD226, mouse binding"},{"PMID":"30659054","why":"PVRIG-PVRL2 as non-redundant inhibitory node in T cells"},{"PMID":"33147937","why":"PVRIG blockade enhances NK killing of AML"}],"covers":["LR001921","LR005260"]},"LR005260":{"pair":"NECTIN2 -> PVRIG","headline":"Well supported high-affinity binding with inhibitory checkpoint function in human cells; mouse binding also shown in one paper.","interaction_type":"direct binding","direction_and_effect":"PVRIG (CD112R) is an inhibitory receptor for Nectin-2 (CD112). CD112-Fc bound CD112R transfectants and CD112R protein bound CD112-coated beads; blocking the interaction enhanced human T-cell response [PMID:26755705]. PVRL2's inhibitory effect on CD8+ T cells was mediated by PVRIG and not TIGIT [PMID:30659054]. PVRIG blockade enhanced NK killing of PVRL2+ AML cell lines [PMID:33147937].","molecular_requirements":"CD112R competes with CD226 for a shared binding site on CD112; CD226 inhibited CD112-CD112R binding and CD112R inhibited CD112-CD226 binding [PMID:26755705]. Single-chain receptor; no further subunits reported.","affinity_potency":[{"value":"Kd 0.088 \u00b5M","assay":"Biacore surface plasmon resonance, CD112R binding to CD112","system":"recombinant human proteins","cite":"PMID:26755705"}],"species_and_systems":"Human cells and recombinant protein for the main evidence [PMID:26755705] [PMID:30659054] [PMID:33147937]. Mouse CD112R fusion protein bound mouse CD112 on RMA-S cells [PMID:26755705].","localisation_and_range":"Membrane-bound receptor and ligand on T/NK and antigen-presenting or tumour cells; contact-dependent [PMID:26755705].","caveats":"Abstract-only reading for curator fields, though full-text excerpts were available. PVRIG-PVRL2 affinity of 88 nmol/L in another paper is a citation of earlier work [PMID:30659054]. PVRIG expression on NK cells falls on activation [PMID:33147937]. Two PDB structures exist [DB:PDB 8X6B].","key_references":[{"PMID":"26755705","why":"Identifies CD112 as ligand; Kd, competition with CD226, mouse binding"},{"PMID":"30659054","why":"PVRIG-PVRL2 as non-redundant inhibitory node in T cells"},{"PMID":"33147937","why":"PVRIG blockade enhances NK killing of AML"}],"covers":["LR001921","LR005260"]},"LR009112":{"pair":"NGF -> MAGED1","headline":"Database-asserted only: Reactome lists NGF:p75NTR:NRAGE complexes; no paper supports direct NGF-MAGED1 interaction.","interaction_type":"database-asserted only","direction_and_effect":"No papers were confirmed. Reactome records NGF:p75NTR:NRAGE and NGF:p75NTR:NRAGE:CHE1 complexes [DB:Reactome]; direction not reported in our evidence.","molecular_requirements":"MAGED1 (NRAGE) appears only as a component of an NGF:p75NTR complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Species and experimental system are not reported in our evidence.","localisation_and_range":"NGF is annotated secreted [flag]; Reactome places the complexes at the plasma membrane [DB:Reactome].","caveats":"No verified paper; other judged papers were review only or a different entity. The pair is likely a complex-membership artefact.","key_references":[],"covers":["LR009112"]},"LR001093":{"pair":"NGF -> NGFR","headline":"NGF binding to p75NTR is well recorded in databases, but the two curated papers give only background or indirect evidence.","interaction_type":"direct binding","direction_and_effect":"NGF is annotated as a stimulatory ligand [flag]; UniProt describes NGF as an extracellular ligand for NTRK1 and NGFR [DB:UniProt]. Reactome records NGF homodimer binding to p75NTR and NGF binding to p75NTR inactivating RHOA [DB:Reactome].","molecular_requirements":"UniProt states the NGF homodimer interacts with a single NGFR chain [DB:UniProt]. proNGF additionally uses sortilin as a co-receptor with p75NTR [PMID:14985763]; UniProt describes a SORCS2:NGFR heterodimer binding precursor forms with high affinity and mature NGF with much lower affinity [DB:UniProt].","affinity_potency":[],"species_and_systems":"Both papers used human partners per the curator, read as abstracts only [PMID:14985763][PMID:2157470]. The mouse pair is ortholog-inferred. BioGRID reconstituted complexes and IntAct cross-linking are recorded [DB:BioGRID][DB:IntAct].","localisation_and_range":"NGF is annotated secreted and NGFR transmembrane [flag].","caveats":"The sortilin paper states NGF-p75NTR binding as background and its new data are on proNGF [PMID:14985763]. The 1990 paper shows p75NTR is a low-affinity receptor for both BDNF and NGF, so ligand discrimination is poor [PMID:2157470]. GtoPdb record has no type or action [DB:GtoPdb].","key_references":[{"PMID":"2157470","why":"Cells transfected with low-affinity NGF receptor bind NGF and BDNF"},{"PMID":"14985763","why":"proNGF binds p75NTR with sortilin; NGF-p75NTR stated as background"}],"covers":["LR001093","LR004504"]},"LR004504":{"pair":"NGF -> NGFR","headline":"NGF binding to p75NTR is well recorded in databases, but the two curated papers give only background or indirect evidence.","interaction_type":"direct binding","direction_and_effect":"NGF is annotated as a stimulatory ligand [flag]; UniProt describes NGF as an extracellular ligand for NTRK1 and NGFR [DB:UniProt]. Reactome records NGF homodimer binding to p75NTR and NGF binding to p75NTR inactivating RHOA [DB:Reactome].","molecular_requirements":"UniProt states the NGF homodimer interacts with a single NGFR chain [DB:UniProt]. proNGF additionally uses sortilin as a co-receptor with p75NTR [PMID:14985763]; UniProt describes a SORCS2:NGFR heterodimer binding precursor forms with high affinity and mature NGF with much lower affinity [DB:UniProt].","affinity_potency":[],"species_and_systems":"Both papers used human partners per the curator, read as abstracts only [PMID:14985763][PMID:2157470]. The mouse pair is ortholog-inferred. BioGRID reconstituted complexes and IntAct cross-linking are recorded [DB:BioGRID][DB:IntAct].","localisation_and_range":"NGF is annotated secreted and NGFR transmembrane [flag].","caveats":"The sortilin paper states NGF-p75NTR binding as background and its new data are on proNGF [PMID:14985763]. The 1990 paper shows p75NTR is a low-affinity receptor for both BDNF and NGF, so ligand discrimination is poor [PMID:2157470]. GtoPdb record has no type or action [DB:GtoPdb].","key_references":[{"PMID":"2157470","why":"Cells transfected with low-affinity NGF receptor bind NGF and BDNF"},{"PMID":"14985763","why":"proNGF binds p75NTR with sortilin; NGF-p75NTR stated as background"}],"covers":["LR001093","LR004504"]},"LR006214":{"pair":"NGF -> SORCS2","headline":"Crystal structure shows NGF bound to the SorCS2 beta-propeller in a 2:4 complex; direct binding confirmed by SPR.","interaction_type":"direct binding","direction_and_effect":"NGF dimers bind SorCS2 in a 2:4 (SorCS2:NGF) complex; the curator labels it agonist [PMID:30061605]. UniProt describes a NGFR:SORCS2 heterodimer as receptor for proNGF and proBDNF [DB:UniProt].","molecular_requirements":"Both NGF dimer chains interact exclusively with the top face of a SorCS2 beta-propeller; NGF, proNGF and proBDNF bind at this site [PMID:30061605]. SorCS2 forms cross-braced homodimers; the F630N interface mutation abrogated NGF binding in SPR [PMID:30061605]. UniProt describes the physiological receptor as an NGFR:SORCS2 heterodimer [DB:UniProt].","affinity_potency":[],"species_and_systems":"Soluble SorCS2 ectodomain with NGF; the curator records human ligand and receptor; paper read in full text [PMID:30061605]. The mouse pair is the non-inferred one and the human pair is ortholog-inferred. IntAct SPR record [DB:IntAct].","localisation_and_range":"NGF is annotated secreted [flag]; UniProt places the heterodimer as a receptor for secreted precursors [DB:UniProt].","caveats":"Precursor forms are the physiological ligands according to UniProt [DB:UniProt]; mature NGF binding is shown directly in vitro [PMID:30061605]. Resolution of 3.9 A is modest.","key_references":[{"PMID":"30061605","why":"Crystal structure and SPR of SorCS2-NGF complex"}],"covers":["LR002989","LR006214"]},"LR007105":{"pair":"NGF -> SORT1","headline":"Sortilin is a co-receptor for proNGF, not shown for mature NGF; second support is computational inference only.","interaction_type":"functional only","direction_and_effect":"proNGF forms a signalling complex by simultaneously binding p75NTR and sortilin, with sortilin as co-receptor governing p75NTR-mediated apoptosis [PMID:14985763]. A bladder single-cell study identified NGF-SORT1 as an active fibroblast pathway by inference [PMID:42399658].","molecular_requirements":"Sortilin acts with p75NTR as co-receptor and the ligand is the NGF precursor proNGF [PMID:14985763]; mature NGF is not tested in the curator notes.","affinity_potency":[],"species_and_systems":"Human neuronal cells per the curator; abstract only [PMID:14985763]. Spatial/single-cell human bladder tissue analysis, computational, abstract only [PMID:42399658]. BioGRID and IntAct SPR records exist [DB:BioGRID][DB:IntAct].","localisation_and_range":"NGF annotated secreted [flag].","caveats":"The ligand specificity is proNGF; the curator notes the row records NGF [PMID:14985763]. The second paper is inference from expression, not a binding or functional assay [PMID:42399658]. Another judged paper was abstract-insufficient.","key_references":[{"PMID":"14985763","why":"proNGF binds p75NTR with sortilin to induce apoptosis"},{"PMID":"42399658","why":"NGF-SORT1 inferred active in bladder fibroblasts"}],"covers":["LR007105"]},"LR004513":{"pair":"NLGN1 -> NRXN1","headline":"Well supported trans-synaptic adhesion pair: SPR and affinity chromatography binding plus a functional neurite-outgrowth readout, mostly from abstracts.","interaction_type":"direct binding","direction_and_effect":"Soluble neuroligin-1 binds neurexin-1beta by SPR [PMID:14522992]; neuroligin 1 binds alpha- and beta-neurexins, regulated by splicing, and the beta-only binding variant potently stimulates synapse formation [PMID:16242404]. NLGN1, soluble or membrane-bound, induces neurite outgrowth dependent on NRXN1beta and FGFR1 activation [PMID:22750515].","molecular_requirements":"Splice site B of neuroligin 1 is a master switch for alpha-neurexin binding but leaves beta-neurexin binding largely unaffected; neurexin splice site 4 modulates binding [PMID:16242404]. Neuroligin-1 extracellular domain associates as a dimer, and N-linked glycosylation at position 303 modifies association [PMID:14522992]. Neurite outgrowth also needs FGFR1 [PMID:22750515].","affinity_potency":[],"species_and_systems":"Human recombinant/hippocampal neuron cultures for neurite outgrowth (curator: human) [PMID:22750515]; rat brain proteins for affinity chromatography [PMID:8576240]; other species unspecified. Mouse and human pairs are ortholog-projected.","localisation_and_range":"Neither partner is secreted; both carry transmembrane flags [flag], so this is a membrane-bound, contact-dependent (trans-synaptic) pair. NLGN1 also appears in BioGRID as a reconstituted complex with NRXN1 [DB:BioGRID].","caveats":"All papers except 8576240 were read as abstracts; the 8576240 quote is a browser read flagged as an unverifiable spot-check pending. No affinity values in our evidence. Results depend on splice isoform.","key_references":[{"PMID":"14522992","why":"SPR of soluble neuroligin-1 with neurexin-1beta"},{"PMID":"16242404","why":"Splice-dependent alpha/beta neurexin binding"},{"PMID":"22750515","why":"Functional NLGN1-NRXN1beta neurite outgrowth"}],"covers":["LR001102","LR004513"]},"LR004522":{"pair":"NMB -> GRPR","headline":"NMB is a lower-affinity, full agonist of GRPR; its preferred receptor is NMBR. Supported by rat and human binding and functional data.","interaction_type":"direct binding","direction_and_effect":"NMB acts as an agonist at GRPR: in rat pancreatic acini NMB and bombesin cross-desensitised each other, indicating a shared receptor [PMID:1720612]. At huGRP-R, bombesin Ki was 1.4 +/- 0.2 nM, with NMB 300-fold weaker [PMID:7838118]. GtoPdb lists NMB-GRPR as full agonist [DB:GtoPdb].","molecular_requirements":"Single receptor chain; no co-receptor reported in our evidence.","affinity_potency":[{"value":"IC50 15-50 nM","assay":"competition binding (curator reader note)","system":"human GRPR, Balb 3T3 and HuTu-80 cells","cite":"PMID:21729729"},{"value":"EC50 2 nM","assay":"amylase secretion","system":"rat pancreatic acini","cite":"PMID:1720612"},{"value":"EC50 141 nM","assay":"inositol phosphate production","system":"rat pancreatic acini","cite":"PMID:1720612"},{"value":"pKi 6.36-8.13","assay":"GtoPdb pKi range","system":"curated records","cite":"PMID:7838118"},{"value":"pIC50 7.42-7.52","assay":"GtoPdb pIC50 range","system":"curated records","cite":"PMID:21729729"}],"species_and_systems":"Rat pancreatic acini [PMID:1720612]; human receptor in cells [PMID:7838118][PMID:21729729]. Mouse pair is ortholog-projected, not tested.","localisation_and_range":"NMB is flagged secreted and GRPR transmembrane [flag]; paracrine peptide signalling to a GPCR.","caveats":"NMB prefers NMBR (0.052-0.054 nM, >650-fold higher than for hGRP receptors) [PMID:21729729]; the GRPR interaction is cross-reactive. Rat and human data differ markedly for GRP receptors [PMID:21729729]. The rat study's receptor is not named GRPR in the abstract. Other papers were abstract-insufficient.","key_references":[{"PMID":"21729729","why":"Human GRPR/NMBR competition binding, full text"},{"PMID":"7838118","why":"Cloned human GRPR agonist affinities"},{"PMID":"1720612","why":"Rat acinar shared receptor, EC50s"}],"covers":["LR001111","LR004522"]},"LR004531":{"pair":"NODAL -> ACVR2B","headline":"ACVR2B is a Nodal type II receptor: binding of Xnr1 plus reconstitution, and frog-assay dominant-negative data.","interaction_type":"direct binding","direction_and_effect":"ALK7 and ActRIIB collaborate to confer responsiveness to Xnr1 and Nodal [PMID:11485994]. ActRIIA or ActRIIB can serve as type II receptor with ALK4 in frog animal caps; effect is agonist [PMID:11952836].","molecular_requirements":"ActRIIB needs a type I partner (ALK7, or ALK4 with Cripto); Cripto binds Nodal-related Xnr1 and ALK7, and enhances responses [PMID:11485994]. ACVR2A can substitute for ACVR2B [PMID:11952836]. BioGRID lists a reconstituted complex [DB:BioGRID, PMID:28126904].","affinity_potency":[],"species_and_systems":"Mouse receptors and Nodal, and Xenopus Nodal-related 1 (Xnr1), in reconstitution; frog animal caps. Both papers abstract only. The mouse pair is not ortholog-inferred; the human pair is.","localisation_and_range":"Nodal flagged secreted, ACVR2B transmembrane [flag].","caveats":"The binding statement ('Both receptors can independently bind Xnr1') is for Xenopus Xnr1, not Nodal itself [PMID:11485994]. No affinity reported. The frog paper is dominant-negative evidence only [PMID:11952836].","key_references":[{"PMID":"11485994","why":"ALK7 and ActRIIB bind Xnr1 independently; reconstitution with Nodal"},{"PMID":"11952836","why":"ActRIIA/ActRIIB as Nodal type II receptors"}],"covers":["LR001120","LR004531"]},"LR001129":{"pair":"NPPA -> NPR3","headline":"ANP binds the clearance receptor NPR3 with high affinity; supported by structures, cloning and databases.","interaction_type":"direct binding","direction_and_effect":"Recombinant human ANP C-receptor has high affinity for ANP [PMID:2169733]. UniProt says NPR3 removes the hormone from circulation [DB:UniProt], so it acts as a clearance receptor rather than a signalling one.","molecular_requirements":"NPR-C acts as a dimer binding one hormone molecule (1:2 hormone:receptor) in the structure with CNP [PMID:11533490]; PDB has an ANP-NPR3 structure [DB:PDB 1YK0].","affinity_potency":[{"value":"Kd 6 nM","assay":"binding after transfection of human cDNA","system":"mammalian cells expressing human ANP C-receptor","cite":"PMID:2169733"}],"species_and_systems":"Human receptor in transfected cells [PMID:2169733]; human crystal structures [PMID:11533490]. Mouse pair is projected.","localisation_and_range":"ANP is annotated secreted [flag].","caveats":"Both papers read as abstracts only. PMID:11533490 reports a CNP complex, not ANP, in its abstract; stoichiometry for ANP is from the curator evidence sentence. BioGRID co-crystal record exists [DB:BioGRID].","key_references":[{"PMID":"2169733","why":"Human NPR3 binds ANP with high affinity"},{"PMID":"11533490","why":"Structural basis of natriuretic peptide binding to NPR-C"}],"covers":["LR001129","LR004539"]},"LR004540":{"pair":"NPPB -> NPR1","headline":"BNP activates NPR1 (GC-A) nearly as potently as ANP; abstract-level and mouse in vivo support.","interaction_type":"functional only","direction_and_effect":"Via GC-A, BNP is nearly as potent as ANP and much more potent than CNP in cGMP production [PMID:1309330]. Supraphysiological ANP and BNP lowered systolic blood pressure by about 30 mm Hg in normotensive mice [PMID:39261724].","molecular_requirements":"NPR1 is a membrane-bound guanylate cyclase producing cGMP on agonism [PMID:39261724]; no subunit requirement reported.","affinity_potency":[],"species_and_systems":"Human/bovine/rat preparations [PMID:1309330]; BNP tested in mice (ortholog) [PMID:39261724]. UniProt notes BNP binding NPR1 [DB:UniProt].","localisation_and_range":"BNP is annotated secreted [flag].","caveats":"PMID:1309330 was read as abstract only and notes marked species differences, especially for BNP. PMID:39261724 is mainly about an agonist antibody; BNP is a comparator.","key_references":[{"PMID":"1309330","why":"Relative potency of ANP, BNP, CNP at GC-A"},{"PMID":"39261724","why":"In vivo BP effects of ANP/BNP via NPR1 in mice"}],"covers":["LR001130","LR004540"]},"LR006223":{"pair":"NPTX1 -> NPTXR","headline":"NPTXR is enriched on NP1 affinity columns; one abstract-level paper, no databases.","interaction_type":"direct binding","direction_and_effect":"NPR (NPTXR) was enriched by affinity chromatography on columns of NP1, NP2 and a toxin [PMID:9261167]. Direction or effect not reported in our evidence.","molecular_requirements":"NPTXR has a putative N-terminal transmembrane domain and is glycosylated; NPR shares 49% identity with NP1 [PMID:9261167].","affinity_potency":[],"species_and_systems":"Affinity chromatography; species not stated in dossier [PMID:9261167]. Both pairs ortholog-inferred.","localisation_and_range":"NPTXR is a putative integral membrane pentraxin [PMID:9261167]; NPTX1 annotated secreted [flag].","caveats":"Single abstract-only paper; pulldown shows association, not affinity. Pentraxin family paralogs complicate interpretation.","key_references":[{"PMID":"9261167","why":"Identification of NPR as NP1-binding protein"}],"covers":["LR002999","LR006223"]},"LR001138":{"pair":"NPW -> NPBWR1","headline":"NPW binds and activates NPBWR1 (GPR7) at nanomolar doses; four confirmed binding/activation records, abstract level.","interaction_type":"direct binding","direction_and_effect":"NPW is an agonist of NPBWR1. Synthetic NPW23 and NPW30 activated and bound GPR7 and GPR8 at similar effective doses [PMID:12130646]; binding with low nanomolar affinity to GPR7 and GPR8 in CHO-K1 cells [PMID:12401809]; GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Single receptor chain; both NPW23 and NPW30 mature forms act [PMID:12130646]. No co-receptor reported.","affinity_potency":[{"value":"pIC50 10.0","assay":"affinity recorded by curators (receptor row not specified in the dossier)","system":"CHO, human receptors, porcine-purified ligand","cite":"PMID:12130646"}],"species_and_systems":"Human receptors in CHO cells; ligand purified from porcine hypothalamus in the first paper, with rat in vivo feeding effects [PMID:12130646]; human peptides in [PMID:12401809]. Mouse pair is projected from human.","localisation_and_range":"NPW is flagged secreted, not transmembrane; NPBWR1 transmembrane [flag]. Neuropeptide acting at a central receptor, paracrine/neuroendocrine, is an inference from flags only.","caveats":"All papers were read as abstracts. NPW is not selective between GPR7 and GPR8 [PMID:12130646]. The pIC50 is a curator-recorded value and is not stated in the abstract.","key_references":[{"PMID":"12130646","why":"Purification of NPW and activation of GPR7/GPR8"},{"PMID":"12401809","why":"Low nanomolar binding of L8/L8C to GPR7 and GPR8"}],"covers":["LR001138","LR004548"]},"LR001147":{"pair":"NRG1 -> ERBB3","headline":"NRG1 binds ERBB3 directly with nanomolar affinity and activates it, usually with ERBB2 as partner; well supported.","interaction_type":"direct binding","direction_and_effect":"Agonist: heregulin activates ERBB3 signalling in cells, and in breast cancer cells HRG stimulation led MTK1 to associate with activated HER3 [PMID:24036211]. ERBB3 alone gives little or no phosphorylation response; co-expression with erbB2 gave higher-affinity binding and signalling [PMID:7514177].","molecular_requirements":"Ligand binds the ERBB3 extracellular domain I-II [PMID:11555649]. ERBB3 needs a partner for signalling: ErbB-1 or ErbB-2 transactivate it, and neither NDF isoform was active on ErbB-3 alone [PMID:8702572]. Ligand bivalence: a high-affinity site binds ErbB-3 and a low-affinity site binds ErbB-2 [PMID:9305636]. Full-length NDF beta 2 bound sHer3 roughly 1000-fold more tightly than sHer2 [PMID:7592681].","affinity_potency":[{"value":"Kd 26 +/- 9 nM","assay":"native gels, light scattering, sedimentation equilibrium","system":"NDF beta 2 with soluble Her3 extracellular domain","cite":"PMID:7592681"},{"value":"68 nM","assay":"HER3-ECD(I-II) binding to hrg","system":"recombinant HER3 domains I-II","cite":"PMID:11555649"},{"value":"pKd 8.89","assay":"heterodimer-formation binding assay (database value)","system":"NDF/neuregulin","cite":"PMID:9305636"},{"value":"pIC50 9.26","assay":"soluble receptor-ligand binding","system":"egf domains on ErbB receptors","cite":"PMID:10214951"}],"species_and_systems":"Human ligand and receptor; recombinant soluble domains, transfected cells, MCF-7 and other breast cancer cells. The mouse pair is projected from human evidence.","localisation_and_range":"NRG1 is flagged secreted and transmembrane [flag]; single-molecule work on live MCF-7 cell surfaces showed heregulin binding at the cell surface [PMID:22891299].","caveats":"Most papers were abstract only. Single-molecule data show negative cooperativity and apparent low- and high-affinity sites [PMID:22891299]. PMID 10995872 and 24036211 are functional readouts that do not isolate ERBB3 binding. PMID 10348342 was browser-read with spot-check pending. Quoted pKd and pIC50 values come from the curated records.","key_references":[{"PMID":"7592681","why":"Kd 26 nM NDF-sHer3, weak sHer2 binding"},{"PMID":"7514177","why":"erbB2 co-expression reconstitutes high-affinity receptor"},{"PMID":"11555649","why":"HER3 domains I-II bind hrg, 68 nM"}],"covers":["LR001147","LR004556"]},"LR006232":{"pair":"NRG3 -> EGFR","headline":"NRG3 activates EGFR in transfected cells, from a single abstract-level 1998 paper.","interaction_type":"functional only","direction_and_effect":"Recombinant NRG-3 EGF-like domain activated EGF receptor (erbB1) when expressed individually, an agonist effect [PMID:9772300].","molecular_requirements":"EGFR acted alone; erbB2 and erbB3 were activated only when expressed together [PMID:9772300].","affinity_potency":[],"species_and_systems":"Human breast cancer cells and 32D cells transfected with erbB family members; recombinant E. coli-made domain [PMID:9772300]. Mouse pair is projected from human.","localisation_and_range":"Annotated secreted and transmembrane [flag]; not tested in the paper.","caveats":"Single paper, abstract only. Activation was shown, not binding; no affinity reported. NRG3 is better known here for ErbB4 (see NRG3 -> ERBB4), so EGFR is a secondary receptor in our evidence.","key_references":[{"PMID":"9772300","why":"NRG-3 activates EGFR and other erbB members"}],"covers":["LR003008","LR006232"]},"LR012433":{"pair":"NRP1 -> FLT4:KDR","headline":"NRP1 with FLT4:KDR rests on database records that concern KDR and FLT1, not FLT4.","interaction_type":"database-asserted only","direction_and_effect":"Curated effect is Stimulatory, but no paper is judged [DB:BioGRID].","molecular_requirements":"Records list NRP1-KDR [DB:BioGRID][DB:IntAct]; Reactome describes NRP-1 with VEGF165 and VEGFR1 [DB:Reactome]. No record names FLT4, so the FLT4 subunit is unsupported.","affinity_potency":[],"species_and_systems":"Human; affinity capture-western and coimmunoprecipitation records [DB:BioGRID][DB:IntAct].","localisation_and_range":"NRP1 flagged secreted, receptor and transmembrane [flag].","caveats":"No papers judged (3 pending). Database-only and not curator-verified. Direction not established.","key_references":[],"covers":["LR012433"]},"LR006241":{"pair":"NRXN1 -> DAG1","headline":"Neurexins bind dystroglycan in a tight, glycosylation-dependent interaction; shown for neurexin class, curator assigned NRXN1.","interaction_type":"direct binding","direction_and_effect":"Alpha- and beta-neurexins were identified as neuronal dystroglycan receptors; dystroglycan binds a subset of neurexin LNS domains [PMID:11470830]. Reactome lists a Dystroglycan:NRXN1 complex [DB:Reactome].","molecular_requirements":"Binding requires glycosylation of dystroglycan, is regulated by alternative splicing of neurexins, and alpha-latrotoxin competes for the site [PMID:11470830].","affinity_potency":[],"species_and_systems":"Affinity chromatography from brain extract; species not stated in the dossier. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"Dystroglycan is flagged secreted and transmembrane [flag]; NRXN1 is transmembrane [flag].","caveats":"The paper's abstract names neurexins generally; the curator note says NRXN1 is recorded as the canonical member, not directly shown. No affinity value in our evidence.","key_references":[{"PMID":"11470830","why":"neurexins identified as neuronal dystroglycan receptors"}],"covers":["LR003017","LR006241"]},"LR003019":{"pair":"NRXN1 -> LRRTM2","headline":"Well supported: LRRTM2 binds neurexins lacking the SS4 insert by affinity chromatography and cell binding; confirmed again in 2024.","interaction_type":"direct binding","direction_and_effect":"Neurexins were identified as LRRTM2 ligands; binding can produce cell-adhesion junctions and recombinant neurexin-1beta blocks LRRTM2-induced presynaptic differentiation [PMID:20064387]. Nrxn1beta-Fc bound cells expressing AP-LRRTM2 [PMID:39394199].","molecular_requirements":"LRRTM2 binds only neurexins lacking an insert at splice site 4 [PMID:20064387]. A mutation in the LRRTM2 C-terminal cap (EQ) abolished Nrxn1beta-Fc binding, while DT/AA reduced it by 50% [PMID:39394199].","affinity_potency":[],"species_and_systems":"Rat brain affinity chromatography and HEK293 cell binding [PMID:20064387]; 39394199 used human-labelled cell binding with a mouse cKO model. Human pair is ortholog-inferred.","localisation_and_range":"Both transmembrane [flag]; trans-synaptic, contact-dependent.","caveats":"20064387 was read as abstract plus excerpts; no affinity value in our evidence.","key_references":[{"PMID":"20064387","why":"identifies neurexins as LRRTM2 ligands, SS4-dependent"},{"PMID":"39394199","why":"Nrxn1beta-Fc binding to LRRTM2 and its mutational dependence"}],"covers":["LR003019","LR006243"]},"LR006250":{"pair":"NRXN2 -> DAG1","headline":"Direct, tight Ca2+-dependent binding of the neurexin-2alpha second LNS domain to dystroglycan, from full text.","interaction_type":"direct binding","direction_and_effect":"The second LNS domain of all three alpha-neurexins (neurexin 1alpha, 2alpha, and 3alpha) formed tight Ca2+-dependent complexes with dystroglycan [PMID:11470830].","molecular_requirements":"Only alpha-neurexins containing the second or sixth LNS domain captured dystroglycan, and a single isolated LNS domain fully bound; binding requires dystroglycan glycosylation and is regulated by neurexin splicing [PMID:11470830].","affinity_potency":[],"species_and_systems":"Ig-fusion affinity chromatography with rat brain extract (curator note); human and mouse pairs are ortholog-inferred.","localisation_and_range":"DAG1 is flagged secreted and transmembrane; NRXN2 is neither flagged as secreted nor transmembrane in the dossier [flag].","caveats":"Evidence is for the alpha-neurexin NRXN2 LNS domain; beta-neurexin NRXN2 not specified. One review_only row was excluded.","key_references":[{"PMID":"11470830","why":"second LNS domain of neurexin-2alpha binds dystroglycan"}],"covers":["LR003026","LR006250"]},"LR003028":{"pair":"NRXN2 -> NLGN2","headline":"Binding of NRXN2 to NLGN2 is used as a readout in cell binding assays; support is abstract-only and indirect.","interaction_type":"direct binding","direction_and_effect":"Truncated NRXN proteins fail to bind LRRTM2 or NLGN2 in cell binding assays, implying wild-type binding [PMID:21424692]. BioGRID lists a reconstituted complex [DB:BioGRID].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human experiments (curator-assigned species) with cell binding assays and neuron co-culture; abstract only [PMID:21424692]. Mouse pair is listed too.","localisation_and_range":"Both partners flagged transmembrane, non-secreted [flag].","caveats":"The paper is a resequencing study of ASD/SCZ/ID cohorts; NLGN2 binding is a functional readout of mutants, not a binding characterisation. Read as abstract only [PMID:21424692].","key_references":[{"PMID":"21424692","why":"Truncating NRXN mutations lose NLGN2 and LRRTM2 binding"}],"covers":["LR003028","LR006252"]},"LR001156":{"pair":"NTF3 -> NGFR","headline":"Mature NT-3 binding to p75NTR is only indirectly supported; the confirmed paper concerns proNT-3 requiring p75NTR.","interaction_type":"functional only","direction_and_effect":"ProNT-3 required p75NTR to promote cell cycle exit of cerebellar granule progenitors; in cells lacking p75NTR it could not reduce Shh-induced BrdU incorporation [PMID:27434667]. Mature NT3 (100 ng/ml) had no effect on proliferation [PMID:27434667]. UniProt describes NGFR as a low affinity receptor binding NGF, BDNF, NTF3 and NTF4 [DB:UniProt].","molecular_requirements":"SorCS2 was the sortilin family co-receptor detected in the EGL; UniProt describes a heterodimer with SORCS2 binding precursor NTF3 with high affinity [PMID:27434667][DB:UniProt].","affinity_potency":[],"species_and_systems":"Cultured rat/mouse cerebellar granule progenitors, WT versus Ngfr-/- [PMID:27434667]. Human pair is ortholog-inferred; mouse pair is direct.","localisation_and_range":"NTF3 flagged secreted, NGFR transmembrane [flag]: secreted ligand acting on a cell-surface receptor.","caveats":"No direct binding assay in this paper; the effect is of the precursor, not mature NT-3. BioGRID reports affinity capture-western [DB:BioGRID]; GtoPdb record has no action or affinity [DB:GtoPdb].","key_references":[{"PMID":"27434667","why":"proNT-3 acts via p75NTR on granule progenitors"}],"covers":["LR001156","LR004565"]},"LR001165":{"pair":"NTN1 -> UNC5A","headline":"Netrin-1 binds UNC5A: netrin-binding evidence from 1997 and a functional stroke paper, both read as abstracts.","interaction_type":"direct binding","direction_and_effect":"UNC5 homologues were shown to be netrin-binding proteins, supporting a netrin receptor role [PMID:9126742]. In stroke models, netrin-1 signalling in microglia ran mainly via UNC5a and shifted microglia towards an anti-inflammatory M2-like state [PMID:37388740].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"The 1997 work used cloned vertebrate UNC-5 homologues [PMID:9126742]; the stroke work used human patients, rat and mouse models [PMID:37388740]. A BioGRID reconstituted complex and Reactome binding reactions are also recorded [DB:BioGRID][DB:Reactome]. Mouse pair is ortholog-inferred.","localisation_and_range":"Netrin-1 is secreted and UNC5A is not secreted [flag].","caveats":"The 1997 abstract refers to two UNC-5 homologues and does not name UNC5A specifically. Both papers read as abstracts only. The stroke abstract is truncated and mostly functional.","key_references":[{"PMID":"9126742","why":"UNC-5 homologues are netrin-binding proteins"},{"PMID":"37388740","why":"UNC5a-mediated netrin-1 signalling in microglia in stroke"}],"covers":["LR001165","LR004574"]},"LR003037":{"pair":"NTN3 -> UNC5B","headline":"Murine netrin-3 binds the UNC5 family in one abstract-only paper; UNC5B is not named individually.","interaction_type":"direct binding","direction_and_effect":"Murine netrin-3 binds the UNC5 family (UNC5H1, UNC5H2 and UNC5H3) with higher affinity than it binds DCC [PMID:10366627].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Murine netrin-3 protein; human pair is ortholog-inferred and the mouse pair too [PMID:10366627].","localisation_and_range":"Netrin-3 is flagged secreted and the receptor transmembrane [flag].","caveats":"Abstract only. The evidence sentence names UNC5H1-3, and the mapping to this specific receptor is not stated in the abstract. No numbers are reported.","key_references":[{"PMID":"10366627","why":"Murine netrin-3 binds UNC5 family receptors"}],"covers":["LR003037","LR006261"]},"LR001930":{"pair":"NTRK3 -> PTPRS","headline":"TrkC (NTRK3) binds PTPsigma directly in trans with high affinity; one abstract-only paper plus database records support it.","interaction_type":"direct binding","direction_and_effect":"Postsynaptic TrkC binds axonal PTPsigma in trans, neurotensin-independent, and the pair acts as a bidirectional synaptic organizer: PTPsigma triggers TrkC-mediated clustering of postsynaptic molecules and TrkC triggers presynaptic differentiation [PMID:21262467]. A TrkC-neutralising antibody that blocks the interaction and TrkC knockdown impair glutamatergic synapse formation [PMID:21262467].","molecular_requirements":"All TrkC isoforms, including noncatalytic ones, bind PTPsigma, but TrkA and TrkB do not [PMID:21262467]. Kinase activity is not needed for this adhesion role (noncatalytic isoforms act) [PMID:21262467]. Reactome lists a PTPRS:NTRK3 complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Hippocampal neuron-fibroblast coculture and in vivo knockdown; the abstract does not name the species [PMID:21262467]. The human pair is ortholog-inferred; the mouse record is the direct one.","localisation_and_range":"Membrane-bound on both sides, acting by trans (contact) binding at synapses [PMID:21262467]. Note the PTPRS entity carries a secreted flag [flag], but the paper describes an axonal membrane protein.","caveats":"Only one paper was judged and it was read as an abstract. No affinity value is reported in our evidence beyond 'high-affinity'. BioGRID has an affinity-capture-western record and UniProt notes an interaction [DB:BioGRID][DB:UniProt]. Ligand/receptor roles are conventional here, since the interaction is symmetric.","key_references":[{"PMID":"21262467","why":"TrkC-PTPsigma trans binding and synaptic organizing function"}],"covers":["LR001930","LR005269"]},"LR001174":{"pair":"NTS -> NTSR1","headline":"Neurotensin is a well-established agonist of NTSR1 with nM-range binding and many confirming papers; large NTS forms are also active.","interaction_type":"direct binding","direction_and_effect":"Neurotensin binds and activates NTSR1 as an agonist: phosphoinositide hydrolysis in CHO cells with rat receptor, pertussis-toxin-insensitive [PMID:1331689]; activation of the yeast pheromone pathway by human NTR1 [PMID:11559354]. Neurotensin binding triggers receptor internalisation [PMID:11801734]. GtoPdb records a full agonist [DB:GtoPdb].","molecular_requirements":"Single receptor chain, a seven-transmembrane GPCR [PMID:1694443]. The third outer loop is the binding site for neurotensin and analogs, and one residue (hTyr339 vs rPhe344) sets species selectivity for an analog [PMID:10930533]. Large NT and large neuromedin N bind and activate human NTS1 with potencies about 10 times lower than the small peptides but are far less sensitive to degradation [PMID:11811984]. An arginylated NT (porcine) acts as agonist on NTR1 [PMID:16087676].","affinity_potency":[{"value":"Kd 3.2 nM","assay":"[125I-Tyr3]NT binding","system":"human NTR1 in yeast","cite":"PMID:11559354"},{"value":"Kd 0.45 nM","assay":"Scatchard, [3H]neurotensin binding","system":"rat NTR1 in CHO cells","cite":"PMID:1331689"},{"value":"pIC50 7.4","assay":"binding/pharmacology of large NT","system":"human NTS1 (COS cells / HT29)","cite":"PMID:11811984"}],"species_and_systems":"Experiments span human (yeast, COS, HT29), rat (CHO, oocytes) and mouse/human/rat receptors [PMID:11559354][PMID:1331689][PMID:11801734]; the mouse pair is ortholog-inferred. Mostly recombinant cells. GtoPdb lists pKi 8.3 to 9.7 [DB:GtoPdb]. Structures exist (PDB 2LYW, 6UP7) [DB:PDB 2LYW][DB:PDB 6UP7].","localisation_and_range":"Neuropeptide flagged secreted [flag], so paracrine or endocrine action on a membrane GPCR.","caveats":"All papers were abstract-only reads. Some confirmed papers are indirect for this pair: PMID:11801734 is about receptor recycling (the NTR2 recycles, human NTR2 and rat NTR1 do not) and PMID:1694443 is the receptor cloning paper without a stated affinity. PMID:16087676 tested a modified peptide.","key_references":[{"PMID":"1331689","why":"Rat NTR1 binding Kd and phospholipase C activation"},{"PMID":"11559354","why":"Human NTR1 binding Kd and agonist signalling in yeast"},{"PMID":"11811984","why":"Large NTS forms bind and activate human NTS1"}],"covers":["LR001174","LR004583"]},"LR003046":{"pair":"OMG -> PTPRS","headline":"OMG binds PTPRS by SPR in the micromolar range in one full-text paper; no other evidence.","interaction_type":"direct binding","direction_and_effect":"OMG is the ligand and PTPRS the receptor. SPR showed micromolar-range binding of OMG to all three R2A RPTPs including PTPRS [PMID:36178190]. Functional effect is not reported in our evidence.","molecular_requirements":"PTPRS ectodomain alone; no co-receptor requirement reported in our evidence.","affinity_potency":[{"value":"micromolar range","assay":"SPR, OMG vs RPTP ectodomains","system":"recombinant human proteins","cite":"PMID:36178190"}],"species_and_systems":"Human OMG and PTPRS recombinant ectodomains, SPR [PMID:36178190]. Mouse pair is projected from human.","localisation_and_range":"OMG is flagged non-secreted [flag]; the paper treats it as a secreted ligand used as a multimerised bait, so range (contact versus diffusible) is not settled in our evidence. PTPRS carries a secreted flag as well as transmembrane and receptor flags [flag], so a shed form is possible but not shown in our evidence.","caveats":"Single paper. The PTPRS interaction came from phylogenetic homology analysis, not the screen [PMID:36178190]. No exact Kd given. No database records.","key_references":[{"PMID":"36178190","why":"SPR validation of OMG binding to R2A RPTPs"}],"covers":["LR003046","LR006270"]},"LR001183":{"pair":"OMG -> RTN4R","headline":"OMG is a well-supported ligand of RTN4R (NgR); binding and function shown, plus database support.","interaction_type":"direct binding","direction_and_effect":"OMgp was identified as a high-affinity NgR-binding protein from an expression library screen; removing NgR makes axons insensitive to OMgp and adding NgR confers responsiveness, so OMgp acts as an agonist and the output is inhibition of neurite outgrowth [PMID:12068310]. Binding of OMgp to NgR-expressing cells is also reported, with selectivity for NgR over NgR2 and NgR3 [PMID:12839991]. UniProt lists RTN4R as receptor for OMG [DB:UniProt].","molecular_requirements":"NgR is GPI-anchored and signals through a co-receptor complex (p75/LINGO-1) rather than autonomously, per curator notes [PMID:12068310]. The abstract of [PMID:12839991] states ligand binding needs the whole LRR region of NgR.","affinity_potency":[{"value":"high-affinity (no value given)","assay":"expression library screen binding","system":"human","cite":"PMID:12068310"}],"species_and_systems":"Curator-labelled human ligand and receptor; both read as abstracts only [PMID:12068310][PMID:12839991]. Both human and mouse pairs are ortholog-inferred.","localisation_and_range":"OMG is flagged non-secreted and RTN4R transmembrane [flag]; OMgp is described as a GPI-anchored myelin protein, so action is by cell contact [PMID:12068310].","caveats":"Both papers read only as abstracts; the second was browser-read with an unverified quote. No numeric affinity reported. NgR2 and NgR3 do not bind OMgp [PMID:12839991]. BioGRID lists a reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"12068310","why":"Identifies NgR as OMgp receptor, necessity and sufficiency"},{"PMID":"12839991","why":"Ligand-binding region and NgR selectivity"}],"covers":["LR001183","LR004592"]},"LR001192":{"pair":"OXT -> AVPR2","headline":"No curator-verified evidence that oxytocin acts on AVPR2; support is a database assertion and the one paper checked was negative.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists oxytocin as a full agonist at AVPR2 [DB:GtoPdb]. The one paper judged did not test oxytocin at V2; the stated selectivity is of its own antagonist compound [PMID:12660315].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experimental system confirmed for this pair in our evidence.","localisation_and_range":"OXT is flagged secreted; AVPR2 is a transmembrane receptor [flag].","caveats":"Verified negative for PMID:12660315 (pair_absent). Five other papers were judged a different entity and two were abstract_insufficient. UniProt notes OXT interacts with AVPR1A, AVPR1B and AVPR2 [DB:UniProt]. GtoPdb pKi range 5.4 to 6.8 [DB:GtoPdb] is low affinity.","key_references":[],"covers":["LR001192","LR004601"]},"LR003082":{"pair":"PCDHGC3 -> PCDHGC3","headline":"Mouse gammaC3 shows homophilic binding in K562 assays across two papers; one is abstract-only.","interaction_type":"direct binding","direction_and_effect":"Homophilic interaction of the C-type isoform gammaC3 [PMID:25171406]; strictly homophilic trans interaction across seven gamma isoforms including C3 [PMID:20679223]. No agonist/antagonist effect reported.","molecular_requirements":"gammaC3 was detected at the cell surface when tagged [PMID:25171406]. Specificity is mediated by EC2-EC3 and gamma-Pcdhs form cis multimers [PMID:20679223].","affinity_potency":[],"species_and_systems":"Mouse isoforms in K562 aggregation assays [PMID:25171406][PMID:20679223]; human pair ortholog-inferred.","localisation_and_range":"Membrane protein (not secreted per annotation flags) [flag]; contact-dependent.","caveats":"Isoform pairs sharing 91-97% identity in EC2-EC3 (including gammaA8-gammaA9) do not cross-react, so paralogue substitution is invalid for this family and results do not transfer to unnamed isoforms [PMID:25171406]. Human pair is projected from mouse by orthology. The PNAS paper is abstract-only with an unverified browser-read quote [PMID:20679223].","key_references":[{"PMID":"25171406","why":"Names gammaC3 as homophilic and surface-detected."},{"PMID":"20679223","why":"Strictly homophilic trans interaction of gamma-Pcdh isoforms incl. C3."}],"covers":["LR003082","LR006305"]},"LR004612":{"pair":"PDYN -> OPRM1","headline":"PDYN -> OPRM1 is asserted by GtoPdb and Reactome only; no curated paper was verified.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb records Agonist, Full agonist [DB:GtoPdb]. Reactome has an Opioid:MOR complex and an opioid-binds-MOR reaction [DB:Reactome].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"PDYN flagged secreted; OPRM1 transmembrane [flag].","caveats":"Ten papers were abstract-insufficient and two were a different entity; none verified. The Reactome records concern generic opioid, not specifically PDYN.","key_references":[],"covers":["LR001203","LR004612"]},"LR006313":{"pair":"PECAM1 -> CD177","headline":"PECAM1 binds CD177 heterophilically; SPR and neutrophil transmigration blocking support it.","interaction_type":"direct binding","direction_and_effect":"CD177 was identified as a PECAM-1 binding partner by flow cytometry and immunoprecipitation; SPR confirmed a cation-dependent, specific interaction with the heterophilic domains of PECAM-1 [PMID:17580308]. Antibodies to CD177 or PECAM-1 domain 6 inhibited adhesion of CD177-expressing U937 cells and human neutrophil transendothelial migration [PMID:17580308].","molecular_requirements":"Cations are needed and PECAM-1 domain 6 is involved [PMID:17580308].","affinity_potency":[],"species_and_systems":"Human proteins and cells (U937 transfectants, human neutrophils); abstract only [PMID:17580308]. IntAct solid phase assay and Reactome binding records exist [DB:IntAct][DB:Reactome].","localisation_and_range":"Both membrane proteins; cell-cell (juxtacrine) adhesion between endothelium and neutrophils [PMID:17580308]. The CD177 secreted flag is an annotation flag [flag].","caveats":"Abstract only; no affinity in our evidence. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"17580308","why":"SPR and adhesion/transmigration data for PECAM-1/CD177"}],"covers":["LR003090","LR006313"]},"LR003091":{"pair":"PECAM1 -> ITGAV","headline":"CD31 is a ligand for integrin alpha v beta 3 in human leukocyte adhesion and precipitation experiments.","interaction_type":"direct binding","direction_and_effect":"Soluble recombinant CD31 supports leukocyte adhesion through its second Ig-like domain, blocked by alpha v beta 3-specific antibodies, and precipitated alpha v beta 3 from cell lysates [PMID:7542249]. Reactome has an integrin alphaVbeta3:PECAM1 complex [DB:Reactome].","molecular_requirements":"The receptor is the alpha v beta 3 heterodimer; ITGAV is one chain, so the beta3 chain is also needed [PMID:7542249]. CD31 Ig domain 2 mediates binding [PMID:7542249].","affinity_potency":[],"species_and_systems":"Human leukocytes and LAK cell lysates; abstract and some full text [PMID:7542249]. BioGRID lists only co-localization with ITGB3 [DB:BioGRID].","localisation_and_range":"PECAM1 is a membrane protein [flag]; used as soluble recombinant in the assay, natural interaction is cell-surface contact [PMID:7542249].","caveats":"No affinity in our evidence. Human pair is ortholog-inferred. ITGAV alone is not shown to bind.","key_references":[{"PMID":"7542249","why":"CD31 binds integrin alpha v beta 3 in adhesion and precipitation assays"}],"covers":["LR003091","LR006314"]},"LR006322":{"pair":"PIANP -> PILRA","headline":"PIANP binds PILRA-Ig on transfected cells and stimulates PILRA reporter cells; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"PILR-alpha-Ig fusion protein bound PANP-transfected cells, and the transfectants stimulated PILR-alpha reporter cells [PMID:21241660]. PILR-alpha is described as an immune inhibitory receptor with an ITIM [PMID:21241660]. Reactome also lists PILRA binding PIANP [DB:Reactome R-HSA-8862090].","molecular_requirements":"Specific O-glycan structures on PANP are required for PILR recognition [PMID:21241660]. Complex partners or chains: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species of the cells and constructs: not reported in our evidence (abstract only) [PMID:21241660]. PANP transcription was mainly in neural tissues [PMID:21241660]. IntAct lists a FACS-based record [DB:IntAct Q9UKJ1-Q8IYJ0].","localisation_and_range":"PIANP is annotated as not secreted, so likely membrane-bound and juxtacrine [flag]; PILRA carries secreted, receptor and transmembrane flags [flag].","caveats":"Only one paper, read as abstract; no affinity. Reactome record groups PILRA with other ligands (COLLEC12 trimer, NPDC1, CLEC4G) [DB:Reactome R-HSA-8862090].","key_references":[{"PMID":"21241660","why":"PANP as O-glycosylated PILR-alpha ligand: Ig-binding and reporter assays"}],"covers":["LR003100","LR006322"]},"LR004621":{"pair":"PIP -> CD4","headline":"Secreted PIP (gp17) binds CD4; recombinant gp17-Ig binding and epitope mapping, supported by one abstract-only paper and BioGRID.","interaction_type":"direct binding","direction_and_effect":"gp17 (PIP), secreted from human seminal vesicles, binds CD4 with high affinity per the authors' earlier work, and gp17-Ig fusion showed binding affinity similar to native gp17 [PMID:10820003]. Previously reported inhibition of CD4/TCR-induced T lymphocyte apoptosis is stated as the authors' earlier finding [PMID:10820003]. BioGRID lists a reconstituted complex [DB:BioGRID 287024].","molecular_requirements":"Three residues in the carboxy-terminal region of gp17 form the major CD4-binding domain; two CD4-binding regions were mapped by overlapping peptides and mutagenesis [PMID:10820003].","affinity_potency":[],"species_and_systems":"Human ligand and human receptor; recombinant gp17-Ig (gp17 fused to human IgG1 Fc) [PMID:10820003]. Mouse pair is projected from human.","localisation_and_range":"Secreted, from the PIP secreted flag [flag] and the paper describing a secreted factor from seminal plasma [PMID:10820003].","caveats":"Abstract only; no numeric affinity in our evidence. The paper is about the gp17 binding site; the primary binding result is from earlier work cited in the abstract [PMID:10820003].","key_references":[{"PMID":"10820003","why":"Mapping the CD4-binding domain of gp17 (PIP)"}],"covers":["LR001218","LR004621"]},"LR001219":{"pair":"PLA2G10 -> PLA2R1","headline":"Mouse sPLA2-X binds mouse PLA2R in two abstract-only papers; human pair projected from mouse.","interaction_type":"direct binding","direction_and_effect":"sPLA2-X bound recombinant PLA2R expressed in COS-7 cells, and specific binding in mouse lung membranes was abolished by PLA2R deficiency [PMID:10922494]. Mature mouse sPLA2-X was a high-affinity ligand for native and recombinant mouse PLA2R [PMID:11019817]. Receptor-mediated signalling effect: not reported in our evidence.","molecular_requirements":"Cross-linking gave a binding-site size of 180 kDa, similar to PLA2R [PMID:10922494]. Mature form was used for binding in [PMID:11019817]; pro-form propeptide removal is needed for optimal enzyme activity [PMID:11019817].","affinity_potency":[],"species_and_systems":"Mouse ligand and mouse receptor: MC3T3-E1 cells, COS-7 recombinant, mouse lung membranes, spleen cells [PMID:10922494][PMID:11019817]. Human is ortholog-inferred.","localisation_and_range":"Secreted, per PLA2G10 secreted flag [flag].","caveats":"Numeric affinity not reported in our evidence. Arachidonic-acid release by sPLA2-X was not different between wild-type and PLA2R-deficient spleen cells, so enzymatic and receptor-binding functions are separable [PMID:11019817]. Human experimental evidence: none.","key_references":[{"PMID":"10922494","why":"sPLA2-X binds PLA2R in COS-7 and mouse lung membranes, lost in PLA2R-deficient mice"},{"PMID":"11019817","why":"Mature sPLA2-X is a high-affinity ligand for native and recombinant mouse PLA2R"}],"covers":["LR001219","LR004622"]},"LR003109":{"pair":"PLAUR -> IGF2R","headline":"Direct binding of purified uPAR to IGF2R (CIMPR) at micromolar affinity, mainly directing uPAR to lysosomes.","interaction_type":"direct binding","direction_and_effect":"Purified uPAR bound the cation-independent M6P/IGF2R but not the cation-dependent M6P receptor; wild-type CIMPR directed uPAR to lysosomes [PMID:9566979]. The record labels this agonist, but the role shown is uPAR disposal; signalling not reported.","molecular_requirements":"Binding involves uPAR domains DII+DIII, not the GPI anchor, at CIMPR sites distinct from mannose 6-phosphate/IGF-II sites; binding was not perturbed by uPA [PMID:9566979].","affinity_potency":[{"value":"Kd ~1 uM (0.9-1.3 uM in five separate experiments)","assay":"BIAcore real-time interaction analysis","system":"CIMPR from FCS binding immobilised baculovirus uPAR","cite":"PMID:9566979"}],"species_and_systems":"Human uPAR from U937/HeLa cells; murine uPAR also bound CIMPR in column assays; transfected cells for localisation [PMID:9566979]. Human pair is itself ortholog-inferred.","localisation_and_range":"Both partners carry transmembrane flags [flag]; uPAR is GPI-anchored in the paper's terms [PMID:9566979].","caveats":"Single paper (full text read). BIAcore stoichiometry was 0.1 mol CIMPR per mol uPAR [PMID:9566979]. Evidence concerns disposal rather than classic signalling.","key_references":[{"PMID":"9566979","why":"binding, affinity and lysosomal targeting"}],"covers":["LR003109","LR006330"]},"LR006331":{"pair":"PLAUR -> ITGA4","headline":"Direct cell-based binding of soluble uPAR to alpha4 (ITGA4) integrin chain in one paper; no affinity.","interaction_type":"direct binding","direction_and_effect":"Soluble uPAR (suPAR D2D3) bound integrin-transfected CHO cells in a cation-dependent manner, blocked by anti-integrin and anti-uPAR antibodies [PMID:11053440]. It acts as a ligand, signalling consequence not reported in our evidence.","molecular_requirements":"Evidence is for the heterodimer; the integrin chain alone was not tested separately [PMID:11053440]. Partner chain beta1 is the paired subunit reported [PMID:11053440].","affinity_potency":[],"species_and_systems":"Human uPAR on hamster (CHO) cells [PMID:11053440].","localisation_and_range":"uPAR is described as a GPI-anchored protein lacking a transmembrane structure that acts as an integrin ligand, in trans between apposed cells, as well as an associated protein in cis [PMID:11053440]. Cell-cell contact range.","caveats":"Single paper (full text); no affinity.","key_references":[{"PMID":"11053440","why":"uPAR binds integrins alpha4beta1, alpha6beta1, alpha9beta1, alphavbeta3 on CHO cells"}],"covers":["LR003110","LR006331"]},"LR003118":{"pair":"PLG -> ENO1","headline":"Cell-surface enolase-1 binding plasminogen is reported in monocytes; one database record also supports it.","interaction_type":"direct binding","direction_and_effect":"ENO-1 binds plasminogen at the cell surface, enhancing plasmin production; LPS raised ENO-1 surface expression on human monocytes and U937 cells, and antibodies against its plasminogen-binding site abrogated the effects [PMID:19182206].","molecular_requirements":"Plasminogen-binding site of ENO-1 is required for the effects [PMID:19182206].","affinity_potency":[],"species_and_systems":"Human blood monocytes and U937 cells; in vivo recruitment also tested, species not given here [PMID:19182206]. BioGRID lists a reconstituted complex [DB:BioGRID].","localisation_and_range":"Ligand flagged secreted; ENO-1 is a cytosolic enzyme translocated to the surface [PMID:19182206].","caveats":"Abstract only. Binding was stated, not quantified. ENO-1 is also a glycolytic enzyme, so receptor role is context-dependent.","key_references":[{"PMID":"19182206","why":"ENO-1 plasminogen-binding site drives monocyte migration"}],"covers":["LR003118","LR006339"]},"LR006340":{"pair":"PLG -> IGF2R","headline":"IGF2R (soluble form) binds plasminogen and acts as a decoy that blocks activation; evidence is abstract-level.","interaction_type":"direct binding","direction_and_effect":"The soluble, TACE-shed M6P/IGF2R ectodomain bound plasminogen, preventing its binding to the cell surface and uPA and inhibiting activation; peptide 18-36 mimicked this [PMID:21273553]. Membrane IGF2R expression down-regulated uPA/CD87-driven plasminogen activation [PMID:12189157]. Effect is antagonist/decoy.","molecular_requirements":"The N-terminal region of IGF2R is described as needed for binding CD87 and Plg jointly [PMID:12189157]. The functional form is the shed soluble ectodomain [PMID:21273553].","affinity_potency":[],"species_and_systems":"Human CD222 in mouse fibroblasts [PMID:12189157]; human endothelial cells plus in vivo models [PMID:21273553].","localisation_and_range":"Ligand flagged secreted; receptor has secreted and transmembrane flags [flag]; the soluble ectodomain acts at range [PMID:21273553].","caveats":"Abstract only for both. Plasminogen binding is stated jointly with CD87 and without separate assay or affinity [PMID:12189157]. IGF2R is not a classical signalling receptor here. Two further confirmed rows are not shown.","key_references":[{"PMID":"21273553","why":"soluble IGF2R binds plasminogen, blocks activation"},{"PMID":"12189157","why":"IGF2R N-terminus binds CD87 and Plg"}],"covers":["LR003119","LR006340"]},"LR001237":{"pair":"PODXL2 -> SELL","headline":"Endoglycan (PODXL2) functions as an L-selectin ligand through tyrosine sulfation and sLex; one primary paper plus a database record.","interaction_type":"direct binding","direction_and_effect":"Endoglycan can function as an L-selectin ligand, like CD34 and podocalyxin [PMID:12889478]. BioGRID records a reconstituted complex [DB:BioGRID].","molecular_requirements":"Binding uses sulfation on two tyrosine residues and O-linked sLex structures in the acidic amino-terminal region, unlike the 6-sulfo-sLex mucin-domain mechanism of CD34 and podocalyxin [PMID:12889478].","affinity_potency":[],"species_and_systems":"Species and cell system not stated in our evidence beyond the abstract [PMID:12889478]; mouse pair is ortholog-inferred.","localisation_and_range":"Flagged transmembrane, not secreted [flag]; contact-dependent adhesion.","caveats":"Primary evidence is a single abstract-only paper. PMID:18606703 only mentions L-selectin as prior work, not as its own result. No affinity reported.","key_references":[{"PMID":"12889478","why":"endoglycan as L-selectin ligand, sulfation and sLex mechanism"}],"covers":["LR001237","LR004639"]},"LR001246":{"pair":"POMC -> OPRM1","headline":"Beta-endorphin activates OPRM1 in a recent HEK293T assay within a heterodimer; support is thin and indirect.","interaction_type":"functional only","direction_and_effect":"In HEK293T cells expressing mouse Oprm1 with MrgprX1, 1 uM beta-endorphin raised intracellular calcium, and naltrexone abolished it [PMID:41904513]. Reactome records opioid binding to MOR [DB:Reactome]; a PDB structure with POMC and OPRM1 exists [DB:PDB 8F7Q].","molecular_requirements":"The response was seen in cells co-expressing OPRM1 and MRGPRX1 (heterodimer, switching to Galpha q/11 calcium signalling) [PMID:41904513]; OPRM1 alone was not tested with beta-endorphin in the excerpts shown.","affinity_potency":[],"species_and_systems":"Mouse receptors in HEK293T cells; human orthologs were used in some other experiments in the paper [PMID:41904513]. Full text was read. The mouse pair is ortholog-inferred.","localisation_and_range":"POMC flagged secreted, OPRM1 transmembrane [flag].","caveats":"The calcium readout is a non-canonical heterodimer response, not classic Gi/o signalling. Ligand is beta-endorphin, not full-length POMC. Curators judged 3 papers as different_entity and others abstract_insufficient or review_only.","key_references":[{"PMID":"41904513","why":"Beta-endorphin evokes naltrexone-sensitive calcium in OPRM1/MRGPRX1 cells"}],"covers":["LR001246","LR004648"]},"LR003127":{"pair":"POSTN -> STAB1","headline":"Periostin was independently confirmed as a circulating ligand of Stab1/Stab2 in one mouse atherosclerosis study, read as an abstract.","interaction_type":"direct binding","direction_and_effect":"Periostin, reelin and TGFBi were independently confirmed as novel circulating ligands of Stab1/2 [PMID:36325910]. Stab1/2 mediate clearance of circulating plasma molecules; ApoE-Stab1-KO and ApoE-Stab2-KO mice show reduced atherogenesis [PMID:36325910]. Receptor clearance, not signalling agonism, is the described effect.","molecular_requirements":"Not reported in our evidence; the curator's notes mention GST-pulldown and endocytosis assays [PMID:36325910].","affinity_potency":[],"species_and_systems":"Mouse knockout and plasma proteomics plus in vitro assays; read as abstract only [PMID:36325910]. Human pair is the dossier species; the mouse pair is ortholog-inferred in the dossier.","localisation_and_range":"Periostin is flagged secreted [flag]; the paper describes circulating ligands cleared by liver sinusoidal endothelium [PMID:36325910].","caveats":"Single abstract-level paper, with no affinity or species-of-binding detail. The paper confirms five ligand-receptor combinations at once, and the abstract does not give per-pair detail. Stab1 and Stab2 are paralogs with shared ligands; one study covers both.","key_references":[{"PMID":"36325910","why":"Stab1/2 identified as clearance receptors for periostin, reelin and TGFBi"}],"covers":["LR003127","LR006348"]},"LR001255":{"pair":"PRND -> RPSA","headline":"Direct physical interaction in yeast two-hybrid and co-immunoprecipitation; one abstract-only paper, no signalling effect shown.","interaction_type":"direct binding","direction_and_effect":"Doppel bound the full-length 37-kDa laminin receptor precursor in yeast two-hybrid, validated by immunoprecipitation and immunoblotting in transfected cells and in vivo tissue [PMID:15246873]. Effect on signalling is not reported in our evidence.","molecular_requirements":"LRP residues 100-220 retained Dpl binding, but deleting the N-terminal domain of full-length LRP abolished it [PMID:15246873].","affinity_potency":[],"species_and_systems":"Human per curator; yeast two-hybrid, transfected cell lines and tissue [PMID:15246873].","localisation_and_range":"PRND is flagged non-secreted [flag]; range is not reported in our evidence.","caveats":"Abstract-only, a single paper. RPSA is a precursor binding partner of prion protein too, bound through different domains [PMID:15246873]. No affinity reported. Whether RPSA acts as a signalling receptor for Dpl is not shown.","key_references":[{"PMID":"15246873","why":"Dpl binds 37-kDa laminin receptor precursor by Y2H and IP"}],"covers":["LR001255","LR004656"]},"LR003136":{"pair":"PRRT1 -> GRIA1","headline":"Structural evidence that PRRT1 (SynDIG4) sits beside GluA1 in native AMPA receptors; an auxiliary-subunit relation, not a classic ligand.","interaction_type":"direct binding","direction_and_effect":"Cryo-EM of native AMPA receptors resolved SynDIG4 density whose helix H2 contacts the pre-M1 and M4 helices of GluA1; it did not visibly alter the ligand-binding domain-transmembrane domain, CNIH or M4 conformation [PMID:42284406].","molecular_requirements":"SynDIG4 occupies a peripheral site in a complex that also contains TARPs and CNIHs; GluA1 is one subunit [PMID:42284406]. Whether GluA1 alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Native AMPA receptors purified for cryo-EM, species not stated in our evidence [PMID:42284406]; human pair is ortholog-inferred, mouse pair is not.","localisation_and_range":"Both partners are membrane proteins; PRRT1 is not flagged secreted [flag], so contact within the membrane complex.","caveats":"Single 2026 paper read from full text. Functional consequences are not established by the authors, and the paper notes SynDIG4 may be partly lost in purification [PMID:42284406]. This is an auxiliary-subunit interaction rather than a signalling ligand; two other rows were about a different entity.","key_references":[{"PMID":"42284406","why":"Native AMPA receptor cryo-EM showing SynDIG4 contacting GluA1."}],"covers":["LR003136","LR006357"]},"LR001264":{"pair":"PSAP -> GPR37L1","headline":"Prosaptide binds and activates GPR37L1 (pEC50 8.3); full-length prosaposin also stimulates; abstract-only.","interaction_type":"direct binding","direction_and_effect":"Prosaptide promoted endocytosis of GPR37L1, bound it and activated GPR37L1-dependent signalling, with ERK phosphorylation, 35S-GTPgammaS binding and cAMP inhibition [PMID:23690594]. UniProt says GPR37L1 binds prosaposin, causing endocytosis and an ERK cascade [DB:UniProt]; GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"Prosaptide is the active fragment; full-length prosaposin also stimulates GPR37L1 signalling [PMID:23690594].","affinity_potency":[{"value":"pEC50 8.3","assay":"prosaptide agonist activity","system":"human prosaptide at human GPR37L1","cite":"PMID:23690594"}],"species_and_systems":"Human proteins in cells; primary astrocytes were protected from oxidative stress, attenuated by siRNA knockdown [PMID:23690594]. Mouse pair is ortholog-inferred.","localisation_and_range":"PSAP flagged secreted and GPR37L1 transmembrane [flag]; paracrine.","caveats":"One paper, abstract-only; one further row pending. Astrocyte knockdown covered GPR37 and GPR37L1 together [PMID:23690594].","key_references":[{"PMID":"23690594","why":"Deorphanisation of GPR37L1 by prosaptide and prosaposin."}],"covers":["LR001264","LR004664"]},"LR009301":{"pair":"PSAP -> SORT1","headline":"Sortilin interaction with prosaposin rests on UniProt annotation only; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states monomeric prosaposin interacts via its C-terminus with SORT1 and that this is required for targeting to lysosomes [DB:UniProt].","molecular_requirements":"Prosaposin C-terminus is involved [DB:UniProt].","affinity_potency":[],"species_and_systems":"Species and assay not reported in our evidence.","localisation_and_range":"Sorting to lysosomes per UniProt [DB:UniProt]; receptor flagged transmembrane [flag].","caveats":"No judged papers; the one literature row was review-only. Support is database text alone and describes trafficking, not signalling.","key_references":[],"covers":["LR009301"]},"LR001273":{"pair":"PTH -> PTH1R","headline":"PTH binds and activates PTH1R; well supported by crosslinking, binding and structural records.","interaction_type":"direct binding","direction_and_effect":"PTH is an agonist at PTH1R [PMID:31594997]. UniProt says PTH activates PTH1R, engaging Gs-cAMP/PKA and Gq-PLC/PKC signalling [DB:UniProt].","molecular_requirements":"Binding involves the receptor extracellular domain and orthosteric pocket [PMID:31594997]; a PTH analogue contacts receptor residues 173-189 [PMID:9108031].","affinity_potency":[{"value":"KD 4 uM","assay":"ITC, PTH1R ECD titrated into PTH (1-34)","system":"purified proteins","cite":"PMID:31594997"},{"value":"KD 3.8 uM","assay":"ITC, PTH (1-34) titrated into PTH1R ECD","system":"purified proteins","cite":"PMID:31594997"}],"species_and_systems":"Human receptor in HEK-293 cells for a photoreactive PTH agonist [PMID:9108031]; human ligand and receptor in COS-7 cells with PTHrP/PTH analogues [PMID:12947048].","localisation_and_range":"Secreted ligand and transmembrane receptor [flag].","caveats":"Many verified papers are abstract-only. Crosslinking papers used analogues, not native PTH. One pending paper not shown.","key_references":[{"PMID":"9108031","why":"Photocrosslinking maps PTH agonist contact to receptor 173-189."},{"PMID":"12947048","why":"Crosslinking localises position 19 contact to Leu232-Lys240."},{"PMID":"31594997","why":"Native binding and ITC of PTH (1-34) to PTH1R ECD."}],"covers":["LR001273","LR004673"]},"LR003145":{"pair":"PTN -> ITGAM","headline":"PTN directly binds the alphaM I domain of Mac-1 (ITGAM/ITGB2) in vitro and drives Mac-1-dependent adhesion and migration.","interaction_type":"direct binding","direction_and_effect":"PTN engages Mac-1 as a receptor for macrophage adhesion and migration: Mac-1 expression on HEK293 cells induced PTN-directed adhesion and migration, with Mac-1-dependent spreading and Erk1/2 phosphorylation [PMID:28939773].","molecular_requirements":"Biolayer interferometry and NMR show direct interaction between the alphaMI domain and PTN; Mac-1 cooperates with cell-surface proteoglycans because both anti-Mac-1 mAb and heparin were required to block adhesion [PMID:28939773]. Recombinant fragments reveal two Mac-1-binding sites, one per PTN domain [PMID:28939773]. ITGB2 (partner chain) is a separate pair in the project.","affinity_potency":[],"species_and_systems":"Human ligand and human receptor; HEK293 cells plus recombinant proteins [PMID:28939773]. Mouse pair is ortholog-inferred.","localisation_and_range":"PTN is flagged as secreted [flag], so signalling would be paracrine. Integrin binding is cell-surface and proteoglycan-assisted.","caveats":"Abstract only; no affinity reported. ITGAM chain alone is the contact site (alphaMI domain), but the functional receptor is the alphaMbeta2 heterodimer. PDB and IntAct records exist [DB:PDB 8VOH] [DB:IntAct].","key_references":[{"PMID":"28939773","why":"PTN as Mac-1 ligand: adhesion, alphaMI binding by BLI/NMR"}],"covers":["LR003145","LR006366"]},"LR003154":{"pair":"PTN -> SDC2","headline":"Co-IP and rescue data in human spermatogonial stem cells support PTN acting on SDC2; binding evidence is indirect.","interaction_type":"functional only","direction_and_effect":"In human testis, PTN from Leydig cells signals to SDC2 on spermatogonial stem cells; SDC2 knockdown impaired proliferation and PLZF and GFRA1 expression, and exogenous PTN rescued proliferation and GFRA1 in knockdown lines [PMID:39285301]. Curator annotation: agonist.","molecular_requirements":"Downstream GFRA1 and HIF-1 signalling reported; subunit or co-receptor requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human testicular tissue and human SSC lines [PMID:39285301].","localisation_and_range":"PTN is flagged secreted [flag]; Leydig-to-SSC paracrine signalling [PMID:39285301]. SDC2 is flagged transmembrane, not secreted [flag].","caveats":"Abstract-level curation plus excerpts. The interaction was shown by immunofluorescence, STRING prediction and co-immunoprecipitation, not purified binding; co-localisation occurred only in approximately 50% of cells [PMID:39285301]. The paper lists SDC2 among five reported PTN receptors but the PTN-SDC2 binding there relies on those assays [PMID:39285301]. Rescue by PTN does not separate SDC2-dependent from SDC2-independent effects.","key_references":[{"PMID":"39285301","why":"PTN-SDC2 in human spermatogonial stem cells"}],"covers":["LR003154","LR006375"]},"LR003163":{"pair":"PTPRF -> LRRC4B","headline":"LAR (PTPRF) binds NGL-3 (LRRC4B) through defined domains; well supported, human data from an abstract plus Reactome.","interaction_type":"direct binding","direction_and_effect":"The NGL-3 leucine-rich repeat domain interacts with the first two FNIII domains of LAR to induce bidirectional synapse formation [PMID:20139422]; curated direction agonist. In a mouse cell-aggregation assay NGL-3 cells showed strong adhesion to LAR cells, used as a positive control [PMID:23345436].","molecular_requirements":"LAR binds via its first two FNIII domains; NGL-3 uses its LRR domain, and Gln-96 in the first LRR is critical for LAR binding and presynaptic differentiation [PMID:20139422]. Reactome lists a complex of LRRC4B with PTPRF, PTPRS and PTPRD [DB:Reactome].","affinity_potency":[],"species_and_systems":"Curated as human proteins for the binding paper (abstract only) [PMID:20139422]; mouse L cells in the second paper [PMID:23345436]. Both pairs listed are ortholog-inferred.","localisation_and_range":"Both flagged transmembrane [flag]; paper describes trans-synaptic adhesion, i.e. contact-dependent [PMID:20139422].","caveats":"Binding paper read only as abstract; the curated row is the reciprocal of an NGL-3 -> LAR row. Second paper's aggregation quote is flagged unverifiable pending spot-check. No affinity in our evidence.","key_references":[{"PMID":"20139422","why":"NGL-3 LRR domain binds LAR FNIII 1-2"},{"PMID":"23345436","why":"NGL-3 cells adhere to LAR cells (positive control)"}],"covers":["LR003163","LR006384"]},"LR003172":{"pair":"PTPRS -> SLITRK3","headline":"Mouse cell-aggregation evidence that PTP-sigma and SLITRK3 adhere; single paper.","interaction_type":"functional only","direction_and_effect":"Slitrk3-expressing cells aggregated with PTP-sigma-expressing cells; the paper concludes PTP-sigma was specifically required for excitatory synaptic differentiation by Slitrks [PMID:23345436].","molecular_requirements":"Slitrks require distinct LAR-RPTP family members for synapse formation, in an isoform-dependent manner [PMID:23345436]. Subunit needs beyond that are not reported.","affinity_potency":[],"species_and_systems":"Mouse proteins in mouse L cells; the abstract also uses rat brain [PMID:23345436]. Both human and mouse pairs are ortholog-inferred.","localisation_and_range":"Cell-cell aggregation implies contact-dependent action; PTPRS is flagged secreted [flag] [PMID:23345436].","caveats":"Evidence is one cell-adhesion assay (aggregation), not a measured binding; the paper's abstract-level result is that Slitrks need distinct LAR-RPTP members for synapse formation [PMID:23345436]. The curation note says the quote is unverifiable pending spot-check.","key_references":[{"PMID":"23345436","why":"Slitrk-PTP-sigma cell aggregation and synapse-formation requirement"}],"covers":["LR003172","LR006393"]},"LR001282":{"pair":"PYY -> NPY4R","headline":"PYY binds human NPY4R (Y4) with nanomolar affinity, but pancreatic polypeptide is the preferred ligand.","interaction_type":"direct binding","direction_and_effect":"PYY acts as a full agonist at Y4 [DB:GtoPdb]; both papers show human Y4 binds PYY with lower affinity than PP [PMID:7592911][PMID:7493937].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"pKd 9.89","assay":"125I-PYY saturation binding","system":"human Y4, transient expression","cite":"PMID:7592911"},{"value":"pKi 9.06","assay":"displacement of 125I-PYY","system":"human Y4, transient expression","cite":"PMID:7592911"},{"value":"Ki 1.44 nM","assay":"radioligand binding","system":"CHO cells, human Y4","cite":"PMID:7493937"}],"species_and_systems":"Human receptor in transfected cells (human placental genomic clone; CHO) [PMID:7592911][PMID:7493937]. Mouse pair is projected.","localisation_and_range":"PYY is flagged secreted [flag]; Y4 is a transmembrane GPCR.","caveats":"Both papers read as abstract. In both, PP binds better (PP pKi = 10.25; Ki 13.8 pM), so Y4 is primarily a PP receptor [PMID:7592911][PMID:7493937]. One additional paper was judged a different entity.","key_references":[{"PMID":"7592911","why":"Y4 cloning with PYY binding, pKi 9.06"},{"PMID":"7493937","why":"Y4 cloning with PYY Ki 1.44 nM; GtoPdb source"}],"covers":["LR001282","LR004682"]},"LR003181":{"pair":"RELN -> EFNB3","headline":"Reelin reportedly binds the extracellular domain of ephrin Bs, with mouse genetic interaction; one abstract-only paper and a BioGRID record.","interaction_type":"direct binding","direction_and_effect":"Reelin binds the extracellular domain of ephrin Bs, which associate at the membrane with VLDLR and ApoER2; ephrin B loss impairs Reelin-induced Dab1 phosphorylation [PMID:21460838]. Compound mutants (Reln+/-; Efnb3-/-) show migration defects like the reeler mouse [PMID:21460838].","molecular_requirements":"Ephrin Bs act together with VLDLR and ApoER2 rather than alone; EFNB3-specific binding is not separated from EFNB1/B2 in our evidence [PMID:21460838].","affinity_potency":[],"species_and_systems":"Mouse genetics and neurons per the abstract; curators record human/human [PMID:21460838]. BioGRID lists a Reconstituted Complex record [DB:BioGRID].","localisation_and_range":"Reelin is flagged secreted; EFNB3 is a membrane-bound ligand [flag].","caveats":"One paper read as abstract only; no affinity. Evidence covers ephrin Bs as a group. Human pair is ortholog-inferred; direct data are mouse.","key_references":[{"PMID":"21460838","why":"Reelin binds ephrin B extracellular domain; genetic interaction"}],"covers":["LR003181","LR006401"]},"LR001291":{"pair":"RELN -> ITGB1","headline":"Reelin associates with alpha3beta1 integrin; the beta1-only attribution rests on one paper.","interaction_type":"direct binding","direction_and_effect":"Reelin was co-immunoprecipitated by beta1 integrin beads and its effect on migration depended on alpha3beta1 [PMID:10939329]. The annotation lists the effect as inhibitory [flag], matching the paper's inhibition of migration [PMID:10939329].","molecular_requirements":"Evidence is for alpha3beta1; beta1 alone is not shown to suffice, and alpha3beta1-deficient neurons lose the response [PMID:10939329].","affinity_potency":[],"species_and_systems":"Mouse and rat cortex and cultured cortical neurons; recombinant Reelin [PMID:10939329]. The human pair is ortholog-inferred.","localisation_and_range":"RELN is flagged secreted [flag].","caveats":"Single paper; chain-only (ITGB1) attribution of a heterodimer result; ITGB1 pairs with many alpha chains, not tested here beyond alpha3 [PMID:10939329].","key_references":[{"PMID":"10939329","why":"Reelin-alpha3beta1 integrin binding and migration inhibition"}],"covers":["LR001291","LR004690"]},"LR003190":{"pair":"ROBO1 -> ROBO2","headline":"ROBO1 and ROBO2 ectodomains interact heterophilically; one abstract-only paper plus an IntAct record.","interaction_type":"direct binding","direction_and_effect":"Extracellular domains of Robo1 and Robo2 are homophilic adhesion molecules that can also interact with each other [PMID:12504588]. Direction is a formality for this symmetric adhesion; no agonist or antagonist effect is reported for the pair itself.","molecular_requirements":"Neurite outgrowth was blocked by an antibody against the first Ig domain of Robo1/2 or by soluble Robo-Fc chimera [PMID:12504588]; subunit requirements otherwise not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human Robo1 and Robo2 transfected into 3T3 cells, tested on retinal and olfactory neurons [PMID:12504588]. The mouse pair is projected from human evidence.","localisation_and_range":"Robo2 carries a secreted flag and Robo1 a membrane flag [flag]; the paper describes trans adhesion between family members [PMID:12504588].","caveats":"Abstract only. Binding between the two ectodomains is stated in a single sentence; no affinity. IntAct lists a 'polymerization' record from the same paper [DB:IntAct].","key_references":[{"PMID":"12504588","why":"Only paper: Robo1/Robo2 ectodomain homophilic and heterophilic interaction"}],"covers":["LR003190","LR006410"]},"LR006412":{"pair":"ROBO2 -> ROBO1","headline":"ROBO2 and ROBO1 ectodomains interact; reverse-direction row of the same abstract-only observation.","interaction_type":"direct binding","direction_and_effect":"Robo1 and Robo2 extracellular domains are homophilic adhesion molecules that can also interact with each other [PMID:12504588]. Direction is a formality; no agonist or antagonist effect reported.","molecular_requirements":"Blocked by an antibody against the first Ig domain of Robo1/2 or soluble Robo-Fc [PMID:12504588]; no further subunit data.","affinity_potency":[],"species_and_systems":"Human Robo1/Robo2 in transfected 3T3 cells with primary neurons [PMID:12504588]. Mouse pair projected from human.","localisation_and_range":"Robo2 secreted flag, Robo1 membrane flag [flag]; paper describes trans adhesion [PMID:12504588].","caveats":"Abstract only; same paper and evidence as ROBO1 -> ROBO2. IntAct record is a 'polymerization' entry from the same paper [DB:IntAct].","key_references":[{"PMID":"12504588","why":"Only paper"}],"covers":["LR003192","LR006412"]},"LR012415":{"pair":"ROR1 -> FZD7","headline":"ROR1-FZD7 rests only on IntAct comigration records; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. The interaction is annotated as stimulatory in the project's annotation, without paper support in this dossier.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct records cite PMID 36994853 (gel comigration) [DB:IntAct]; species and system not stated beyond human entities.","localisation_and_range":"Both are receptors [flag]; no range information.","caveats":"No papers were judged (3 pending). Support is two IntAct comigration-in-gel entries only, and the paper behind them was not read here.","key_references":[],"covers":["LR012415"]},"LR004702":{"pair":"RPS19 -> C5AR1","headline":"RPS19 cross-linked homodimer binds and activates C5aR1 in one abstract-only study; GtoPdb lists agonist.","interaction_type":"direct binding","direction_and_effect":"The RP S19 dimer activated the receptor by a two-step binding mechanism as with C5a; the second site triggered chemotaxis [PMID:11733378]. GtoPdb lists full agonist [DB:GtoPdb].","molecular_requirements":"The ligand is the cross-linked homodimer of S19, not the monomer. Receptor binding sites on S19 are a Lys41-His42-Lys43 basic cluster and a Leu131-Asp132-Arg133 moiety [PMID:11733378].","affinity_potency":[],"species_and_systems":"Human recombinant S19 mutants and synthetic peptides; monocyte C5a receptor [PMID:11733378].","localisation_and_range":"Ligand carries a secreted flag [flag]; paper concerns an extracellular dimer attracting monocytes.","caveats":"Abstract only; no affinity values reported (GtoPdb affinity units not given) [DB:GtoPdb]. One additional paper was review-only and one abstract-insufficient.","key_references":[{"PMID":"11733378","why":"Mapping of S19 dimer binding sites on C5a receptor"}],"covers":["LR001305","LR004702"]},"LR001309":{"pair":"RSPO1 -> LGR6","headline":"RSPO1 binds LGR6 according to one paper (abstract only) and GtoPdb/Reactome; less direct than LGR4/5.","interaction_type":"direct binding","direction_and_effect":"Each of the four R-spondins can bind Lgr4, -5 and -6 [PMID:21727895]. GtoPdb lists full agonist [DB:GtoPdb].","molecular_requirements":"LGR4, -5 or -6 re-expression rescues RSPO1-mediated WNT3A enhancement lost on LGR4 deletion [PMID:21727895].","affinity_potency":[],"species_and_systems":"Mouse gut and intestinal crypt cultures and HEK293 cells; species of the LGR6 result not stated [PMID:21727895].","localisation_and_range":"RSPO1 secreted per flag [flag].","caveats":"Abstract only; LGR6 binding is a family-level claim by mass spectrometry and rescue, not LGR6-specific. One abstract-insufficient and one unresolvable row exist. GtoPdb lists a pIC50 entry without a value [DB:GtoPdb].","key_references":[{"PMID":"21727895","why":"Family-wide R-spondin binding to LGR4/5/6"}],"covers":["LR001309","LR004706"]},"LR004711":{"pair":"RSPO2 -> LGR6","headline":"RSPO2 binds LGR6 by Fc-fusion binding assay (browser-read) and impaired mutant binding in human disease.","interaction_type":"direct binding","direction_and_effect":"RSPO2, RSPO3 and RSPO4 Fc fusions at about 1 \u00b5g ml-1 bound specifically to LGR4, LGR5 and LGR6 [PMID:21727895]. Human RSPO2 mutants show impaired binding to LGR4/5/6 [PMID:29769720]. GtoPdb lists full agonist [DB:GtoPdb].","molecular_requirements":"LGR4/5/6 binding is separate from RNF43/ZNRF3 binding; RSPO2 limb function was independent of LGR4/5/6 [PMID:29769720].","affinity_potency":[],"species_and_systems":"Binding assay species not stated [PMID:21727895]; human mutations [PMID:29769720]. Human pair is ortholog-inferred.","localisation_and_range":"RSPO2 secreted per flag [flag].","caveats":"The 21727895 Results sentence was browser-read and its spot-check is pending; the 29769720 paper is abstract only. One abstract-insufficient, one review-only and one different-entity row exist.","key_references":[{"PMID":"21727895","why":"Fc-fusion binding of RSPO2 to LGR4/5/6"},{"PMID":"29769720","why":"RSPO2 mutants lose LGR4/5/6 binding"}],"covers":["LR001314","LR004711"]},"LR001318":{"pair":"RSPO3 -> LGR6","headline":"RSPO3 binding to LGR6 rests on a family-level statement that RSPO2-4 bind LGR4-6, plus databases.","interaction_type":"direct binding","direction_and_effect":"RSPO3 acts as an agonist at LGR6 in GtoPdb [DB:GtoPdb]; the paper reports Fc fusions of RSPO2, RSPO3 and RSPO4 bound specifically to LGR4, LGR5 and LGR6 [PMID:21727895].","molecular_requirements":"LGR4, -5 or -6 re-expression rescued RSPO1-mediated WNT3A signal enhancement in LGR4-removed HEK293 cells [PMID:21727895]. Other subunit needs are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Binding assay species not recorded for the RSPO3 row; the paper used mouse gut and HEK293 cells [PMID:21727895]. The human pair is ortholog-inferred, the mouse pair is not.","localisation_and_range":"RSPO3 is flagged secreted and LGR6 transmembrane [flag].","caveats":"The binding sentence for PMID 21727895 comes from a browser read of the main text and is marked as an unverifiable quote with spot-check pending. PMID 29769720 is an RSPO2 paper reporting impaired LGR4/5/6 binding by mutants. No affinity is reported.","key_references":[{"PMID":"21727895","why":"Fc-RSPO3 binds LGR4/5/6"},{"PMID":"29769720","why":"RSPO2 mutants impair LGR4/5/6 binding; not RSPO3-specific"}],"covers":["LR001318","LR004715"]},"LR004720":{"pair":"RSPO4 -> LGR6","headline":"RSPO4 binding to LGR6 rests on a family-level statement in one abstract and on database records.","interaction_type":"direct binding","direction_and_effect":"Each of the four R-spondins can bind Lgr4, -5 and -6 [PMID:21727895]; GtoPdb records RSPO4 as a full agonist at LGR6 [DB:GtoPdb].","molecular_requirements":"LGR4, -5 or -6 re-expression rescued RSPO1-mediated WNT3A enhancement [PMID:21727895]. Other requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse gut and HEK293 cells in the paper [PMID:21727895]; IntAct has a pull down record [DB:IntAct]. The mouse pair is ortholog-inferred.","localisation_and_range":"RSPO4 is flagged secreted and LGR6 transmembrane [flag].","caveats":"Abstract only; no RSPO4-specific experiment or affinity is described. One further paper was unresolvable and one abstract insufficient.","key_references":[{"PMID":"21727895","why":"R-spondins bind Lgr4, -5 and -6"}],"covers":["LR001323","LR004720"]},"LR001327":{"pair":"RTN4 -> RTN4RL1","headline":"Nogo-B is reported to bind NgR3 directly in nasopharyngeal carcinoma cells, but an earlier paper says reticulon-family members do not bind NgR3.","interaction_type":"conflicting","direction_and_effect":"Nogo-B promotes EMT and invasion in NPC by interacting directly with NgR3, and NgR3 siRNA abolished Nogo-B-driven invasion [PMID:35075114].","molecular_requirements":"Not reported for this pair beyond the NPC co-IP [PMID:35075114].","affinity_potency":[],"species_and_systems":"HEK293T co-IP with tagged Nogo-B and NgR3, CNE2 NPC cells and mouse xenografts [PMID:35075114]. The negative paper used cultured cells [PMID:22133682].","localisation_and_range":"RTN4 is flagged non-secreted [flag]; co-IP and colocalisation were reported in the cytoplasm of NPC cells [PMID:35075114].","caveats":"A verified negative states other reticulon family members, to which Nogo-A belongs, do not bind NgR3 [PMID:22133682]. The positive paper uses overexpression co-IP with Nogo-B and cytoplasmic colocalisation, which does not show extracellular ligand binding. No database records.","key_references":[{"PMID":"35075114","why":"Nogo-B co-IP with NgR3 in NPC"},{"PMID":"22133682","why":"Verified negative: reticulon family members do not bind NgR3"}],"covers":["LR001327","LR004724"]},"LR006421":{"pair":"RTN4RL1 -> ADGRB1","headline":"Direct binding of RTN4RL1 to BAI1 shown by cell-surface binding, AVEXIS, aggregation and SPR across two full-text papers.","interaction_type":"direct binding","direction_and_effect":"RTN4RL1 binds the ADGRB1 ectodomain: ADGRB1 probes stained RTN4RL1-transfected cells and the ectodomains interacted directly in both bait-prey orientations [PMID:30477585]. RTN4RL1 was a top pulldown interactor of BAI1 and BAI3 ECDs [PMID:34758294]. RTN4RL1 loss in human neurons altered synapse density and size and increased axon length and branching [PMID:34758294]; direction of signalling is not reported.","molecular_requirements":"ADGRB1 TSR1-3 were sufficient for binding [PMID:30477585]. The BAI1 N-terminal domains including the TSRs formed a stable complex with RTN4RL1 ECD by SEC [PMID:34758294]. ADGRB2 did not bind the family [PMID:30477585].","affinity_potency":[],"species_and_systems":"HEK293 cells, recombinant ectodomains and human neurons [PMID:30477585][PMID:34758294]. Affinity by SPR is reported only as the range for the BAI/RTN4R family (1.9 nM to 30.0 nM); a value specific to RTN4RL1-BAI1 is not reported in our excerpts.","localisation_and_range":"Trans-cellular adhesion shown, so juxtacrine; RTN4RL1 is described as GPI-linked membrane protein [PMID:30477585][PMID:34758294]. RTN4RL1 has no secreted flag; ADGRB1 carries a secreted flag [flag].","caveats":"Single CRISPRa screen per bait [PMID:30477585]. ADGRB1 secreted flag looks odd for a membrane receptor [flag].","key_references":[{"PMID":"34758294","why":"binding, SPR family range and neuronal function"},{"PMID":"30477585","why":"CRISPRa screen with AVEXIS validation"}],"covers":["LR003201","LR006421"]},"LR003208":{"pair":"S100A10 -> HTR1B","headline":"p11/S100A10 is reported to interact with 5-HT1B and modulate its signalling; support rests on one abstract-only paper that mainly studied 5-HT4.","interaction_type":"functional only","direction_and_effect":"p11 interacts with 5-HTR1B, modulates its signal transduction and is required for antidepressant responses to receptor activation [PMID:19211900]. This is stated as background in the abstract.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Abstract states human-labelled entities; behavioural work is in vivo, species not stated in the abstract [PMID:19211900].","localisation_and_range":"S100A10 is not flagged secreted [flag]; p11 acts as an intracellular accessory protein, per the abstract's description of modulating receptor signalling [PMID:19211900].","caveats":"Curated from background sentence of a paper whose new findings concern HTR4. Abstract only. The curator noted a corrupted receptor-symbol field in the source record. The assay class 'direct_binding' is not directly shown in the abstract.","key_references":[{"PMID":"19211900","why":"Specificity screen of p11 against serotonin receptors"}],"covers":["LR003208","LR006428"]},"LR006430":{"pair":"S100A10 -> HTR4","headline":"p11/S100A10 is a newly identified 5-HT4 interactor that raises surface expression and signalling; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"p11 increases 5-HTR4 surface expression and facilitates 5-HTR4 signalling; p11 is required for behavioural antidepressant responses to 5-HTR4 stimulation in vivo [PMID:19211900].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"p11 and 5-HTR4 mRNA and protein are coexpressed in brain regions relevant to depression; in vivo behavioural work, species not stated in the abstract [PMID:19211900].","localisation_and_range":"S100A10 is not flagged secreted [flag]; the paper describes an accessory-protein role in receptor trafficking and signalling [PMID:19211900].","caveats":"Abstract only; binding method not reported in our evidence. The curator noted a corrupted receptor-symbol field in the source record.","key_references":[{"PMID":"19211900","why":"Identifies p11-5-HTR4 interaction and function"}],"covers":["LR003210","LR006430"]},"LR003217":{"pair":"S100A4 -> EGFR","headline":"SPR shows direct S100A4-EGFR binding with Kd 21.4 nM, but EGFR blockade did not affect neuroprotection.","interaction_type":"direct binding","direction_and_effect":"S100A4 binds ErbB1 (EGFR) in label-transfer and SPR; two EGFR inhibitors and anti-EGFR antibody did not significantly affect S100A4-induced neuroprotection, which depends mainly on ErbB4 [PMID:30083275].","molecular_requirements":"ErbB2 did not bind S100A4 but its knockdown abolished neuroprotection, suggesting it signals as a partner [PMID:30083275].","affinity_potency":[{"value":"Kd 21.4 \u00b1 5.5 nM","assay":"surface plasmon resonance, S100A4 on immobilized ErbB1","system":"recombinant proteins","cite":"PMID:30083275"}],"species_and_systems":"Cultured hippocampal neurons and dopaminergic cell models; species of cells not stated in excerpts [PMID:30083275]. BioGRID and IntAct list further assays [DB:BioGRID][DB:IntAct].","localisation_and_range":"S100A4 is flagged secreted and EGFR transmembrane [flag].","caveats":"Binding is shown but functional contribution of EGFR is not supported: inhibitors had no effect. The Kd is apparent, from binding kinetics. Curator read abstract only.","key_references":[{"PMID":"30083275","why":"SPR and label-transfer binding of S100A4 to ErbB1/3/4"}],"covers":["LR003217","LR006435"]},"LR003226":{"pair":"S100A8 -> CD68","headline":"Recombinant rat S100A8 binds CD68 in ELISA and affinity chromatography, glycosylation-dependent; abstract-only.","interaction_type":"direct binding","direction_and_effect":"S100A8 and S100A9 bound CD68 but not CD14; anti-CD68 antibody suppressed S100A8/S100A9 expression and CD68 siRNA reduced macrophage activation by r-S100A8 or r-S100A9 [PMID:27312849].","molecular_requirements":"Less S100A8 bound macrophages after deglycosylation; anti-TLR4 or anti-RAGE antibodies suppressed r-S100A9-induced IL-1beta, so other receptors may cooperate [PMID:27312849].","affinity_potency":[],"species_and_systems":"Recombinant rat proteins and macrophages; human and mouse pairs are both projected [PMID:27312849].","localisation_and_range":"S100A8 is flagged secreted [flag].","caveats":"Abstract only. Both interactions are ortholog-inferred from rat data. No affinity reported.","key_references":[{"PMID":"27312849","why":"S100A8 and S100A9 binding to CD68"}],"covers":["LR003226","LR006443"]},"LR003235":{"pair":"S100A9 -> CD14","headline":"CD14 binds S100A9 by SPR and is required for its endocytosis and cytokine response; works as a TLR4 co-receptor (abstract-only).","interaction_type":"direct binding","direction_and_effect":"Saturable S100A9 binding to CD14 was detected by surface plasmon resonance; the S100A9-induced cytokine response was inhibited in CD14-deficient cells and by CD14 blocking antibodies, and S100A9 was not internalized into CD14-deficient cells [PMID:27228163]. Authors conclude CD14 is a co-receptor of TLR4 [PMID:27228163]. Agonist-like.","molecular_requirements":"CD14 acts with TLR4: stimulation of monocytes by S100A9 was strictly TLR4-dependent, while CD14 mediated binding and endocytosis [PMID:27228163]. Both are needed for signalling in this system.","affinity_potency":[],"species_and_systems":"Human monocytes, CD14- and TLR4-deficient cells; SPR with recombinant proteins; mouse pair is ortholog-inferred [PMID:27228163].","localisation_and_range":"Ligand secreted [flag]; CD14 also flagged secreted [flag] (soluble form possible). S100A9 was seen on membrane subdomains and in early endosomes [PMID:27228163].","caveats":"Abstract only; no Kd reported in our evidence. CD14 is a co-receptor and does not signal alone.","key_references":[{"PMID":"27228163","why":"SPR binding and CD14 requirement for S100A9 responses"}],"covers":["LR003235","LR006452"]},"LR003244":{"pair":"SAA1 -> TLR4","headline":"SAA1 is reported to bind TLR4/MD2 and activate NF-kappaB in hepatocytes; one in vivo-heavy study.","interaction_type":"direct binding","direction_and_effect":"SAA1 directly bound TLR4/MD2, induced TLR4 internalization and activated NF-kappaB, raising SAA1, IL-6 and CCL2 in hepatocytes [PMID:35247611]. Hepatic SAA1 overexpression worsened metabolic disease in mice, and this was markedly alleviated by TLR4 knockout [PMID:35247611].","molecular_requirements":"Binding was with the TLR4/MD2 complex; the methods describe SPR of mouse SAA1 with MD2 or TLR4, but the per-partner result is not shown in our excerpts [PMID:35247611].","affinity_potency":[],"species_and_systems":"Mouse in vivo (AAV8, knockout mice) and mouse recombinant TLR4/MD2 for binding; human NAFLD livers showed raised SAA1 [PMID:35247611]. The human pair is ortholog-inferred.","localisation_and_range":"Secreted ligand, membrane receptor; hepatocyte autocrine/paracrine loop [flag][PMID:35247611].","caveats":"Abstract-level support for binding; the curated species labels (human) differ from the mouse experiments. No affinity reported in our evidence. A second confirmed paper is not shown.","key_references":[{"PMID":"35247611","why":"SAA1 binds TLR4/MD2 and drives hepatic inflammation"}],"covers":["LR003244","LR006460"]},"LR001336":{"pair":"SCT -> VIPR1","headline":"Secretin acts at VPAC1 only with very low affinity; evidence is analogue binding and selectivity studies, so the pair is weak.","interaction_type":"conflicting","direction_and_effect":"Wild-type human VPAC1 displays very low affinity for secretin; secretin stimulates cAMP but the S/V ratio (EC50 secretin/EC50 VIP) is 300 [PMID:12133828]. GtoPdb records secretin as agonist [DB:GtoPdb].","molecular_requirements":"Selectivity is set by the N-terminal ectodomain: swapping it for the secretin receptor's gives S/V = 1.2, and the Gln135/Thr136 and Gly140/Ser141 pairs restrict secretin access [PMID:12133828].","affinity_potency":[{"value":"IC50 60 nM","assay":"binding of [R16]chicken secretin, a secretin-derived analogue","system":"human VIP1 receptor","cite":"PMID:9437714"},{"value":"IC50 1 nM","assay":"binding of the same analogue","system":"rat VIP1 receptor","cite":"PMID:9437714"}],"species_and_systems":"Human VPAC1-secretin chimeras in COS-7 cells [PMID:12133828]; binding on rat and human receptors with an analogue [PMID:9437714].","localisation_and_range":"Secretin is flagged secreted [flag].","caveats":"The affinity figures are for a modified chicken secretin analogue, not native secretin [PMID:9437714]. The main paper is about how VPAC1 excludes secretin, so this looks like low-affinity cross-reactivity [PMID:12133828]. Both papers were read as abstracts only.","key_references":[{"PMID":"12133828","why":"Shows VPAC1 has very low affinity for secretin and maps the filter"},{"PMID":"9437714","why":"Secretin-derived analogue binding at VIP1 receptors"}],"covers":["LR001336","LR004732"]},"LR003253":{"pair":"SDC1 -> ADGRA2","headline":"SDC1 guides were enriched in an ADGRA2 binding-probe CRISPRa screen; one screen, no direct binding test.","interaction_type":"functional only","direction_and_effect":"SDC1 and SDC2 guides were enriched in an ADGRA2 ligand selection, consistent with known ADGRA2-glycosaminoglycan interactions; effect direction is not reported in our evidence [PMID:30477585].","molecular_requirements":"Syndecans are heparan sulfate proteoglycans, so the interaction may depend on glycosaminoglycan chains [PMID:30477585]; not tested directly.","affinity_potency":[],"species_and_systems":"Genome-wide CRISPRa in cells selected with a recombinant ADGRA2 probe; a single screen was done per adhesion GPCR bait [PMID:30477585]. Species is not reported in our evidence.","localisation_and_range":"SDC1 is flagged secreted, receptor and transmembrane [flag].","caveats":"Enrichment of guides is indirect and could reflect glycosaminoglycan binding rather than a protein-protein ligand interaction. Not validated by purified-protein binding in our evidence.","key_references":[{"PMID":"30477585","why":"CRISPRa selection enriched SDC1 and SDC2 guides with ADGRA2 probe"}],"covers":["LR003253","LR006469"]},"LR003262":{"pair":"SEMA3A -> CNTN2","headline":"Direct Sema3A-Cntn2 binding was seen in one unbiased ectodomain screen; no other evidence.","interaction_type":"direct binding","direction_and_effect":"A pairwise screen of purified ectodomains detected a direct Sema3A-Cntn2 interaction in the absence of Nrp1, suggesting Sema3A may signal directly through Cntn2 [PMID:26633812]. Effect direction is not reported in our evidence.","molecular_requirements":"Nrp1 was not needed for the binding in the screen; earlier work cited by the authors held that Cntn2 touched Sema3A only indirectly via Nrp1 [PMID:26633812].","affinity_potency":[],"species_and_systems":"Purified ectodomain screen [PMID:26633812]; the curator labelled both partners human, while the paper's context is mouse retina and the human pair is inferred.","localisation_and_range":"Sema3A is secreted [flag]; Cntn2 carries a secreted flag [flag]. Range is not reported in our evidence.","caveats":"Single study, a screen with no affinity or functional test of this pair [PMID:26633812]. No database records.","key_references":[{"PMID":"26633812","why":"Unbiased biochemical screen finding direct Sema3A-Cntn2 binding"}],"covers":["LR003262","LR006478"]},"LR001345":{"pair":"SEMA3A -> PLXNA4","headline":"Direct binding screen plus functional and genetic data support SEMA3A signalling via PLXNA4, with NRP1 normally involved.","interaction_type":"direct binding","direction_and_effect":"A pairwise ectodomain screen detected direct Sema3A-PlxnA4 binding in the absence of Nrp1 [PMID:26633812]. PLXNA4 is upregulated in cortical interneurons and conveys SEMA3A repulsion [PMID:33503438]. In endothelial/glioblastoma cells Sema3A signalling depended on neuropilin-1, plexin-A1 and plexin-A4 [PMID:25335892]. Interaction class is stimulatory [flag].","molecular_requirements":"Sema3A may bind PlxnA4 directly without Nrp1 [PMID:26633812], yet functional work finds NRP1 required [PMID:25335892]; in mice Neuropilin-1 signalling is mediated principally by Plexin-A4 [PMID:15721238].","affinity_potency":[],"species_and_systems":"Screen with purified ectodomains (labelled human in dossier) [PMID:26633812]; mouse cortex [PMID:33503438]; human-labelled cells [PMID:25335892]; Plexin-A3/A4 double-mutant mouse neurons [PMID:15721238].","localisation_and_range":"SEMA3A is flagged as secreted and not transmembrane [flag], so it acts as a diffusible paracrine cue on membrane receptors. PLXNA4 is flagged transmembrane [flag].","caveats":"Functional papers [PMID:25335892][PMID:15721238] were read as abstracts only and concern the co-receptor complex. No affinity reported in our evidence.","key_references":[{"PMID":"26633812","why":"Direct Sema3A-PlxnA4 binding in a pairwise screen"},{"PMID":"33503438","why":"SEMA3A as PLXNA4 ligand in cortical interneurons"},{"PMID":"15721238","why":"Plexin-A4 mediates Neuropilin-1 Sema3A signalling in vivo"}],"covers":["LR001345","LR004741"]},"LR003271":{"pair":"SEMA3E -> PLXNB3","headline":"Sema3E binds Plexin B3-expressing cells and interacts genetically in zebrafish retinal axon guidance; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Either Sema3E or Sema3D bound to cells expressing Plexin B3 in an AP-tagged ligand binding assay in HEK293 cells [PMID:38628398]. Plexin B3 might function as a receptor for Sema3E in axon guidance [PMID:38628398].","molecular_requirements":"Neuropilin1 could be a co-receptor [PMID:38628398]; binding was stronger with Plexin B3 plus Neuropilin-1a, per the curator's note. Half-dose Plexin B3 plus Sema3E morpholinos gave up to more than 30% ipsilateral misprojections versus less than 5% each alone [PMID:38628398].","affinity_potency":[],"species_and_systems":"HEK293 binding assay and zebrafish embryos [PMID:38628398]. Both human and mouse pairs are ortholog-inferred.","localisation_and_range":"SEMA3E is annotated secreted and PLXNB3 transmembrane [flag].","caveats":"One paper; no affinity value; the authors say Plexin B3 'might' be the receptor, so in vivo causation is suggestive.","key_references":[{"PMID":"38628398","why":"Plexin B3 binds Sema3E and guides zebrafish retinal axons"}],"covers":["LR003271","LR006487"]},"LR001354":{"pair":"SEMA3F -> NRP2","headline":"SEMA3F binds NRP2, with direct binding and functional papers in neurons, T-cell precursors and tumour cells; well supported.","interaction_type":"direct binding","direction_and_effect":"NRP2 is reported as a high-affinity receptor for Sema IV (SEMA3F) but not Sema III, and mediates repulsive guidance [PMID:9331348][PMID:9856463]. SEMA3F-NRP2 signalling inhibits PI3K/Akt and mTOR/rictor assembly [PMID:26156437]. Anti-NRP2 antibody reversed SEMA3F inhibition of CXCL12-driven thymocyte migration [PMID:25068647].","molecular_requirements":"Plexin partners are needed for signalling: SEMA3F's effect on Akt/mTOR required NRP2/Plexin A1 complexes, since knockdown of either removed it [PMID:26156437]. Plexin-A3 is the principal plexin for NRP2-mediated signalling in mouse neurons [PMID:15721238]. NRP2 CUB/coagulation-factor domains confer Sema IV specificity [PMID:9856463].","affinity_potency":[],"species_and_systems":"Binding papers used human-labelled partners [PMID:9331348][PMID:9856463]; signalling work used human endothelial, T-cell and tumour cells plus xenografts [PMID:26156437] and human thymocytes [PMID:25068647]; plexin genetics used mouse neurons [PMID:15721238].","localisation_and_range":"SEMA3F is flagged secreted and NRP2 transmembrane [flag], so paracrine signalling to NRP2-expressing cells is implied. BioGRID lists a reconstituted complex [DB:BioGRID].","caveats":"Three of the key papers were read as abstracts only [PMID:9331348][PMID:9856463][PMID:26156437]. The 1997 paper is mostly about Sema IV naming, so SEMA3F identity rests on curator mapping. No affinity values are reported in our evidence.","key_references":[{"PMID":"9331348","why":"first report of high-affinity NRP2 binding to Sema IV, not Sema III"},{"PMID":"26156437","why":"SEMA3F-NRP2 signalling requires NRP2/Plexin A1; inhibits Akt/mTOR"},{"PMID":"25068647","why":"anti-NRP2 blocks SEMA3F effect on human thymocyte migration"}],"covers":["LR001354","LR004750"]},"LR001363":{"pair":"SEMA4D -> PLXNB2","headline":"Plexin-B2 is only a candidate Sema4D receptor, from one abstract-level binding report.","interaction_type":"direct binding","direction_and_effect":"Binding experiments indicate plexin-B2 as another receptor candidate for Sema4D, in addition to plexin-B1; Sema4D stimulated axonal outgrowth of embryonic DRG neurones, requiring endogenous NGF and Trk activation [PMID:15330859]. Curators label it agonist.","molecular_requirements":"Not reported in our evidence for plexin-B2 itself; the DRG effect depends on NGF/Trk activity [PMID:15330859].","affinity_potency":[],"species_and_systems":"Embryonic DRG neurones; species recorded as human but not stated in the abstract. Both pairs are ortholog-inferred. IntAct has a fluorescence-activated cell sorting record [DB:IntAct]; UniProt describes a cell surface receptor role for PLXNB1 and PLXNB2 [DB:UniProt].","localisation_and_range":"Sema4D flagged secreted and transmembrane [flag].","caveats":"The wording is hedged ('candidate') and the paper is abstract only. No affinity.","key_references":[{"PMID":"15330859","why":"Binding experiments suggest plexin-B2 as Sema4D receptor candidate"}],"covers":["LR001363","LR004759"]},"LR008032":{"pair":"SEMA5A -> MET:PLXNB3","headline":"Sema5A signals to Met through a plexin-B3 complex; one abstract-level functional paper.","interaction_type":"functional only","direction_and_effect":"Sema5A can trigger intracellular signalling of Met when it is associated in a complex with plexin-B3; plexin-B3 is reported as a high-affinity receptor specific for Sema5A (agonist) [PMID:15218527].","molecular_requirements":"Met signalling requires the Met/plexin-B3 complex per the abstract [PMID:15218527]. Reactome records SEMA5A:PLXNB3 complex and binding reaction [DB:Reactome].","affinity_potency":[],"species_and_systems":"Plexin-B3-expressing fibroblasts, epithelial and primary endothelial cells; human labels [PMID:15218527].","localisation_and_range":"Sema5A flagged transmembrane, not secreted [flag].","caveats":"Abstract only; no numeric affinity is given for 'high-affinity'. Binding to the Met:PLXNB3 complex was not separated from PLXNB3 alone.","key_references":[{"PMID":"15218527","why":"Sema5A triggers Met signalling via plexin-B3"}],"covers":["LR008032"]},"LR003280":{"pair":"SEMA5A -> PLXNA1","headline":"Mouse evidence is mixed: one abstract-only osteoclast study supports Sema5a-PlexinA1 binding, while a full-text hippocampal study argues against a functional role.","interaction_type":"conflicting","direction_and_effect":"Sema5a from osteocytes is reported to bind osteoclast Plexin A1 and activate PI3K/AKT/Myc signalling, driving bone resorption [PMID:41250977]. In hippocampal neurons, Sema5A-Fc binding was greatly reduced in Plxna1-/- neurons, but Plxna1-/- mice showed no significant spine-density increase (1.79 \u00b1 0.05 spines/\u00b5m vs WT 1.70 \u00b1 0.04), unlike Plxna2-/- (2.24 \u00b1 0.07) [PMID:25313870].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Both studies used mouse cells or animals (osteoclasts; hippocampal neurons and mice). Human and mouse pairs are in the dossier; the human pair is ortholog-inferred.","localisation_and_range":"Ligand is flagged membrane-bound (not secreted), so contact-dependent signalling is likely [flag].","caveats":"The positive paper was read as an abstract only and its assay is functional, not direct binding [PMID:41250977]. The hippocampal paper's abstract names PlexinA2, not PlexinA1, as the Sema5A receptor [PMID:25313870]. Plxna1 mRNA is virtually absent in dentate granule cells in that study [PMID:25313870].","key_references":[{"PMID":"41250977","why":"Osteocyte Sema5a reported to bind osteoclast Plexin A1 (abstract only)"},{"PMID":"25313870","why":"Sema5A-Fc binding reduced in Plxna1-/- neurons; no spine phenotype in Plxna1-/-"}],"covers":["LR003280","LR006496"]},"LR007402":{"pair":"SEMA6D -> PLXNA1:TREM2:TYROBP","headline":"Database-asserted only: Reactome and UniProt describe a SEMA6D receptor complex with PLXNA1, TREM2 and TYROBP; no paper in our evidence supports it directly.","interaction_type":"database-asserted only","direction_and_effect":"Reactome lists SEMA6D binding to PLXNA1:TREM2:DAP12 [DB:Reactome]. UniProt states that in dendritic cells SEMA6D has a receptor with PLEXNA1 as coreceptor, mediating CCR7 up-regulation and dendritic cell maturation and survival [DB:UniProt].","molecular_requirements":"UniProt says the interaction mediates SEMA6D binding and signalling through TYROBP (By similarity) [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human entities; no experiment in our evidence beyond what the records cite.","localisation_and_range":"Ligand flagged membrane-bound [flag]; TREM2 carries a secreted flag [flag].","caveats":"The only paper row is review_only; no curator-verified primary evidence, and the UniProt subunit line is by similarity.","key_references":[],"covers":["LR007402"]},"LR001372":{"pair":"SERPINA1 -> LRP1","headline":"Alpha1-antitrypsin-trypsin complex binds purified LRP1 and is internalised; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"The alpha1-antitrypsin-trypsin complex bound purified LRP, and binding was inhibited by RAP, an LRP antagonist; LRP-expressing fibroblasts internalised and degraded such complexes while LRP-deficient fibroblasts did not [PMID:8626456]. Curators label it agonist.","molecular_requirements":"The ligand is the serpin-enzyme complex; native or modified inhibitor forms alone were unable to bind LRP [PMID:8626456].","affinity_potency":[],"species_and_systems":"Human proteins as labelled; purified LRP, mouse embryonic fibroblasts, HepG2 cells and rat in vivo clearance (the in vivo rat data are shown for ATIII-thrombin, not this complex) [PMID:8626456].","localisation_and_range":"SERPINA1 is flagged secreted and LRP1 as a receptor [flag]; the complex acts as a clearance (endocytic) ligand.","caveats":"Free SERPINA1 is not shown to bind; evidence is for the trypsin complex only. One paper, read as abstract only. Other judged papers were abstract_insufficient or a different entity.","key_references":[{"PMID":"8626456","why":"Complex binding to LRP, RAP-inhibitable, with cellular uptake"}],"covers":["LR001372"]},"LR001381":{"pair":"SFRP1 -> FZD2","headline":"SFRP1 interacts with Frizzled-2 and acts through it to steer axon growth cones; one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"SFRP1 reoriented retinal ganglion cell axon growth, and Fz2 knockdown abolished growth cone responses, so the authors propose guidance via Fz2 [PMID:16172602]. Curators label the effect agonist although SFRP1 is classically a Wnt inhibitor.","molecular_requirements":"The activity did not require Wnt inhibition; intracellular signalling needs G(alpha) activation [PMID:16172602].","affinity_potency":[],"species_and_systems":"Chick and Xenopus laevis retinal ganglion cell axons [PMID:16172602]; dossier labels species human. Both human and mouse pairs here are ortholog-projected.","localisation_and_range":"SFRP1 is flagged secreted [flag]; acts as a diffusible guidance cue per the paper [PMID:16172602].","caveats":"Abstract says SFRP1 interacts with Fz2 but binding data are not reported in our evidence. One further row is pending.","key_references":[{"PMID":"16172602","why":"SFRP1 guides growth cones through Fz2"}],"covers":["LR001381","LR004776"]},"LR006511":{"pair":"SFTPA1 -> SIRPA","headline":"SP-A binds SIRPalpha through its globular heads and blocks proinflammatory signalling; one abstract-level paper plus Reactome.","interaction_type":"direct binding","direction_and_effect":"SP-A binds SIRPalpha through globular heads to initiate a signalling pathway that blocks proinflammatory mediator production; classified antagonist-like [PMID:14531999].","molecular_requirements":"Globular head domains mediate SIRPalpha binding; the same ligand uses collagenous tails for calreticulin/CD91 [PMID:14531999]. Reactome has an SIRPA:SFTPA oligomer complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human ligand and receptor listed; both species pairs ortholog-inferred [PMID:14531999].","localisation_and_range":"SIRPA is flagged transmembrane and SP-A secreted [flag].","caveats":"One paper, abstract only; affinity not reported in our evidence; generic SP-A.","key_references":[{"PMID":"14531999","why":"SP-A/SP-D bind SIRPalpha via globular heads to suppress inflammation"}],"covers":["LR003295","LR006511"]},"LR005305":{"pair":"SFTPD -> SIRPA","headline":"SP-D binds the D3 domain of SIRPalpha and signals anti-inflammatory; two abstract-level papers plus Reactome.","interaction_type":"direct binding","direction_and_effect":"Via the globular head SP-D binding to SIRPalpha blocks proinflammatory mediator production (antagonist-like) [PMID:14531999]. A second paper reports Ca2+- and carbohydrate-dependent binding to the membrane-proximal Ig domain D3, distinct from the CD47 site [PMID:22511785].","molecular_requirements":"SIRPalpha D3 domain with specific N-glycosylated residues is needed [PMID:22511785]. Reactome has SIRPA:SFTPD complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human ligand and receptor in both papers; mouse pair is ortholog-inferred.","localisation_and_range":"SIRPA is flagged transmembrane and SP-D secreted [flag].","caveats":"Both papers are abstract-only; no affinity reported.","key_references":[{"PMID":"22511785","why":"SP-D binds SIRPalpha D3 domain, Ca2+/carbohydrate-dependent"},{"PMID":"14531999","why":"Globular-head binding and anti-inflammatory signalling"}],"covers":["LR001975","LR005305"]},"LR007411":{"pair":"SHH -> GAS1:PTCH1","headline":"Complex GAS1:PTCH1 has one in vivo paper on GAS1 and database records for SHH-PTCH1; the complex itself is not tested.","interaction_type":"functional only","direction_and_effect":"GAS1 is described as a SHH co-receptor, and Gas1 gain and loss of function in neural crest mesenchyme alters cell number and jaw size [PMID:42484465]. UniProt: GAS1 transfers ShhN to PTCH1 or PTCH2 [DB:UniProt].","molecular_requirements":"The paper does not name PTCH1 [PMID:42484465]. SHH-PTCH1 binding is supported by structures [DB:PDB 6DMY] [DB:PDB 6E1H] and IntAct pull-down records [DB:IntAct].","affinity_potency":[],"species_and_systems":"Quail-duck chimeras; GAS1 is expressed 20-75-fold higher in duck than quail mandibular primordia [PMID:42484465]. In vivo avian embryos, not human cells.","localisation_and_range":"SHH is flagged secreted [flag]; the receptor is flagged transmembrane [flag], so signalling is paracrine to a membrane receptor. GAS1 is flagged not secreted [flag].","caveats":"Abstract-only. The paper reports expression and function of Gas1 in jaw size and does not show binding to SHH or PTCH1. One more paper was judged abstract-insufficient.","key_references":[{"PMID":"42484465","why":"Gas1 expression and function in SHH-dependent jaw size"}],"covers":["LR007411"]},"LR001390":{"pair":"SHH -> PTCH1","headline":"SHH binds PTCH1 directly, with structures, biochemical papers and database support; PTCH1 is the canonical receptor.","interaction_type":"direct binding","direction_and_effect":"Shh binding to PTCH is described as preventing PTCH inhibition of SMO [PMID:9811851]. Vertebrate Patched1 inhibition is caused by direct, palmitate-dependent interaction with Shh; a palmitoylated N-terminal fragment binds Patched1 and is sufficient to inhibit it [PMID:27647915]. UniProt: negative regulator of the smoothened pathway [DB:UniProt].","molecular_requirements":"The Shh N-terminal palmitoylated fragment binds, while the rest of Shh confers high-affinity binding [PMID:27647915]. UniProt: two PTCH1 molecules engage one hedgehog [DB:UniProt]; cryo-EM structures [DB:PDB 6DMY] [DB:PDB 6E1H].","affinity_potency":[],"species_and_systems":"PTCH binds all hedgehog family members with similar affinity and can form a complex with SMO [PMID:9811851]; Patched1 work with species unspecified [PMID:27647915]. Mouse pair is primary; human ortholog-inferred.","localisation_and_range":"SHH is flagged secreted [flag]; PTCH1 is a multitransmembrane receptor [PMID:9811851].","caveats":"Both papers are abstract-only. No numeric affinity in the dossier. Several other papers were abstract-insufficient, pending or review-only.","key_references":[{"PMID":"27647915","why":"Direct palmitate-dependent Shh-Patched1 binding"},{"PMID":"9811851","why":"PTCH and PTCH2 bind hedgehog proteins"}],"covers":["LR001390","LR004785"]},"LR006520":{"pair":"SIGLEC15 -> CD44","headline":"Siglec-15 interacts with CD44 in human hepatoma cells in a sialylation-dependent way; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Siglec-15 interacts with CD44 and promotes CD44 stability by preventing its lysosomal-mediated degradation, promoting hepatoma cell migration [PMID:34328657].","molecular_requirements":"Interaction depends on CD44 alpha2,6-linked sialic acids on N-glycans; removal of sialic acid suppressed the interaction [PMID:34328657].","affinity_potency":[],"species_and_systems":"Human hepatoma cells [PMID:34328657]. Mouse pair is ortholog-inferred.","localisation_and_range":"CD44 is flagged secreted [flag] and transmembrane [flag]; the paper treats it as a transmembrane glycoprotein [PMID:34328657]. SIGLEC15 not flagged secreted [flag].","caveats":"Abstract-only. The effect (stabilisation) is on the receptor protein, not classical ligand signalling. One review-only paper not shown. No affinity.","key_references":[{"PMID":"34328657","why":"Siglec-15 interacts with and stabilises CD44"}],"covers":["LR003306","LR006520"]},"LR003307":{"pair":"SIGLEC15 -> ITGAM","headline":"One full-text human study reports CD11b (ITGAM) as a sialic-acid-dependent Siglec-15 binding partner on T cells.","interaction_type":"direct binding","direction_and_effect":"Siglec-15-Fc bound CD11b/CD18 by ELISA and co-immunoprecipitation, and anti-CD11b blocking, CD11b knockdown and CD11b/CD18 overexpression changed Siglec-15 binding to human T cells [PMID:37311743]. Effect on signalling is not reported in our evidence (the curator labelled it agonist).","molecular_requirements":"A functional sialic-acid-binding domain is needed: the Siglec-15 R143A mutant bound CD11b much less [PMID:37311743]. CD11b and CD18 form a heterodimer; the assays used CD11b/CD18, so CD18 may be co-required, which is not tested separately in our evidence [PMID:37311743].","affinity_potency":[],"species_and_systems":"Human Siglec-15 and human T cells (CD4+, CD8+, n = 4 to 6 donors), plus recombinant proteins and STD-NMR [PMID:37311743]. Mouse pair is projected from human.","localisation_and_range":"Siglec-15 is annotated as membrane-bound [flag]; binding to CD11b is via sialylated N-glycans on T cells, so likely contact-dependent, but range is not tested.","caveats":"Single paper; the curator read only the abstract, though full-text excerpts are present. Binding depends on sialoglycans, and the interaction is a lectin-glycan one rather than a protein-protein one. No affinity reported.","key_references":[{"PMID":"37311743","why":"Siglec-15 binds CD11b/CD18 by ELISA, co-IP, STD-NMR and T-cell blocking assays"}],"covers":["LR003307","LR006521"]},"LR005314":{"pair":"SLIT2 -> APP","headline":"SLIT2 binds the APP E1 domain; one abstract-level paper supports APP as a Slit receptor.","interaction_type":"direct binding","direction_and_effect":"Slit binds APP through the E1 domain, triggering APP ectodomain shedding and FE65/Pak1/Rac1 signalling; APP loss abolishes Slit repulsion in olfactory explants [PMID:28785723].","molecular_requirements":"E1 domain of APP is the binding region [PMID:28785723]. Co-receptor needs not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse explants and knockouts, HEK293 co-culture, and C. elegans APL-1 genetics; the Slit2 used was Myc-tagged and expressed in HEK293 cells [PMID:28785723]. Dossier covers human and mouse pairs.","localisation_and_range":"SLIT2 is flagged secreted and APP flagged secreted and transmembrane [flag]; Slit2 was supplied by co-cultured cells and cell-surface binding was detected [PMID:28785723].","caveats":"Single paper; binding statement is taken from the abstract (read depth abstract only), and excerpts show expression and mutant phenotypes rather than binding data. No affinity.","key_references":[{"PMID":"28785723","why":"APP as Slit receptor, E1 binding, axon guidance"}],"covers":["LR001985","LR005314"]},"LR005323":{"pair":"SLITRK5 -> PTPRD","headline":"Slitrk5 binds PTPdelta through its LRR1 domain; one full-text paper with a Kd of about 100 nM in the curator notes.","interaction_type":"direct binding","direction_and_effect":"Slitrk5 binds PTPdelta through its LRR1 domain; under basal conditions it interacts mainly with PTPdelta, then shifts to cis-interaction with TrkB on BDNF [PMID:26004511].","molecular_requirements":"LRR1 domain of Slitrk5 is required [PMID:26004511].","affinity_potency":[{"value":"Kd ~100 nM","assay":"soluble PTPdelta-Fc binding to cells (curator note; not in excerpts)","system":"HEK293T expressing full-length Slitrk5","cite":"PMID:26004511"}],"species_and_systems":"HEK293T cells with soluble PTPdelta-Fc; neurons for TrkB work [PMID:26004511]. Mouse pair ortholog-inferred.","localisation_and_range":"Trans-synaptic (PTPdelta presynaptic) versus cis (TrkB) [PMID:26004511]; SLITRK5 flagged transmembrane [flag].","caveats":"Single paper; the Kd appears only in the curator notes, not in the supplied excerpts. A competing BDNF-induced cis-interaction with TrkB can displace PTPdelta binding [PMID:26004511].","key_references":[{"PMID":"26004511","why":"Slitrk5 LRR1 binding to PTPdelta"}],"covers":["LR001994","LR005323"]},"LR003316":{"pair":"SLPI -> ANXA2","headline":"SLPI binds annexin A2 (annexin II) on human macrophages by co-immunoprecipitation; a second paper reports an interaction from abstract only.","interaction_type":"direct binding","direction_and_effect":"SLPI acts as an antagonist: it disrupts the HIV-1 phosphatidylserine-annexin II interaction that supports macrophage infection [PMID:15545357]. In oral squamous cell carcinoma work, SLPI interacting with annexin A2 inhibits plasminogen activation and reduces plasmin generation [PMID:21641406].","molecular_requirements":"Annexin II was identified as the 36 kD SLPI-binding protein by LC-MS/MS and confirmed by coimmunoprecipitation; a ~42 kD band was actin, which associates with annexin II in a trimolecular complex rather than binding SLPI directly [PMID:15545357]. No other subunits reported in our evidence.","affinity_potency":[],"species_and_systems":"Human SLPI and human annexin II in primary human macrophages and monocytes [PMID:15545357]; human macrophages and OSCC cell lines [PMID:21641406]. Mouse pair is projected from human evidence.","localisation_and_range":"SLPI is flagged secreted and annexin A2 is also flagged secreted [flag]. Binding occurs at the macrophage cell surface membrane [PMID:15545357].","caveats":"The curator read both papers from abstract level; the second paper's interaction claim comes from the abstract only [PMID:21641406]. Annexin II binding was higher on macrophages than monocytes and absent on the U937 line [PMID:15545357]. The authors say additional SLPI targets are not ruled out [PMID:15545357]. Annexin A2 is not a classical signalling receptor, and no downstream signalling is reported in our evidence.","key_references":[{"PMID":"15545357","why":"Co-IP and mass spectrometry identify annexin II as the SLPI membrane-binding protein on human macrophages"},{"PMID":"21641406","why":"SLPI-annexin A2 interaction inhibits plasminogen activation in OSCC (abstract only)"}],"covers":["LR003316","LR006530"]},"LR010723":{"pair":"SLURP1 -> CHRNA4","headline":"Synthetic SLURP-1 inhibits alpha4beta4 nAChRs in functional assays; no direct binding shown for this subunit.","interaction_type":"functional only","direction_and_effect":"Synthetic SLURP-1 inhibits human alpha4beta4 nAChRs (antagonist). [PMID:29192197]","molecular_requirements":"Tested as the alpha4beta4 heteromer; alpha4 alone is not reported in our evidence [PMID:29192197].","affinity_potency":[],"species_and_systems":"Human receptors expressed heterologously (two-electrode voltage clamp), synthetic human SLURP-1 tested at 10 uM [PMID:29192197].","localisation_and_range":"SLURP1 is flagged secreted [flag]; the paper describes it as a secreted protein that co-localizes with nAChRs [PMID:29192197]. ","caveats":"Curator read abstract level only. The evidence is inhibition of ACh-evoked currents, not binding. Synthetic SLURP-1 did not compete with alpha-bungarotoxin at human alpha7 or muscle-type nAChRs and did not inhibit alpha7 currents without PNU120596; earlier recombinant SLURP-1 with extensions gave conflicting results [PMID:29192197].","key_references":[{"PMID":"29192197","why":"Chemically synthesized human SLURP-1 tested on nAChR subtypes"}],"covers":["LR010723"]},"LR003325":{"pair":"SMOC2 -> LRP6","headline":"One cancer-cell paper reports SMOC-2 co-immunoprecipitating with LRP6 and enhancing WNT signalling; support rests on a co-IP.","interaction_type":"direct binding","direction_and_effect":"By co-culture IP, SMOC-2 directly interacted with the WNT receptors Fzd6 and LRP6, enhanced ligand-receptor interaction with canonical WNT ligands (Wnt3a and Wnt10b) and activated the WNT/beta-catenin pathway in endometrial cancer [PMID:30594556]. This acts as a positive facilitator, not a classical WNT ligand, per the curator note.","molecular_requirements":"Fzd6 and LRP6 were both reported as interactors, so a FZD-LRP complex may be involved; whether LRP6 alone is sufficient is not reported [PMID:30594556].","affinity_potency":[],"species_and_systems":"Species: not stated for the co-culture IP in our excerpts; endometrial cancer cell lines (AN3CA, Ishikawa, HEC-1A, ECC-1) and mouse xenografts were used elsewhere in the paper [PMID:30594556]. The mouse pair is projected from human evidence.","localisation_and_range":"SMOC2 is flagged as secreted and as a receptor [flag]; LRP6 is flagged as a receptor [flag]. Paracrine or autocrine range is not tested in our evidence.","caveats":"Evidence is a co-culture IP in cancer cells; 'directly' is the authors' wording and affinity is not reported. The excerpts available to us are mostly general statements. Only one paper.","key_references":[{"PMID":"30594556","why":"Co-IP of SMOC-2 with Fzd6 and LRP6 and WNT pathway activation in endometrial cancer"}],"covers":["LR003325","LR006532"]},"LR005332":{"pair":"SPON1 -> APP","headline":"F-spondin binds the extracellular domain of APP and inhibits its beta-secretase cleavage; one abstract-level paper plus IntAct.","interaction_type":"direct binding","direction_and_effect":"F-spondin binds the conserved central extracellular domain of APP and inhibits beta-secretase cleavage of APP [PMID:14983046]. Effect: antagonist-like on processing; presented as the first functionally active extracellular APP ligand.","molecular_requirements":"Binds the central extracellular domain of APP [PMID:14983046].","affinity_potency":[],"species_and_systems":"Human proteins per curator record; IntAct pull-down records cite this paper [DB:IntAct]. Mouse pair ortholog-inferred.","localisation_and_range":"F-spondin is secreted and APP is a membrane protein [flag]; acts at the cell surface.","caveats":"Abstract only; no affinity; APP is more a precursor than a classical signalling receptor.","key_references":[{"PMID":"14983046","why":"F-spondin binds APP extracellular domain, inhibits beta-secretase cleavage"}],"covers":["LR002004","LR005332"]},"LR008230":{"pair":"SPON2 -> ITGA5:ITGB1","headline":"SPON2-alpha5beta1 signalling inhibits HCC cell migration; one abstract.","interaction_type":"functional only","direction_and_effect":"SPON2-alpha5beta1 integrin signalling inactivated RhoA and prevented F-actin assembly, inhibiting HCC cell migration; the Hippo pathway was not noticeably involved [PMID:29440144]. Antagonist.","molecular_requirements":"The alpha5beta1 heterodimer is the receptor in this report [PMID:29440144].","affinity_potency":[],"species_and_systems":"Hepatocellular carcinoma context; species per curator human [PMID:29440144].","localisation_and_range":"SPON2 flagged secreted [flag]; matrix protein acting on cell-surface integrin.","caveats":"Abstract only; physical binding not shown.","key_references":[{"PMID":"29440144","why":"SPON2-alpha5beta1 inhibits HCC migration"}],"covers":["LR008230"]},"LR004801":{"pair":"SPP1 -> ITGA5","headline":"SPP1 activates integrin alpha5beta1 in rat nucleus pulposus cells; one full-text functional paper and database complexes.","interaction_type":"functional only","direction_and_effect":"SPP1 accelerates nucleus pulposus cell degeneration by activating integrin alpha5beta1, aggravating mitochondrial damage and inhibiting mitophagy via PINK1/PARKIN blockade [PMID:39721032].","molecular_requirements":"The receptor is alpha5beta1 (ITGA5/ITGB1) [PMID:39721032]. The ITGA5 entity is annotated as integrin alpha5beta1 [flag]. Reactome lists SPP1 with alpha5beta1 and alpha9beta1 [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human degenerated discs showed elevated SPP1 and ITGA5; rat nucleus pulposus cells were used for SPP1 knockdown experiments [PMID:39721032].","localisation_and_range":"SPP1 is flagged secreted and not transmembrane [flag]; ITGA5 not secreted [flag].","caveats":"The paper is a disease-mechanism study; the excerpts shown do not include a direct binding assay. Read with abstract plus excerpts only. Binding evidence sits in the ITGA5:ITGB1 dossier.","key_references":[{"PMID":"39721032","why":"SPP1-ITGA5/B1 axis inhibits mitophagy in nucleus pulposus cells"}],"covers":["LR001406","LR004801"]},"LR007060":{"pair":"SPP1 -> ITGA9:ITGB1","headline":"Osteopontin engages alpha9beta1 through a cryptic site exposed by thrombin cleavage; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"The osteopontin N-terminal fragment supports adhesion of a melanoma line that cannot bind native osteopontin, and a cryptic adhesive sequence distinct from RGD was identified [PMID:8910476].","molecular_requirements":"Thrombin cleavage exposes the cryptic alpha9beta1 site [PMID:8910476]; the abstract text shown is truncated before naming alpha9beta1 explicitly.","affinity_potency":[],"species_and_systems":"Human cell-line adhesion assays with GST-osteopontin fragments [PMID:8910476].","localisation_and_range":"SPP1 is flagged secreted and not transmembrane [flag]; conditional on cleavage state.","caveats":"Abstract-only and truncated; the evidence sentence is general background. Reactome lists alpha5beta1, alpha9beta1 reaction records citing this paper [DB:Reactome]. Two further papers were abstract_insufficient.","key_references":[{"PMID":"8910476","why":"Cryptic thrombin-exposed site in osteopontin engaging alpha9beta1"}],"covers":["LR007060"]},"LR001408":{"pair":"SPP1 -> ITGAV","headline":"Osteopontin binds alphaV integrins (alphavbeta1, beta3, beta5, beta6); nanomolar affinities reported for beta1 and beta5.","interaction_type":"direct binding","direction_and_effect":"Osteopontin is a receptor ligand for alphavbeta1 and alphavbeta5 in adhesion assays [PMID:7592829]; alphavbeta6 is an additional receptor [PMID:16005200]; PC3 cell adhesion and migration on osteopontin are alphavbeta3-dependent and activate PI 3-kinase/AKT [PMID:10835423].","molecular_requirements":"alphaV pairs with different beta chains; alphavbeta3, beta5 and beta6 bind the RGD site, with thrombin cleavage not needed; alphavbeta5/beta6 adhesion also depends on two aspartates upstream of RGD [PMID:16005200]. Mg2+ and Mn2+ support binding, Ca2+ does not [PMID:7592829].","affinity_potency":[{"value":"18 nM","assay":"GST-OPN binding to alphavbeta1 in Mn2+","system":"HEK293 cells, human recombinant OPN","cite":"PMID:7592829"},{"value":"48 nM","assay":"GST-OPN binding to alphavbeta5 in Mn2+","system":"HEK293 cells transfected with beta5","cite":"PMID:7592829"}],"species_and_systems":"Human cells and recombinant human OPN [PMID:7592829]; prostate cancer PC3 and LNCaP cells [PMID:10835423].","localisation_and_range":"SPP1 is flagged secreted and not transmembrane [flag]; ITGAV is a receptor [flag].","caveats":"All three papers are abstract-only. Affinity is for alphavbeta1 and alphavbeta5, not alphavbeta3. Binding to beta3 in LNCaP required EGF activation [PMID:10835423]. Reactome lists the alphaVbeta3:SPP1 complex [DB:Reactome].","key_references":[{"PMID":"7592829","why":"Affinities for alphavbeta1 and alphavbeta5"},{"PMID":"16005200","why":"alphavbeta6 and RGD dependence"},{"PMID":"10835423","why":"alphavbeta3-dependent migration on osteopontin"}],"covers":["LR001408","LR004803"]},"LR008221":{"pair":"SPP1 -> ITGAV:ITGB5","headline":"alphavbeta5 is named among osteopontin integrins in one paper's background; this paper did not test it.","interaction_type":"database-asserted only","direction_and_effect":"The only paper cited lists alphavbeta5 among osteopontin integrins as a summary of prior work [PMID:10673366].","molecular_requirements":"not reported in our evidence beyond the complex pairing alphaV with beta5.","affinity_potency":[],"species_and_systems":"Paper itself used K562 cells with alpha5beta1 [PMID:10673366].","localisation_and_range":"SPP1 is flagged secreted and not transmembrane [flag]; matrix-adhesion context only.","caveats":"Support is a background statement in a paper whose finding is alpha5beta1. BioGRID lists SPP1-ITGB5 reconstituted complex [DB:BioGRID]; Reactome lists alphaVbeta3:SPP1 [DB:Reactome].","key_references":[{"PMID":"10673366","why":"Background list including alphavbeta5"}],"covers":["LR008221"]},"LR005341":{"pair":"ST6GAL1 -> CD22","headline":"CD22 binds cell-surface ST6GAL1 (CD75) on activated B cells, shown by a single 1991 abstract-level study.","interaction_type":"direct binding","direction_and_effect":"CD22 recognises CD75, a cell-surface alpha 2-6 sialyltransferase, as a second ligand, expressed mainly on activated B cells [PMID:1717156]. Agonist or antagonist effect is not reported in our evidence.","molecular_requirements":"Not reported in our evidence. The CD22 beta polypeptide was the form that interacted with CD45RO on CD4+ T cells in the same study [PMID:1717156].","affinity_potency":[],"species_and_systems":"Human ligand and receptor [PMID:1717156]. The mouse entry is projected from human evidence.","localisation_and_range":"ST6GAL1 is flagged secreted [flag], but the paper describes it as a cell-surface enzyme on B cells, so contact (juxtacrine) signalling is suggested [PMID:1717156].","caveats":"One paper read as abstract only; the second confirmed row is not shown. The ligand is an enzyme recognised via its CD75 glycan identity; whether protein or glycan epitope is bound is not stated. No databases support the pair.","key_references":[{"PMID":"1717156","why":"CD22 recognises CD75 (alpha 2-6 sialyltransferase) on activated B cells"}],"covers":["LR002013","LR005341"]},"LR004810":{"pair":"TAC1 -> TACR1","headline":"Tachykinins from TAC1 (substance P, neurokinin A) bind and activate NK1/TACR1 with nanomolar affinity; strongly supported by binding, structures and databases.","interaction_type":"direct binding","direction_and_effect":"Agonist. Substance P binds NK1 saturably with high affinity [PMID:1311270]. Neurokinin A also binds NK-1 with high affinity, though it competes poorly against radiolabelled substance P [PMID:8985159]. GtoPdb records full agonist [DB:GtoPdb]. In NT2-N neuronal cells SP/NK-1R signalling regulates MIP-1beta [PMID:12548712].","molecular_requirements":"Single receptor chain. Chimeric human NK1/NK3 receptors showed conserved C-terminal tachykinin sequences matter for binding [PMID:8702757]. Structures of TACR1 with TAC1 peptide are in PDB [DB:PDB 2KS9][DB:PDB 7P00]; Reactome lists TACR1:TAC1(58-68) [DB:Reactome].","affinity_potency":[{"value":"Kd = 0.17 nM","assay":"radiolabelled substance P saturation binding","system":"stable CHO clones expressing rat NK1","cite":"PMID:1311270"},{"value":"Kd=0.51nM","assay":"homologous binding of radiolabelled NKA","system":"cloned NK-1 receptor in COS-7 cells","cite":"PMID:8985159"},{"value":"Ki=0.13 nM","assay":"SP, [3H]-substance P competition","system":"human NK1","cite":"PMID:11786503"}],"species_and_systems":"Mostly recombinant human receptors (COS-7, HEK) [PMID:8985159][PMID:11786503][PMID:8702757]; rat receptors in CHO cells [PMID:1311270]; human NT2-N cells [PMID:12548712]. Mouse pair is projected from human.","localisation_and_range":"TAC1 is flagged secreted and TACR1 transmembrane, implying paracrine or neuronal signalling [flag].","caveats":"All shown papers are abstract-level. Dossier ligand is labelled neurokinin A but most evidence uses substance P; NKA is a lower-potency NK1 ligand than SP in competition [PMID:8985159]. The NT2-N paper shows co-expression and functional coupling, not binding [PMID:12548712]. Rat Kd for NKA (3.4 nM) in PMID:1311270 is at NK2, not NK1.","key_references":[{"PMID":"8985159","why":"NKA and septide bind NK-1 with high affinity"},{"PMID":"1311270","why":"SP binding to rat NK1 in stable CHO clones"},{"PMID":"11786503","why":"SP Ki at human NK1"}],"covers":["LR001415","LR004810"]},"LR001417":{"pair":"TAC1 -> TACR3","headline":"Neurokinin A (TAC1) is a low-affinity agonist of the NK3 receptor (TACR3); one abstract-only paper plus GtoPdb and UniProt.","interaction_type":"direct binding","direction_and_effect":"Agonist with low receptor affinity per UniProt [DB:UniProt]; GtoPdb lists a full agonist [DB:GtoPdb]. Binding and Ca2+ mobilisation were similar in HEK293 cells expressing murine or human NK3 receptor, with substance P and neurokinin A more potent in the murine NK3 cells [PMID:11226387].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"pKi 5.5-6.3","assay":"curated agonist affinity range","system":"GtoPdb record","cite":"DB:GtoPdb"}],"species_and_systems":"HEK293 cells expressing murine or human NK3 receptor [PMID:11226387]. The mouse pair is projected from human evidence.","localisation_and_range":"TAC1 is flagged secreted and TACR3 transmembrane [flag]; range not otherwise reported.","caveats":"Abstract only. The curators note NK3's preferred ligand is neurokinin B (TAC3) and this is cross-reactivity [PMID:11226387]. The paper's affinity numbers for NKA are not in the abstract.","key_references":[{"PMID":"11226387","why":"Binding and Ca2+ responses to tachykinin agonists at murine and human NK3"}],"covers":["LR001417","LR004812"]},"LR003343":{"pair":"TAFA1 -> NRXN1","headline":"FAM19A1 (TAFA1) binds neurexins through a disulfide-linked complex with the cysteine-loop domain; full text read.","interaction_type":"direct binding","direction_and_effect":"Not a classical agonist. FAM19A1-A4 bind the cysteine-loop domain of neurexins and form intermolecular disulfide bonds during transport; FAM19A1 expression decreased neurexin O-glycosylation and heparan sulfate modification in hippocampal cultures [PMID:32706374].","molecular_requirements":"Binding needed the cysteines of the cysteine-loop domain and an adjacent sequence; deleting the cysteine-loop of Nrxn1beta abolished FAM19A binding; all neurexins except neurexin-1gamma interact [PMID:32706374].","affinity_potency":[],"species_and_systems":"Co-IP in HEK293T cells with recombinant FAM19A and Nrxn1beta-ECD; endogenous complexes purified from adult mouse brain; hippocampal cultures [PMID:32706374].","localisation_and_range":"TAFA1 flagged secreted and NRXN1 transmembrane [flag]; the complex forms in the secretory pathway, so the paper suggests regulation of neurexin modification, not canonical paracrine signalling [PMID:32706374].","caveats":"Covalent binding mechanism is unusual and may not behave like standard ligand-receptor signalling. Neurexin-1gamma does not bind [PMID:32706374]. No affinity reported; experiments were largely mouse and recombinant.","key_references":[{"PMID":"32706374","why":"FAM19A/TAFA proteins as neurexin-binding regulators"}],"covers":["LR003343","LR006550"]},"LR003352":{"pair":"TAFA4 -> NRXN1","headline":"TAFA4 (FAM19A4) binds neurexins, including NRXN1; one paper, recombinant and mouse brain work.","interaction_type":"direct binding","direction_and_effect":"FAM19A1-A4 bind neurexins other than neurexin-1\u03b3 [PMID:32706374]. Recombinant FAM19A4 was detected on the surface of HEK293T cells with neurexins [PMID:32706374]. The authors argue neurexins are the predominant binding partners of FAM19A1-A4 and ask how this fits with FAM19A4 as an FPR1 ligand [PMID:32706374].","molecular_requirements":"FAM19A1-A4 bind the cysteine-loop domain of neurexins by forming intermolecular disulfide bonds; both the cysteines and an adjacent neurexin sequence were required [PMID:32706374]. FAM19A5 does not bind [PMID:32706374].","affinity_potency":[],"species_and_systems":"Recombinant proteins in HEK293T cells; neurexin complexes from mouse brain were analysed for FAM19A1 and FAM19A2 [PMID:32706374]. Human pair projected from mouse evidence.","localisation_and_range":"TAFA4 annotated secreted; NRXN1 annotated transmembrane [flag].","caveats":"Supported by one paper read as an abstract plus full-text excerpts; the abstract states that neurexin-1\u03b3 is the exception [PMID:32706374]. Binding is covalent and forms during transit through the secretory pathway, which is unusual for a ligand-receptor pair. A separate report proposes FPR1 as the FAM19A4 receptor [PMID:32706374].","key_references":[{"PMID":"32706374","why":"FAM19A1-A4 bind neurexins via disulfide linkage"}],"covers":["LR003352","LR006555"]},"LR007420":{"pair":"TENM3 -> ADGRL3","headline":"Supported only by a UniProt similarity-based subunit note; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect: not reported in our evidence.","molecular_requirements":"UniProt notes the receptor interacts via its extracellular domain with TENM3, by similarity [DB:UniProt].","affinity_potency":[],"species_and_systems":"No experiment in our evidence; the UniProt statement is 'by similarity' [DB:UniProt].","localisation_and_range":"Both partners carry a transmembrane flag [flag], which would imply contact-dependent signalling; not tested in our evidence.","caveats":"No paper was verified for this pair (judged papers: 0; review-only and abstract-insufficient reads exist but are not usable). The only support is a by-similarity database note.","key_references":[],"covers":["LR007420"]},"LR003361":{"pair":"TENM4 -> ADGRL1","headline":"Direct binding shown by pulldown of teneurin-4 with latrophilin-1 in one full-text paper; no affinity for this pair.","interaction_type":"direct binding","direction_and_effect":"Teneurin-4 (Ten4) binds latrophilin-1 (Lphn1) in pulldowns; Ten1 did not bind. The paper reports that teneurin binding mediates cell adhesion, consistent with trans-synaptic adhesion rather than classic agonist signalling [PMID:24273166].","molecular_requirements":"Binding is to the lectin-like domain of latrophilins; Ten4 bound all Lphn1 constructs tested. Alternative splicing of latrophilin-1 modulates teneurin binding [PMID:24273166].","affinity_potency":[],"species_and_systems":"Pulldown with purified Lphn1-Ig fusion proteins and immobilized teneurin ectodomains, HEK293T-derived; species of ligand and receptor unspecified. The mouse pair is projected from human evidence (ortholog-inferred) [PMID:24273166].","localisation_and_range":"Both partners have transmembrane flags [flag], so interaction is likely cell-contact (juxtacrine). The abstract says nanomolar affinity for teneurin-latrophilin binding in general; no value is given for Ten4/Lphn1 in our evidence [PMID:24273166].","caveats":"Curator quote came from a browser read and is marked unverifiable (spot-check pending); only the abstract is stored. Ten4 is also flagged as a receptor.","key_references":[{"PMID":"24273166","why":"Pulldown of Ten4 with Lphn1; teneurin-latrophilin cell adhesion"}],"covers":["LR003361","LR006564"]},"LR001435":{"pair":"TGFA -> EGFR","headline":"Well supported: co-crystal structure of TGFalpha with the EGFR ectodomain, plus kinase activation by the TGFalpha precursor.","interaction_type":"direct binding","direction_and_effect":"TGFalpha binds EGFR; a 17-19 kDa TGFalpha precursor binds EGF/TGF-alpha receptors and activates receptor-associated tyrosine kinase activity in intact cells [PMID:3018723].","molecular_requirements":"In the 2.5 A structure, a 2:2 TGFalpha:sEGFR501 complex, each ligand contacts one receptor molecule via L1 and L2 domains; the back-to-back dimer is favoured as biologically relevant [PMID:12297049].","affinity_potency":[],"species_and_systems":"Truncated human EGFR ectodomain crystal structure [PMID:12297049]; retrovirus-transformed rat cells for the precursor [PMID:3018723]. Mouse pair is ortholog-inferred. PDB 1MOX is listed [DB:PDB 1MOX].","localisation_and_range":"Ligand is annotated both secreted and transmembrane [flag]; the precursor was released as a soluble protein from transformed rat cells [PMID:3018723].","caveats":"Abstracts only. No affinity value is in our evidence; GtoPdb has a binding record with pKi units but no value shown [DB:GtoPdb].","key_references":[{"PMID":"12297049","why":"Crystal structure of TGFalpha bound to EGFR ectodomain"},{"PMID":"3018723","why":"TGFalpha precursor binds and activates EGFR"}],"covers":["LR001435","LR004830"]},"LR003370":{"pair":"TGFB1 -> ITGB1","headline":"Only adhesion of alpha8beta1 cells to LAP-TGFbeta1; ITGB1 evidence is indirect.","interaction_type":"functional only","direction_and_effect":"alpha8-transfected cells adhere to recombinant LAP-TGFbeta1 better than mock cells [PMID:12415008].","molecular_requirements":"The paper concerns alpha8beta1; beta1 is the partner chain, and alpha8 is required here [PMID:12415008]. Beta1 activating antibody 8A2 enhanced adhesion per curator notes [PMID:12415008].","affinity_potency":[],"species_and_systems":"Species not reported in our evidence; transfected cell lines [PMID:12415008].","localisation_and_range":"TGFB1 is flagged secreted [flag]. Receptor localisation not reported in our evidence.","caveats":"The same paper supports ITGA8; beta1 alone is not shown to bind. Latent LAP form assayed, read as abstract only. No database records.","key_references":[{"PMID":"12415008","why":"alpha8beta1 adhesion to LAP-TGFbeta1"}],"covers":["LR003370","LR006571"]},"LR001444":{"pair":"TGFB1 -> TGFBR2","headline":"Canonical type II receptor, but the one curated paper concerns ALK1 binding; most support comes from databases.","interaction_type":"direct binding","direction_and_effect":"The curated paper shows ALK1 in endothelial cells binds TGF-beta1 and TbetaR-II [PMID:10716993]. GtoPdb lists agonist [DB:GtoPdb]; records include SPR, co-IP and cross-linking [DB:IntAct] and structures [DB:PDB 3KFD].","molecular_requirements":"Type I receptor partner not specified in this dossier beyond ALK1 in the paper [PMID:10716993].","affinity_potency":[],"species_and_systems":"Mouse cells and knockout mice [PMID:10716993]; human pair is ortholog-inferred.","localisation_and_range":"TGFB1 is flagged secreted [flag]. Receptor localisation not reported in our evidence.","caveats":"The paper does not test TGF-beta1 binding to TbetaR-II itself; abstract only. Two review-only papers excluded. Main support is from databases [DB:BioGRID].","key_references":[{"PMID":"10716993","why":"ALK1 binds TGF-beta1 and TbetaR-II in endothelial cells"}],"covers":["LR001444","LR004839"]},"LR001453":{"pair":"TGFB3 -> TGFBR3","headline":"TGF-beta3 binds betaglycan (TGFBR3), a co-receptor, in purified-protein SPR assays; well supported but abstract-level for most evidence.","interaction_type":"direct binding","direction_and_effect":"Betaglycan is a coreceptor for TGF-beta superfamily members [PMID:19842711]. GtoPdb lists the interaction as agonist [DB:GtoPdb]. Soluble betaglycan blocks TGF-beta activity [PMID:19842711].","molecular_requirements":"Betaglycan has two independent ligand-binding regions, membrane-distal and membrane-proximal, and the 45 and 55 kDa fragments each bind TGF-beta but neutralise poorly; tethering the domains gives high affinity [PMID:19842711]. The type III ectodomain bound two TGF-beta molecules [PMID:11382746].","affinity_potency":[{"value":"Kd low nanomolar range (soluble betaglycan, three TGF-beta isoforms)","assay":"SPR","system":"soluble betaglycan","cite":"PMID:19842711"}],"species_and_systems":"Soluble betaglycan was rat and expressed in insect cells; fragment labelling used 125I-TGF-beta2, not beta3 [PMID:19842711]. Species in [PMID:11382746] unspecified.","localisation_and_range":"Betaglycan is flagged transmembrane [flag]; soluble forms also bind [PMID:19842711].","caveats":"Direct-binding data are for betaglycan alone; signalling-receptor requirements are not reported in our evidence. Species is rat for the main paper; the pair is human.","key_references":[{"PMID":"19842711","why":"Two binding domains in betaglycan, SPR Kd"},{"PMID":"11382746","why":"SPR with type III receptor ectodomain"}],"covers":["LR001453","LR004848"]},"LR008311":{"pair":"TGFBR3 -> FGFR4","headline":"No curated paper supports this receptor-receptor pair; the only record is an IntAct SPR entry.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct lists a surface plasmon resonance experiment [DB:IntAct]; species and system are not reported in our evidence.","localisation_and_range":"Both partners are flagged transmembrane receptors [flag]; contact-dependent interaction is only a guess from flags.","caveats":"No papers were judged; the two candidate papers were abstract_insufficient or different_entity. This pair rests on one database record and is not a classical ligand-receptor pair.","key_references":[],"covers":["LR008311"]},"LR001462":{"pair":"THBS1 -> CD36","headline":"Well-supported: THBS1 is a ligand of CD36 with gain/loss-of-function, co-IP, peptide and knockout evidence; effects vary by context.","interaction_type":"direct binding","direction_and_effect":"Sense CD36 transfection gave TSP binding and antisense removed it, supporting a TSP receptor role [PMID:1379600]. THBS1 interacts with CD36 and inhibits cAMP signalling and trophoblast fusion, abolished by a CD36-blocking antibody [PMID:33997182]. TSP-1 ligation of CD36 on monocytes inhibits lymphangiogenesis [PMID:21536744]. CD36 blocking antibody inhibited latent TGF-beta1 activation [PMID:10487979]. The CSVTCG peptide stimulates osteoclast resorption [PMID:10772961].","molecular_requirements":"The CD36-binding region of TSP-1 is represented by CSVTCG [PMID:10772961]. Binding was 1:1 with CD36 expression [PMID:1379600].","affinity_potency":[],"species_and_systems":"Human melanoma cells [PMID:1379600]; human BeWo cells [PMID:33997182]; mouse corneas [PMID:21536744]; rat alveolar macrophages [PMID:10487979]; avian osteoclasts [PMID:10772961].","localisation_and_range":"THBS1 is flagged secreted and CD36 transmembrane [flag]; TSP-1 acts on platelets and cell surfaces [PMID:1379600].","caveats":"Effects are inhibitory or stimulatory depending on cell type, so direction is context dependent. Most papers were read as abstracts. In [PMID:10772961] and [PMID:10487979] CD36 involvement is functional, not direct binding.","key_references":[{"PMID":"1379600","why":"Gain and loss of function show CD36 binds TSP"},{"PMID":"33997182","why":"THBS1-CD36 co-IP, cAMP inhibition"},{"PMID":"21536744","why":"TSP-1 ligation of CD36 in vivo"}],"covers":["LR001462","LR004857"]},"LR001471":{"pair":"THBS1 -> SDC1","headline":"Syndecan-1 supports cell spreading and fascin-spike formation on THBS1 in transfection assays; functional evidence, not direct binding.","interaction_type":"functional only","direction_and_effect":"Syndecan-1 transfection of COS-7 cells is sufficient to stimulate spreading and fascin spike assembly on TSP-1 [PMID:11257118]. It is necessary for spreading and spike formation by C2C12 cells on TSP-1 in the VC2-deletion and GAG-negative mutant experiments [PMID:11257118]. Stimulatory effect.","molecular_requirements":"Requires glycosaminoglycan modification at S45 or S47 for spreading and the cytoplasmic VC2 region for spreading and spike formation [PMID:11257118]. Syndecan-2 in COS-7 stimulated spreading but not fascin spikes [PMID:11257118].","affinity_potency":[],"species_and_systems":"Mouse syndecan-1 in green monkey COS-7 and C2C12 cells, TSP-1 as substrate [PMID:11257118]; curated species human, mouse ortholog-inferred. Full text was available.","localisation_and_range":"THBS1 flagged secreted; acts as immobilised matrix substrate, so matrix-contact signalling [flag] [PMID:11257118]. SDC1 carries both secreted and transmembrane flags [flag].","caveats":"No direct physical binding shown in the dossier; antibody ligation and transfection only. One review-only row excluded.","key_references":[{"PMID":"11257118","why":"Syndecan-1 sufficient/necessary for fascin spikes on TSP-1"}],"covers":["LR001471","LR004866"]},"LR006601":{"pair":"TIMP1 -> CD74","headline":"TIMP-1 shown to bind CD74 by co-IP and confocal microscopy and to trigger ZAP-70 activation; one paper, abstract plus excerpts.","interaction_type":"direct binding","direction_and_effect":"TIMP-1 and CD74 interacted by co-immunoprecipitation and confocal microscopy in CD74-overexpressing cells, and in Namalwa B-lymphoma cells with endogenous CD74 (dot blot and confocal). TIMP-1 binding triggered intracellular ZAP-70 activation, and a synthetic peptide interfering with the CD74 cytokine-binding site abrogated it, consistent with an activating effect [PMID:34391782].","molecular_requirements":"N-terminal TIMP-1 domain (N-TIMP-1) lacking the C-terminal domain was sufficient to bind CD74 and to induce ZAP-70 activation [PMID:34391782]. Co-receptors are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human recombinant TIMP-1 on CD74-overexpressing LX-2 cells and Namalwa B-lymphoma cells; mouse pair is ortholog-inferred [PMID:34391782].","localisation_and_range":"TIMP1 flagged secreted; CD74 flagged transmembrane receptor [flag].","caveats":"Single paper; docking was in silico and the binding evidence is qualitative with no affinity reported. Dossier gives no independent replication.","key_references":[{"PMID":"34391782","why":"TIMP-1-CD74 binding and ZAP-70 activation"}],"covers":["LR003400","LR006601"]},"LR001480":{"pair":"TIMP3 -> AGTR2","headline":"TIMP-3 identified as binding AGTR2 by yeast two-hybrid and co-IP records; functional data suggest additive anti-angiogenic action.","interaction_type":"direct binding","direction_and_effect":"A human ovary cDNA two-hybrid screen identified AGTR2 as a TIMP-3-interacting partner; combined TIMP-3 and AGTR2 treatment additively inhibited VEGF-induced HUVEC proliferation and blocked the inhibition of Akt and eNOS phosphorylation [PMID:18344519]. BioGRID and IntAct list two-hybrid and co-IP records from the same paper [DB:BioGRID][DB:IntAct].","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human cDNA library, HUVECs and an ovarian cancer experimental model [PMID:18344519]; mouse pair is ortholog-inferred.","localisation_and_range":"TIMP3 is flagged secreted; AGTR2 flagged transmembrane receptor [flag].","caveats":"Single paper read as abstract; all database records derive from it. No affinity reported, and whether TIMP-3 binds the AGTR2 ligand-binding site is not reported in our evidence.","key_references":[{"PMID":"18344519","why":"Two-hybrid identification and functional study"}],"covers":["LR001480","LR004875"]},"LR003406":{"pair":"TIMP3 -> LRP1","headline":"TIMP-3 binds LRP-1 with high affinity by SPR and bridges metalloproteinases to it; endocytic receptor interaction.","interaction_type":"direct binding","direction_and_effect":"TIMP-3 bound LRP-1 with the highest affinity among proteins tested, and also bridged MMP-1, MMP-13 and MMP-14 to LRP-1, facilitating metalloproteinase clearance [PMID:32694578]. LRP-1 acts as an endocytic receptor here [PMID:32694578].","molecular_requirements":"Complex with MMP-1 binds with higher affinity: free MMP-1 KD 34.6 nM versus MMP-1/TIMP-3 4.96 nM [PMID:32694578]. TIMP-3 alone suffices for binding.","affinity_potency":[{"value":"KD 1.68 nM","assay":"surface plasmon resonance","system":"TIMP-3 over immobilised LRP-1","cite":"PMID:32694578"},{"value":"KD 4.96 nM","assay":"surface plasmon resonance","system":"MMP-1/TIMP-3 complex over LRP-1","cite":"PMID:32694578"}],"species_and_systems":"Human recombinant proteins by SPR and HTB94 cells for internalisation [PMID:32694578]; mouse pair is ortholog-inferred.","localisation_and_range":"TIMP3 is flagged secreted; uptake is by endocytosis [PMID:32694578].","caveats":"Both papers read as abstracts with excerpts. The role is clearance, not classical activation; the curated effect label is agonist though the evidence concerns endocytosis.","key_references":[{"PMID":"32694578","why":"SPR affinity of TIMP-3 for LRP-1 and bridging"}],"covers":["LR003406","LR006607"]},"LR006610":{"pair":"TNC -> CNTN2","headline":"Tenascin-C binds TAG-1/axonin-1 (CNTN2) with Kd about 9 nM in vitro; single abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"Specific binding of TAG-1/axonin-1 to tenascin-C was observed; the two proteins also overlapped in embryonic and early postnatal nervous tissue [PMID:8663515]. Directionality of signalling is not reported in our evidence.","molecular_requirements":"not reported in our evidence.","affinity_potency":[{"value":"Kd approximately 9 nM","assay":"binding assay (as described in the abstract)","system":"TAG-1/axonin-1 with tenascin-C","cite":"PMID:8663515"}],"species_and_systems":"Experiment species not stated in the dossier; tissue used was nervous tissue; both human and mouse pairs are ortholog-inferred [PMID:8663515].","localisation_and_range":"CNTN2 is flagged secreted as well as receptor, and TNC secreted [flag]; the paper concerns cell-adhesion and extracellular matrix context [PMID:8663515].","caveats":"Abstract only. Tenascin-C was a secondary finding next to neurocan, phosphacan and N-CAM. Directional signalling effect is the curated label 'agonist' without functional data.","key_references":[{"PMID":"8663515","why":"Kd approximately 9 nM binding of TAG-1 to tenascin-C"}],"covers":["LR003409","LR006610"]},"LR005350":{"pair":"TNC -> ITGB3","headline":"Beta3 (alphavbeta3) binds tenascin-C: C-terminal fibrinogen-like domain binding and SMC functional data; abstract-only.","interaction_type":"direct binding","direction_and_effect":"The tenascin C C-terminal fibrinogen-like domain specifically binds alpha(v)beta(3), as does a peptide derived from it [PMID:10747940]. Affinity purification identified alphavbeta3 as a tenascin-binding receptor on endothelial cells [PMID:7693733]. TN-C/alphavbeta3 interaction promotes EGF-dependent SMC growth [PMID:9314546].","molecular_requirements":"Partner alphaV chain is needed [PMID:10747940]; binding via the SRRGDMS site in one paper [PMID:7693733].","affinity_potency":[],"species_and_systems":"Human cells per curator records; HUVEC [PMID:7693733], SMC [PMID:9314546].","localisation_and_range":"Ligand flagged as secreted, non-transmembrane [flag]; presented as extracellular matrix, so acts locally on adjacent cells.","caveats":"All abstract-only. Single-chain entry. Two further rows abstract_insufficient.","key_references":[{"PMID":"10747940","why":"TNC fibrinogen-like domain binds alphavbeta3"},{"PMID":"7693733","why":"alphavbeta3 identified as tenascin receptor"},{"PMID":"9314546","why":"alphavbeta3 and EGF-R in SMCs"}],"covers":["LR002022","LR005350"]},"LR003415":{"pair":"TNFSF11 -> LGR4","headline":"LGR4 is reported as a second RANKL receptor that competes with RANK and dampens osteoclast differentiation; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"LGR4 competes with RANK for RANKL and suppresses canonical RANK signalling; RANKL binding to LGR4 activates the G-alpha-q and GSK3-beta pathway, reducing NFATC1 expression and activity [PMID:27064449]. Knockout mice show osteoclast hyperactivation, and soluble LGR4 ECD binds RANKL and blocks bone loss in three mouse osteoporosis models [PMID:27064449]. Effect: negative regulator, with decoy-like ECD.","molecular_requirements":"RANK competition is central; co-receptor requirements are not reported in our evidence [PMID:27064449].","affinity_potency":[],"species_and_systems":"Dossier records human, with mouse knockout and disease models in vivo [PMID:27064449]. No database records.","localisation_and_range":"RANKL is flagged secreted and transmembrane [flag].","caveats":"Only one paper, read as an abstract; no independent replication or affinity in our evidence.","key_references":[{"PMID":"27064449","why":"LGR4 as a second RANKL receptor"}],"covers":["LR003415","LR006616"]},"LR001507":{"pair":"TNFSF14 -> TNFRSF14","headline":"LIGHT-HVEM is well supported by several papers and structures; activating, with a mast-cell costimulation example.","interaction_type":"direct binding","direction_and_effect":"HVEM binds LIGHT, and HSV1 gD inhibits the HVEM-LIGHT interaction [PMID:9462508]. In human mast cells, TNFSF14 with anti-IgE enhanced LAMP-1 and IL-8 and TNF-alpha production, with no response to TNFSF14 alone [PMID:27982078].","molecular_requirements":"TNFRSF14 engagement activated mast cells only alongside Fc\u03b5RI aggregation [PMID:27982078]. LIGHT also engages LTBR [PMID:9462508].","affinity_potency":[],"species_and_systems":"Human cells and recombinant proteins; LAD2 and cultured peripheral blood mast cells [PMID:27982078]; immunoprecipitation cross-reactivity with mouse LIGHT [PMID:11390428].","localisation_and_range":"LIGHT flagged secreted and transmembrane; HVEM transmembrane, not secreted [flag]; described as a type II transmembrane protein [PMID:9462508].","caveats":"Several papers abstract only. One shows binding only indirectly, through competition by decoy TR6-Fc [PMID:11390428]. PDB structures exist [DB:PDB 4RSU].","key_references":[{"PMID":"9462508","why":"Identification of HVEM as LIGHT receptor"},{"PMID":"11390428","why":"TR6-Fc competes with HVEM for LIGHT"},{"PMID":"27982078","why":"Mast-cell costimulation via TNFRSF14"}],"covers":["LR001507","LR004897"]},"LR004900":{"pair":"TNFSF4 -> TNFRSF4","headline":"OX40L-OX40 is supported by databases and structures; one abstract-only in vivo paper.","interaction_type":"functional only","direction_and_effect":"The CD134/CD134L interaction provides a strong CD28-independent costimulatory signal in rat small bowel allotransplantation [PMID:12134113].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Rat transplantation model; pair species human and mouse are orthology-projected [PMID:12134113].","localisation_and_range":"OX40L flagged transmembrane, not secreted [flag].","caveats":"Single paper, abstract only, no direct binding. Binding support comes from PDB 2HEV [DB:PDB 2HEV], IntAct [DB:IntAct] and Reactome [DB:Reactome].","key_references":[{"PMID":"12134113","why":"In vivo costimulation by CD134/CD134L"}],"covers":["LR001510","LR004900"]},"LR001516":{"pair":"TSHB -> TSHR","headline":"TSH activates the cloned human TSH receptor in CHO cells; established agonist pair supported by GtoPdb, PDB and Reactome.","interaction_type":"direct binding","direction_and_effect":"Agonist: CHO cells stably expressing the cloned receptor activated adenylate cyclase specifically in response to TSH [PMID:2558651]. GtoPdb lists Agonist/Agonist [DB:GtoPdb]; UniProt describes TSHR as the receptor for TSH [DB:UniProt].","molecular_requirements":"Single seven-transmembrane GPCR in the cloning paper [PMID:2558651]; the dossier notes Reactome records TSHR binding TSH/thyrostimulin [DB:Reactome R-HSA-391375]. Alpha subunit requirement not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human thyroid cDNA, CHO cells; the TSH species is not stated in the abstract [PMID:2558651]. PDB complexes exist [DB:PDB 7T9I].","localisation_and_range":"TSHB flagged secreted; TSHR flagged transmembrane [flag].","caveats":"The cloning paper shows functional response, not direct binding, so the assay_class direct_binding is generous; abstract read only. The row is tagged mouse in the source though the paper is human. No affinity in the dossier.","key_references":[{"PMID":"2558651","why":"Cloning of human TSH receptor; TSH-specific adenylate cyclase activation"}],"covers":["LR001516","LR004906"]},"LR003424":{"pair":"TUB -> MERTK","headline":"Tubby binds MerTK selectively among TAM receptors and induces activation and phagocytosis; one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"Agonist: tubby binds only MerTK among the TAM receptors; both tubby and Tulp1 induced MerTK activation with receptor phosphorylation and signalling, and soluble MerTK extracellular domain blocked tubby-mediated phagocytosis [PMID:20978472].","molecular_requirements":"Tubby's N-terminal region is the MerTK-binding domain; the C-terminal region is the phagocytosis prey-binding domain, mapped to 54 conserved amino acids [PMID:20978472].","affinity_potency":[],"species_and_systems":"Retinal pigment epithelium and macrophage phagocytosis assays; species not stated in the abstract [PMID:20978472]. Human pair ortholog-inferred, mouse pair not.","localisation_and_range":"No classical signal peptide, unconventional secretion shown [PMID:20978472]; ligand flagged secreted [flag].","caveats":"Abstract read only; no affinity value. Bridging ligand with prey-binding domain.","key_references":[{"PMID":"20978472","why":"Tubby binds only MerTK among TAM receptors"}],"covers":["LR003424","LR006625"]},"LR002029":{"pair":"ULBP3 -> KLRK1","headline":"ULBP3 engages the NKG2D receptor on NK cells; supported by one functional paper and a crystal structure with KLRK1.","interaction_type":"direct binding","direction_and_effect":"Agonist, activating: ULBPs stimulate cytokine and chemokine production from NK cells and make NK-resistant target cells susceptible to NK cytotoxicity [PMID:11239445]. The structural record is a database assertion of physical contact [DB:PDB 1KCG].","molecular_requirements":"NKG2D (KLRK1) is an essential component of the ULBP receptor complex: anti-NKG2D antiserum blocked ULBP1-Fc binding to human NKL cells [PMID:11239445]. Whether DAP10 is also needed is not reported in our evidence for this receptor row.","affinity_potency":[],"species_and_systems":"Human proteins and human NKL cells, using Fc fusion proteins [PMID:11239445]. A crystal structure with chains of ULBP3 and KLRK1 exists [DB:PDB 1KCG]; IntAct lists X-ray crystallography, FACS and SPR records [DB:IntAct] [PMID:11754823] [PMID:18544572]; UniProt notes interaction with KLRK1/NKG2D [DB:UniProt] [PMID:11491531].","localisation_and_range":"Ligand is membrane-bound [flag]; the paper describes ULBPs as GPI-linked glycoproteins [PMID:11239445].","caveats":"Blocking evidence was shown with ULBP1-Fc, with the paper's text extending it to all ULBP/MIC-Fc fusions per the curator. Binding affinity is not reported in our evidence. Only one paper supports this pair [PMID:11239445]; it is functional in vitro (human NKL cells), read in full text. Database records add physical-interaction support only.","key_references":[{"PMID":"11239445","why":"ULBPs bind NKG2D on NK cells and stimulate cytotoxicity"}],"covers":["LR002029"]},"LR003433":{"pair":"UNC5B -> FLRT2","headline":"UNC5B-FLRT2 binding shown in a mouse-protein screen; UniProt reports lower affinity than for FLRT3; one abstract-only paper judged negative.","interaction_type":"direct binding","direction_and_effect":"Binding was seen in an ELISA-based screen with AP/Fc-tagged extracellular domains, with every FLRT1-3 x Unc5A-D pair reported at or near saturation (mean Abs650nm value = 2.14) [PMID:26633812]. Titration with purified protein and CHO.K1 cell aggregation confirmed the family pairs [PMID:26633812]. In this paper Unc5-expressing neurons are repelled by FLRT, so FLRT acts as ligand and Unc5 as receptor, the reverse of the listed direction [PMID:26633812]. ","molecular_requirements":"Extracellular domains of both partners are used; no co-receptor or extra subunit is reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse proteins in recombinant ELISA and cell-aggregation assays; the human pair is ortholog-inferred and the mouse pair is the direct one [PMID:26633812].","localisation_and_range":"UNC5B is annotated as a transmembrane receptor and FLRT2 as both secreted and transmembrane [flag]; contact-mediated signalling is likely, but this is not tested here.","caveats":"The binding statement is family-wide rather than specific to this pair. Pair-specific functional data are absent. An abstract-only 2011 paper was judged pair_absent: it states Unc5D binds specifically to FLRT2 and names FLRT3 as Unc5B's partner [PMID:21673655]. UniProt notes UNC5B binds FLRT2 and FLRT3 but with higher affinity for FLRT3 [DB:UniProt]. No affinity value is given.","key_references":[{"PMID":"26633812","why":"Extracellular screen and titration binding of all FLRT x Unc5 pairs, mouse proteins"}],"covers":["LR003433","LR006634"]},"LR003442":{"pair":"UTS2B -> SSTR5","headline":"UTS2B inhibits GLP-1 secretion in mouse gut via SSTR5 rather than UTS2R; functional evidence from one abstract.","interaction_type":"functional only","direction_and_effect":"UTS2B inhibits GLP-1 secretion in mouse intestinal crypts and organoids, not through UTS2R but through activation of SSTR5 [PMID:31556942]. Given to starved mice, UTS2B regulates blood glucose and plasma GLP-1 and insulin [PMID:31556942].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse intestinal crypts, organoids and whole animals; the human pair is ortholog-inferred [PMID:31556942].","localisation_and_range":"UTS2B is annotated as secreted [flag]; the curator notes describe paracrine action from a gut enteroendocrine cell source [PMID:31556942].","caveats":"Abstract only. No direct binding or affinity is shown, so SSTR5 engagement is inferred from function. The paper itself says UTS2R is not involved.","key_references":[{"PMID":"31556942","why":"UTS2B acts through SSTR5 to inhibit GLP-1 secretion in mouse gut"}],"covers":["LR003442","LR006643"]},"LR001525":{"pair":"UTS2B -> UTS2R","headline":"URP (UTS2B) binds and activates the UT receptor; three curator-confirmed papers, all read as abstracts only.","interaction_type":"direct binding","direction_and_effect":"URP is an agonist: it binds and activates human or rat UII receptors (GPR14) and lowers blood pressure in anaesthetised rats [PMID:14550283][PMID:17628210]. In mouse, URP and UII(17) were equally potent in calcium mobilisation at the UT receptor [PMID:18710417]. GtoPdb lists it as a full agonist [DB:GtoPdb].","molecular_requirements":"Single receptor chain (UT receptor/GPR14); no co-receptor or subunit requirement reported in our evidence.","affinity_potency":[{"value":"pIC50 8.6","assay":"curator-recorded affinity; abstract does not state the value","system":"URP on human/rat UII receptors","cite":"PMID:14550283"},{"value":"pKd 9.6","assay":"curator-recorded affinity; abstract does not state the value","system":"human UT receptor","cite":"PMID:17628210"}],"species_and_systems":"Rat-derived URP on human or rat receptors, with in vivo rat blood pressure [PMID:14550283]; human ligand and receptor [PMID:17628210]; mouse calcium assays [PMID:18710417]. The mouse pair is ortholog-inferred from human evidence.","localisation_and_range":"Secreted peptide acting on a transmembrane receptor (entity flags) [flag]; tissue expression of URP and UT mRNA reported in mouse [PMID:18710417].","caveats":"All three papers were read as abstracts only. Affinity values are curator-recorded and not seen in abstract text. BioGRID lists a reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"14550283","why":"URP isolated from rat brain; binds and activates UII receptors"},{"PMID":"17628210","why":"URP binds and activates human UT receptor"},{"PMID":"18710417","why":"UII and URP equipotent at mouse UT receptor"}],"covers":["LR001525","LR004914"]},"LR001534":{"pair":"VCAN -> ITGB1","headline":"Beta1 integrin pulled down with the versican C-terminal domain in glioma cells; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"beta(1)-integrin bound the C-terminal domain of PG-M/versican; the interaction activated focal adhesion kinase, enhanced integrin expression and promoted cell adhesion [PMID:11805102].","molecular_requirements":"Calcium- and manganese-dependent; the used peptide has no RGD motif; alpha partner not reported in our evidence [PMID:11805102].","affinity_potency":[],"species_and_systems":"Pull-down, immunoprecipitation and cell-surface binding in glioma cells; species not stated in the curated row [PMID:11805102]. Mouse pair is ortholog-inferred.","localisation_and_range":"Versican flagged secreted [flag].","caveats":"Abstract only; only the C-terminal domain was tested, not full-length versican. No database records.","key_references":[{"PMID":"11805102","why":"beta1 integrin binds versican C-terminal domain"}],"covers":["LR001534","LR004923"]},"LR001543":{"pair":"VEGFA -> NRP2","headline":"VEGF165 binds neuropilin-2 with high affinity in a heparin-dependent way; NRP2 also complexes with VEGFR-2.","interaction_type":"direct binding","direction_and_effect":"Both np-2 splice forms bind VEGF165 but not VEGF121 [PMID:10748121]. VEGF-A induces NRP2 interaction with VEGFR-2, enhancing VEGFR-2 phosphorylation and cell survival [PMID:16621967].","molecular_requirements":"Heparin is needed for high-affinity VEGF165 binding to np-2 [PMID:10748121]; VEGFR-2 forms a complex with NRP2 [PMID:16621967].","affinity_potency":[{"value":"KD 1.3 x 10(-10) M","assay":"binding of VEGF165 to np-2 in presence of heparin","system":"HUVEC-expressed np-2 a17/a22 splice forms","cite":"PMID:10748121"}],"species_and_systems":"Human endothelial cells [PMID:10748121, PMID:16621967]; a PDB structure exists [DB:PDB 5DN2].","localisation_and_range":"Not reported in our evidence.","caveats":"Two shown papers, abstract-level; the binding paper also reports VEGF145 with KD 7e-10 M. VEGF121 does not bind.","key_references":[{"PMID":"10748121","why":"VEGF165 binding and KD for neuropilin-2"},{"PMID":"16621967","why":"VEGF-A induced NRP2/VEGFR-2 interaction"}],"covers":["LR001543","LR004932"]},"LR004135":{"pair":"VEGFD -> KDR","headline":"VEGF-D is a ligand for KDR (VEGFR-2) from one foundational abstract-level paper plus database records.","interaction_type":"direct binding","direction_and_effect":"VEGF-D is a ligand for VEGFR-2 and VEGFR-3 and can activate them; it does not bind VEGFR-1 [PMID:9435229]. Curators label it stimulatory agonist.","molecular_requirements":"No complex requirement in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and receptor, abstract-level reading [PMID:9435229]. Mouse pair is ortholog-inferred.","localisation_and_range":"VEGFD flagged secreted [flag].","caveats":"Single confirmed paper shown, read as abstract; no affinity. BioGRID reconstituted-complex record [DB:BioGRID] and Reactome [DB:Reactome]. Two review-only rows not shown.","key_references":[{"PMID":"9435229","why":"VEGF-D binds and activates VEGFR-2 and VEGFR-3"}],"covers":["LR000651","LR004135"]},"LR000652":{"pair":"VEGFD -> NRP2","headline":"VEGF-D binds NP2 in a heparin-dependent manner in one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"VEGF-D interacts with NP2 in a heparin-dependent manner; NP2 cointernalises with VEGFR-3 in lymphatic endothelial cells on VEGF-C or VEGF-D stimulation [PMID:16816121].","molecular_requirements":"Heparin is needed for VEGF-D/NP2 binding; NP2 coprecipitates with VEGFR-3, suggesting a co-receptor role [PMID:16816121].","affinity_potency":[],"species_and_systems":"Human ligand and receptor, in vitro binding and lymphatic endothelial cells; abstract-level [PMID:16816121]. Mouse pair is ortholog-inferred.","localisation_and_range":"VEGFD flagged secreted [flag].","caveats":"Single paper; no affinity; one abstract_insufficient row not shown. No database records in this dossier.","key_references":[{"PMID":"16816121","why":"VEGF-C/VEGF-D binding to NP2 and VEGFR-3 complex"}],"covers":["LR000652","LR004136"]},"LR001552":{"pair":"VIP -> ADCYAP1R1","headline":"VIP is a lower-affinity, agonist ligand of the PAC1 receptor, well below PACAP; supported by two human recombinant studies and database records.","interaction_type":"direct binding","direction_and_effect":"VIP acts as an agonist at human PAC1 in CHO cells, with cAMP and calcium readouts [PMID:16930633]. GtoPdb lists it as agonist [DB:GtoPdb].","molecular_requirements":"Splice-variant dependent: PAC1n bound VIP with up to 400-fold lower affinity than PACAP, PAC1vs bound VIP with Ki>1000 nM, whereas PAC1s bound all three ligands with high affinity; residues 53-88 of the N-terminus matter for ligand selectivity [PMID:10583729].","affinity_potency":[{"value":"pEC50 8.7","assay":"binding/cAMP in PAC1-variant cells (curator-recorded)","system":"transfected HEK293, human","cite":"PMID:10583729"},{"value":"pEC50 7.8","assay":"cAMP","system":"CHO cells expressing human PAC1","cite":"PMID:16930633"}],"species_and_systems":"Human receptor variants in HEK293 [PMID:10583729] and CHO cells [PMID:16930633].","localisation_and_range":"VIP is flagged secreted and PAC1 transmembrane [flag]; paracrine or endocrine action is implied by the flags only.","caveats":"Both papers read as abstracts only. Potency differs by receptor splice variant, so expression of the PAC1 isoform matters. Calcium EC50 values run about 100-fold higher than cAMP [PMID:16930633]. PDB structures (9P92, 9P93) contain both chains [DB:PDB 9P92]. Mouse pair is projected from human.","key_references":[{"PMID":"10583729","why":"VIP affinity depends on PAC1 splice variant"},{"PMID":"16930633","why":"VIP potency at PAC1 in cAMP and calcium assays"}],"covers":["LR001552","LR004941"]},"LR008212":{"pair":"VTN -> ITGA8:ITGB1","headline":"The alpha8beta1 integrin binds vitronectin in human cell systems; supported by one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Alpha8beta1 bound vitronectin-Sepharose and was specifically eluted by GRGDSP; alpha8-transfected 293 cells adhered to vitronectin. The authors conclude that vitronectin is a ligand through the RGD site, by a mechanism separate from alpha5- and alphaV-containing integrins [PMID:7559467].","molecular_requirements":"Both chains (ITGA8 with ITGB1) form the receptor; the paper states alpha8 associates with beta1 [PMID:7559467].","affinity_potency":[],"species_and_systems":"Human 293 cells and cell extracts [PMID:7559467].","localisation_and_range":"Vitronectin is flagged as secreted and not transmembrane [flag]; the integrin is a membrane receptor, so signalling is by cell contact with soluble or matrix-bound ligand. The dossier's papers do not describe range further.","caveats":"Abstract only; no affinity. Reactome records shown name alphaVbeta1, alphaVbeta3, alpha3beta5 and alphaIIBbeta3, not alpha8beta1 [DB:Reactome]. One further paper was review only.","key_references":[{"PMID":"7559467","why":"alpha8beta1 as a receptor for vitronectin, with RGD elution"}],"covers":["LR008212"]},"LR001561":{"pair":"VTN -> ITGB1","headline":"Beta1 appears only as the partner chain of alpha8beta1 in a single abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Alpha8beta1 bound vitronectin-Sepharose, eluted by GRGDSP, and supported adhesion of alpha8-transfected 293 cells [PMID:7559467]. Reactome lists vitronectin binding to alphaVbeta1 among others [DB:Reactome].","molecular_requirements":"ITGB1 is shown only as part of a heterodimer with alpha8; chain-only evidence for beta1 is not available [PMID:7559467].","affinity_potency":[],"species_and_systems":"Human 293 cells and extracts; mouse pair is ortholog-inferred [PMID:7559467].","localisation_and_range":"Vitronectin is flagged as secreted and not transmembrane [flag]; the integrin is a membrane receptor, so signalling is by cell contact with soluble or matrix-bound ligand. The dossier's papers do not describe range further.","caveats":"Chain-only entry: the evidence is for alpha8beta1, not beta1 alone. Abstract only; no affinity. One further abstract was insufficient.","key_references":[{"PMID":"7559467","why":"alpha8beta1 binds vitronectin, supports the beta1 partner"}],"covers":["LR001561","LR004950"]},"LR012037":{"pair":"VTN -> NECTIN2","headline":"Weak or negligible vitronectin binding to mPRR2 (NECTIN2) in one abstract; the strong binder was CD155.","interaction_type":"direct binding","direction_and_effect":"The abstract reports that mPRR2 bound vitronectin only weakly by surface plasmon resonance [PMID:11437656]. Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Surface plasmon resonance; the protein is mPRR2 as named in the abstract; the pair is human [PMID:11437656].","localisation_and_range":"Vitronectin is flagged as secreted and NECTIN2 as transmembrane [flag].","caveats":"Abstract only. The 310 nM Kd belongs to mPRR2 self-adhesion, not vitronectin binding, and the stated 72 nM Kd is for CD155, a different receptor [PMID:11437656]. Support for this pair is therefore weak.","key_references":[{"PMID":"11437656","why":"SPR comparison: CD155 binds vitronectin; mPRR2 only weakly"}],"covers":["LR012037"]},"LR003451":{"pair":"VWF -> GP9","headline":"GP9 is supported only through the GPIb-IX complex; the one paper concerns GPIbbeta phosphorylation.","interaction_type":"functional only","direction_and_effect":"In CHO cells expressing GPIb-IX, PKA inhibitor PKI reduced Ser166 phosphorylation of GPIbbeta and enhanced VWF binding; the S166A and Delta165 mutants showed enhanced VWF binding and adhesion under flow [PMID:12361948].","molecular_requirements":"The paper studies the whole GPIb-IX complex and the GPIbbeta chain, not GP9 specifically [PMID:12361948]; the pair rests on complex-level evidence. Reactome lists GPIb:IX:V with VWF multimer [DB:Reactome].","affinity_potency":[],"species_and_systems":"CHO cells and human platelets [PMID:12361948]. Mouse pair is ortholog-inferred.","localisation_and_range":"Not reported in our evidence.","caveats":"Abstract-only read. The paper does not test GP9 alone, and the signal is on GPIbbeta regulation, so this is chain-level inference rather than direct GP9 binding.","key_references":[{"PMID":"12361948","why":"PKA phosphorylation of GPIbbeta regulates VWF binding to GPIb-IX"}],"covers":["LR003451","LR006651"]},"LR001570":{"pair":"VWF -> SELP","headline":"P-selectin's lumenal domain binds the D'-D3 domains of VWF; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Coexpression mapping in HEK293 cells and conventional co-immunoprecipitation indicate the lumenal domain of P-selectin interacts with the D'-D3 domains of VWF [PMID:16418330]. Anchoring of VWF strings is suggested in the abstract.","molecular_requirements":"VWF D'-D3 and P-selectin lumenal domain are required [PMID:16418330].","affinity_potency":[],"species_and_systems":"Human proteins coexpressed in HEK293 cells, which form Weibel-Palade-body-like structures [PMID:16418330]. Mouse pair is ortholog-inferred.","localisation_and_range":"P-selectin is flagged transmembrane [flag]; interaction occurs in Weibel-Palade bodies and at the endothelial surface [PMID:16418330].","caveats":"Abstract-only read. No affinity; interaction may be assisted by the cellular context.","key_references":[{"PMID":"16418330","why":"D'-D3 of VWF interacts with P-selectin lumenal domain"}],"covers":["LR001570","LR004959"]},"LR003460":{"pair":"WFIKKN2 -> IGDCC3","headline":"WFIKKN2 binds IGDCC3 (PUNC) by SPR on recombinant proteins; an axon-guidance paper also names it as a ligand, from abstract only.","interaction_type":"direct binding","direction_and_effect":"WFIKKN2 ECD-Fc and PUNC analyte-Fc were observed in the apECIA screen and listed as SPR-validated [PMID:32822567]. A preprint reports WFIKKN2 as a secreted ligand of Punc, Nope and Prtg that guides axons; the Punc-specific role is not delineated in the abstract [PMID:37398498].","molecular_requirements":"Not reported in our evidence; the SPR work used ECD-Fc fusions of the extracellular domains [PMID:32822567].","affinity_potency":[],"species_and_systems":"Binding: recombinant human ECD-Fc proteins, SPR and apECIA [PMID:32822567]. Axon-guidance work was in mouse axons; the dossier lists human proteins for the pair [PMID:37398498].","localisation_and_range":"WFIKKN2 is flagged secreted [flag]; the receptor is flagged as a receptor [flag].","caveats":"No affinity values for this pair are given in our evidence. The functional paper was read as abstract only and its Nope-mediated repulsion result concerns a different receptor [PMID:37398498].","key_references":[{"PMID":"32822567","why":"SPR-validated binding of WFIKKN2 to PUNC in a cell-surface interactome screen"},{"PMID":"37398498","why":"WFIKKN2 as axon guidance ligand for Punc/Nope/Prtg (abstract only)"}],"covers":["LR003460","LR006660"]},"LR011236":{"pair":"WNT1 -> FZD10:LRP5","headline":"WNT1 acting through a FZD10:LRP5 complex has only an abstract-level paper on FZD10 plus Lrp6 and UniProt notes on LRP5.","interaction_type":"functional only","direction_and_effect":"In developing spinal cord, Wnt1-induced dorsal markers require FZD10, and Lrp6 enhances Wnt1/FZD10 activity [PMID:32531778].","molecular_requirements":"The paper's co-receptor is Lrp6, not LRP5; LRP5 is not tested in our evidence. UniProt notes an LRP5 subunit interaction enhanced by GSK3B and WNT1 or WNT3A [DB:UniProt].","affinity_potency":[],"species_and_systems":"Developing spinal cord (in vivo knockdown and gain of function); species not stated in the dossier [PMID:32531778].","localisation_and_range":"WNT1 is flagged secreted and non-transmembrane [flag]; the receptor is flagged as a receptor [flag], so signalling is presumably paracrine, but range is not reported in our evidence.","caveats":"The confirmed paper concerns FZD10 and Lrp6, so it supports FZD10 but not the LRP5 pairing. Abstract only. FZD10 alone was not sufficient and excess FZD10 inhibited Wnt1 [PMID:32531778].","key_references":[{"PMID":"32531778","why":"FZD10 and Lrp6 needed for Wnt1 activity in spinal cord"}],"covers":["LR011236"]},"LR011245":{"pair":"WNT10A -> FZD9:LRP5","headline":"Complex-level pair with no curated paper; rests on one IntAct co-immunoprecipitation record only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect (agonist or antagonist) not reported in our evidence. The only support is an IntAct record of association by anti-tag coimmunoprecipitation [DB:IntAct EBI-54877040].","molecular_requirements":"Receptor is listed as a two-chain complex; whether both chains, or either alone, are required is not reported in our evidence. ","affinity_potency":[],"species_and_systems":"Pair is human; the experimental system of the IntAct record is not reported in our evidence.","localisation_and_range":"Ligand is flagged secreted [flag]; the receptor chains are flagged as receptors, with LRP chain transmembrane [flag]. Range is not otherwise reported in our evidence.","caveats":"Three curation rows are still pending; no paper has been judged. Whether WNT10A binding was tested directly is not reported in our evidence.","key_references":[],"covers":["LR011245"]},"LR002038":{"pair":"WNT11 -> FZD8","headline":"FZD8 is reported as a major WNT11 receptor in prostate cancer cells, shown by co-localisation, co-IP and knockdown.","interaction_type":"direct binding","direction_and_effect":"FZD8 co-localised and co-immunoprecipitated with Wnt-11 and potentiated Wnt-11 activation of ATF2-dependent transcription; FZD8 silencing reduced it by 40% [PMID:29717114]. Annotated agonist.","molecular_requirements":"Endogenous FZD8 was required for the response; FZD5 silencing had no effect, FZD2 silencing reduced it by 20% [PMID:29717114]. FZD8 also forms a TGF-beta-regulated complex with TGF-beta receptors via extracellular domains [PMID:29717114].","affinity_potency":[],"species_and_systems":"Human PC-3M prostate cancer cells (transfected, tagged proteins) and patient datasets; mouse FZD8 rescued siRNA effect [PMID:29717114]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted [flag]; signalling is beta-catenin-independent [PMID:29717114].","caveats":"Wnt-11 also co-localised moderately with FZD6 and FZD10, so FZD8 is not exclusive [PMID:29717114]. No affinity.","key_references":[{"PMID":"29717114","why":"FZD8 as Wnt-11 receptor in prostate cancer; co-IP and ATF2 reporter"}],"covers":["LR002038","LR005364"]},"LR011263":{"pair":"WNT2 -> FZD7:LRP5","headline":"WNT2 to FZD7:LRP5 rests on an in silico Wnt2-Fzd7 study; LRP5 was not modelled.","interaction_type":"functional only","direction_and_effect":"Docking and MD simulations suggest Wnt2 binds the Fzd7 cysteine-rich domain [PMID:30191337].","molecular_requirements":"LRP5 contribution is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Purely computational [PMID:30191337].","localisation_and_range":"Wnt2 flagged secreted [flag].","caveats":"No experimental data; one review-only and one abstract_insufficient row.","key_references":[{"PMID":"30191337","why":"In silico Wnt2-Fzd7 CRD model"}],"covers":["LR011263"]},"LR008104":{"pair":"WNT2 -> FZD9:LRP6","headline":"FZD9 interaction supported by co-IP in human cumulus cells and TCF reporter in rat Fz9; LRP6 not tested.","interaction_type":"direct binding","direction_and_effect":"WNT2 interacted with FZD9 by co-immunoprecipitation [PMID:19038973]; only Wnt-2 among Wnts tested activated rat Frizzled-9 in TCF transcription [PMID:12138115].","molecular_requirements":"Both papers address FZD9; neither abstract reports LRP6 [PMID:19038973][PMID:12138115].","affinity_potency":[],"species_and_systems":"Human cumulus cells (co-IP) [PMID:19038973]; rat Frizzled-9 in 293T cells (reporter) [PMID:12138115].","localisation_and_range":"WNT2 is annotated as secreted [flag].","caveats":"LRP6 contribution is not shown; support is for the FZD9 subunit. Both papers read as abstracts only. Co-IP was asymmetric [PMID:19038973].","key_references":[{"PMID":"19038973","why":"Co-IP of WNT2 with FZD9, human cells"},{"PMID":"12138115","why":"Wnt-2 specifically activates rat Fz9"}],"covers":["LR008104"]},"LR008050":{"pair":"WNT3 -> FZD2:LRP6","headline":"Functional Wnt3-FZD2 signalling in HEK293T is supported, but nothing in our evidence tests the FZD2:LRP6 complex itself.","interaction_type":"functional only","direction_and_effect":"The single curated paper reports that FZD1, FZD2 and FZD7 \"specifically induce signaling after binding of Wnt3 and Wnt3a\" [PMID:28733458]; this is a statement in the Discussion, and the paper's tested readout was TCF4/Wnt reporter signalling.","molecular_requirements":"FZD2 is the evidence-bearing subunit; the paper's excerpts do not test LRP6 as a partner, so whether the full complex or FZD2 alone is needed is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and receptor; HEK293T cells with CRISPR FZD mutations [PMID:28733458].","localisation_and_range":"WNT3 carries a secreted annotation flag [flag], so it acts as a secreted ligand; range is not reported in our evidence.","caveats":"Complex-level support is inferred from a single-chain Frizzled result; the paper is a functional map, not a binding study. A database record exists (IntAct, surface plasmon resonance, accession pair O75581-P56703) [DB:IntAct], but it does not name the Frizzled member.","key_references":[{"PMID":"28733458","why":"Functional Wnt-FZD map in FZD-mutant HEK293T cells"}],"covers":["LR008050"]},"LR008041":{"pair":"WNT3A -> FZD1:LRP6","headline":"FZD1 co-precipitates Wnt-3a in one abstract-level paper; LRP6 contribution rests on database records.","interaction_type":"direct binding","direction_and_effect":"Hfz1 enhanced Wnt-3a-induced TCF-dependent transcription in autocrine and paracrine modes [PMID:10557084].","molecular_requirements":"The curated paper concerns FZD1 alone and does not test LRP6. BioGRID lists LRP6-WNT3A Affinity Capture-Western [DB:BioGRID] [PMID:19910923]; Reactome has a WNT3A:FZD:LRP5/6 complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human Hfz1 and Wnt-3a, coimmunoprecipitation in transfected cells (curator label HEK) [PMID:10557084].","localisation_and_range":"WNT3A is flagged secreted and not transmembrane [flag], so signalling is expected to be paracrine or autocrine; range is not measured in our evidence.","caveats":"Chain-only evidence: the confirmed paper supports FZD1, not the FZD1:LRP6 complex. Read as abstract only. No affinity reported.","key_references":[{"PMID":"10557084","why":"FZD1 co-IP with Wnt-3a and TCF signalling"}],"covers":["LR008041"]},"LR006700":{"pair":"WNT4 -> FZD7","headline":"WNT4 shows only very weak to intermediate binding to the FZD7 CRD in purified-protein assays.","interaction_type":"direct binding","direction_and_effect":"WNT-4 showed very weak to intermediate binding to the FZD1/2/4/5/7 CRDs [PMID:25605717].","molecular_requirements":"Binding was measured to the CRD-Fc fusion alone [PMID:25605717].","affinity_potency":[],"species_and_systems":"Purified mouse proteins, bio-layer interferometry (Octet) [PMID:25605717]. Mouse pair is direct; human ortholog-inferred.","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"KD values are in a table not shown in our evidence. Browser-read, not spot-checked. Binding only; signalling not reported here.","key_references":[{"PMID":"25605717","why":"BLI of WNT-4 binding to FZD CRDs"}],"covers":["LR003500","LR006700"]},"LR001606":{"pair":"WNT5A -> FZD7","headline":"WNT5A binds the FZD7 CRD only weakly in BLI; Xenopus data show a functional interaction; thin evidence.","interaction_type":"conflicting","direction_and_effect":"Xfz7 interacts with Xwnt5A to activate the beta-catenin pathway in Xenopus [PMID:10990458]. WNT-5A showed weak binding to the FZD7 CRD [PMID:25605717].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse proteins for BLI [PMID:25605717]; Xenopus for the pathway study [PMID:10990458]. The human pair is ortholog-inferred; the mouse pair is not.","localisation_and_range":"WNT5A is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine by this annotation.","caveats":"The binding paper reports only weak binding with no KD given in the quoted sentence, and its quote is an unverified browser read. The pathway paper is an abstract read. Reactome and IntAct list WNT5:FZD7 [DB:Reactome][DB:IntAct], but the IntAct records are for another protein pair (O75084-P41221).","key_references":[{"PMID":"25605717","why":"WNT-5A weak binding to FZD7 CRD"},{"PMID":"10990458","why":"Xfz7 and Xwnt5A activate beta-catenin signalling"}],"covers":["LR001606","LR004995"]},"LR003505":{"pair":"WNT5A -> FZD9","headline":"Functional evidence in neurons that FZD9 interacts with Wnt-5a and is required for spine formation; one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"FZD9 is required for the Wnt-5a-mediated increase in dendritic spine density; Wnt-5a stimulation dissociates a precoupled FZD9-Galphao complex, and Gbetagamma is needed for the cytosolic calcium increase [PMID:27402827]. Curated stimulatory.","molecular_requirements":"Galphao and Gbetagamma are downstream requirements; co-receptors not reported in our evidence [PMID:27402827].","affinity_potency":[],"species_and_systems":"Cultured hippocampal neurons; the abstract refers to rodent neurons, while the curation lists human, so species should be checked [PMID:27402827].","localisation_and_range":"Ligand flagged secreted [flag]; FZD9 localised to the postsynaptic region [PMID:27402827].","caveats":"Abstract only. The paper reports that FZD9 'interacts' with Wnt-5a, but no binding constant or direct binding assay is reported in our evidence.","key_references":[{"PMID":"27402827","why":"FZD9 required for Wnt-5a spine formation; G protein coupling"}],"covers":["LR003505","LR006705"]},"LR003514":{"pair":"WNT5B -> FZD5","headline":"WNT5B binds the FZD5 CRD with intermediate to strong affinity in a single BLI mapping study.","interaction_type":"direct binding","direction_and_effect":"Binding: WNT-5A and WNT-5B showed intermediate to strong binding to the FZD5 CRD; signalling effect of WNT-5B is not shown [PMID:25605717].","molecular_requirements":"CRD only; co-receptors not reported in our evidence.","affinity_potency":[{"value":"KD = 5\u201322 nm","assay":"bio-layer interferometry, FZD CRD-Fc (+++ to ++++), range given for WNT-5A and WNT-5B","system":"purified mouse proteins","cite":"PMID:25605717"}],"species_and_systems":"Mouse proteins (purified WNT binding to FZD CRD-Fc), bio-layer interferometry [PMID:25605717]; human pair is ortholog-inferred.","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only.","caveats":"Binding only; Wnt5b was not shown to activate signalling in this paper (the abstract reports WNT-3A but not WNT-5A as the activator in 32D cells) [PMID:25605717]. Only the abstract was curated, with excerpts from a browser read. The KD range is shared with WNT-5A.","key_references":[{"PMID":"25605717","why":"FZD5 CRD binding by WNT-5A/5B"}],"covers":["LR003514","LR006714"]},"LR002047":{"pair":"WNT5B -> FZD8","headline":"WNT5B binds the FZD8 CRD in two BLI studies with differing KD, and FZD8 knockdown reduces WNT-5B responses in human fibroblasts.","interaction_type":"direct binding","direction_and_effect":"Stimulatory: FZD8 knockdown reduced WNT-5B-induced fibronectin and alpha-sm-actin expression and WNT-5B-induced impedance changes in lung fibroblasts [PMID:26849959].","molecular_requirements":"CRD alone was used for binding; co-receptor need not reported in our evidence.","affinity_potency":[{"value":"KD = 4\u20138 nm","assay":"bio-layer interferometry, FZD8 CRD-Fc; WNT-5A and WNT-5B","system":"purified mouse proteins","cite":"PMID:25605717"},{"value":"KD = 36 nm","assay":"biolayer interferometry, Wnt5b to Fz8 CRD-Fc","system":"mouse Fz8 CRD","cite":"PMID:20093360"}],"species_and_systems":"Binding with mouse proteins; function in human MRC-5 and primary lung fibroblasts, plus FZD8-deficient mice in a fibrosis model [PMID:26849959].","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only.","caveats":"The two KD values disagree (4\u20138 nm vs 36 nm) [PMID:25605717, PMID:20093360]. The mouse fibrosis result concerns TGF-beta signalling, and the WNT-5B link is from siRNA in cells [PMID:26849959].","key_references":[{"PMID":"25605717","why":"FZD8 CRD binding by WNT-5A/5B"},{"PMID":"20093360","why":"Wnt5b KD to Fz8 CRD"},{"PMID":"26849959","why":"FZD8-dependent WNT-5B profibrotic signalling"}],"covers":["LR002047","LR005373"]},"LR008113":{"pair":"WNT7A -> FZD1:LRP5","headline":"No paper evidence; the only record says FZD1 is apparently not activated by WNT7A.","interaction_type":"database-asserted only","direction_and_effect":"No confirmed paper. UniProt says FZD1 is apparently not activated by WNT7A or WNT7B [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"WNT7A is flagged secreted and non-transmembrane [flag]; LRP5 is flagged transmembrane [flag].","caveats":"Only abstract-insufficient or review-only judgements exist; the database record argues against the pair.","key_references":[],"covers":["LR008113"]},"LR003523":{"pair":"WNT7A -> FZD8","headline":"WNT7A binds soluble FZD8 in a full-text-verified pull-down; direct binding, single paper.","interaction_type":"direct binding","direction_and_effect":"sFZD8 captured WNT7A more efficiently than sRECK in co-pull-down from HEK293 conditioned medium, i.e. WNT7A binds FZD8 [PMID:30304675]. FZD8 overexpression with WNT7 activated the STF reporter even in FZD1/2/4/5/7/8 knockout cells [PMID:30304675].","molecular_requirements":"RECK drastically enhanced FZD8:WNT7 binding [PMID:30304675]. Functionally, GPR124/RECK/WNT7 signalling depends on endogenous FZDs [PMID:30304675].","affinity_potency":[],"species_and_systems":"Human WNT7A and FZD8 constructs in HEK293 cells, recombinant soluble ECD-Fc [PMID:30304675]. Mouse pair is projected from human.","localisation_and_range":"Ligand is flagged secreted and non-transmembrane [flag], so paracrine or autocrine action is expected; the paper's own data on range are not reported in our evidence. Receptor is flagged as not secreted [flag].","caveats":"Binding was seen only when sFZD8 was added to the medium of WNT7A-expressing cells; cell-free conditioned medium WNT7A did not bind sFZD8, indicating short-lived active WNT7A [PMID:30304675]. No affinity reported. Single paper.","key_references":[{"PMID":"30304675","why":"Co-pull-down of WNT7A with sFZD8 (full text)"}],"covers":["LR003523","LR006723"]},"LR001615":{"pair":"WNT7A -> FZD9","headline":"WNT7A co-immunoprecipitates with FZD9 in lung cancer cells; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Wnt-7a was present in Fzd-9 immunoprecipitates, which the authors read as direct interaction; Wnt-7a/Fzd-9 stimulated JNK but not beta-catenin/TCF activity and suppressed anchorage-independent growth [PMID:15705594]. Curator labels the effect antagonist (tumour-suppressive signalling), but the dossier does not define it as receptor antagonism.","molecular_requirements":"Not reported in our evidence beyond Fzd-9 transfection conferring Wnt-7a sensitivity [PMID:15705594].","affinity_potency":[],"species_and_systems":"Human NSCLC cell lines and human proteins [PMID:15705594]. Human and mouse pairs in the dossier are ortholog-inferred.","localisation_and_range":"Ligand is flagged secreted and non-transmembrane [flag], so paracrine or autocrine action is expected; the paper's own data on range are not reported in our evidence.","caveats":"Abstract only. Co-immunoprecipitation does not show a purified-protein interaction. Signalling is non-canonical (JNK), unlike canonical Wnt7a signalling noted by curators for other receptors [PMID:15705594].","key_references":[{"PMID":"15705594","why":"Co-IP and Fzd-9-dependent Wnt-7a response in NSCLC"}],"covers":["LR001615","LR005004"]},"LR005008":{"pair":"WNT7B -> LRP5","headline":"WNT7B requires LRP5 as co-receptor for canonical signalling with Fzd1/Fzd10; LRP5 effect shown functionally, not by direct binding.","interaction_type":"functional only","direction_and_effect":"Wnt7b activates canonical Wnt signalling cooperatively with Fzd1 and Fzd10 in the presence of LRP5 (agonist, stimulatory) [PMID:15923619].","molecular_requirements":"LRP5 acts as a required co-receptor with Fzd1/Fzd10. LRP5 but not LRP6 expression is seen in vascular smooth muscle including the aorta, while both are expressed in airway epithelium [PMID:15923619].","affinity_potency":[],"species_and_systems":"Human ligand and receptor constructs in transfected cells; expression analysis in developing lung and vasculature [PMID:15923619].","localisation_and_range":"WNT ligand is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine; no paper in our evidence measured range.","caveats":"Abstract only. Direct binding was shown for Fzd1 and Fzd10, not for LRP5; the LRP5 role is inferred from co-receptor function [PMID:15923619]. Two further judged papers were abstract_insufficient.","key_references":[{"PMID":"15923619","why":"Wnt7b signals via Fzd1/Fzd10 with LRP5 co-receptor"}],"covers":["LR001619","LR005008"]},"LR003532":{"pair":"WNT8A -> PTK7","headline":"WNT8A co-precipitates with PTK7 in one abstract, but PTK7 inhibits rather than activates canonical signalling.","interaction_type":"direct binding","direction_and_effect":"PTK7/Otk co-precipitates canonical Wnt3a and Wnt8, yet PTK7 inhibits rather than activates canonical Wnt activity in Xenopus, Drosophila and luciferase reporter assays [PMID:21772251]. Loss of PTK7 activates canonical signalling and PTK7 acts at the level of the Frizzled receptor [PMID:21772251].","molecular_requirements":"Not reported in our evidence beyond placing PTK7 at the Frizzled level.","affinity_potency":[],"species_and_systems":"Xenopus, Drosophila and luciferase reporter assays; Wnt8 not resolved to WNT8A in the abstract [PMID:21772251]. The mouse pair is projected from human.","localisation_and_range":"WNT ligand is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine; no paper in our evidence measured range.","caveats":"Abstract only; co-precipitation is not proof of direct binding, and the effect is inhibitory (PTK7 turns off canonical signalling), not agonist [PMID:21772251]. Paralog 'Wnt8' is generic.","key_references":[{"PMID":"21772251","why":"PTK7 co-precipitates Wnt8 and inhibits canonical Wnt"}],"covers":["LR003532","LR006732"]},"LR002056":{"pair":"WNT9A -> FZD10","headline":"WNT9A signals through FZD10 in a reporter-cell rescue map; functional evidence from one paper, no binding data.","interaction_type":"functional only","direction_and_effect":"WNT9A signalled only via FZD4 and FZD10 among the FZDs tested, inducing canonical reporter signalling (agonism) [PMID:28733458].","molecular_requirements":"Only the Frizzled receptor is tested; co-receptors are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiments used reporter cells in a rescue design with FZD-mutant lines [PMID:28733458]; species of the cells is not stated in the excerpts. The mouse pair is projected from the human evidence (ortholog-inferred).","localisation_and_range":"Secreted ligand per the entity annotation flag [flag]; paracrine range is inferred from that flag only, not reported in the papers.","caveats":"Functional reporter readout only; no direct binding shown. Paper is a genetic rescue map of Wnt-FZD pairs, so paralog FZDs differ in specificity [PMID:28733458].","key_references":[{"PMID":"28733458","why":"Multiplex CRISPR FZD-knockout rescue map of Wnt-Frizzled signalling (full text read)."}],"covers":["LR002056","LR005382"]},"LR008140":{"pair":"WNT9A -> FZD4:LRP5","headline":"WNT9A signals through FZD4 in a reporter-cell rescue map; functional evidence from one paper, no binding data.","interaction_type":"functional only","direction_and_effect":"WNT9A signalled only via FZD4 and FZD10 among the FZDs tested, inducing canonical reporter signalling (agonism) [PMID:28733458].","molecular_requirements":"The receptor is listed as FZD4 plus LRP5; the paper's statement names only the Frizzled, and a requirement for LRP5 is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiments used reporter cells in a rescue design with FZD-mutant lines [PMID:28733458]; species of the cells is not stated in the excerpts.","localisation_and_range":"Secreted ligand per the entity annotation flag [flag]; paracrine range is inferred from that flag only, not reported in the papers.","caveats":"Functional reporter readout only; no direct binding shown. Paper is a genetic rescue map of Wnt-FZD pairs, so paralog FZDs differ in specificity [PMID:28733458].","key_references":[{"PMID":"28733458","why":"Multiplex CRISPR FZD-knockout rescue map of Wnt-Frizzled signalling (full text read)."}],"covers":["LR008140"]},"LR003541":{"pair":"WNT9A -> FZD9","headline":"WNT9A signals specifically through FZD9 in zebrafish and human cells; functional evidence, one paper.","interaction_type":"functional only","direction_and_effect":"Wnt9a signals specifically through Fzd9b to elicit beta-catenin-dependent signalling regulating haematopoietic stem and progenitor cell emergence; in the STF reporter assay only human FZD9 coupled effectively with WNT9A [PMID:31110287].","molecular_requirements":"EGFR is required as a cofactor, and LRP6 is needed (synergy with Lrp6 co-transfection) [PMID:31110287].","affinity_potency":[],"species_and_systems":"Zebrafish in vivo, human embryonic stem cells and HEK293T cells [PMID:31110287]. The mouse pair is projected from human evidence (ortholog-inferred).","localisation_and_range":"Secreted ligand per the entity annotation flag [flag]; paracrine range is inferred from that flag only, not reported in the papers.","caveats":"Curated from the abstract for this pair, with supporting full-text passages in the dossier. Functional only; no binding measurement in our evidence.","key_references":[{"PMID":"31110287","why":"Wnt9a-Fzd9b specificity, EGFR and LRP6 requirements."}],"covers":["LR003541","LR006741"]},"LR008014":{"pair":"ZG16B -> CXCR4:TLR2","headline":"Reported association of PAUF with the CXCR4-TLR2 complex that dampens TLR2-driven NF-kB; one paper, human cells.","interaction_type":"functional only","direction_and_effect":"PAUF associated with the CXCR4-TLR2 complex and inhibited CXCR4-dependent, TLR2-mediated NF-kB activation [PMID:20802527]. PAUF and SDF-1alpha both increased cAMP reporter activity (abolished by AMD3100) and both inhibited Pam3Cys-induced NF-kB activation, so the effect is antagonistic toward TLR2-NF-kB while PAUF still activates ERK through TLR2 [PMID:20802527].","molecular_requirements":"Both subunits appear involved: HA-TLR2 co-precipitated Flag-CXCR4 and myc-PAUF, and Flag-CXCR4 precipitates contained TLR2 and PAUF [PMID:20802527]. Whether each chain alone is enough is not reported in our evidence; the complex row requires both CXCR4 and TLR2 to be expressed.","affinity_potency":[],"species_and_systems":"Human proteins in HEK293T cells and THP-1 cells [PMID:20802527].","localisation_and_range":"ZG16B (PAUF) is flagged secreted [flag] and the paper treats it as a soluble ligand acting on cell-surface receptors [PMID:20802527].","caveats":"Evidence is co-immunoprecipitation and reporter assays; a stable ternary complex is suggested but not measured, and the authors say mechanisms remain to be clarified [PMID:20802527]. Single paper.","key_references":[{"PMID":"20802527","why":"PAUF associates with CXCR4-TLR2 complex; inhibits NF-kB"}],"covers":["LR008014"]},"LR001624":{"pair":"ZG16B -> TLR4","headline":"Direct binding reported by ELISA and co-IP, supported by antibody blocking in THP-1 cells; weaker than for TLR2 in the initial screen.","interaction_type":"direct binding","direction_and_effect":"ELISA with purified TLR4 ectodomain showed dose-dependent PAUF binding, and full-length TLR4 co-immunoprecipitated PAUF in HEK293T cells [PMID:20802527]. Anti-TLR4 antibody reduced Alexa 488-PAUF binding to THP-1 cells (median 97.3 to 47.6) [PMID:20802527]. Downstream effect specific to TLR4 is not reported in our evidence.","molecular_requirements":"Not reported in our evidence beyond direct interaction without other cofactors, as the authors conclude [PMID:20802527].","affinity_potency":[],"species_and_systems":"Human proteins; recombinant ectodomain, HEK293T cells, THP-1 cells [PMID:20802527]. UniProt notes TLR4 interacts with ZG16B/PAUF [DB:UniProt].","localisation_and_range":"ZG16B (PAUF) is flagged secreted [flag] and the paper treats it as a soluble ligand acting on cell-surface receptors [PMID:20802527].","caveats":"The receptor-pool screen gave a positive signal for TLR2 only, with TLR4 shown in follow-up assays [PMID:20802527]. No affinity reported. A single primary paper.","key_references":[{"PMID":"20802527","why":"PAUF binds TLR4 ectodomain and cell-surface TLR4"}],"covers":["LR001624"]},"LR012361":{"pair":"ZNRF3 -> FZD1:LRP6","headline":"Database-asserted only: ZNRF3 (an E3 ligase) is listed as inhibiting a FZD:LRP receptor complex; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Marked inhibitory in the resource, with ZNRF3 acting as a membrane receptor-receptor regulator rather than a classical secreted ligand [flag]. UniProt states ZNRF3 interacts with LRP6, FZD4, FZD5, FZD6 and FZD8 [PMID:22575959][DB:UniProt]; IntAct records anti-bait co-immunoprecipitation (Q9ULT6-O75581) [DB:IntAct]; BioGRID records ZNRF3 - LRP6: Affinity Capture-Western; LRP6 - ZNRF3: Affinity Capture-Western [DB:BioGRID]; Reactome lists ZNRF3,RNF43 binding the FZD:LRP5/6 receptor complex [DB:Reactome]. Functional effect not reported in our evidence.","molecular_requirements":"The listed FZD1 partner is not named in the UniProt statement; LRP6 evidence is present [DB:UniProt]. Whether FZD or LRP alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human. Experimental system not reported in our evidence beyond the database assay labels.","localisation_and_range":"ZNRF3 is flagged as a receptor, not secreted [flag]; this is a membrane-level interaction.","caveats":"All papers for this pair are pending or insufficient; support comes only from databases. The pair is a receptor-receptor complex projection and a given FZD paralog may not have been tested individually.","key_references":[],"covers":["LR012361"]},"LR012145":{"pair":"ZNRF3 -> FZD4:LRP5","headline":"Database-asserted only: ZNRF3 (an E3 ligase) is listed as inhibiting a FZD:LRP receptor complex; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Marked inhibitory in the resource, with ZNRF3 acting as a membrane receptor-receptor regulator rather than a classical secreted ligand [flag]. UniProt states ZNRF3 interacts with LRP6, FZD4, FZD5, FZD6 and FZD8 [PMID:22575959][DB:UniProt]. Functional effect not reported in our evidence.","molecular_requirements":"The listed FZD4 partner is named in the UniProt statement; LRP5 evidence is limited to the UniProt statement or absent [DB:UniProt]. Whether FZD or LRP alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human. Experimental system not reported in our evidence beyond the database assay labels.","localisation_and_range":"ZNRF3 is flagged as a receptor, not secreted [flag]; this is a membrane-level interaction.","caveats":"All papers for this pair are pending or insufficient; support comes only from databases. The pair is a receptor-receptor complex projection and a given FZD paralog may not have been tested individually.","key_references":[],"covers":["LR012145"]},"LR009400":{"pair":"ZP3 -> EGFR","headline":"Single abstract-read mouse paper reports a ZP3-EGFR interaction by microfluidic assay; EGFR is also proposed downstream of alpha7.","interaction_type":"direct binding","direction_and_effect":"A microfluidic affinity in vitro assay showed EGFR, as well as alpha7 nAChR, interacted with ZP3; the induced acrosome reaction was inhibited by EGFR antagonists [PMID:22577141].","molecular_requirements":"EGFR activation was SFK-dependent and downstream of alpha7 activation [PMID:22577141]. Whether ZP3 engages EGFR directly or via alpha7 is not resolved in our evidence.","affinity_potency":[],"species_and_systems":"Mouse sperm system per the study's WT and alpha7-null design [PMID:22577141]; the dossier pair is listed as human, not ortholog-inferred, although the evidence is mouse.","localisation_and_range":"ZP3 is flagged secreted and EGFR transmembrane [flag]; ZP3 is an egg zona pellucida component, so contact-dependent [PMID:22577141].","caveats":"Abstract only; no affinity; the title frames EGFR as mediating alpha7 activation, not as the primary ZP3 receptor [PMID:22577141].","key_references":[{"PMID":"22577141","why":"ZP3 interacts with EGFR in microfluidic assay"}],"covers":["LR009400"]},"LR004603":{"pair":"PDGFA -> PDGFRA","headline":"Well supported direct binding: cloned PDGFRA binds PDGF A-chain dimers with high affinity; database support is extensive.","interaction_type":"direct binding","direction_and_effect":"Stimulatory ligand-receptor pair. The expressed receptor bound 125I-labelled AA, AB and BB PDGF dimers with high affinity [PMID:2544881].","molecular_requirements":"PDGFA acts as a dimer (AA, or AB with B chain). Reactome describes a PDGF:PDGF receptor dimer complex [DB:Reactome]. Whether PDGFRA alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human receptor cDNA expressed in COS cells [PMID:2544881]. Mouse pair is ortholog-inferred.","localisation_and_range":"PDGFA is annotated secreted and PDGFRA transmembrane [flag]; paracrine signalling.","caveats":"Only one paper judged, abstract only; a numerical affinity is not reported in our evidence. BioGRID lists reconstituted complex and affinity capture-MS records [DB:BioGRID]; IntAct lists cross-linking and ELISA [DB:IntAct]. The binding result covers AB and BB dimers too, so is not specific to the A chain.","key_references":[{"PMID":"2544881","why":"Cloning of PDGFRA and radioligand binding of PDGF dimers."}],"covers":["LR001194","LR004603"]}};